/* Editorial corrections; load after all earlier content dictionaries. */
(function(){var edits={"en": {"bio-research-01": "Research agenda", "bio-research-02": "Research agenda <span class=\"grad\">and methods</span>", "bio-research-18": "Methods and analytical approach", "research-theme-government": "Digital government and public trust", "research-theme-ai": "AI, smart cities and public services", "research-theme-culture": "Information, culture and inclusion", "research-theme-learning": "Digital learning and professional capacity", "bio-research-19": "<strong>Comparative policy analysis.</strong> Her work compares institutional arrangements and digital-government practices across jurisdictions, with attention to the conditions required for their adaptation.", "bio-research-20": "<strong>Documentary and historical analysis.</strong> Legislation, institutional records and archives provide evidence of how public responsibilities, information policy and administrative practices have developed.", "bio-research-21": "<strong>Case studies and programme analysis.</strong> Studies of electronic services and smart-city initiatives examine implementation in its organisational context, including participation, service continuity and access.", "bio-research-22": "<strong>Stakeholder perspectives.</strong> Consultation and practitioner engagement inform the analysis of implementation constraints and the translation of research into guidance for public institutions.", "bio-research-23": "<strong>Research-informed learning design.</strong> Research on digital governance, AI-assisted learning and gamification informs scenarios, teaching resources and professional-development activities.", "bio-research-24": "<strong>Qualitative and quantitative evidence.</strong> Her portfolio includes mixed-methods projects and research on public servants’ AI competencies. The research question and available evidence determine the analytical approach.", "bio-research-25": "<strong>Knowledge mobilisation.</strong> Publications, practitioner guides, policy contributions and teaching connect research findings with institutional decisions and professional practice.", "bio-research-26": "<strong>Accessibility and inclusion.</strong> Her applied work considers barriers associated with disability, language and cultural context. Accessibility principles inform the design of digital learning resources.", "page-courses-02": "Courses and learning programmes", "courses-list-01": "Course development", "courses-list-03": "Prof. Svitlana Chukut developed the courses presented here across her work in Ukraine and Canada. The catalogue brings together university teaching, professional development for public servants and applied digital learning. Open a course to explore its content.", "courses-public-03": "This section presents courses developed by Prof. Svitlana Chukut at Ukraine’s National Academy of Public Administration and Igor Sikorsky Kyiv Polytechnic Institute. Each catalogue entry identifies its programme context and available course content.", "courses-kpi-02": "KPI <span class=\"grad\">course catalogue</span>", "courses-kpi-03": "The KPI catalogue presents 24 courses, with programme level, ECTS credits, status, development dates and descriptions where documented. Courses appear alphabetically. Open a course to explore its content and assessment.", "courses-kpi-06": "Required course", "courses-kpi-54": "Required course", "home-quick-17": "University courses and applied learning modules developed across her academic and curriculum-design work.", "home-quick-20": "Conferences, public lectures and forums, with dates, roles and supporting records.", "home-quick-21": "documented events", "home-quick-32": "Academic CVs, certificates, awards and supporting publication materials.", "home-quick-33": "documents and supporting files", "mdMoreT": "Explore events and public engagements", "courses-napa-26": "Specialty 8.150110 «E-Governance» · master's · required course", "courses-napa-28": "A required course of the Master's programme in specialty 8.150110 «E-Governance» at the National Academy's Chair of Information Policy (150 hours, 5 credits), compiled by Svitlana Chukut and Olha Zahvoiska. It forms students' modern theoretical and practical knowledge and skills in state information policy and e-governance, and in establishing effective communications, preparing them for cooperation and interaction in the information society. The programme comprises two modules: «Public Administration and State Policy in the Developing Information Society: Ukrainian and Foreign Experience» (90 hours, 3 credits) — the conceptual foundations of public administration in the information society, state information policy in Ukraine and the world with its legal frameworks and organisational and institutional support, and foreign strategies of information-policy development; and «Communications and Cooperation in the Information Society» (60 hours, 2 credits).", "courses-kpi-08": "A required course of the Doctor of Philosophy programme «Public Management and Administration» in specialty 281 (Year 2, autumn semester; 150 hours, 5 ECTS). It builds doctoral students' theoretical and practical knowledge and skills for the creative use and implementation of modern e-governance and digital-governance technologies and tools — including artificial intelligence — aimed at improving the public administration system itself and fostering innovation processes in society in line with world standards. Its subject is the study of the strategic directions of e-governance development: current trends, technologies and methodologies, including AI, digital tools and innovative practices. The fourteen webinars and their hands-on workshops cover an introduction to e-governance and digital governance; development trends — mobile, digital and smart governance; AI in public administration — opportunities and challenges; international e-governance indices — methodology and assessment; current trends in e-democracy; e-governance and smart cities — strategies, plans and indices; e-voting — challenges and threats; the Diia platform's role in Ukraine's digital transformation; crisis-oriented digital governance in emergencies (war and pandemics); priority directions from the best international and Ukrainian practices; ethics and data privacy in digital governance; and future trends — AI, blockchain and beyond. The course culminates in team presentations of the e-governance development strategies the doctoral students have developed.", "courses-kpi-41": "An elective course of the «Public Management and Administration» programme (Year 2, spring semester; 120 hours, 4 ECTS). It forms doctoral students' knowledge and skills in applying communication mechanisms within management activity — in particular to ensure the openness and transparency of public authorities — covering communication strategies and campaigns, communication channels, campaign planning, work with stakeholders and evaluation of campaign effectiveness. The topics include fakes and countering disinformation, social networks and blogs, drawing up a campaign scenario, and successful campaign experience in foreign countries and in Ukraine, together with the challenges and threats of running campaigns. Each doctoral student develops recommendations for a communication campaign aligned with the topic of their own dissertation research.", "courses-kpi-56": "A required course of the «Administrative Management» programme (Year 2, spring semester; 150 hours, 5 ECTS). It forms students' knowledge of the foundations and current trends of e-governance and e-democracy — the G2G, G2C, G2B and G2E interaction models, the stages of e-governance development and the UN EGDI index — and of identifying the challenges and threats that arise in implementation. The topics move from foreign experience and implementation in Ukraine to electronic services (including the Diia platform), e-democracy and e-voting, artificial intelligence in public administration, and e-governance in emergencies such as war and pandemics. Students learn to monitor and assess the level of electronic services and e-readiness, and present a team e-governance project developed during the course.", "courses-kpi-66": "A required course of the third (educational-scientific) level of higher education, within the educational programme «Public Management and Administration» of specialty 281 (field 28 «Public Management and Administration») (Year 2, autumn semester; 210 hours, 7 ECTS). Its aim is to combine scholarly research with practice: each doctoral student follows an individual working programme of the practice, formed in line with the topic of their dissertation research and from the tasks of pedagogical, educational, methodological and organisational work at the department. Doctoral students deepen their knowledge of higher-education pedagogy, carry out scholarly-methodical analysis of course programmes, draw up lesson plans, conduct different kinds of classroom sessions, improve bachelor's and master's disciplines with an author's approach and test their dissertation materials. Taking part in lectures, seminars, conferences, round tables and research circles develops leadership potential, oratorical skills and communication culture. The content comprises six sections: pedagogical activity; methodological activity; research activity; educational activity; organisational activity; and independent work. Semester assessment comprises drawing up the individual working programme and defending the practice report.", "courses-kpi-99": "A required course module of the professional and practical training cycle of the Master's specialty 8.15010011 «Electronic Governance», specialisation «Information Management in the E-Governance System» (Year 1, Semester 1; 120 hours, 4 ECTS), assessed by a coursework project and an oral examination. It forms students' theoretical and practical knowledge and skills for the creative use and introduction of modern e-governance methods and public administration methods aimed at improving the public administration system itself and fostering innovation processes in society on the basis of world standards — using modern information and advanced communication technologies in forming electronic state power, to provide public services to citizens, improve the functioning of the civil service and develop e-democracy. The programme comprises three content modules: the theoretical-methodological foundations of e-governance (its concept, essence and concepts, and foreign implementation experience); the organisational foundations (sectoral e-governance and its normative-legal support); and institutions in e-governance (electronic state power and the electronic institution). Students learn to assess an institution's e-readiness, to develop e-governance strategies for a sector, a territory or a public administration body, to draft legislative and normative acts regulating e-governance implementation, and to adapt foreign experience to Ukraine.", "courses-kpi-103": "A required course module of the professional and practical training cycle of the Master's specialty 8.15010011 «Electronic Governance», specialisation «Information Management in the E-Governance System» (Semester 1; 120 hours, 4 ECTS), assessed by an oral examination, with a creative work as the individual assignment. It forms students' theoretical and practical knowledge and skills for the creative use and introduction of modern e-governance methods and information and communication technologies in the system of providing state and municipal electronic services. The programme covers the essence and classification of electronic services; the systems of state services and of municipal services — their standards, regulations and catalogues; information management in the electronic-services system; the experience of organising electronic service provision in leading countries of the world; and the normative-legal support for electronic services in Ukraine. Students learn to coordinate the creation and functioning of an electronic-services system, to apply the basic technologies of providing electronic services, to organise information management within it, and to organise citizens' access to electronic services.", "courses-kpi-107": "A required course module of the professional and practical training cycle of the Master's specialty 8.15010011 «Electronic Governance», specialisation «Information Management in the E-Governance System» (Year 1, Semester 2; 120 hours, 4 ECTS), assessed by an oral credit, with a creative work as the individual assignment. It forms students' modern theoretical and practical knowledge, skills and abilities in applying communication mechanisms within management activity, ensuring the openness and transparency of public authorities. Its subject is communications within public administration bodies, communications between them, and communications between public authorities and the public. The programme comprises four topics: communications and communicative links in public administration — their concepts, types and legal foundations in Ukraine; intra-organisational communication — individual and group forms, meetings and management styles; the regional aspect of communications — vertical and horizontal links between central and local authorities, and between state power and local self-government; and communications as a democratic mechanism — public consultations and public councils, coverage of authorities' activities, agreements with non-state institutions and forms of local democracy. Students learn to prepare press releases, press conferences and briefings, to work with citizens' appeals and information requests, and to use the Internet for communication with the public, drawing also on international experience of communications in public administration, including in the institutions of the European Communities.", "courses-kpi-125": "A required course module of the discipline «E-Governance and E-Democracy» of the Master's specialty 281 «Public Administration and Management», specialisation «E-Governance» (Year 1, Semester 1; 60 hours, 2 ECTS), assessed by a differentiated credit, with a creative work as the individual assignment. It forms students' theoretical and practical knowledge and skills for the creative use of modern foreign approaches to e-governance and e-democracy, aimed at improving the public administration system itself and fostering innovation processes in society on the basis of world standards. The module is delivered in full-time and part-time forms of study. Its subject is the foreign experience of implementing e-governance and e-democracy. The programme comprises nine topics: information-society development strategy; the concept, principles, methods and models of e-governance; the main models and approaches to implementing e-governance in foreign countries, on the example of the EU — the «eEurope» programme and the European e-government action plans; institutions in e-governance; electronic services; the essence of e-democracy and its components; the normative-legal support of e-governance and e-democracy; citizens' e-participation in management decision-making; and the e-parliament. In the creative work, each student analyses in depth the e-governance experience of one of the UN's top-50 e-government countries and formulates conclusions and recommendations on applying that experience in Ukraine.", "courses-kpi-129": "A required course module of the discipline «E-Governance and E-Democracy» of the Master's specialty 281 «Public Administration and Management», specialisation «E-Governance» (Year 1, Semester 2; 90 hours, 3 ECTS), assessed by an examination, with a creative work as the individual assignment. It forms students' theoretical and practical knowledge and skills for the creative use of modern domestic approaches to e-governance and e-democracy, aimed at improving the public administration system itself and fostering innovation processes in society on the basis of world standards. Its subject is the domestic experience of implementing e-governance and e-democracy. The programme comprises nine topics: the information-society development strategy in Ukraine; the main stages of e-governance development in Ukraine; the structure and functions of e-governance across the sectors of public administration; e-democracy and e-governance under network warfare; the development of e-democracy and its main components in Ukraine; the normative-legal support of e-governance and e-democracy in Ukraine; e-democracy tools; electronic services; and the communication campaign, identifying topical e-governance problems. Practical classes are also held in state authorities and local self-government bodies and as a business game; in the creative work, students continue their analysis of a foreign country's experience and compare it with the development of e-governance and e-democracy in Ukraine.", "events-gallery-09": "Award ceremony of the All-Ukrainian competition of the National Agency of Ukraine on Civil Service (NADS) “Best Practices in Implementing Educational Innovations in the System of Professional Training of Civil Servants, Heads of Local State Administrations, Their First Deputies and Deputies, Local Self-Government Officials and Deputies of Local Councils”, 2020. Nomination “Training of Master’s Students in Specialty 281 ‘Public Management and Administration’”: the educational innovative practice “Master It, Research It, Implement It!” (author — Svitlana Anatoliivna Chukut, Doctor of Sciences in Public Administration, Professor)", "events-gallery-17": "The X International Scientific and Practical Conference “Modern Problems of Management 2019”. Talk “From E-Government to Smart Governance: Current Challenges and Threats”. Svitlana Chukut — deputy chair of the conference organising committee, acting head of the Department of Theory and Practice of Management at Igor Sikorsky Kyiv Polytechnic Institute, deputy chair of Sectoral Expert Council No. 28 “Public Management and Administration” of the National Agency for Higher Education Quality Assurance", "events-gallery-19": "Conducting the All-Ukrainian seminar-meeting to discuss the draft standard of higher education in Public Management and Administration (master’s level), 2018", "events-gallery-21": "Extended meeting of the subcommission of the Scientific-Methodical Commission for specialty 281 “Public Management and Administration” on the standard of higher education of the third (educational-scientific) level — the Doctor of Philosophy degree, Hall of Administrative Meetings of Igor Sikorsky Kyiv Polytechnic Institute, 12 October 2017 (over 60 participants: state officials, heads of higher education institutions, scholars from different regions of Ukraine)", "alt-event-subcommission-2017": "Extended meeting of the subcommission for specialty 281 “Public Management and Administration”, Igor Sikorsky Kyiv Polytechnic Institute, 12 October 2017", "description-book-76-title": "<p>Part 7 of the fifteen-part textbook \"E-Governance and E-Democracy\" (Kyiv, 2017), prepared within the EGAP programme \"E-Governance for Accountability and Participation\" with the support of the Swiss Agency for Development and Cooperation and approved by the Academic Council of the National Academy of Public Administration under the President of Ukraine. Chukut's part covers the development of e-governance at the local and regional levels: the concepts of the e-region and the e-city (\"smart city\"), the state of regional e-governance in Ukraine, the implementation experience of Lviv and Vinnytsia, and the main directions of e-governance development in Kyiv, including electronic administrative services at the local level. A second section presents best foreign practices — Australia, France, Switzerland and the United Arab Emirates. The 72-page part closes with self-check questions, recommended literature and assignments for practical classes, and is addressed to students of Public Management and Administration, civil servants and local officials in professional development, and representatives of civil-society organisations and business.</p>", "description-book-187-title": "<p>Textbook by Vitalii Skurativskyi, Volodymyr Troshchynskyi and Svitlana Chukut (UAPA Publishing House; Milenium, Kyiv, 2002, 262 pp.). One of the first systematic Ukrainian study guides devoted to the theoretical-methodological and applied aspects of public administration of the humanitarian sphere. The work comprehensively analyses the essence, structure and priorities of state humanitarian policy amid the transformation of Ukrainian society, with particular attention to the mechanisms of state regulation of the development of education, science, culture, language and information policy, and to the interaction of state authorities with civil-society institutions. The book systematises domestic and foreign experience of forming a state's humanitarian policy and establishes the basic conceptual and categorical apparatus for training specialists in public administration and local self-government; it became a basic source for teaching normative and elective disciplines in humanitarian and social policy in Ukrainian higher education institutions. Intended for students, master's students and doctoral candidates in the \"Public Management and Administration\" field, civil servants, local self-government officials and researchers.</p>", "staticLibrary": "<div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Organiser of the XIII Int. conf. 'Contemporary Problems of Management' <a href=\"http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-0\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-0\" hidden><p>Organisational work for the 13th Contemporary Problems of Management conference at Igor Sikorsky Kyiv Polytechnic Institute in September 2025. The entry documents Svitlana Chukut’s organising role in a departmental conference on contemporary issues in management and public administration.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2025, September 25). <i>Organiser of the XIII int. conf. &#x27;contemporary problems of management&#x27;</i> [Conference record]. <a class=\"apa-source\" href=\"http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/\" target=\"_blank\" rel=\"noopener\">http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/</a></p><div class=\"m\">Talks · 2025 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute», 25.09.2025</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Innovative Approaches to Smart Tourism during War and Post-War Recovery <a href=\"https://ela.kpi.ua/items/b5e7707d-f944-4157-b0a8-4d214682e58e\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-1\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-1\" hidden><p>Based on in-depth expert interviews, the study traces how Ukraine's tourism businesses adapted to the compounded shocks of the pandemic and the full-scale war — financial instability, closures and workforce migration. It identifies the strategies that worked, from digital transformation and remote service models to personalised offers, and examines the rise of military, solidarity and virtual tourism. Its conclusion points to lighter tax burdens, better regulation and stronger professional expertise as conditions for recovery.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Yenin, M. N., Akimova, O. A., Ischenko, A. M., Perga, I. M., & Zahvoiska, O. V. (2025). Innovative approaches to smart tourism during war and post-war recovery: The case of Ukraine. <i>Bulletin of NTUU “KPI”: Political Science. Sociology. Law</i>, (1(65)), 58–67. <a class=\"apa-source\" href=\"https://doi.org/10.20535/2308-5053.2025.1(65).332550\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/2308-5053.2025.1(65).332550</a></p><div class=\"m\">Articles · 2025 · Bulletin of NTUU 'KPI': Political Science. Sociology. Law</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Assessment of skills in using AI tools among public servants in Ukraine <a href=\"https://doi.org/10.52058/2708-7530-2024-10(52)-16-31\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-2\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-2\" hidden><p>A survey of Ukrainian civil servants, analysed with descriptive statistics and multivariate methods, maps their current command of AI tools through a gender lens. It shows how gender, age and job category relate to these skills, and argues that gender-responsive design makes AI-supported services more equitable and inclusive. The authors recommend national AI training programmes, experimentation centres and gender-sensitive digital policies to close the digital gender divide.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Ishchenko, A. (2024). Assessment of skills in using AI tools among public servants in Ukraine. <i>Naukovi Perspektyvy</i>, (10(52)), 16–31. <a class=\"apa-source\" href=\"https://doi.org/10.52058/2708-7530-2024-10(52)-16-31\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.52058/2708-7530-2024-10(52)-16-31</a></p><div class=\"m\">Articles · 2024 · Naukovi perspektyvy, No. 10(52), pp. 16–31</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Faculty of Sociology and Law, National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute» coordinator for the MoU with Western Sydney University <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-3\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-3\" hidden><p>Coordinated the signing of a memorandum of understanding with Western Sydney University on behalf of KPI’s Faculty of Sociology and Law. The memorandum formalised a relationship between the two institutions. The entry documents the Faculty of Sociology and Law’s role in establishing that academic cooperation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2024). <i>Faculty of sociology and law, national technical university of Ukraine «Igor Sikorsky Kyiv Polytechnic institute» coordinator for the MoU with Western Sydney university</i> [Collaboration record]. <a class=\"apa-source\" href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\">https://icd.kpi.ua/?p=18255</a></p><div class=\"m\">Talks · 2024 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute» — WSU</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Organising e-service delivery in Ukraine during wartime <a href=\"https://doi.org/10.34132/pard2023.20.14\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-4\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-4\" hidden><p>The authors review how state authorities and local governments in Ukraine kept electronic services running after the full-scale invasion, tracing the war's specific effects on this sphere. They compare Ukraine's Online Services Index and E-Government Development Index for 2016–2022, including the UN's revised 2022 methodology, and map the legal acts and institutions — above all the Ministry of Digital Transformation — behind service delivery. The article closes with proposals for further wartime research centred on the needs of citizens and business.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Karpenko, Y. (2023). Organising e-service delivery in Ukraine during wartime. <i>Public Administration and Regional Development</i>, (20), 589–613. <a class=\"apa-source\" href=\"https://doi.org/10.34132/pard2023.20.14\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.34132/pard2023.20.14</a></p><div class=\"m\">Articles · 2023 · Public Administration and Regional Development, No. 20, pp. 589–613</div><div class=\"publication-translations policy-document-actions\" role=\"group\" aria-label=\"Read the translation\"><a class=\"text-link\" href=\"article-translations/wartime-e-services-en.html\" lang=\"en\" hreflang=\"en\">English</a><a class=\"text-link\" href=\"article-translations/wartime-e-services-fr.html\" lang=\"fr\" hreflang=\"fr\">Français</a></div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>20</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Digitising archival processes amid the National Archival Fond's formation <a href=\"https://doi.org/10.32702/2306-6814.2023.24.163\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-5\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-5\" hidden><p>Drawing on foreign archival practice, the article examines how archival work is being digitised as Ukraine's National Archival Fond takes shape and integrates into the world information space. It compares the United States' NARA — with its comprehensive digital preservation strategy of standardisation, risk planning and file management — and the National Archives of Australia, and also considers Chinese and Polish experience. Both archives rely on cloud storage and use artificial intelligence to automate document processing, including metadata completion, which lowers maintenance costs.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Karapoziuk, A. (2023). Digitising archival processes amid the national archival fond's formation. <i>Investytsiyi: Praktyka ta Dosvid</i>, (24), 163–170. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2023.24.163\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2023.24.163</a></p><div class=\"m\">Articles · 2023 · Investytsiyi: praktyka ta dosvid, No. 24, pp. 163–170</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>8</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The Smart Tourism during the War and post-War Recovery: The Case of Ukraine <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-6\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-6\" hidden><p>The study examines how the pandemic and the war affected tourism in Ukraine. It draws on expert interviews to identify recovery options and uses of digital tools in the sector.</p><p>The analysis distinguishes the pressures on tourism businesses from their responses, including adapting their offers and moving services online.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Akimova, O., Ischenko, A., Yenin, M., Perga, I., & Zahvoiska, O. (2023). The smart tourism during the war and post-war recovery: The case of Ukraine. In <i>Business rejuvenation, resilience, and creativity in a changing world and post pandemic future: Book of papers and posters for the 2023 GISU International Research Symposium</i> (pp. 18–23). GISU Alliance. <a class=\"apa-source\" href=\"https://imathm.edu.lk/files/documents/file_name/1ab71bb9-f35d-42f4-a006-6234f88ff6a3/book_of_papers_and_posters.pdf\" target=\"_blank\" rel=\"noopener\">https://imathm.edu.lk/files/documents/file_name/1ab71bb9-f35d-42f4-a006-6234f88ff6a3/book_of_papers_and_posters.pdf</a></p><div class=\"m\">Conferences · 2023 · GISU symposium, Sydney, Australia (most active participant)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Artificial intelligence in public administration: challenges and threats</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-7\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-7\" hidden><p>Conference theses in the proceedings of the XII International Conference \"Contemporary Problems of Management\" (Kyiv, 24 November 2023, pp. 147–150). Chukut notes that the risks of ICT in public administration have grown sharply with artificial intelligence — a field opened for government by the OECD's \"Hello World\" report — and, since Ukraine's EU membership bid makes European practice directly relevant, examines the European Union's approach: investment through Digital Europe and Horizon Europe, the European strategy for data, and the risk-based legal framework agreed in December 2023. She explains the AI Act's tiers: unacceptable-risk systems are banned (cognitive behavioural manipulation, social scoring, biometric categorisation, real-time remote biometric identification, with narrow law-enforcement exceptions); high-risk systems — most of them in public administration, from critical infrastructure and education to employment, essential services, law enforcement, migration and legal interpretation, including systems influencing elections — require assessment before deployment and throughout their life cycle, with citizens gaining rights to complain and to explanations; generative AI must disclose AI-generated content, prevent illegal content and publish summaries of training data, with systemic-risk general-purpose models evaluated and incidents reported; limited-risk systems owe minimal transparency, such as labelling deepfakes. Non-compliance fines run from 7.5 million euros or 1.5 percent of turnover to 35 million euros or 7 percent. She also points to the ELISE platform's open dataset of public-sector AI cases (143 by December 2023) and to CitizenLab's use of natural-language processing for civic participation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2023). Artificial intelligence in public administration: Challenges and threats. In <i>Proceedings of the XII International Scientific-Practical Conference “Contemporary Problems of Management”</i> (pp. 147–150). Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Conferences · 2023 · Proceedings of the XII International Conference 'Contemporary Problems of Management', Kyiv, 24 November 2023, pp. 147–150</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Orbicom 'Digital transformation of public administration for SDGs'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-8\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-8\" hidden><p>How can governments and cities go digital in a way that also helps meet the Sustainable Development Goals — the UN's global goals for health, education, equality and the environment? This international Orbicom network project (March 2023 – September 2025) studies that question, and Svitlana Chukut takes part as a researcher associated with Igor Sikorsky Kyiv Polytechnic Institute, where she leads the university's registered initiative research theme 'Digital transformation of state administration and local self-government: challenges and opportunities for achieving the SDGs' (state registration No. 0123U101483) — fundamental research intended to produce methodological documents and analytical materials. The work runs in three strands: digitalisation of public administration at state and local levels, including her papers on organising electronic services in wartime (with Ye. Karpenko) and on digitalising archives (with A. Karapoziuk); smart cities and artificial intelligence, including the smart-tourism study, smart energy systems using big data (with L. Shumska) and the challenges and threats of artificial intelligence in public administration; and the impact of digitalisation on social processes and public administration. In the first reporting period alone (March 2023 – May 2024), the theme produced 12 articles in professional (category B) journals; student research was prepared for international competitions — a work by O. Shyts and L. Shumska took 1st place at the international competition on management, social and behavioural sciences in implementing sustainable development — and for the national Civil Service Day youth competition; and two project proposals were drafted: a Ukrainian–Latvian project on digital skills and access to digital technologies for Ukrainian forced migrant women in Latvia, and a proposal to the National Research Foundation of Ukraine on the digital and educational reintegration of young people from de-occupied and temporarily occupied territories. The results go straight into teaching: they were implemented in her courses — Fundamentals of E-Governance, Smart Cities, E-Democracy, E-Governance and E-Democracy, and Strategic Directions of E-Governance Development — five distance courses were developed and certified on the Sikorsky (Moodle) platform, and the team presented at four international conferences and seminars, including the 2023 GISU research symposium.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Orbicom &#x27;digital transformation of public administration for SDGs&#x27;</i> [Research project]. (2023–2025). Orbicom.</p><div class=\"m\">Projects · 2023–2025 · Participant</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Public lecture 'How Social Media & E-Messaging are the Real Weapons in the Russia-Ukraine War' <a href=\"https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-9\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-9\" hidden><p>A public lecture at the Rotary Club of Kingston on how social media and electronic messaging spread information and shape narratives during Russia’s war against Ukraine. The talk situates activity on these platforms within the broader context of public communication and the circulation of information during wartime.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2023). <i>How social media &amp; e-messaging are the real weapons in the bitter Russia–Ukraine war</i> [Public lecture]. Rotary Club of Kingston, Ontario, Canada. <a class=\"apa-source\" href=\"https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war\" target=\"_blank\" rel=\"noopener\">https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war</a></p><div class=\"m\">Talks · 2023 · Rotary Club of Kingston, Ontario, Canada</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Most active participant of the GISU international symposium <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-10\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-10\" hidden><p>Recognition for participation in the GISU Alliance research symposium in Sydney, where research on the resilience of Ukrainian tourism was presented. The symposium proceedings contain the team’s paper on how Ukrainian tourism businesses responded to wartime disruption.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>GISU Alliance. (2023). <i>Most active participant of the GISU international symposium</i> [Award record]. <a class=\"apa-source\" href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\">https://icd.kpi.ua/?p=18255</a></p><div class=\"m\">Talks · 2023 · Sydney, Australia</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude for mentoring an international competition winner</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-11\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-11\" hidden><p>Recognition for supervising a student research project that placed first in an international competition.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Gratitude for mentoring an international competition winner</i> [Award record]. (2023).</p><div class=\"m\">Awards · 2023 · International competition</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L. Shumska & O. Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-12\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-12\" hidden><p>Student research work “Ensuring social inclusion in smart power systems to achieve sustainable development in conditions of war” by L. Shumska and O. Shyts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The first study of social inclusion in the context of smart power systems: it analyses the experience of Poland, Scotland and the United Kingdom, and Canada, and develops recommendations for implementing the best foreign experience in Ukraine under wartime conditions. The work was presented at three international conferences, and its results were implemented at the Solomianska District State Administration in Kyiv, the Khmelnytskyi Nuclear Power Plant of Energoatom, the Sotsioplus centre and the “Drevo Nadii” charitable foundation; two articles and four conference papers were published.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Shumska, L., & Shyts, O. (2023). <i>Ensuring social inclusion in smart power systems to achieve sustainable development in conditions of war</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/vitayemo-z-pershym-mistsem-na-mizhnarodnomu-konkursi-studentskyh-naukovyh-robit/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/vitayemo-z-pershym-mistsem-na-mizhnarodnomu-konkursi-studentskyh-naukovyh-robit/</a></p><div class=\"m\">Supervised research · 2023 · 1st place — Diploma of the 1st degree · international competition — Ensuring social inclusion in smart power systems to achieve sustainable development in conditions of war</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">Innovative Teaching with ChatGPT</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-13\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-13\" hidden><p>Professional development in integrating ChatGPT into teaching and designing learning activities that use generative AI. In a teaching context, these uses raise practical questions about the tool’s role in an assignment, the work expected of learners and how that work will be assessed.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Vanderbilt University. (2023). <i>Innovative teaching with ChatGPT</i> [Training certificate].</p><div class=\"m\">Certificates · 2023 · Vanderbilt University</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">Qualitative Methods in Research</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-14\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-14\" hidden><p>Training from Ukraine Global Faculty on qualitative approaches and their use in designing a research study. Qualitative methods help investigate experiences, interpretations and practices. The choice of approach depends on the research question and the evidence needed to answer it.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ukraine Global Faculty. (2023). <i>Qualitative methods in research</i> [Training certificate].</p><div class=\"m\">Certificates · 2023 · Ukraine Global Faculty</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">Quantitative Methods in Research</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-15\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-15\" hidden><p>Training from Ukraine Global Faculty on quantitative methods and their application to research questions. This area of research training addresses measurable data and how they can be analysed to describe patterns, compare groups or examine relationships between variables.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ukraine Global Faculty. (2023). <i>Quantitative methods in research</i> [Training certificate].</p><div class=\"m\">Certificates · 2023 · Ukraine Global Faculty</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">TCPS 2: CORE — Research Ethics</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-16\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-16\" hidden><p>Canadian training in research ethics for studies involving humans, based on the Tri-Council Policy Statement. The Canadian framework addresses issues such as consent, privacy and risk assessment in studies involving participants.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Tri-agency Institutional Programs Secretariat. (2023). <i>TCPS 2: CORE — research ethics</i> [Training certificate].</p><div class=\"m\">Certificates · 2023 · Tri-agency Institutional Programs Secretariat</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">Enhanced Language Training (ELT)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-17\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-17\" hidden><p>COSTI training to develop English-language skills for the Canadian workplace. The programme situates language learning in workplace situations involving communication with colleagues, understanding instructions and interacting with the public.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>COSTI. (2023). <i>Enhanced language training (ELT)</i> [Training certificate].</p><div class=\"m\">Certificates · 2023 · COSTI</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Cultural diversity in smart cities: experience of the European Union and challenges for Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-18\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-18\" hidden><p>A chapter written with Olha Zahvoiska for the collective monograph \"European Benchmarks of Public Administration\" (Kyiv, 2023), in its section on European identity and cultural diversity. It examines what cultural diversity means inside a smart city — inclusive digital infrastructure, multilingual interfaces, digitally preserved heritage, cultural events and data-informed cultural planning — and sets out the European Union's approaches and legal framework for protecting it. Against that background it works through the challenges for Ukraine, from the ethnic and linguistic divide and the digital gap to the war's destruction of cultural heritage and the displacement of communities, and closes with recommendations for bringing Ukrainian legislation on smart cities into line with European requirements.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Zahvoiska, O. (2023). Cultural diversity in smart cities: Experience of the European Union and challenges for Ukraine. In Y. Lykhach (Ed.), <i>European benchmarks of public administration</i> (pp. 185–194).</p><div class=\"m\">Books & monographs · 2023 · Chapter 7.1. In: 'European Benchmarks of Public Administration'. Kyiv, 2023, pp. 185–194</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Smart grids as a smart-city component using big data <a href=\"https://doi.org/10.32702/2306-6814.2022.3.88\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-19\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-19\" hidden><p>The article sets out the conceptual links between the smart city, big data and smart energy grids, then examines management strategies in Canada (the Smart Metering Initiative), Denmark (EcoGrid 2.0) and South Korea (the Jeju Island testbed). In Ukraine, it finds, smart metering is being rolled out by private electricity suppliers rather than government initiative, with no legal definition of a smart grid or smart meter and no approved transition strategy. It identifies privacy and cybersecurity risks and offers practical recommendations for applying foreign experience while avoiding cyber threats.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Shumska, L. (2022). Smart grids as a smart-city component using big data. <i>Investytsiyi: Praktyka ta Dosvid</i>, <i>3</i>, 88–95. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2022.3.88\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2022.3.88</a></p><div class=\"m\">Articles · 2022 · Investytsiyi: praktyka ta dosvid, vol. 3, pp. 88–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/osnovy-egu-2022-titlepage-hq.webp\" alt=\"Fundamentals of Electronic Governance: a textbook\"><div class=\"lib-copy\"><div class=\"t\">Fundamentals of Electronic Governance: a textbook <a href=\"https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-20\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-20\" hidden><p>This 268-page electronic textbook, published by Igor Sikorsky Kyiv Polytechnic Institute in 2022, provides a structured introduction to e-governance for undergraduate students in Specialty 281, Public Administration and Management, including the Administrative Management and E-Governance programmes. It also supports the university-wide course Fundamentals of Electronic Governance. Prof. Svitlana Chukut is a co-author and the responsible editor, alongside co-authors Olha Zahvoiska and Yana Tsymbalenko.</p><p>Its eight chapters connect conceptual foundations with the institutional and societal dimensions of digital government. They examine models of e-governance and implementation barriers; United Nations assessment methods and indices, including e-government development, online services, telecommunications infrastructure, human capital, e-participation and local online services; and the development of e-governance in Ukraine.</p><p>The treatment of digital public services addresses service maturity, interoperability, inclusion of vulnerable groups and the Diia portal, with examples from Austria and Denmark. Further chapters examine e-democracy, electronic petitions, e-parliament and electronic voting, including Council of Europe standards and experience from the United States and Estonia. The final chapter considers network warfare and the COVID-19 pandemic as challenges for digital governance and democratic participation.</p><p>The teaching framework extends beyond subject knowledge. The introduction identifies skills in evidence gathering, analysis, recommendations, teamwork and decision-making. The textbook includes individual research assignments, team-project requirements and suggested topics, a glossary and references. These elements support independent inquiry and discussion of how institutions can introduce digital services while considering participation, inclusion and implementation risks.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Zahvoiska, O. V., & Tsymbalenko, Y. Y. (2022). <i>Fundamentals of electronic governance</i>. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463</a></p><div class=\"m\">Books & monographs · 2022 · Kyiv: National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute». — 268 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>74</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude for mentoring an international competition winner</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-21\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-21\" hidden><p>Recognition from Ivano-Frankivsk National Technical University of Oil and Gas for supervising a student project that received an international competition award.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ivano-Frankivsk National Technical University of Oil and Gas. (2022). <i>Gratitude for mentoring an international competition winner</i> [Award record].</p><div class=\"m\">Awards · 2022 · Ivano-Frankivsk National Technical University of Oil and Gas</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mykyta Skreminskyi <a href=\"https://ktpu.kpi.ua/dosiahnennia-kafedry/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-22\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-22\" hidden><p>Student research work “Electronic governance in the process of achieving sustainable development goals in the context of the COVID-19 pandemic” by Mykyta Skreminskyi, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work examines the role of e-governance in achieving the UN Sustainable Development Goals during the COVID-19 pandemic, when quarantine restrictions made e-governance an effective tool against the spread of infection. It analyses international and Ukrainian experience of the e-governance tools used against the pandemic and develops recommendations. Its results were implemented at the Educational and Scientific Centre of Applied Sociology “Sotsioplus”; the author has three publications.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Skreminskyi, M. (2022). <i>Electronic governance in the process of achieving sustainable development goals in the context of the COVID-19 pandemic</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/dosiahnennia-kafedry/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/dosiahnennia-kafedry/</a></p><div class=\"m\">Supervised research · 2022 · 2nd place — Diploma of the 2nd degree · International competition of student scientific works “Managerial, Social and Behavioural Sciences in Implementing the Principles of Sustainable Development” — Electronic governance in the process of achieving sustainable development goals in the context of the COVID-19 pandemic</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Oleksandra Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-23\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-23\" hidden><p>Student research work “Social inclusion and sustainable development” by Oleksandra Shyts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies social inclusion and sustainable development, including digital inclusion and digital inequality in smart cities; a survey found problems of accessibility, involvement and equality of opportunity in Ukraine and Kyiv. It analyses the best foreign practices and gives recommendations for Ukraine. Its results were implemented at the Sotsioplus centre; the author has three publications (2021).</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Shyts, O. (2022). <i>Social inclusion and sustainable development</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2022 · 1st place — Diploma of the 1st degree · Stage I · All-Ukrainian competition of student scientific works “Management of E-Business and Smart Technologies” — Social inclusion and sustainable development</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Sofiia Potapenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-24\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-24\" hidden><p>Student research work “The experience of implementing the smart city in Zurich and the possibilities of its implementation in Ukraine” (competition code “Compbeg”) by Potapenko, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work analyses the development of the smart city of Zurich in Switzerland and the possibilities of implementing this experience in Ukraine, comparing the components and development stages of smart cities in Switzerland and Ukraine. It was published in SWorldJournal (issue 11, 2022, Bulgaria) and presented at the III All-Ukrainian conference in Kyiv (2021); its results and recommendations were implemented at EVON LLC (implementation certificate).</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Potapenko, S. (2022). <i>The experience of implementing the smart city in Zurich and the possibilities of its implementation in Ukraine</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2022 · 3rd place — Diploma of the 3rd degree · Stage I · All-Ukrainian competition of student scientific works “Management of E-Business and Smart Technologies” — The experience of implementing the smart city in Zurich and the possibilities of its implementation in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ensuring social inclusion in smart cities: challenges and current trends <a href=\"https://doi.org/10.32702/2307-2156-2021.1.5\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-25\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-25\" hidden><p>The study unpacks the concepts of digital inequality, the digital divide, digital illiteracy and digital and social inclusion, showing how digital inequality deepens social inequality. It reviews the legal frameworks at international and EU level and the practice of individual smart cities such as Vienna, and derives the core requirements for accessibility when modern technologies are not adapted to the most vulnerable citizens. Ukrainian experience is then assessed against those requirements, and ways of securing inclusion in Ukraine are proposed.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Shyts, O. (2021). Ensuring social inclusion in smart cities: Challenges and current trends. <i>Derzhavne Upravlinnia</i>, (1). <a class=\"apa-source\" href=\"https://doi.org/10.32702/2307-2156-2021.1.5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2307-2156-2021.1.5</a></p><div class=\"m\">Articles · 2021 · Derzhavne upravlinnia, No. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Communication strategies in public management and administration: foreign and Ukrainian experience <a href=\"https://doi.org/10.32702/2306-6814.2021.12.72\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-26\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-26\" hidden><p>After defining communication, communication strategies and communicative policy, the article compares how such strategies are built and implemented in Europe, North America and Asia — Madrid's Consul participation project, Canada's citizen-focused strategy and Bangladesh's local-level model. It argues that a strategy works only when the roles of each side are clearly defined, turning an organisation's core idea into key messages for each audience. Ukrainian practice is analysed at state and local level, through the Verkhovna Rada and the Merefa city council.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Yatsenko, V. (2021). Communication strategies in public management and administration: Foreign and Ukrainian experience. <i>Investytsiyi: Praktyka ta Dosvid</i>, (12), 72–79. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2021.12.72\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2021.12.72</a></p><div class=\"m\">Articles · 2021 · Investytsiyi: praktyka ta dosvid, No. 12, pp. 72–79</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>44</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Interpreting 'sustainable development' in Ukraine's public administration <a href=\"https://doi.org/10.51547/ppp.dp.ua/2021.6.4\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-27\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-27\" hidden><p>The work gathers the arguments and counter-arguments in the scholarly debate over how 'sustainable development' is understood in Ukrainian political documents — a meaning shaped by political usage and by translation from English rather than by research findings alone. Comparing voluntary national reviews of the countries whose experience Ukraine draws on (2017–2020) with Ukrainian scholarship and practice, it shows how divergent readings affect public engagement, partnership-building and e-governance. It concludes that Ukrainian public administration must re-evaluate its applied approaches, since the concept's ambiguity leaves the country without a clear strategy or stable goals.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Drahomyretska, N., Romanenko, Y., & Sazykina, T. (2021). Interpreting 'sustainable development' in Ukraine's public administration. <i>Dnipro Scientific Journal</i>, (6). <a class=\"apa-source\" href=\"https://doi.org/10.51547/ppp.dp.ua/2021.6.4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.51547/ppp.dp.ua/2021.6.4</a></p><div class=\"m\">Articles · 2021 · Dnipro Scientific Journal, No. 6</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The organisational and legal context of Ukraine's government action on sustainable development <a href=\"https://doi.org/10.51547/ppp.dp.ua/2021.5.1\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-28\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-28\" hidden><p>Ukraine, the article notes, imports foreign sustainable-development experience and adapts it, rather than exporting its own — and its scholarship likewise adapts foreign concepts. The authors compare how Ukraine and the countries it learns from have built organisational and advisory structures responsible for sustainable development. They find a gap between the concept's legal and scholarly definitions in Ukraine, which keeps those structures being created and abolished in turn and destabilises policy direction.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Drahomyretska, N., & Romanenko, Y. (2021). The organisational and legal context of Ukraine's government action on sustainable development. <i>Dnipro Scientific Journal</i>, (5). <a class=\"apa-source\" href=\"https://doi.org/10.51547/ppp.dp.ua/2021.5.1\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.51547/ppp.dp.ua/2021.5.1</a></p><div class=\"m\">Articles · 2021 · Dnipro Scientific Journal, No. 5</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Public management and COVID-19: challenges and digital transformation <a href=\"https://doi.org/10.20535/spu2021.249115\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-29\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-29\" hidden><p>COVID-19 acted as a catalyst that forced change in public management at an accelerated pace, as governments had to decide quickly under force-majeure pressure. Beyond the challenges already set by the UN Sustainable Development Goals, the pandemic deepened the digital divide, poverty and hunger and posed a real threat to citizens' lives. The paper frames these compounded pressures as the starting point for the digital transformation of public management.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2021). Public management and COVID-19: Challenges and digital transformation. In <i>Proceedings of the XI International Scientific-Practical Conference “Contemporary Problems of Management”</i> (pp. 323–326). Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://doi.org/10.20535/spu2021.249115\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/spu2021.249115</a></p><div class=\"m\">Articles · 2021 · Proc. XI Int. conf., pp. 323–326</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Public management and COVID-19: challenges and digital transformation <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-30\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-30\" hidden><p>Conference theses in which Chukut treats the COVID-19 pandemic as a catalyst of accelerated change in public administration. Following the World Bank, she groups the challenges into health, the economy and taxes, adds the corruption risks of emergency procurement, and notes how the crisis exposed weak coordination, fragile institutions, poor accountability and patronage — together with the danger that governments use the emergency to usurp power and restrict rights. She sets out the OECD's directions for government action in a pandemic, from public trust and digital government to risk management and public integrity, and the role of digital transformation: as the UN's Liu Zhenmin observed, digital technologies let governments keep communicating and delivering services online throughout the pandemic, even as privacy and disinformation problems sharpened. The theses present the UN Compendium of digital government initiatives responding to COVID-19 and examine France's state-built tools in detail — above all Tchap, the secure government messenger run by the Interministerial Digital Directorate (over 200,000 users by November 2021), alongside state web- and audio-conferencing, the Osmose professional-communities platform and the Resana collaborative workspace. She concludes that responses should adapt government operating, service and citizen-interaction models to digital tools, build collective action on trust — \"come together while staying apart\" — and develop effective, inclusive and accountable government.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2021). <i>Public management and COVID-19: Challenges and digital transformation</i> [Plenary presentation]. 11th Contemporary Problems of Management International Conference, Kyiv, Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf</a></p><div class=\"m\">Conferences · 2021 · PLENARY talk. XI Int. conf., Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Audit of management and stakeholder engagement systems, Energoatom</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-31\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-31\" hidden><p>Making a nuclear power plant safer is not only about equipment: the upgrades affect the people who work at the plants and the communities who live around them, and those people need to be properly informed and involved. In 2021 Svitlana Chukut carried out, as a project executor, an audit of the social side of that work at SE NNEGC 'Energoatom', Ukraine's nuclear energy operator. The audit covered the company's activity on social issues — concerning its personnel and the population — during implementation of the Complex (Consolidated) Programme for improving the safety of Ukraine's nuclear power plant units and the Plan of environmental and social measures, under a research contract between Igor Sikorsky Kyiv Polytechnic Institute and Energoatom (No. D/0201.01/3011.01); the customer side was led by the research-topic head, Anatolii Melnychenko. From 27 August to 20 September 2021, the work combined the audit itself with methodological, analytical and organisational support of the sociological research. Its core was a review and analysis of whether Energoatom's management system and its system of informing and engaging stakeholders comply with Ukrainian legislation, the requirements of the European Bank for Reconstruction and Development (EBRD) and best world practice. The work also included expert analysis of the company's documentation, collection of additional data and, where needed, checks directly at nuclear power plant sites, followed by a final analysis and discussion of the results with the customer. The result was a scientific (audit) report with an executive summary in Ukrainian, Russian and English, and the signed acceptance act confirms that the works were completed in full.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Audit of management and stakeholder engagement systems, Energoatom</i> [Research project]. (2021). Energoatom.</p><div class=\"m\">Projects · 2021 · Project executor</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">GISU 'Smart Cities & Tourism Research Projects'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-32\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-32\" hidden><p>How can Ukraine's tourism keep working during a war — and rebuild afterwards? That is the question behind this GISU Alliance research on smart cities and tourism, in which Svitlana Chukut takes part for Igor Sikorsky Kyiv Polytechnic Institute. Drawing on in-depth interviews with experts, the work looks at how tourism businesses coped with the combined shocks of the pandemic and the full-scale war — money problems, closures and staff leaving — and sets out the approaches that helped: going digital, offering services remotely, tailoring offers to each traveller, and new forms such as military, solidarity and virtual tourism. The point is practical: with a lighter tax burden, clearer rules and stronger professional expertise, Ukraine's tourism can recover and come back more resilient.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>GISU &#x27;Smart cities &amp; tourism research projects&#x27;</i> [Research project]. (2021–). GISU Alliance.</p><div class=\"m\">Projects · 2021–… · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute» participant</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">GISU 'Innovative Business Strategies in Response to COVID-19 Impact on Tourism'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-33\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-33\" hidden><p>When COVID-19 stopped travel, tourism businesses had to reinvent how they work almost overnight. This GISU Alliance project (2021–2024) collected and compared the new business strategies that helped tourism through the pandemic. Its goal was a practical framework — a set of guidelines — to help tourism recover and become more resilient after COVID-19; Svitlana Chukut took part as a participant associated with Igor Sikorsky Kyiv Polytechnic Institute.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>GISU &#x27;innovative business strategies in response to COVID-19 impact on tourism&#x27;</i> [Research project]. (2021–2024). GISU Alliance.</p><div class=\"m\">Projects · 2021–2024 · Participant</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diploma, 2nd place, 'Best Educational Innovation Practices'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-34\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-34\" hidden><p>Second-place diploma from Ukraine’s National Agency on Civil Service for an educational innovation developed with Yana Tsymbalenko.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National Agency of Ukraine on Civil Service. (2021). <i>Diploma, 2nd place, &#x27;best educational innovation practices&#x27;</i> [Award record].</p><div class=\"m\">Awards · 2021 · National Agency of Ukraine on Civil Service (co-author Y. Tsymbalenko)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude as e-governance olympiad organiser</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-35\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-35\" hidden><p>Recognition from KPI for organising a student olympiad on e-governance.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2021). <i>Gratitude as e-governance olympiad organiser</i> [Award record].</p><div class=\"m\">Awards · 2021 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude as e-governance olympiad jury member</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-36\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-36\" hidden><p>Recognition from KPI for serving on the jury of an e-governance olympiad.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2021). <i>Gratitude as e-governance olympiad jury member</i> [Award record].</p><div class=\"m\">Awards · 2021 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude for mentoring a prizewinner</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-37\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-37\" hidden><p>Recognition from Vadym Hetman Kyiv National Economic University for supervising a prize-winning student project.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Vadym Hetman Kyiv National Economic University. (2021). <i>Gratitude for mentoring a prizewinner</i> [Award record].</p><div class=\"m\">Awards · 2021 · Vadym Hetman Kyiv National Economic University</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Oleksandra Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-38\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-38\" hidden><p>Student research work “Social inclusion as a determinant of the development of smart technologies” (competition code “Buty poruch”) by Oleksandra Shyts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies current trends in social inclusion as a determinant of the development of smart technologies, drawing on the best foreign and Ukrainian experience; a survey identified problems of accessibility, involvement and equality of opportunity. It analyses foreign practices and gives recommendations for Ukraine. The work was presented at the II International Scientific Conference on Scientific and Practical Technologies (Luxembourg, 2021) and the IV International Scientific-Practical Conference in Chernihiv (2021); its results are used at the Sotsioplus centre. One article in a professional journal (category B) and two international conference papers were published.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Shyts, O. (2021). <i>Social inclusion as a determinant of the development of smart technologies</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2021 · 2nd place — Diploma of the 2nd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Social inclusion as a determinant of the development of smart technologies</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Lidiia Shumska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-39\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-39\" hidden><p>Student research work “Managing smart power systems using big data: best foreign practices” (competition code “Smart power systems”) by L. Shumska, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work examines the best foreign practices of managing smart power systems using big data and the possibilities of implementing them in Ukraine. It was presented at the XI International Scientific-Practical Conference “Contemporary Problems of Management: Transformation of Public Management in the Post-COVID World”; its results were implemented at the Solomianska District State Administration in Kyiv and the Khmelnytskyi Nuclear Power Plant of Energoatom. One article and one conference paper were published.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Shumska, L. (2021). <i>Managing smart power systems using big data: Best foreign practices</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2021 · 2nd place (2022) — Diploma of the 2nd degree · Stage I · All-Ukrainian competition of student scientific works “Management of E-Business and Smart Technologies” ; 2nd place (2022) — Diploma of the 2nd degree · Stage I · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Managing smart power systems using big data: best foreign practices</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-40\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-40\" hidden><p>Student research work “Modernisation of infrastructure and transport management through the application of Internet of Things technologies” (competition code “Smart mobility”) by Anna Kruts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies the modernisation of infrastructure and transport management through the application of Internet of Things technologies. It examines the theoretical foundations of the Internet of Things in the context of e-governance, the structure of transport and infrastructure management in Ukraine, foreign experience of the Internet of Things in transport and infrastructure and current smart-mobility trends, the Ukrainian legal framework and practice, and the prospects of the Internet of Things in this sphere, and sets out conclusions and recommendations.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kruts, A. (2021). <i>Modernisation of infrastructure and transport management through the application of Internet of Things technologies</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2021 · Modernisation of infrastructure and transport management through the application of Internet of Things technologies</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">Fundamentals of Test Theory</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-41\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-41\" hidden><p>Training from Ukraine’s Ministry of Education and Science on test theory and the development and review of assessment questions. Test theory helps assessment designers examine how test questions gather evidence about the competencies being assessed.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ministry of Education and Science of Ukraine. (2021). <i>Fundamentals of test theory</i> [Training certificate].</p><div class=\"m\">Certificates · 2021 · Ministry of Education and Science of Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The formation of Ukrainian scholarly thought on the history of domestic e-governance <a href=\"https://doi.org/10.20535/2307-5244.51.2020.220187\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-42\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-42\" hidden><p>Based on a decade of scholarship across public administration, political science, economics, law, history and technical sciences, the authors characterise the current state of Ukrainian thought on the history of domestic e-governance. They map the main research directions and theoretical frameworks, and outline the gaps and controversies that still need study. The discourse is divided into six stages, from the 1990s awareness of new technologies to a sixth stage, begun in 2019, of intensive development, new theoretical models and a consolidated research base.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Drahomyretska, N., & Mykhailutsa, M. (2020). The formation of Ukrainian scholarly thought on the history of domestic e-governance. <i>Storinky Istorii</i>, (51). <a class=\"apa-source\" href=\"https://doi.org/10.20535/2307-5244.51.2020.220187\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/2307-5244.51.2020.220187</a></p><div class=\"m\">Articles · 2020 · Storinky Istorii, No. 51 (Web of Science)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>9</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diploma, 3rd place, 'Best Educational Innovation Practices' <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-43\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-43\" hidden><p>Third-place diploma from Ukraine’s National Agency on Civil Service in its educational innovation practices competition.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National Agency of Ukraine on Civil Service. (2020). <i>Diploma, 3rd place, &#x27;best educational innovation practices&#x27;</i> [Award record]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg</a></p><div class=\"m\">Awards · 2020 · National Agency of Ukraine on Civil Service</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Award for mentoring competition winners</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-44\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-44\" hidden><p>Recognition from Kyiv National University of Trade and Economics for supervising students who received competition awards.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kyiv National University of Trade and Economics. (2020). <i>Award for mentoring competition winners</i> [Award record].</p><div class=\"m\">Awards · 2020 · Kyiv National University of Trade and Economics</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Nazarii Volytskyi</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-45\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-45\" hidden><p>Student research work “Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories” by Nazarii Volytskyi and Vladyslav Trachuk, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works (3rd place).</p><p>The paper considers how essential administrative processes can continue when people have limited access to in-person services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Volytskyi, N., & Trachuk, V. (2020). <i>Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf</a></p><div class=\"m\">Supervised research · 2020 · 3rd place — Diploma of the 3rd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories ; 1st place — Diploma of the 1st degree · All-Ukrainian competition of creative works among youth for Civil Service Day (National Agency of Ukraine on Civil Service), 2020</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mariia Ruban</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-46\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-46\" hidden><p>Creative work by Mariia Ruban, prepared under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Winner of the All-Ukrainian competition of creative works among youth for Civil Service Day (National Agency of Ukraine on Civil Service), 2020 — 1st place, Diploma of the 1st degree.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Award-winning work in the civil service Day creative competition</i> [Student award record]. (2020). National Agency of Ukraine on Civil Service.</p><div class=\"m\">Supervised research · 2020 · 1st place — Diploma of the 1st degree · All-Ukrainian competition of creative works among youth for Civil Service Day (National Agency of Ukraine on Civil Service)</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Vladyslav Trachuk</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-47\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-47\" hidden><p>Student research work “Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories” by Nazarii Volytskyi and Vladyslav Trachuk, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works (3rd place).</p><p>The paper considers how essential administrative processes can continue when people have limited access to in-person services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Volytskyi, N., & Trachuk, V. (2020). <i>Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf</a></p><div class=\"m\">Supervised research · 2020 · 3rd place — Diploma of the 3rd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-48\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-48\" hidden><p>Student research work “Introducing electronic services in healthcare using Internet of Things technologies” by Anna Kruts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies the introduction of electronic services in healthcare using Internet of Things technologies. It examines the theoretical and methodological foundations of electronic services and the Internet of Things, the conceptual and legal foundations for introducing healthcare e-services in Ukraine, the best foreign practices — the Internet of Things in electronic medical services, the depersonalisation of data, the experience of the United States with electronic medical records under anonymisation of personal data and electronic medical services in the countries of the European Union — and current trends in Ukraine, including the development and implementation of the e-Health system and electronic medical information systems, and ways to improve healthcare e-services in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kruts, A. (2020). <i>Introducing electronic services in healthcare using Internet of Things technologies</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-kruts.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-kruts.pdf</a></p><div class=\"m\">Supervised research · 2020 · 3rd place — Diploma of the 3rd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Introducing electronic services in healthcare using Internet of Things technologies</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Karina Feshchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-49\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-49\" hidden><p>Student research work “Providing electronic services in the context of smart city development” by Karina Feshchenko, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work examines the provision of electronic services in the context of smart city development: Singapore’s use of electronic data, electronic services in Estonia and Denmark, Chicago’s experience and the “Kyiv Smart City” programme; it assesses the provision of electronic services at the Forum of Smart Cities of Ukraine and draws conclusions for Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Feshchenko, K. (2020). <i>Providing electronic services in the context of smart city development</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2020 · Providing electronic services in the context of smart city development</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Methodological recommendations for preparing and defending a qualification thesis <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/02/recommendation_am_qualification-work-bakalavrat.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-50\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-50\" hidden><p>A guide for Administrative Management students on preparing a qualification thesis and planning its oral defence. The guide is intended for undergraduate Administrative Management students. It sets out the stages of preparing the thesis and the expectations for writing, formatting and defending it.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ivanytska, O. M., Melnychenko, A. A., Chukut, S. A., & Bryl, Y. O. (2020). <i>Methodological recommendations for preparing and defending a qualification thesis</i>. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/0e9d12d7-bd6a-4e02-8118-4f314070e6c4\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/0e9d12d7-bd6a-4e02-8118-4f314070e6c4</a></p><div class=\"m\">Books & monographs · 2020 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Methodological recommendations on the writing, content and formatting of a qualification thesis <a href=\"https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-51\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-51\" hidden><p>The guide specifies the content, writing, formatting and defence requirements for undergraduate E-Governance qualification theses. Written for undergraduate E-Governance students, the guide distinguishes requirements for the structure and content of the thesis from the expectations for formatting and the oral defence.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Tsymbalenko, Y. Y., Arkhypova, Y. O., & Bryl, Y. O. (2020). <i>Methodological recommendations on the writing, content and formatting of a qualification thesis</i>. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93</a></p><div class=\"m\">Books & monographs · 2020 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Best European and Ukrainian e-service practices for vulnerable populations <a href=\"https://doi.org/10.32702/2306-6814.2019.5.91\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-52\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-52\" hidden><p>The article surveys EU practice in supporting people with disabilities and pensioners through electronic services — including annual monitoring of digital public services — and the projects that encourage people with limitations to use modern ICT, with Denmark's directions highlighted. Ukrainian provision is then analysed for quality and accessibility, and found legally wanting: the law sets almost no requirement to adapt e-services to vulnerable groups or to prioritise them. The authors develop the Accessibility Index of Electronic Services Use in Ukraine (AIES) to measure take-up, accessibility and quality.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Tsiptsiura, T. (2019). Best European and Ukrainian e-service practices for vulnerable populations. <i>Investytsiyi: Praktyka ta Dosvid</i>, (5), 91–97. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2019.5.91\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2019.5.91</a></p><div class=\"m\">Articles · 2019 · Investytsiyi: praktyka ta dosvid, No. 5, pp. 91–97</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>9</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-services for vulnerable citizens in Ukraine <a href=\"https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-53\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-53\" hidden><p>A round-table contribution in Vinnytsia on access to digital public services for vulnerable people in Ukraine. The central issue is whether online procedures are usable by people who face barriers involving connectivity, devices or digital skills.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2019). Implementation of electronic services in Ukraine for vulnerable groups of citizens. In S. O. Dorohykh (Ed.), <i>Information, legal, organisational and managerial support for regional innovation: Round-table proceedings</i> (pp. 124–128). Artek. <a class=\"apa-source\" href=\"https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf\" target=\"_blank\" rel=\"noopener\">https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf</a></p><div class=\"m\">Conferences · 2019 · Round table, Vinnytsia · Round-table proceedings, pp. 124–128</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">From e-government to smart governance: current challenges <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-54\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-54\" hidden><p>A plenary talk in Kyiv on the shift from e-government to using data and digital tools to improve public governance. The presentation places digital service delivery in the wider context of institutional organisation, use of information and relationships with citizens.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2019). From e-government to smart governance: Current challenges and threats. In <i>Contemporary problems of management: Governance in the context of digital transformation</i> (pp. 8–10). Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8</a></p><div class=\"m\">Conferences · 2019 · PLENARY talk. X Int. conf., Kyiv · Conference proceedings, pp. 8–10</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude of the Ministry</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-55\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-55\" hidden><p>Formal recognition from Ukraine’s Ministry of Education and Science recorded in Svitlana Chukut’s professional record.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ministry of Education and Science of Ukraine. (2019). <i>Gratitude of the Ministry</i> [Award record].</p><div class=\"m\">Awards · 2019 · Ministry of Education and Science of Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Honorary Award of the Academic Council</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-56\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-56\" hidden><p>An honorary distinction conferred by the Academic Council of Igor Sikorsky Kyiv Polytechnic Institute.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>KPI Academic Council. (2019). <i>Honorary award of the academic council</i> [Award record].</p><div class=\"m\">Awards · 2019 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Award for mentoring winners</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-57\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-57\" hidden><p>Recognition from Kyiv National University of Trade and Economics for supervising prize-winning student research in 2019.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kyiv National University of Trade and Economics. (2019). <i>Award for mentoring winners</i> [Award record].</p><div class=\"m\">Awards · 2019 · Kyiv National University of Trade and Economics</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude for competition committee work</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-58\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-58\" hidden><p>Recognition from Kyiv National University of Trade and Economics for serving on a competition committee.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kyiv National University of Trade and Economics. (2019). <i>Gratitude for competition committee work</i> [Award record].</p><div class=\"m\">Awards · 2019 · Kyiv National University of Trade and Economics</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gratitude as olympiad jury member</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-59\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-59\" hidden><p>Recognition from Igor Sikorsky Kyiv Polytechnic Institute for serving on a student olympiad jury.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2019). <i>Gratitude as olympiad jury member</i> [Award record].</p><div class=\"m\">Awards · 2019 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diploma, 2nd place, 'Best Educational Innovation Practices'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-60\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-60\" hidden><p>Second-place diploma awarded in 2019 by Ukraine’s National Agency on Civil Service in an educational innovation competition.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National Agency of Ukraine on Civil Service. (2019). <i>Diploma, 2nd place, &#x27;best educational innovation practices&#x27;</i> [Award record].</p><div class=\"m\">Awards · 2019 · National Agency of Ukraine on Civil Service</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Tetiana Tsiptsiura</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-61\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-61\" hidden><p>Student research work “Introducing electronic services for vulnerable populations: the best foreign and Ukrainian experience” by Tetiana Tsiptsiura, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works in “Public Management and Administration” (1st place). The work studies current trends in introducing electronic services for vulnerable populations, drawing on the best foreign and Ukrainian experience. It stresses that the convenience and accessibility of e-services are decisive for people with special needs and that vulnerable groups face a high risk of digital isolation. It analyses the legal framework and foreign practices, assesses the state and problems of e-service introduction in Ukraine, develops an index for calculating the accessibility of e-service use in Ukraine, and gives recommendations on implementing the best foreign experience.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Tsiptsiura, T. (2019). <i>Introducing electronic services for vulnerable populations: The best foreign and Ukrainian experience</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-tsiptsyura.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-tsiptsyura.pdf</a></p><div class=\"m\">Supervised research · 2019 · 1st place — Diploma of the 1st degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” ; 2nd place — Diploma of the 2nd degree · Stage II · All-Ukrainian student olympiad in the specialty “Public Management and Administration” (2019) — Introducing electronic services for vulnerable populations: the best foreign and Ukrainian experience</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-62\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-62\" hidden><p>Student research work “Current trends in the use of Internet of Things technologies in implementing e-governance at the local level” by Anna Kruts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works in “Public Management and Administration” (2nd place, 2019; 3rd place, 2020). The work studies current trends in applying Internet of Things technologies in implementing e-governance at the local level. It treats IoT technologies as a necessary condition for the development of smart cities and examines the theoretical and legal foundations of the Internet of Things, noting the growing threats of misuse of IoT technologies and of privacy violations.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kruts, A. (2019). <i>Current trends in the use of Internet of Things technologies in implementing e-governance at the local level</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2019 · 2nd place (2019) — Diploma of the 2nd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Current trends in the use of Internet of Things technologies in implementing e-governance at the local level</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Karina Feshchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-63\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-63\" hidden><p>Student research work “Best foreign practices of smart city development and the possibilities of their implementation in Ukraine” (competition code “Znaiemo yak!”) by Karyna Feshchenko, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work analyses the best foreign practices of smart city development and the possibilities of implementing them in Ukraine: the concept and core technologies of smart cities, the legal framework in Ukraine, the experience of Singapore, Amsterdam and Chicago, the “Kyiv Smart City” programme and the Forum of Smart Cities of Ukraine, and develops recommendations for Ukraine. Its results and recommendations can be used to improve smart city development in Ukraine, in particular in the work of the Information Technology Department of the Vinnytsia City Council. The work was presented at five conferences in 2017–2018: the scientific-practical conference “Internet of Things: Problems of Legal Regulation and Implementation” (Kyiv, 2017 and 2018), the International Scientific-Practical Conference “Contemporary Problems of Management: Imperatives for Ensuring Sustainable Development” (Kyiv, 2017), the International Scientific-Practical Conference in Poltava (2018) and the All-Ukrainian conference “Forum of Direct Democracy” (Kyiv, 2018).</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Feshchenko, K. (2019). <i>Best foreign practices of smart city development and the possibilities of their implementation in Ukraine</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-feschenko-2019.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-feschenko-2019.pdf</a></p><div class=\"m\">Supervised research · 2019 · 2nd place — Diploma of the 2nd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Best foreign practices of smart city development and the possibilities of their implementation in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">'Educational Programme Accreditation Expert' (Prometheus)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-64\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-64\" hidden><p>Training delivered through Prometheus to prepare experts to evaluate academic programmes for higher education accreditation. In quality assurance, programme evaluation considers how well a programme’s objectives, curriculum and expected learning outcomes align.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National Agency for Higher Education Quality Assurance. (2019). <i>&#x27;Educational programme accreditation expert&#x27; (prometheus)</i> [Training certificate].</p><div class=\"m\">Certificates · 2019 · National Agency for Higher Education Quality Assurance</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Blockchain or e-document management: implementation trends in Ukraine's executive bodies <a href=\"http://www.investplan.com.ua/?op=1&z=5871&i=12\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-65\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-65\" hidden><p>The article examines how electronic document circulation is being implemented in Ukraine's executive authorities, with special attention to blockchain — the modern technology of distributed registers. Chukut and Buryachenko analyse the most widespread electronic document circulation systems used by executive bodies and the principal legal acts regulating them, and consider the experience of using modern information and communication technologies in executive authorities, in particular the National Agency of Ukraine on Civil Service. They identify the main problems hindering the effective implementation of electronic document circulation systems in Ukraine and analyse modern approaches to applying blockchain technology in the development of e-governance, noting the technology's principal problems and the risks of its introduction. They conclude that introducing blockchain technologies without proper testing may produce even greater problems than the advantages claimed for their use.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Buriachenko, K. O. (2018). Blockchain or an electronic document management system: Implementation trends in Ukraine’s executive authorities. <i>Investytsiyi: Praktyka ta Dosvid</i>, (1), 70–77. <a class=\"apa-source\" href=\"https://library.wunu.edu.ua/libsearch/DocDescription?doc_id=379092\" target=\"_blank\" rel=\"noopener\">https://library.wunu.edu.ua/libsearch/DocDescription?doc_id=379092</a></p><div class=\"m\">Articles · 2018 · Investytsiyi: praktyka ta dosvid, No. 1, pp. 70–76</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>31</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Applying the 'digital by default' principle</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-66\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-66\" hidden><p>A presentation in Kyiv on the digital-by-default principle and its application in the context of information law. The topic raises questions about translating administrative procedures into digital workflows and maintaining access when an online channel becomes the default.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2018). <i>Applying the &#x27;digital by default&#x27; principle</i> [Conference presentation]. Information Law, Kyiv, Ukraine.</p><div class=\"m\">Conferences · 2018 · 'Information Law', Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance: realities and challenges</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-67\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-67\" hidden><p>An open lecture at a national student olympiad hosted by KPI on the state of e-governance and barriers to implementation. Delivered in a public administration education setting, the lecture connects digital tools with the institutional conditions and skills needed to use them.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2018). <i>E-governance: Realities and challenges</i> [Public lecture]. All-Ukrainian Olympiad, Igor Sikorsky Kyiv Polytechnic Institute, Kyiv, Ukraine.</p><div class=\"m\">Conferences · 2018 · Open lecture. All-Ukrainian olympiad, National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">'Current e-governance trends in Ukraine: best practices'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-68\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-68\" hidden><p>Ukraine was moving more and more public services online — but which approaches were actually working? Led by Svitlana Chukut, this state-registered research (2018–2020, No. 0118U100305) reviewed how e-governance — public services and procedures online — was being introduced across the country. It gathered the most successful examples ('best practices') so that other authorities could learn from what already worked.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>&#x27;Current e-governance trends in Ukraine: Best practices&#x27;</i> [Research project]. (2018–2020). Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Projects · 2018–2020 · Research supervisor · State registration No. 0118U100305</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Award for mentoring student competition winners</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-69\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-69\" hidden><p>Recognition from Kyiv National University of Trade and Economics for supervising student competition winners in 2018.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kyiv National University of Trade and Economics. (2018). <i>Award for mentoring student competition winners</i> [Award record].</p><div class=\"m\">Awards · 2018 · Kyiv National University of Trade and Economics</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Arina Kuts <a href=\"https://ktpu.kpi.ua/kuts-arina-dvichi-peremozhnitsya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-70\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-70\" hidden><p>Student research work “Transferring procurement to electronic format as an effective tool for combating corruption” by Arina Kuts, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies the transfer of procurement to electronic format as an effective tool for combating corruption. It examines the theoretical foundations of public procurement — its concept, essence, basic principles and the procurement cycle — international experience of public procurement and the architecture of electronic public procurement systems, and the functioning of the “ProZorro” electronic public procurement system as an anti-corruption instrument, together with the problems and development prospects of electronic public procurement.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kuts, A. R. (2018). <i>Transferring procurement to electronic format as an effective tool for combating corruption</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-kruts-2018.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-kruts-2018.pdf</a></p><div class=\"m\">Supervised research · 2018 · 1st place — Diploma of the 1st degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” ; 1st place — Diploma of the 1st degree · Stage II · All-Ukrainian student olympiad in the specialty “Public Management and Administration” — Transferring procurement to electronic format as an effective tool for combating corruption</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Maria Pashchak</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-71\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-71\" hidden><p>Student research work “Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine” by Maria Pashchak and Olena Plotnikova, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works (2nd place).</p><p>The study compares Chilean support for startups with Belgium’s federal services and electronic identity, then considers what could be adapted in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pashchak, M. Z., & Plotnikova, O. V. (2018). <i>Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf</a></p><div class=\"m\">Supervised research · 2018 · 2nd place — Diploma of the 2nd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Olena Plotnikova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-72\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-72\" hidden><p>Student research work “Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine” by Maria Pashchak and Olena Plotnikova, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Presented in the All-Ukrainian competition of student research works (2nd place).</p><p>The study compares Chilean support for startups with Belgium’s federal services and electronic identity, then considers what could be adapted in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pashchak, M. Z., & Plotnikova, O. V. (2018). <i>Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf</a></p><div class=\"m\">Supervised research · 2018 · 2nd place — Diploma of the 2nd degree · Stage II · All-Ukrainian competition of student scientific works in the specialty “Public Management and Administration” — Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">K. V. Prylepko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-73\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-73\" hidden><p>Student research work “Introducing electronic interaction as a necessary condition for the development of e-governance: foreign and domestic experience” by K. V. Prylepko, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies the introduction of electronic interaction as a necessary condition for the development of e-governance, drawing on foreign and domestic experience.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Prylepko, K. V. (2018). <i>Introducing electronic interaction as a necessary condition for the development of e-governance: Foreign and domestic experience</i> [Student research presentation]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-prylepko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-prylepko.pdf</a></p><div class=\"m\">Supervised research · 2018 · All-Ukrainian competition of student research works in the specialty “Public Management and Administration” — Introducing electronic interaction as a necessary condition for the development of e-governance: foreign and domestic experience</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Higher Education Standard for Specialty 281 Public Management and Administration <a href=\"https://kntu.net.ua/ukr/content/download/77869/451807/file/Наказ%20МОНУ%20№%201172%20«Про%20затвердження%20стандарту%20вищої%20освіти%20за%20спеціальністю%20281%20«Публічне%20управління%20та%20адміністрування»%20для%20першого%20(бакалаврського)%20рівня%20ВО.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-74\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-74\" hidden><p>The national standard sets out the competencies and learning outcomes expected of bachelor’s graduates in specialty 281, Public Management and Administration. The standard also establishes a framework for training and assessment. Universities can use it when developing or revising bachelor’s programmes in the discipline.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ministry of Education and Science of Ukraine. (2018, October 29). <i>Higher education standard for specialty 281 public management and administration</i> [Order No. 1172]. <a class=\"apa-source\" href=\"https://mon.gov.ua/npa/pro-zatverdzhennya-standartu-vishoyi-osviti-za-specialnistyu-281-publichne-upravlinnya-ta-administruvannya-dlya-pershogo-bakalavrskogo-rivnya-vishoyi-osviti\" target=\"_blank\" rel=\"noopener\">https://mon.gov.ua/npa/pro-zatverdzhennya-standartu-vishoyi-osviti-za-specialnistyu-281-publichne-upravlinnya-ta-administruvannya-dlya-pershogo-bakalavrskogo-rivnya-vishoyi-osviti</a></p><div class=\"m\">Books & monographs · 2018 · Ministry of Education and Science of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Interoperability as a necessary condition for the implementation of e-governance: experience of the European Union <a href=\"http://journals.maup.com.ua/index.php/public-management/article/view/587\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-75\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-75\" hidden><p>Written with Valerii Dmytrenko, the article treats interoperability as the precondition without which electronic government cannot work, at either the local or the national level. It analyses the European Union's new European Interoperability Framework and Interoperability Action Plan, adopted for the era of the single European digital market, and the tools and solutions the Union applies to make electronic services work together. Two local cases — the e-Bourgogne platform in France and the OSLO open-standards programme in Flanders — show interoperability in practice, and the article closes by mapping the European experience onto the local level in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Dmytrenko, V. (2017). Interoperability as a necessary condition for the implementation of e-governance: Experience of the European Union. <i>Public Management</i>, (5(10)), 293–303. <a class=\"apa-source\" href=\"http://journals.maup.com.ua/index.php/public-management/article/view/587\" target=\"_blank\" rel=\"noopener\">http://journals.maup.com.ua/index.php/public-management/article/view/587</a></p><div class=\"m\">Articles · 2017 · Public Management, No. 5 (10), pp. 293–303</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance development at local and regional levels</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-76\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-76\" hidden><p>Part 7 of the fifteen-part textbook \"E-Governance and E-Democracy\" (Kyiv, 2017), prepared within the EGAP programme \"E-Governance for Accountability and Participation\" with the support of the Swiss Agency for Development and Cooperation and approved by the Academic Council of the National Academy of Public Administration under the President of Ukraine. Chukut's part covers the development of e-governance at the local and regional levels: the concepts of the e-region and the e-city (\"smart city\"), the state of regional e-governance in Ukraine, the implementation experience of Lviv and Vinnytsia, and the main directions of e-governance development in Kyiv, including electronic administrative services at the local level. A second section presents best foreign practices — Australia, France, Switzerland and the United Arab Emirates. The 72-page part closes with self-check questions, recommended literature and assignments for practical classes, and is addressed to students of Public Management and Administration, civil servants and local officials in professional development, and representatives of civil-society organisations and business.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2017). E-governance development at local and regional levels. In A. I. Semenchenko & V. M. Dreshpak (Eds.), <i>E-governance and e-democracy: A textbook in 15 parts</i>. FOP Moskalenko O. M. <a class=\"apa-source\" href=\"https://library.pdpu.edu.ua/images/2018/NN/demokrat/07.pdf\" target=\"_blank\" rel=\"noopener\">https://library.pdpu.edu.ua/images/2018/NN/demokrat/07.pdf</a></p><div class=\"m\">Books & monographs · 2017 · Part 7. In: 'E-Governance and E-Democracy', a textbook in 15 parts. Kyiv: FOP Moskalenko O. M., 2017. — 72 pp. ISBN 978-966-2214-78-9</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>14</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">From the Internet of Things to Smart City: problems and prospects <a href=\"https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-77\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-77\" hidden><p>Conference paper in the proceedings \"Internet of Things: Problems of Legal Regulation and Implementation\" (scientific-practical conference, Kyiv, 24 October 2017, pp. 83–85). Against the background of continuing urbanisation — over 2.5 billion more city dwellers in the coming decades — and the spread of information and communication technologies and the Internet of Things, which improve quality of life while sharpening the problems of personal-data security, privacy and digital inequality, the paper examines current trends in smart-city development through the \"Smart Dubai\" strategy. Dubai's experience — over 100 smart initiatives and over 1,000 smart services launched by some twenty government departments and private-sector partners in under three years, and the Smart Dubai 2021 roadmap, which sets human happiness as the key indicator of success and pursues an efficient, seamless, safe and personalised city across six strategic dimensions: smart living, smart economy, smart governance, smart mobility, smart environment and smart people — is assessed as a model of the city-innovation approach based on cooperation between administrations, companies, the research community and citizens. The paper concludes that this experience can serve Ukraine, provided citizens and their needs — not developer companies — guide smart-city strategies, with account taken of each city's specific problems and advantages.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2017). Current trends in Smart City development: The \"Smart Dubai 2021\" example. In Internet of Things: Problems of Legal Regulation and Implementation (pp. 83–85). Kyiv: Polytechnic Publishing House, Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/</a></p><div class=\"m\">Conferences · 2017 · \"Internet of Things: Problems of Legal Regulation and Implementation\", Kyiv, 2017, pp. 83–85</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Letter of gratitude</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-78\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-78\" hidden><p>A formal letter of appreciation from Igor Sikorsky Kyiv Polytechnic Institute dated 2017.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2017). <i>Letter of gratitude</i> [Award record].</p><div class=\"m\">Awards · 2017 · National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">'Developing Civic Competences' (DOCCU)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-79\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-79\" hidden><p>Training from the Swiss–Ukrainian DOCCU project on civic competencies and their development through education. The project connects civic education to participation, dialogue and decision-making in public life.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Swiss–Ukrainian DOCCU project. (2017). <i>&#x27;Developing civic competences&#x27; (DOCCU)</i> [Training certificate].</p><div class=\"m\">Certificates · 2017 · Swiss-Ukrainian project</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. L. Poliarna & V. V. Riabets <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-80\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-80\" hidden><p>Student research work carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. Kyiv: National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute», 2017.</p><p>The authors compare online policing services in several European countries with the services then available in Ukraine. They propose ways to make police information and procedures more accessible online.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Poliarna, V. L., & Riabets, V. V. (2017). <i>European practices of e-service delivery in law enforcement</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf</a></p><div class=\"m\">Supervised research · 2017 · Second round of the All-Ukrainian competition of student research works in the field of sciences “Public Administration”, Sumy State University, 22–23 March 2017 — European practices of e-service delivery in law enforcement</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>15</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Arina Kuts <a href=\"https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-81\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-81\" hidden><p>Student research paper written under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor at Igor Sikorsky Kyiv Polytechnic Institute. 'Glushkov Readings' conference proceedings, 2017, p. 101.</p><p>The paper addresses where smart contracts fit in a legal framework, including recognition of commitments executed by code and the responsibilities of the parties.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kuts, A. R. (2017). Prospects for the legal regulation of smart contracts. In <i>Glushkov Readings</i> (p. 101). <a class=\"apa-source\" href=\"https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf\" target=\"_blank\" rel=\"noopener\">https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf</a></p><div class=\"m\">Supervised research · 2017 · Prospects for the legal regulation of smart contracts</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">K. V. Konashevska & O. L. Kyselova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-82\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-82\" hidden><p>Student research work “Implementing the e-democracy development experience of Japan and New Zealand in Ukraine” by K. V. Konashevska and O. L. Kyselova, carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor. The work studies the essence of electronic democracy, the international experience of implementing e-democracy in Japan and New Zealand, and the current state of e-democracy development in Ukraine, and draws conclusions on implementing this experience in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Konashevska, K. V., & Kyseliova, O. L. (2017). <i>Implementing the e-democracy development experience of Japan and New Zealand in Ukraine</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-konashevska-kiselova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-konashevska-kiselova.pdf</a></p><div class=\"m\">Supervised research · 2017 · Second round of the All-Ukrainian competition of student research works in the field of sciences “Public Administration”, Sumy State University, 22–23 March 2017 — Implementing the e-democracy development experience of Japan and New Zealand in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Draft higher education standard of Ukraine, master’s level (281) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-83\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-83\" hidden><p>The 2017 draft standard sets out master’s-level competencies and learning outcomes in Public Management and Administration. The document also covers programme credits, graduate assessment and internal quality assurance. Its draft status places these proposals in the standard-setting process.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Ministry of Education and Science of Ukraine. (2017). <i>Draft higher education standard of Ukraine, master’s level (281)</i>. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf</a></p><div class=\"m\">Books & monographs · 2017 · Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-parliament in Ukraine in light of current world trends</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-84\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-84\" hidden><p>The study examines how an electronic parliament is being introduced in Ukraine in line with current world trends. It analyses the structure of the information published on the Verkhovna Rada portal and its completeness against the recommendations of specialists of the Global Centre for Information and Communication Technologies in Parliament. On that basis it identifies the main priorities and problems in developing Ukraine's e-parliament.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2016). E-parliament in Ukraine in light of current world trends. <i>State and Regions. Public Administration</i>, (1(53)), 133–137.</p><div class=\"m\">Articles · 2016 · State and Regions. Public Administration, No. 1 (53), pp. 133–137</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>22</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance implementation in the UAE: specifics <a href=\"http://www.investplan.com.ua/?op=1&z=4986&i=19\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-85\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-85\" hidden><p>The article studies the Emirates' experience of implementing e-governance and whether it can be applied in Ukraine, analysing the strategic foundations of the process from 2001 to 2016 and its main directions. It finds that successful state policy carried the UAE into the group of countries with a high e-government development index, and examines the principles of e-service provision to citizens. Particular attention goes to the national identification system — the introduction of ID cards and their protection — and to the country's best e-city practices.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Shuliak, M. (2016). E-governance implementation in the UAE: Specifics. <i>Investytsiyi: Praktyka ta Dosvid</i>, (8), 92–95. <a class=\"apa-source\" href=\"http://www.investplan.com.ua/?op=1&amp;z=4986&amp;i=19\" target=\"_blank\" rel=\"noopener\">http://www.investplan.com.ua/?op=1&amp;z=4986&amp;i=19</a></p><div class=\"m\">Articles · 2016 · Investytsiyi: praktyka ta dosvid, No. 8, pp. 92–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>29</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Best e-service practices in the UAE: analysis <a href=\"http://www.dy.nayka.com.ua/?op=1&z=962\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-86\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-86\" hidden><p>Drawing on the United Nations e-government surveys from 2003 to 2014, the article tracks how the Emirates' online services matured — including the sharp 2010 fall in its index, which it attributes to a change in the UN's calculation methodology rather than to a real decline. It examines the government's response, above all the 2010 national agenda \"UAE Vision 2021\" and the launch of a dedicated e-services portal, and reviews the services citizens and businesses actually use, from Emirates ID cards and university admission to driving licences and medical services. The authors conclude that this experience follows the leading worldwide trends in electronic service delivery.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Shuliak, M. (2016). Best e-service practices in the UAE: Analysis. <i>Derzhavne Upravlinnia</i>, (4). <a class=\"apa-source\" href=\"http://www.dy.nayka.com.ua/?op=1&amp;z=962\" target=\"_blank\" rel=\"noopener\">http://www.dy.nayka.com.ua/?op=1&amp;z=962</a></p><div class=\"m\">Articles · 2016 · Derzhavne upravlinnia, No. 4</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Best European e-governance practices: the Danish experience <a href=\"http://www.investplan.com.ua/?op=1&z=5314&i=28\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-87\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-87\" hidden><p>The article traces the stages of e-governance development in the Kingdom of Denmark, from the 2002–2007 e-government programme to the Joint Public Digital Strategy 2011–2016, and assesses its current state and prospects. It identifies three main directions: the move to electronic document flow, electronic welfare, and electronic cooperation between citizens, state authorities at all levels and local self-government, alongside mechanisms of online public participation in government decisions. It concludes that the Danish experience matches current world trends and offers recommendations for applying it in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Poliarna, V. (2016). Best European e-governance practices: The Danish experience. <i>Investytsiyi: Praktyka ta Dosvid</i>, (24), 140–145. <a class=\"apa-source\" href=\"http://www.investplan.com.ua/?op=1&amp;z=5314&amp;i=28\" target=\"_blank\" rel=\"noopener\">http://www.investplan.com.ua/?op=1&amp;z=5314&amp;i=28</a></p><div class=\"m\">Articles · 2016 · Investytsiyi: praktyka ta dosvid, No. 24, pp. 140–145</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-service priorities in the EU: the Danish case <a href=\"http://www.dy.nayka.com.ua/?op=1&z=1015\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-88\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-88\" hidden><p>Using the United Nations e-government surveys from 2003 to 2016, the article follows Denmark's online services through their indices and maturity stages, including the marked 2014 drop that cost the country places in the world ranking. It examines the policy framework behind the system — the 2011 joint public digital strategy and the digital welfare strategy for 2013–2020 — and the infrastructure citizens and businesses actually use: the Borger.dk portal, the NemID digital signature, and the NemHandel e-invoicing system that is mandatory for suppliers to public authorities. The authors conclude that the Danish experience follows the leading worldwide trends and can be drawn on in Ukraine, pointing in particular to the Digitalisér.dk platform for sharing digitisation knowledge.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Poliarna, V. (2016). E-service priorities in the EU: The Danish case. <i>Derzhavne Upravlinnia</i>, (4). <a class=\"apa-source\" href=\"http://www.dy.nayka.com.ua/?op=1&amp;z=1015\" target=\"_blank\" rel=\"noopener\">http://www.dy.nayka.com.ua/?op=1&amp;z=1015</a></p><div class=\"m\">Articles · 2016 · Derzhavne upravlinnia, No. 4</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>23</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-parliament development in Ukraine in current world context</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-89\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-89\" hidden><p>This chapter compares Ukraine’s development of an electronic parliament with international practice. It examines access to parliamentary information, transparency and opportunities for public participation. The chapter places these tools in the operation of a legislature and its relationship with the public. It is relevant to readers studying how parliamentary institutions modernise.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Lutsuk, L. (2016). E-parliament development in Ukraine in current world context. In O. A. Ivakin & D. V. Yakovlev (Eds.), <i>Time of Choice: Challenges of the Information Era</i> (pp. 360–371). Helvetyka Publishing House.</p><div class=\"m\">Books & monographs · 2016 · Chapter in the collective monograph 'Time of Choice: Challenges of the Information Era', edited by O. A. Ivakin and D. V. Yakovlev. Odesa: Helvetyka Publishing House, 2016, pp. 360–371</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">'The impact of e-governance on social transformations'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-90\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-90\" hidden><p>Does putting government online actually change how society works? Led by Svitlana Chukut (2016–2018, state registration No. 0115U000019), the research examined two examples: Ukraine's e-parliament (the online work and published information of the Verkhovna Rada, the national parliament) compared with world practice, and 'smart city' ideas for running local services digitally. It ended with practical recommendations for fixing the problems it found, for use by Ukrainian and local authorities.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>&#x27;The impact of e-governance on social transformations&#x27;</i> [Research project]. (2016–2018). Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Projects · 2016–2018 · Research supervisor · State registration No. 0115U000019, 2016–2018</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Smart city or e-city: modern approaches to understanding the implementation <a href=\"https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&I21DBN=UJRN&IMAGE_FILE_DOWNLOAD=0&Image_file_name=PDF%2Fipd_2016_13_17.pdf&P21DBN=UJRN&Z21ID=\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-91\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-91\" hidden><p>The article sets the two terms side by side and asks what each one actually means for local government. It distinguishes two readings of the \"smart city\": a corporate one, promoted by large IT companies to sell products and automate every urban process, and a sustainable-development one, in which technology serves residents' quality of life across all spheres of city life. Against the first it weighs the risks — loss of privacy, total control over citizens and the devaluation of public participation in decisions — and illustrates both readings with foreign and Ukrainian practice. It closes with the main problems holding back local e-governance in Ukraine and the possibilities for overcoming them.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Dmytrenko, V. (2016). Smart city or e-city: Modern approaches to understanding the implementation. <i>Investments: Practice and Experience</i>, (13), 89–93. <a class=\"apa-source\" href=\"https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&amp;I21DBN=UJRN&amp;IMAGE_FILE_DOWNLOAD=0&amp;Image_file_name=PDF%2Fipd_2016_13_17.pdf&amp;P21DBN=UJRN&amp;Z21ID=\" target=\"_blank\" rel=\"noopener\">https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&amp;I21DBN=UJRN&amp;IMAGE_FILE_DOWNLOAD=0&amp;Image_file_name=PDF%2Fipd_2016_13_17.pdf&amp;P21DBN=UJRN&amp;Z21ID=</a></p><div class=\"m\">Articles · 2016 · Investments: practice and experience, №13, pp. 89–93</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>183</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The state of public administration of the information sphere in Ukraine <a href=\"http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-92\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-92\" hidden><p>The chapter surveys how Ukraine's information sphere was governed at the turn of the 2000s and where that governance was failing. It documents the pressure on independent media — censorship attempts, selective state support and punitive damages claims — that drew concern from the Council of Europe, and backs the picture with the period's statistics: more than 10,000 registered periodicals, of which only about 6,500 actually appeared; book output down to 0.3 copies per capita; and 791 television and radio organisations operating on 931 licences, most of them loss-making. It concludes that a stable national television and radio space depends above all on the state of the economy and on sound legislation giving all information actors equal rules.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2016). The state of public administration of the information sphere in Ukraine. <i>State Information Policy of Ukraine</i>. <a class=\"apa-source\" href=\"http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf\" target=\"_blank\" rel=\"noopener\">http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf</a></p><div class=\"m\">Articles · 2016 · State Information Policy of Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Comparative analysis of Internet use in European Union countries <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-93\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-93\" hidden><p>A comparative snapshot of Internet use across the European Union at the turn of the 2000s, built on European Commission statistics from 1999–2001 and framed by the Council of Europe's 1999 Budapest declaration on new information technologies. It compares the member states on citizens' use of government pages, Internet access at schools and universities and searches for medical information, then traces institutional uptake between 1999 and 2001 — users, workplace access, organisations online and intranets — across ten countries. It closes with the human profile of the early European Internet: where people connected, what they used it for, why a third of Europeans stayed offline, and how telework was spreading.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2016). Comparative analysis of Internet use in European Union countries. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf</a></p><div class=\"m\">Articles · 2016</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Implementing e-governance amid network warfare</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-94\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-94\" hidden><p>Written as Russia's war against Ukraine was unfolding, the article examines what network warfare does to a state that is simultaneously trying to govern electronically. It identifies the most exposed components of e-government and e-democracy — state information resources and databases, citizens' personal data, including those of residents of the occupied territories and anti-terrorist operation participants, and any electronic service that requires personal identification — and shows how social networks, public polls and some civic organisations can be turned against national security. Its prescription is sequenced: build a national electronic identification system to European eIDAS standards, protect information and personal data, and block the destructive channels, keeping the balance between security and privacy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2016). Implementing e-governance amid network warfare. <i>'Public Management and Administration', Kyiv</i>, (1).</p><div class=\"m\">Articles · 2016 · 'Public Management and Administration', Kyiv, No. 1</div><div class=\"publication-translations policy-document-actions\" role=\"group\" aria-label=\"Read the translation\"><a class=\"text-link\" href=\"article-translations/network-warfare-en.html\" lang=\"en\" hreflang=\"en\">English</a><a class=\"text-link\" href=\"article-translations/network-warfare-fr.html\" lang=\"fr\" hreflang=\"fr\">Français</a></div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">How e-governance transforms the role of the state</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-95\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-95\" hidden><p>A presentation in Kyiv on how e-governance changes the role of the state and its relationship with society. The topic links changes in administrative processes to questions of public accountability, access to information and citizen participation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2015). <i>How e-governance transforms the role of the state</i> [Conference presentation]. The State and Global Social Change, Kyiv, Ukraine.</p><div class=\"m\">Conferences · 2015 · 'The State and Global Social Change', Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">How e-governance impacts decentralisation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-96\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-96\" hidden><p>The paper examines how e-governance relates to decentralisation, with attention to the role of local authorities in delivering public services. The paper places digital tools in the context of responsibilities shared across central and local government. It raises the question of how to coordinate services when responsibilities span several levels.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2015). How e-governance impacts decentralisation. In A. A. Melnychenko & I. V. Vyselko (Eds.), <i>Proceedings of the VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation'</i> (pp. 181–182). TOV NVP Interservis.</p><div class=\"m\">Conferences · 2015 · Proceedings of the VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 181–182</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">EGAP 'E-governance for accountability and community participation' (Switzerland)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-97\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-97\" hidden><p>EGAP is the Swiss-Ukrainian programme ‘E-Governance for Accountability and Participation’, implemented by East Europe Foundation with the support of Switzerland to make government more accountable and to widen citizen participation through digital tools. Its first phase ran from 2015 to 2019. Citizens trust government more when they can see how decisions are made and take part in them. EGAP — 'E-Governance for Accountability and Community Participation' — is a Swiss-Ukrainian programme, run by the East Europe Foundation, that used digital tools to open up government and involve communities. Svitlana Chukut joined the programme as an expert in November 2015. In its training component (Component 2) — which studied and generalised the best international and national experience and developed the training documentation on that basis, trained trainers and gave methodological and consultative help to those organising and running classes for state servants and local-government officials, and built the capacity of executive bodies, local self-government and citizens to use e-governance and e-democracy tools — her expert task in 2016 was to help create a national training course on e-governance and e-democracy for civil servants and local-government officials. She co-authored the curriculum of an elective university discipline on the subject (the study and work programme texts; 40 hours in total, her personal contribution 20 hours) and prepared ready-to-teach materials for two themes of the course documentation set, each with theory, practical and seminar guidance, test tasks, a glossary and recommended literature: Theme 7, 'Monitoring, evaluation and forecasting of the development of the e-governance system', and Theme 8, 'Development of electronic governance at the regional and local levels', co-authored with V. M. Dreshpak. The final products were delivered to the working-group head and the Component 2 coordinator, so officials across Ukraine get one national course and ready teaching materials on e-governance and e-democracy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>EGAP programme. (2015–2017). <i>EGAP &#x27;e-governance for accountability and community participation&#x27; (switzerland)</i> [Research project].</p><div class=\"m\">Projects · 2015–2017 · Expert</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ya. A. Braiko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-98\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-98\" hidden><p>Student conference paper by Ya. A. Braiko on electronic services in Australia, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Australian case provides a point of comparison for examining how access to public services is organised online and what makes those services usable.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Braiko, Y. A. (2015). Electronic services in Australia. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 89–90).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 89–90 — Electronic services in Australia</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">I. A. Buzmakova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-99\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-99\" hidden><p>Student conference paper by I. A. Buzmakova on implementing e-governance as a way to improve management and service delivery, on the experience of India, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Indian example connects the modernisation of administrative processes with citizens’ access to public services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Buzmakova, I. A. (2015). Implementing e-governance as a way to improve management and service delivery: The experience of India. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 90–92).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 90–92 — Implementing e-governance as a way to improve management and service delivery: The experience of India</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-100\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-100\" hidden><p>Student conference paper by B. V. Viskushchenko on the impact of e-governance on citizens' trust in public authorities, presented at the XIII International Scientific-Practical Conference 'Creativity in Philosophical Dimensions' (Kyiv, 14–15 May 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper examines the relationship between people’s experience of digital services and their trust in institutions, an issue also shaped by how government communicates with the public.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Viskushchenko, B. V. (2015). <i>The impact of e-governance on citizens&#x27; trust in public authorities</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2015 · XIII International Scientific-Practical Conference 'Creativity in Philosophical Dimensions', Kyiv, 14–15 May 2015 — The impact of e-governance on citizens' trust in public authorities</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-101\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-101\" hidden><p>Student conference paper by B. V. Viskushchenko on the advantages of online government activity, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The topic concerns the use of digital channels to make public information easier to access and simplify interaction with government.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Viskushchenko, B. V. (2015). Advantages of online government activity. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 92–93).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 92–93 — Advantages of online government activity</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Kh. O. Kapitan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-102\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-102\" hidden><p>Student conference paper by Kh. O. Kapitan on the formation and development of the electronic customs of Ukraine, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper places customs digitisation in the development of declaration procedures and the handling of administrative information.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kapitan, K. O. (2015). Formation and development of the electronic customs of Ukraine. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 99–100).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 99–100 — Formation and development of the electronic customs of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">T. V. Kvasha</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-103\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-103\" hidden><p>Student conference paper by T. V. Kvasha on the advantages of electronic services in government–citizen interaction, presented at the XVIII All-Ukrainian Conference of Students and Postgraduates 'Days of Science' (Kyiv, 22–23 April 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The analysis considers what online procedures change for residents, including access to information and the ability to interact with government remotely.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kvasha, T. V. (2015). Advantages of electronic services in government–citizen interaction. In <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (pp. 150–151).</p><div class=\"m\">Supervised research · 2015 · XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates 'Days of Science', Kyiv, 22–23 April 2015, pp. 150–151 — Advantages of electronic services in government–citizen interaction</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. S. Kvitkovska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-104\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-104\" hidden><p>Student conference paper by V. S. Kvitkovska on the development of e-governance in Singapore as an example for Ukraine, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>Singapore provides a case for examining which elements of digital government could be adapted by Ukrainian institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kvitkovska, V. S. (2015). Development of e-governance in Singapore as an example for Ukraine. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 102–104).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 102–104 — Development of e-governance in Singapore as an example for Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Kokhan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-105\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-105\" hidden><p>Student conference paper by O. A. Kokhan on using benchmarking technology in e-governance in Ukraine, presented at the XVIII All-Ukrainian Conference of Students and Postgraduates 'Days of Science' (Kyiv, 22–23 April 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The topic connects benchmarking with the assessment of government practices, focusing on how services can be compared before selecting improvements.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kokhan, O. A. (2015). Using benchmarking technology in e-governance in Ukraine. In <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (pp. 168–169).</p><div class=\"m\">Supervised research · 2015 · XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates 'Days of Science', Kyiv, 22–23 April 2015, pp. 168–169 — Using benchmarking technology in e-governance in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">H. O. Kulikova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-106\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-106\" hidden><p>Student conference paper by H. O. Kulikova on the best world practices of e-governance, on the example of Norway, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Norwegian case broadens the comparison of institutional choices and delivery arrangements that underpin digital government.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kulikova, H. O. (2015). Best world practices of e-governance: Norway. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 104–105).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 104–105 — Best world practices of e-governance: Norway</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Petrakovych</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-107\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-107\" hidden><p>Student conference paper by O. A. Petrakovych on London as an example of an electronic city for Ukraine, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>London provides a case for considering how a municipality can organise access to services and information across a city.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Petrakovych, O. A. (2015). London as an example of an electronic city for Ukraine. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 107–109).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 107–109 — London as an example of an electronic city for Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. L. Poliarna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-108\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-108\" hidden><p>Student conference paper by V. L. Poliarna on e-governance as an indicator of successful public administration, on the experience of Denmark, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Danish experience is used to examine the relationship between the maturity of online services and the ability of government to deliver them.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Poliarna, V. L. (2015). E-governance as an indicator of successful public administration: The experience of denmark. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 111–112).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 111–112 — E-governance as an indicator of successful public administration: The experience of Denmark</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. V. Tivonenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-109\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-109\" hidden><p>Student conference paper by A. V. Tivonenko on decentralisation and its impact on the development of e-governance in Ukraine, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper considers how responsibilities are distributed across levels of government and what that means for coordinating online services in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Tivonenko, A. V. (2015). Decentralisation and its impact on the development of e-governance in Ukraine. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 112–114).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 112–114 — Decentralisation and its impact on the development of e-governance in Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. S. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-110\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-110\" hidden><p>Student conference paper by A. S. Umanska on electronic government as an effective mechanism for combating corruption, presented at the XVIII All-Ukrainian Conference of Students and Postgraduates 'Days of Science' (Kyiv, 22–23 April 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper addresses transparency in digital procedures and how traceable decisions can support corruption prevention.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Umanska, A. S. (2015). Electronic government as an effective mechanism for combating corruption. In <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (pp. 161–162).</p><div class=\"m\">Supervised research · 2015 · XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates 'Days of Science', Kyiv, 22–23 April 2015, pp. 161–162 — Electronic government as an effective mechanism for combating corruption</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-111\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-111\" hidden><p>Student conference paper by A. M. Chorna on introducing electronic commerce for public procurement, presented at the VIII International Scientific-Practical Conference 'Contemporary Problems of Management' (Kyiv, 10 December 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The study connects e-commerce tools with the public procurement process, from publishing a call for tenders to submitting bids.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chorna, A. M. (2015). Introducing electronic commerce for public procurement. In <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (pp. 114–115).</p><div class=\"m\">Supervised research · 2015 · VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation', Kyiv, 10 December 2015, pp. 114–115 — Introducing electronic commerce for public procurement</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-112\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-112\" hidden><p>Student conference paper by A. M. Chorna on the prospects of foresight research in implementing e-governance, presented at the XVIII All-Ukrainian Conference of Students and Postgraduates 'Days of Science' (Kyiv, 22–23 April 2015), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper situates foresight in digital government planning, where institutions must account for changes in technology and users’ needs.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chorna, A. M. (2015). Prospects of foresight research in implementing e-governance. In <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (pp. 178–179).</p><div class=\"m\">Supervised research · 2015 · XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates 'Days of Science', Kyiv, 22–23 April 2015, pp. 178–179 — Prospects of foresight research in implementing e-governance</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Modern warfare, the network society and crowd psychology <a href=\"https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-113\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-113\" hidden><p>Conference theses applying Serge Moscovici's theory of the crowd to Russia's war against Ukraine in 2013–2014. Chukut restates the theory's postulates — the crowd as a psychic community acting unconsciously, its conservatism and need of a leader, propaganda's irrational basis, and the role of a higher idea turned into collective images — and shows how Russian propaganda built its \"fascist\" framing over a decade, from the 2004 campaign to the Revolution of Dignity, the occupation of Crimea and the invasion of the mainland. In a network society, she argues, television, radio, print, online media and social networks act synergistically on mass consciousness through overlay and projection, and simplified, endlessly repeated idea-images (\"Kyiv junta\", \"fascists\", \"punishers\") trigger behaviour automatically. The Maidan, she notes, was not a crowd but a community of like-minded individuals, which is why the weapon failed in Kyiv; as a counter-example she cites Serhiy Loiko's Tolkien imagery (\"Mordor\", \"orcs\") in the October 2014 Echo of Moscow interview, removed from the station's site by Roskomnadzor. Modern war, she concludes, is fought with information weapons as much as with armies, and Ukraine can use them offensively as well as in defence.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2014). Modern warfare, the network society and crowd psychology. <i>Plenary talk, 'Great Wars, Great Transformations' Conference, Kyiv</i>. <a class=\"apa-source\" href=\"https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf\" target=\"_blank\" rel=\"noopener\">https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf</a></p><div class=\"m\">Conferences · 2014 · PLENARY talk. 'Great Wars, Great Transformations', Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance implementation amid network warfare</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-114\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-114\" hidden><p>Conference theses in which Chukut asks what e-governance becomes under the network war Russia is waging against Ukraine. She recalls the positive steps of 2014 — the creation of the State Agency for E-Governance Development and the draft Green Paper on e-governance in Ukraine — and sets them against the nature of network war as defined by its Russian ideologue Alexander Dugin: destroying a people's fundamental ideas of their culture, society and state so as to sow fear, disorientation and chaos, reorient and then destroy traditional spiritual and cultural values, and establish control without direct occupation, through integrated physical, informational, cognitive and social efforts in which the information component leads. Against this background, she warns, the Green Paper's e-democracy instruments — collecting signatures and petitions, appeals, consultations, questionnaires, electronic voting — can produce the opposite effect: she cites the Le Figaro poll on selling the Mistrals to Russia, falsified by mass automated voting (of some 260,000 respondents, 180,000 came from robot-like IP addresses, most of them Russian). Particular risks attach to electronic interaction between state and local authorities, where IT companies with a \"Russian trace\" may be involved; to electronic services, which require a national electronic identification system; and to the protection and content of the databases state bodies create. She poses the unresolved balance — state security against privacy, e-democracy's development against victory in the network war — and concludes that Ukraine's task is to use e-governance's advantages for victory while shielding its most vulnerable components from foreign interference: better to move more slowly, but in the right direction.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2014). E-governance implementation amid network warfare. <i>'V. Hlushkov, Cybernetics Pioneer', Kyiv</i>.</p><div class=\"m\">Conferences · 2014 · 'V. Hlushkov, Cybernetics Pioneer', Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Yu. S. Bielik</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-115\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-115\" hidden><p>Student conference paper by Yu. S. Bielik on the experience of implementing e-governance in Sweden, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Swedish case provides a point of comparison for studying institutional arrangements and digital public service delivery.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Bielik, Y. S. (2014). Experience of implementing e-governance in sweden. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 80–82).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 80–82 — Experience of implementing e-governance in Sweden</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-116\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-116\" hidden><p>Student conference paper by B. V. Viskushchenko on implementing e-governance in foreign countries, on the example of Ireland, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Irish case makes it possible to compare one country’s approach to modernising government with implementation needs and conditions in Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Viskushchenko, B. V. (2014). Implementing e-governance in foreign countries: The example of ireland. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 83–84).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 83–84 — Implementing e-governance in foreign countries: The example of Ireland</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. V. Volodin</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-117\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-117\" hidden><p>Student conference paper by O. V. Volodin on introducing the e-archive as a management factor in e-governance, presented at the Scientific-Practical Conference 'Modern Challenges for the Social Sciences in the Context of Globalisation' (Lviv, 30–31 May 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The study situates digital archives within the public records lifecycle and connects their organisation with government’s ability to preserve and retrieve information.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Volodin, O. V. (2014). Introducing the e-archive as a management factor in e-governance. In <i>Scientific-Practical Conference &#x27;Modern Challenges for the Social Sciences in the Context of Globalisation&#x27;</i> (pp. 35–37).</p><div class=\"m\">Supervised research · 2014 · Scientific-Practical Conference 'Modern Challenges for the Social Sciences in the Context of Globalisation', Lviv, 30–31 May 2014, pp. 35–37 — Introducing the e-archive as a management factor in e-governance</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. V. Volodin</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-118\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-118\" hidden><p>Student conference paper by O. V. Volodin on social design as a component of socio-engineering activity in organisational management, presented at the international scientific-practical conference of the International Scientific Forum (Kyiv, 8 May 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The topic connects the design of social interventions with how organisations operate and how they define management problems.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Volodin, O. V. (2014). Social design as a component of socio-engineering activity in organisational management. In <i>International Scientific-Practical Conference &#x27;International Scientific Forum: Science and Practice in the Modern World&#x27;</i> (pp. 5–9).</p><div class=\"m\">Supervised research · 2014 · International Scientific-Practical Conference 'International Scientific Forum: Science and Practice in the Modern World', Kyiv, 8 May 2014, pp. 5–9 — Social design as a component of socio-engineering activity in organisational management</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">T. Kvasha</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-119\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-119\" hidden><p>Student conference paper by T. Kvasha on the Internet as a tool of communication between government and citizens, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper examines the internet as a channel for both public information and dialogue, with implications for citizen participation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kvasha, T. (2014). The Internet as a tool of communication between government and citizens. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 99–101).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 99–101 — The Internet as a tool of communication between government and citizens</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Kokhan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-120\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-120\" hidden><p>Student conference paper by O. A. Kokhan on information surplus and the technologies of its creation in the modern information space, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The topic concerns the mechanisms that increase the amount of available information and the challenges of selecting and interpreting it.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Kokhan, O. A. (2014). Information surplus and the technologies of its creation in the modern information space. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 200–202).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 200–202 — Information surplus and the technologies of its creation in the modern information space</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">N. A. Saukh</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-121\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-121\" hidden><p>Student conference paper by N. A. Saukh on the activities of civil society organisations in the development of electronic democracy, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The paper considers civil society organisations as actors that help citizens express their views and engage with public institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Saukh, N. A. (2014). Activities of civil society organisations in the development of electronic democracy. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 122–124).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 122–124 — Activities of civil society organisations in the development of electronic democracy</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-122\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-122\" hidden><p>Student conference paper by A. Umanska on the e-governance system in the Kingdom of Bahrain, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>Bahrain extends the international comparison of digital government strategies and the organisation of online services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Umanska, A. (2014). The e-governance system in the kingdom of bahrain. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 125–126).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 125–126 — The e-governance system in the Kingdom of Bahrain</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. S. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-123\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-123\" hidden><p>Student conference paper by A. S. Umanska on democratic governance and information and communication technologies — their key concepts — presented at the International Scientific-Practical Conference on Sociology 'Great Wars, Great Transformations' (Kyiv, 27–28 November 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The conceptual framework connects information and communication technologies with questions of participation, transparency and democratic governance.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Umanska, A. S. (2014). <i>Democratic governance and information and communication technologies: Key concepts</i> [Student research paper]. Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Supervised research · 2014 · International Scientific-Practical Conference on Sociology 'Great Wars, Great Transformations: Historical Sociology of the 20th Century, 1914–2014', Kyiv, 27–28 November 2014 — Democratic governance and information and communication technologies: Key concepts</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-124\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-124\" hidden><p>Student conference paper by A. M. Chorna on implementing e-governance in foreign countries, on the example of Australia, presented at the All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics' (Kyiv, 2014), carried out under the scientific supervision of S. A. Chukut, Doctor of Sciences in Public Administration, Professor.</p><p>The Australian example provides a framework for comparing the institutional arrangements that make online public services possible.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chorna, A. M. (2014). Implementing e-governance in foreign countries: The example of Australia. In <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (pp. 129–130).</p><div class=\"m\">Supervised research · 2014 · All-Ukrainian Scientific-Practical Conference 'V. M. Glushkov — Pioneer of Cybernetics', Kyiv, 2014, pp. 129–130 — Implementing e-governance in foreign countries: The example of Australia</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Trends and problems of e-governance implementation in Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-125\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-125\" hidden><p>Conference theses in which Chukut frames e-governance as the answer to a worldwide deficit of trust between citizens and government: the global network creates sustainable feedback and interactive interaction, and e-democracy — a core component of e-governance — serves citizens' needs while countering corruption, bureaucratisation and formalism. She restates the OECD criteria for building e-government and its working principles — services at any time (24/7), maximal simplicity and transparency for ordinary citizens, common technical standards and interoperability, confidentiality and information security, and unconditional orientation to citizens' opinion — and surveys Ukraine's current development: electronic document flow with digital signature, administrative service centres and the \"single window\", and sectoral e-governance from telemedicine and distance education to the courts. She closes by outlining seven problem blocks: interoperability, national security, national identity, economic security, privacy protection (warning of an Orwellian outcome if personal-data rules fail), responsibility, and force majeure — arguing that the most critical services should keep a 70–80 percent electronic share rather than going fully electronic.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2013). Trends and problems of e-governance implementation in Ukraine. <i>VII International Conference 'Contemporary Problems of Management', Kyiv</i>.</p><div class=\"m\">Conferences · 2013 · VII Int. conf. 'Contemporary Problems of Management', Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>30</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Programme and organising committees member <a href=\"https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-126\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-126\" hidden><p>Service on the programme and organising committees of the Contemporary Problems of Management conference at Igor Sikorsky Kyiv Polytechnic Institute. The role contributes to coordinating a scholarly forum for research on management and public administration.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Igor Sikorsky Kyiv Polytechnic Institute. (2013–). <i>Programme and organising committees member</i> [Conference record]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/</a></p><div class=\"m\">Conferences · 2013–… · Int. conf. 'Contemporary Problems of Management', National Technical University of Ukraine «Igor Sikorsky Kyiv Polytechnic Institute»</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The Impact of E-Governance on Societal Transformations</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-127\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-127\" hidden><p>Can digital government change society for the better — and what gets in the way? From 2013 to 2017, an initiative research theme led by Svitlana Chukut at the Faculty of Sociology and Law of Kyiv Polytechnic (Department of Theory and Practice of Management) studied that question on three fronts. First, the e-parliament: the team analysed how e-parliament is being introduced in Ukraine against current world trends, checking the structure and completeness of the information on the Verkhovna Rada portal against the recommendations of the Global Centre for ICT in Parliament, and identified the priorities and the problems. An e-parliament is a legislature empowered by ICT to be more open, transparent and accountable, and Ukraine's level matches international trends; the main obstacles are citizens' poor awareness of what the e-parliament offers and weak coordination between the legislative and executive branches. The work also stressed mobile applications — for simpler access to information and services, and for monitoring public opinion. Second, smart cities: the team studied modern approaches to the concepts of 'smart city' and 'e-city' in local e-governance — one approach, promoted by large IT companies, aims at automating all city processes, while the other, set in the frame of sustainable development, uses ICT in every sphere of city life to improve residents' quality of life — and named the threats of excessive enthusiasm for smart-city technologies: risks to privacy, total control over citizens, and the devaluation of citizen participation in decision-making. Third, the local level: Ukrainian and foreign practices of e-governance development at the local level were analysed, the main problems slowing local e-governance in Ukraine were identified, and recommendations for overcoming them were developed. The results were implemented in the teaching process; the theme produced 5 articles in journals indexed in scientometric databases and 5 in professional journals from the list of the Ministry of Education and Science of Ukraine, 22 conference presentations (18 of them at international conferences), involved 17 students, and 10 master's theses were prepared and defended. The results can be used by the Verkhovna Rada of Ukraine, the State Agency for E-Governance Development, the Ministry of Economic Development, local state administrations and local self-government bodies, and in teaching specialty 074 'Public Management and Administration'.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>The impact of e-Governance on societal transformations</i> [Research project]. (2013–2017). Igor Sikorsky Kyiv Polytechnic Institute.</p><div class=\"m\">Projects · 2013–2017 · Initiative research theme — Faculty of Sociology and Law, Department of Theory and Practice of Management; research supervisor · State registration No. 0115U000019 (2016–2018)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Copyright certificate No. 42281: 'E-governance: concept, methodology, tools and programmes'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-128\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-128\" hidden><p>Copyright certificate No. 42281 covers a work on e-governance concepts, methods, tools and programmes prepared with Olha Zahvoiska. The record identifies the document and its co-authors. The four elements in its title indicate its scope, from conceptual foundations to implementing e-governance programmes.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Zahvoiska, O. V. (2012). <i>E-governance: Concept, methodology, tools and programmes</i> [Copyright certificate No. 42281].</p><div class=\"m\">Books & monographs · 2012 · Copyright certificate</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance development trends and implementation risks</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-129\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-129\" hidden><p>Conference theses in which Chukut frames e-governance as the answer to a worldwide deficit of trust between citizens and government: the global network creates sustainable feedback and interactive interaction, and e-democracy — a core component of e-governance — serves citizens' needs while countering corruption, bureaucratisation and formalism. She restates the OECD criteria for building e-government and its working principles — services at any time (24/7), maximal simplicity and transparency for ordinary citizens, common technical standards and interoperability, confidentiality and information security, and unconditional orientation to citizens' opinion — and surveys Ukraine's current development: electronic document flow with digital signature, administrative service centres and the \"single window\", and sectoral e-governance from telemedicine and distance education to the courts. She closes by outlining seven problem blocks: interoperability, national security, national identity, economic security, privacy protection (warning of an Orwellian outcome if personal-data rules fail), responsibility, and force majeure — arguing that the most critical services should keep a 70–80 percent electronic share rather than going fully electronic.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2012). E-governance development trends and implementation risks. <i>'Information Society in Ukraine' congress, Kyiv</i>.</p><div class=\"m\">Conferences · 2012 · 'Information Society in Ukraine' congress, Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Theoretical, methodological, institutional and organisational foundations of e-governance</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-130\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-130\" hidden><p>Sets out the theoretical, methodological, institutional and organisational foundations of e-governance. The work distinguishes the principles that guide reform from the institutional and organisational arrangements that make it possible. It situates e-governance within the transformation of government processes.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Zahvoiska, O. (2011). Theoretical, methodological, institutional and organisational foundations of e-governance. <i>Research Digest, Kyiv</i>, (3).</p><div class=\"m\">Articles · 2011 · Research digest, iss. 3, Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Foundations for implementing e-governance</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-131\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-131\" hidden><p>Final report of the 2011 research project carried out at the National Academy of Public Administration's Information Policy Department under Svitlana Chukut's scientific supervision (180 pp., 152 sources). It systematises the theory and practice of introducing electronic governance in Ukraine: the national e-governance development concept the team helped draft for the government, a pilot project for state and local bodies, electronic services, staffing and the master's programme in e-governance, national electronic information resources and the protection of personal data. A separate part examines the regional and local levels, and the closing part surveys the institutional and organisational foundations of e-governance in ten countries — from Australia and Canada to Singapore and Thailand — as best foreign practice for Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Theoretical, methodological, organisational and institutional foundations of e-governance implementation</i> [Final research report]. (2011). National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zvit_Teoretiko-metodologichni-institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zvit_Teoretiko-metodologichni-institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2011 · Final research report, Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Building government–NGO interaction mechanisms</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-132\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-132\" hidden><p>The 2011 edition connects NGO participation, media and civic responsibility. It gives practitioners working with civil society ways to strengthen government–public interaction. The guide is intended for practitioners who work with government and civil society. It places participation in the context of media relations and the responsibilities of public institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Zahvoiska, O. V., Drahomyretska, N. M., Dreshpak, V. M., Soloviov, S. H., Dzhyha, T. V., Kandahura, K. S., Matvieienko, I. V., Shmatovalenko, L. S., Fomenko, T. M., Loshkariova, Y. M., Demkiv, T. F., Derekh, I. A., Kupriianenko, L. V., & Martynets, N. S. (2011). <i>Building government–NGO interaction mechanisms</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/02/CHukut-S.A.-Nalagodzhennya-mehanizmiv-vzayemodiyi-z-neuryadovimi-gromad-organizatsiyami.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2014/02/CHukut-S.A.-Nalagodzhennya-mehanizmiv-vzayemodiyi-z-neuryadovimi-gromad-organizatsiyami.pdf</a></p><div class=\"m\">Books & monographs · 2011 · Research guide. Kyiv: National Academy of Public Administration under the President of Ukraine. — 80 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">'Public Sector Modernisation through E-Government'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-133\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-133\" hidden><p>Training from the National University of Kyiv-Mohyla Academy on using e-government to modernise public-sector institutions and services. The training topic connects online services with changes to administrative processes and the skills needed in the public sector.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National University of Kyiv-Mohyla Academy. (2011). <i>&#x27;Public sector modernisation through e-government&#x27;</i> [Training certificate].</p><div class=\"m\">Certificates · 2011 · National University of Kyiv-Mohyla Academy</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Institutional and organisational foundations for implementing e-governance in Ukraine <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-134\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-134\" hidden><p>A collective volume of the master's programme in e-governance, published in Kyiv in 2011 (172 pp.) under the general editorship of Svitlana Chukut and Olha Zahvoiska, and the opening title of the \"E-Governance Library\" series. Written by the programme's students within the department's research project on the foundations of e-governance, it surveys how seven countries — Austria, Belgium, Ireland, Russia, Singapore, Thailand and Finland — organise the institutional support of electronic government: the responsible bodies, coordination and legislation. Svitlana Chukut directed the work behind the volume and taught the e-governance discipline within which the research was carried out. Its preface draws the lesson for Ukraine: create a dedicated institutional structure for the information society and e-governance, and turn the existing IT units of state and local bodies into e-governance units.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Zahvoiska, O. V. (Eds.). (2011). <i>Institutional and organisational foundations of e-governance implementation: Best foreign practices</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2011</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>12</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The master's programme in e-governance as a modern institutional mechanism for reforming public administration <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-135\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-135\" hidden><p>Written with Olha Zahvoiska for the first issue of the journal \"E-Governance\" (2010), the article presents the master's programme in e-governance as a modern institutional mechanism for reforming public administration. It examines how other countries introduced such programmes, then sets out how Ukraine's own programme was developed: the speciality 8.150110 \"E-Governance\", designed by the Information Policy Department in 2008 and licensed in 2009, and what its graduates — leaders and specialists of organisational e-governance systems — are trained to do under the educational-qualification characteristic and the educational-professional programme.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Zahvoiska, O. (2010). The master's programme in e-governance as a modern institutional mechanism for reforming public administration. <i>E-Governance</i>, (1), 41–54. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf</a></p><div class=\"m\">Articles · 2010 · 'E-Governance' journal, No. 1, pp. 41–54</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Staffing for e-governance implementation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-136\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-136\" hidden><p>Written with Oleksandr Kukarin and Olha Zahvoiska, the article treats qualified personnel as the precondition for implementing electronic governance. It describes how the National Academy began training masters in the new \"E-Governance\" speciality in 2009, and how in 2010 the national Classifier of Professions introduced a formal qualification — \"leader of organisational systems of e-governance\" (code 1229.7) — with defined duties: strategy and concepts, project coordination, legal drafting, readiness analysis and information management. The authors set qualification requirements for such leaders, principles for continuous training, a two-stage internship model for the master's students, and a structural proposal: convert the existing IT units of state and local bodies into e-governance units, beginning with the Cabinet of Ministers Secretariat.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Zahvoiska, O., & Kukarin, O. (2010). Staffing for e-governance implementation. <i>Richelieu Readings, Odesa</i>, 67–70.</p><div class=\"m\">Articles · 2010 · Richelieu readings, Odesa, pp. 67–70</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The e-governance master's programme</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-137\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-137\" hidden><p>Chukut's contribution to the Kyiv collection \"Experience in Implementation of E-Democracy and E-Governance in Ukraine\" (2010) presents the master's programme in electronic governance developed at the National Academy of Public Administration — the first of its kind in Ukraine, prepared in 2008 for the speciality \"Electronic Governance\" (8.150110) and approved by Ministry of Education and Science Directive No. 268 of 24 March 2009. The text sets out the programme's goals — training specialists who use modern ICT creatively, introduce advanced e-governance technologies for public services, and improve public administration to world and European standards — the eight professional skills it forms, from drafting strategies and concepts to assessing an institution's electronic readiness, and its distinctive features: strong practical orientation, two-stage traineeship ending in a defended master's thesis, and European training dimensions. It lists the mandatory disciplines, from e-democracy to electronic services, and the four specialisation tracks — national, local and regional, business, and information management.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2010). Master's program in electronic governance. In S. Dziuba (Ed.), <i>Experience in implementation of e-democracy and e-governance in Ukraine</i> (pp. 36–37). National Center for Support of Electronic Governance, Kyiv.</p><div class=\"m\">Articles · 2010 · Section 4.4. In: 'Experience in Implementation of E-Democracy and E-Governance in Ukraine'. National Center for Support of Electronic Governance, Kyiv, 2010, pp. 36–37</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Research: 'Foundations for e-governance implementation'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-138\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-138\" hidden><p>Ukraine wanted digital government, but there was no shared playbook for how to build it. Led by Svitlana Chukut at the National Academy of Public Administration (2010–2011, state registration No. 0201U004833), this project studied the regularities of how e-governance forms and develops in Ukraine and the world, set out its essence, methods and principles, and examined models of its implementation at national, regional and local levels. It studied the problems and prospects of e-governance formation against domestic practice, and the stages and tasks of implementation against best foreign practice — and the team took direct part in drafting the Concept of E-Governance Development in Ukraine. Its products were practical: a methodological guide on introducing e-governance in a general-education school; the methodological materials 'Best practices of e-governance implementation: foreign experience' (2010, 144 pp.); information-analytical materials 'State and problems of e-governance implementation in the central and local executive bodies of Ukraine'; the electronic proceedings of the conference 'Challenges and opportunities of e-governance implementation in a crisis'; and the first two issues of the international scientific journal 'E-Governance'. The results were used by the Secretariat of the Cabinet of Ministers (its information resources and technologies department) and by the State Committee for Informatization, and were embedded in the course 'Theoretical-methodological, organisational and institutional foundations of e-governance' for the master's speciality 'E-Governance'.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Research: &#x27;Foundations for e-governance implementation&#x27;</i> [Research project]. (2010–2011). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2010–2011 · Research supervisor</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Among the e-governance expert working group <a href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-139\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-139\" hidden><p>The International Renaissance Foundation documents Svitlana Chukut’s participation in an expert working group on e-governance development in Ukraine. The source places this participation in the preparation of Ukraine’s first national framework for developing e-governance and documents cooperation between public institutions and experts.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>International Renaissance Foundation. (2010). <i>Among the e-governance expert working group</i> [Project record]. <a class=\"apa-source\" href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\">https://www.irf.ua/en/?p=70400</a></p><div class=\"m\">Talks · 2010 · Renaissance Foundation news</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Best practices in implementing e-governance: foreign experience (collection) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-140\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-140\" hidden><p>Methodical materials for the discipline \"Theoretical, methodological, organisational and institutional foundations of e-governance\", published in Kyiv in 2010 (166 pp.) under the scientific editorship of Svitlana Chukut and Olha Zahvoiska and approved by the National Academy's Academic Council. Written by nine students of the master's programme in e-governance, the volume surveys best foreign practice in implementing electronic government across nine countries — Australia, India, Canada, Germany, Norway, South Korea, Russia, Singapore and the United States — from United Nations development indices and national strategies to flagship portals and services. Svitlana Chukut directed the work behind the volume and taught the discipline for which the materials were prepared.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Zahvoiska, O. V. (Eds.). (2010). <i>Best practices in implementing e-governance: Foreign experience</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf</a></p><div class=\"m\">Books & monographs · 2010</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Establishing mechanisms of interaction between the Government and non-governmental public organisations</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-141\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-141\" hidden><p>A scientific and methodical development (Kyiv, 2010, 64 pp.) prepared by a fifteen-author collective under Chukut's scientific supervision as a product of the research project \"Establishing mechanisms of effective interaction between the Government, the public and the media: theoretical and applied aspect\" (state registration No. 0109U003027). It examines the formation of civic responsibility and its role in civil society, the interaction of the individual and the state in perceiving information, government–public interaction and media influence on these processes, sociocultural project design at the regional level, risks in communication projects, and the project-based introduction of e-governance and e-democracy in the regions, including the \"School of E-Governance\" pilot. It also addresses media propaganda and \"dirty\" PR technologies, non-governmental analytical centres, and the media's influence on the formation of civil society, and is addressed to students, lecturers, civil-society institutes and the government officials responsible for public and media relations.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Zahvoiska, O., Drahomyretska, N., Dreshpak, V., Soloviov, S., Dzhyha, T., Kandahura, K., Matvieienko, I., Shmatovalenko, L., Fomenko, T., Loshkariova (Hrechishkina), Y., Demkiv, T., Derekh, I., Kupriianenko, L., & Martynets, N. (2010). <i>Establishing mechanisms of interaction between the Government and non-governmental public organisations: Scientific and methodical development</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2010 · Scientific and methodical development. Kyiv: National Academy of Public Administration under the President of Ukraine, 2010. — 64 pp.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Interoperability of e-public service delivery</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-142\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-142\" hidden><p>Written with Olha Zahvoiska for the \"Bulletin of the Civil Service of Ukraine\" (2009, No. 1), the article argues that interoperability is not a narrow technical question of computer networks: it extends to exchanging information between networks and reorganising administrative procedures so that electronic public services can actually be delivered — across administrations, across levels of government and across the European Union's borders. Uncoordinated development, the authors warn, produces \"islands\" of e-government that cannot interact. The answer they develop is professional training: after surveying master's programmes in e-governance from Syracuse and McGill to Oslo, Tampere and Waseda, the article presents the first Ukrainian master's programme in e-governance, developed at the National Academy's Information Policy Department in 2008 — its modules, four specialisations and the competencies its graduates were expected to carry into state and local administration.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Zahvoiska, O. (2009). Interoperability of e-public service delivery. <i>Bulletin of the Civil Service of Ukraine</i>, (1), 78–81.</p><div class=\"m\">Articles · 2009 · Civil Service Bulletin, iss. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>10</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance: course outline <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-143\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-143\" hidden><p>This course outline introduces core e-governance concepts and implementation principles. It links institutional and technology choices to the organisation of public services. The outline gives learners a framework for studying coordination across agencies, access to online services and the decisions that accompany implementation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Kukarin, O. B. (2009). <i>E-governance: Course outline</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf</a></p><div class=\"m\">Books & monographs · 2009 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information policy in Ukraine: practical class guidelines</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-144\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-144\" hidden><p>These recommendations support practical classes and independent study in the Information Policy in Ukraine course. They connect course concepts to public-administration situations. The guide structures practical work around analysing information policies and putting them into practice. The exercises complement coursework for future public administration specialists.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Zahvoiska, O. V., Kukarin, O. B., & Poprotskyi, O. P. (2009). <i>Information policy in Ukraine: Practical class guidelines</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod-rekomend_Informatsijna-politika.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod-rekomend_Informatsijna-politika.pdf</a></p><div class=\"m\">Books & monographs · 2009 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Editor-in-chief of the international journal 'E-Governance'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-145\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-145\" hidden><p>Editor-in-chief of E-Governance, an international scholarly journal on digital government research and practice, from 2009 to 2011. The editorial role helped provide a venue for publishing research on digital government and modernisation of public services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Editor-in-chief of the international journal &#x27;e-Governance&#x27;</i> [Editorial service record]. (2009–2011).</p><div class=\"m\">Books & monographs · 2009–2011 · Editorial work</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Research: 'Establishing mechanisms of effective interaction between the Government, the public and the media: theoretical and applied aspect'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-146\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-146\" hidden><p>Government decisions land better when officials, citizens and the media actually understand each other. Led by Svitlana Chukut (2009–2010, state registration No. 0109U003027), this research designed practical mechanisms for that interaction — and tested them outside the classroom. The team pilot-tested the level of civic responsibility: through the 'School of e-governance' pilot in Novovorontsovka district, Kherson region, and through a communicative project run under a resolution of the Head of the Council of Ministers of Crimea. It developed and put into practice the sociocultural and information projects 'Civic responsibility' and a video, and developed and implemented, at the Kherson Regional State Administration, the project 'Mechanisms of forming the Presidential personnel reserve \"New Elite of the Nation\" at the regional level'. Its written products included methodological recommendations for the course 'Communications in public administration' (48 pp.), the scientific-methodical manual 'Establishing mechanisms of the Government's interaction with non-governmental organisations' (64 pp., produced by an author team led by Chukut), a seminar-training programme on the Government's interaction with NGOs, and the completed textbook 'Communications in public administration'. The uptake was formalised in implementation acts: the Public Relations Department of the Secretariat of the Cabinet of Ministers (December 2009), the Council of Ministers of Crimea (21 January 2010), the Press and Information Department of the Kherson Regional State Administration (15 December 2010) and the Education Department of Novovorontsovka district (22 January 2010). Through her participation in the State Committee for Informatization working group, the work also fed into the Concept of E-Governance Development in Ukraine, adopted by Cabinet Resolution No. 2250-r of 13 December 2010.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Research: &#x27;Establishing mechanisms of effective interaction between the government, the public and the media: Theoretical and applied aspect&#x27;</i> [Research project]. (2009–2010). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2009–2010 · Research supervisor</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Electronic Government Development Concept for Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-147\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-147\" hidden><p>A collective policy document prepared with the International Renaissance Foundation's support and edited by Andrii Semenchenko, with Chukut among its twelve authors. The Concept defines the goal, main objectives, tasks, functions and basic principles of implementing and developing electronic governance in Ukraine to 2015, its stages and preconditions, and its specific features in crisis conditions, together with the state's policy in this sphere. It proposes a categorical and conceptual apparatus for the field, mechanisms for managing e-governance development and for providing state services, and serves as the basis for a development strategy, programme documents and a draft law on e-governance.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Baranov, O. A., Demkova, M. S., Dziuba, S. V., Yefanov, A. V., Zhyliaiev, I. B., Klepets, E. L., Misnikov, I., Arvo, O., Popova, T. V., Ruban, I. A., & Semenchenko, A. I. (2009). <i>Electronic government development concept for Ukraine</i> [Working paper].</p><div class=\"m\">Books & monographs · 2009 · Kyiv, 2009. — 16 pp.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Draft textbook 'Conceptual Foundations of E-Governance Development' <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-148\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-148\" hidden><p>A draft textbook prepared by a twelve-author collective edited by Andrii Semenchenko, with Chukut among the authors. Building on the national Concept, it defines the purpose, goals, tasks, functions and basic principles of implementing and developing electronic governance in Ukraine, analyses Ukrainian and foreign practice in applying e-governance technologies, and proposes a model of public administration for the information society. It develops the stages of e-governance development, its management mechanisms, and the legislative, administrative-organisational and technological support the system requires, and is recommended for public administration specialists, lecturers and researchers.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Semenchenko, A. I. (Ed.). (2009). <i>Conceptual foundations of e-governance development in Ukraine</i> [Draft teaching manual]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf</a></p><div class=\"m\">Books & monographs · 2009 · Kyiv, 2009. — 82 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>77</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Establishing mechanisms for effective government interaction with the public and mass media: interim research report (State Registration No. 0109U003027)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-149\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-149\" hidden><p>This is the halfway report (Kyiv, 2009) of the Academy research led by Svitlana Chukut on how government, citizens and the media can interact more effectively (state registration No. 0109U003027). Written with colleagues including N. M. Drahomyretska and V. M. Dreshpak, it recorded the project's progress and interim findings. The completed research went on to produce a textbook, teaching recommendations and pilot work adopted by the Secretariat of the Cabinet of Ministers.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Establishing mechanisms for effective government interaction with the public and mass media: Interim research report (state registration no. 0109u003027)</i> [Interim report]. (2009). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2009 · Kyiv: National Academy of Public Administration under the President of Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Scientific and methodological support for public relations in executive bodies <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-150\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-150\" hidden><p>Methodical recommendations produced by a seven-author collective under Chukut's general editorship at the National Academy of Public Administration (Kyiv, 2008, 72 pp.), as a product of the research project \"Developing scientific and methodological support for public relations in executive bodies\" (state registration No. 0107U005909), which Chukut supervised. The recommendations set out the organisational foundations of public relations in executive bodies, the planning and legal regulation of the units responsible for media interaction and public relations, and the methods and technologies through which state authorities work with the media and the public. They are addressed to students of the \"Public Administration\" speciality and to the staff of those units.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (General Ed.), Dzhyha, T., Barovska, A., Karpenko, O., Nedashkivska, T., Poprotskyi, O., & Skrebets, R. (2008). Scientific and methodological support for public relations in executive bodies: Methodical recommendations. National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf</a></p><div class=\"m\">Articles · 2008 · Methodical recommendations. Kyiv: National Academy of Public Administration under the President of Ukraine, 2008. — 72 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>5</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/egov-2008.jpg\" alt=\"Domestic and foreign experience of e-governance implementation\"><div class=\"lib-copy\"><div class=\"t\">Domestic and foreign experience of e-governance implementation <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-151\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-151\" hidden><p>Proceedings of the scientific-practical conference held at the National Academy of Public Administration under the President of Ukraine for E-Governance Day on 14 May 2008 (Kyiv, 2008, 128 pp.; general editors Svitlana Chukut and Olha Zahvoiska; recommended by the Academy's Academic Council, protocol No. 148/8-4 of 28 August 2008). The volume presents scientific-practical approaches, research results and implementation experience in e-governance and e-democracy: its sections cover e-governance at the central level and at the local level, electronic services, e-democracy, and the main tasks of e-government — including the role of the Microsoft corporation in carrying them out — and it closes with the recommendations adopted from E-Governance Day 2008. The materials, drawn from the leading domestic and foreign experience of e-governance in central, local and regional administration, are addressed to public-administration and business practitioners, heads of state and local authorities, enterprises, institutions and civil-society organisations, and to everyone who studies, researches, implements or uses e-governance technologies.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Zahvoiska, O. V. (Eds.). (2008). <i>Domestic and foreign experience of implementing e-governance</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2008 · Proceedings of the scientific-practical conference 'E-Governance Day 2008'. Kyiv: National Academy of Public Administration under the President of Ukraine, 2008. — 128 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>24</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/info-policy-textbook-cover.jpg\" alt=\"Information Policy: a textbook (2nd ed.)\"><div class=\"lib-copy\"><div class=\"t\">Information Policy: a textbook (2nd ed.)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-152\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-152\" hidden><p>A fundamental study guide offering a comprehensive examination of the theoretical, legal and managerial foundations of information policy in the context of building the information society, integrating the approaches of public administration, political science, law and the theory of strategic communications. Svitlana Chukut's authorial contribution covers the institutional-managerial and digital blocks of the discipline: the theoretical and methodological foundations of implementing electronic government, the stages of the digital transformation of public administration and the models of electronic democracy; a comparative analysis of successful world practices of information-society and e-governance development (the European Union, the USA, Great Britain, Estonia, Singapore); and the mechanisms of Ukraine's state information policy, the protection of information resources, citizens' access to public information and overcoming the digital divide. One of the first basic academic editions in Ukraine to integrate e-governance into a general course on state information policy, the book contains a complete teaching and methodological complex — a glossary, review questions, topics for research papers and the normative base — and is widely used in training specialists in public administration, political science, international relations and information security.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pocheptsov, H. H., & Chukut, S. A. (2008). <i>Information policy</i> (2nd ed.). Znannia. <a class=\"apa-source\" href=\"https://koha.oa.edu.ua/cgi-bin/koha/opac-detail.pl?biblionumber=340847\" target=\"_blank\" rel=\"noopener\">https://koha.oa.edu.ua/cgi-bin/koha/opac-detail.pl?biblionumber=340847</a></p><div class=\"m\">Books & monographs · 2008 · Kyiv: Znannia, 2nd ed. — 663 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>35</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Communicative policy in public authorities: lecture outline</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-153\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-153\" hidden><p>Lecture outline for the course \"Communicative Policy in Government Bodies\" by Svitlana Chukut and Tetiana Dzhyha (NAPA Publishing House, Kyiv, 2008, 72 pp.; approved by the Academic Council of the National Academy of Public Administration under the President of Ukraine, protocol No. 111/11-1 of 11 November 2008). The outline sets out the main theoretical and methodological foundations of the discipline: it defines the key provisions of communicative policy, presents the main tasks of the communication units of government bodies, analyses foreign experience in implementing communicative policy, and discloses the principal technologies of interaction with the public. Its chapters cover the democratisation of decision-making in Ukraine, the regulatory and legal framework for authorities' interaction with the public, the tasks and functions of communication units, foreign practice, and the planning of executive bodies' communications with the public and the media. The guide is intended for master's students of the National Academy in the \"Public Administration\" specialty, specialisation \"Information Processes in Public Administration\", and is also useful for practitioner managers and specialists in information policy, communications and public relations.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Dzhyha, T. (2008). Communicative policy in public authorities: Lecture outline. NAPA Publishing House.</p><div class=\"m\">Books & monographs · 2008 · Kyiv: NAPA Publishing House, 2008. — 72 pp.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information policy and e-governance: course outline</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-154\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-154\" hidden><p>This course outline connects information policy to how digital administrations operate. It covers the organisation of information exchange and the delivery of online services. The outline allows readers to consider information policy alongside the administrative decisions needed to provide online services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Kukarin, O. B. (2008). <i>Information policy and e-governance: Course outline</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_Informatsijna-politika-ta-elektronne-uryaduvannya_CHukut_Kukarin.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_Informatsijna-politika-ta-elektronne-uryaduvannya_CHukut_Kukarin.pdf</a></p><div class=\"m\">Books & monographs · 2008 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Academic editor of e-governance collections</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-155\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-155\" hidden><p>Academic editorship of three collections on international experience, good practice and the institutional foundations of e-governance. The collections assemble comparative studies for teaching and practice. They cover the role of institutions, national strategies and public-facing services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Academic editor of e-governance collections</i> [Editorial service record]. (2008–2011).</p><div class=\"m\">Books & monographs · 2008–2011 · 'Foreign Experience' (2008), 'Best Practices' (2010), 'Institutional Foundations' (2011)</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Research: 'Developing scientific and methodological support for public relations in executive bodies' (State Registration No. 0107U005909)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-156\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-156\" hidden><p>How should a ministry or a town hall talk with the public — openly, professionally, and especially in a crisis? This 2008 Academy study, led by Svitlana Chukut (state registration No. 0107U005909; research report of 135 pages), set out to give government public relations in Ukraine a scientific and methodological basis. The team defined the main directions in which public relations in public administration develops and functions, analysed foreign experience, and further developed the methodological foundations of interaction between state authorities and the public, in line with proposals of the Presidential Administration and executive bodies. It also developed the foundations of information-analytical work for PR services in state bodies, analysed how state authorities interact with the public councils at the President, the Government, ministries and heads of local state administrations, studied public relations in crisis situations, and analysed the influence of modern information technologies on PR. The results were practical: the manuscript of the scientific-practical manual 'Public relations in public administration: theoretical and applied aspect' was prepared for print, 22 scientific articles were published and 5 scientific-methodical manuals were prepared; the results were implemented in cooperation with the Public Relations Department of the Secretariat of the Cabinet of Ministers of Ukraine and built into the department's teaching materials.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Research: &#x27;Developing scientific and methodological support for public relations in executive bodies&#x27; (state registration no. 0107u005909)</i> [Research project]. (2008). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2008 · Research supervisor</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ukraine's E-Governance Development Concept (Cabinet Resolution No. 2250-r) <a href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-157\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-157\" hidden><p>Before 2010, Ukraine had no single national plan for digital government. A working group under the State Committee of Informatization, supported by the International Renaissance Foundation, wrote the country's first E-Governance Development Concept — a plan setting out what to build and in what order. Svitlana Chukut was a member of the group, and the Cabinet of Ministers approved the Concept on 13 December 2010 (Resolution No. 2250-r), making it the official starting point for Ukraine's digital-government reforms.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Cabinet of Ministers of Ukraine. (2010, December 13). <i>Approval of the concept for the development of e-governance in Ukraine</i> [Order No. 2250-r]. <a class=\"apa-source\" href=\"https://zakon.rada.gov.ua/laws/show/2250-2010-%D1%80\" target=\"_blank\" rel=\"noopener\">https://zakon.rada.gov.ua/laws/show/2250-2010-%D1%80</a></p><div class=\"m\">Projects · 2008–2010 · Working group member (Renaissance Foundation grant)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Foreign experience in implementing e-governance <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-158\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-158\" hidden><p>A collection of the best creative works of students of the new \"Public Administration\" specialty, written for the \"E-Governance\" discipline at the National Academy of Public Administration under the President of Ukraine (Kyiv, 2008, 200 pp.; author collective of ten students; general editor Svitlana Chukut). Ten country chapters survey how e-governance was implemented in Great Britain, Estonia, Canada, Germany, Poland, Russia, Singapore, the United States, France and Sweden. Addressed to everyone interested in the problems of implementing e-governance in Ukraine and in the world.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (Ed.), Kaminska, T., Kaminskyi, A., Pasichnyk, M., Seleshchuk, V., Havrylets, O., Kyryliuk, I., Mazhak, N., Yakymenko, O., Bekirova, A., & Yesypenko, A. (2008). Foreign experience in implementing e-governance. National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2008 · Kyiv: National Academy of Public Administration under the President of Ukraine, 2008. — 200 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>29</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-Democracy: essence and main stages <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-159\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-159\" hidden><p>Chukut's paper in the E-Governance Day 2008 proceedings (pp. 89–95). She defines e-democracy as the state ensuring the necessary preconditions for citizens to participate in developing and adopting state decisions with the help of modern information and communication technologies, and explains that e-governance builds the trust between government and citizens on which it rests — through participation in decision-making, openness, accountability and the prevention of corruption. She sets out the main stages of e-democracy's formation: e-informing, a one-way flow from state bodies to citizens (access to documents, catalogues, registers and indexes, published draft laws and white and green papers, online reports and guides, via email, web portals, mobile communication, information kiosks and discs — with the attendant problems of confidential information, state secrets, privacy and national security); e-consultation, in which the government asks citizens' opinion online and receives requests, complaints, proposals and survey answers in a limited two-way relationship hindered by the digital divide; e-participation, citizens' active, feedback-based involvement in decision-making and policy-making through government and public forums and chats, interactive games and virtual workspaces; and e-partnership, in which responsibility for decisions is shared by both sides on a basis of mutual trust — a stage still in its infancy. She closes with the problems to be solved — digital inequality, access for people with disabilities, ICT illiteracy, staffing, technical capacity, financing, legal status and accountability, security and privacy — and the ways to solve them, from ensuring access and re-engineering the civil service to amending legislation and combining ICT with traditional means.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2008). E-democracy: Essence and main stages. In S. Chukut & O. Zahvoiska (Eds.), <i>Domestic and foreign experience of e-governance implementation</i> (pp. 89–95). National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf</a></p><div class=\"m\">Articles · 2008 · Proceedings of the scientific-practical conference 'E-Governance Day 2008': 'Domestic and foreign experience of e-governance implementation'. Kyiv: National Academy of Public Administration under the President of Ukraine, 2008, pp. 89–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-government: a scientific and practical guide <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-160\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-160\" hidden><p>A scientific and practical handbook compiled by Svitlana Chukut with I. V. Klymenko and K. O. Lynov. It sets out the essence, principles and approaches of implementing electronic government in Ukraine, drawing on foreign experience, and works through the practical machinery: the obstacles posed by digital inequality, the goals and expected results of the \"Electronic Government\" information system, a classification of electronic state services and processes, government portals as the main channel of communication, and architectural models for integrating the system's components. It is addressed to trainees in the public-administration professional development system, civil servants and researchers.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Klymenko, I. V., & Lynov, K. O. (2007). <i>Electronic government: A scientific and practical reference guide</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf</a></p><div class=\"m\">Articles · 2007 · Digital copy of the 2007 reference guide</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a><span class=\"scholar-record-note\">This digital copy is included in the combined citation count for the reference guide.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-Government: a research and practice guide</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-161\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-161\" hidden><p>Written for civil servants, researchers and professional learners, this reference guide covers e-government architecture, data and document standards, government portals and digital public services. The guide compares international models and relates them to implementation in Ukraine, from central government to regional and local authorities.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Klymenko, I. V., & Lynov, K. O. (2007). <i>Electronic government: A scientific and practical reference guide</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf</a></p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine. — 70 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>38</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information policy in Ukraine: course guidelines</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-162\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-162\" hidden><p>A companion to the Information Policy in Ukraine course, this guide supports class preparation and analysis of public institutions’ role in information policy. The recommendations support the study of state responsibilities, rules governing information and their implications for Ukrainian public institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2007). <i>Information policy in Ukraine: Course guidelines</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/info-policy.jpg\" alt=\"Information policy in Ukraine: lecture outline\"><div class=\"lib-copy\"><div class=\"t\">Information policy in Ukraine: lecture outline <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-163\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-163\" hidden><p>Lecture outline for the course \"Information Policy in Ukraine\" by Svitlana Chukut and Tetiana Dzhyha (Kyiv, 2007, 94 pp.). The outline sets out the main theoretical and methodological foundations of the discipline: it describes the key provisions of information policy, discloses the activity of the central authorities in the field of information, presents the main principles of foreign countries' information policy on building the information society, analyses the legal regulation of the information sphere and the main aspects of implementing e-governance in Ukraine and worldwide, and focuses on the principal problem and key issues of communicative policy in government bodies. Its chapters cover Ukraine's state information policy and the central authorities in the information sphere, foreign information policy on building the information society, and the legal regulation of the information sphere. The guide is intended for master's students of the National Academy of Public Administration under the President of Ukraine in the \"Public Administration\" specialty, and is also useful for practitioner managers, information-policy specialists, students and lecturers of economic specialties.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Dzhyha, T. V. (2007). <i>Information policy in Ukraine: Lecture outline</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf</a></p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine, 2007. — 94 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Communicative policy in public authorities: distance course guide</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-164\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-164\" hidden><p>Methodological recommendations for students of the distance course \"Communicative Policy in Government Bodies\", compiled by Svitlana Chukut with Tetiana Dzhyha and Anna Barovska (National Academy of Public Administration under the President of Ukraine, Kyiv, 2007, 39 pp.). The recommendations support a professional-development course for staff of executive bodies responsible for interaction with the media and the public: its task is to train highly qualified personnel able to develop, analyse and implement state communicative policy and to introduce advanced public-administration technologies to world and European standards. They set out the course's goals — to disclose the principles of state authorities' interaction with the public, the methods of working with civic associations and the media, the current state of Ukrainian authorities' interaction with the media, its most pressing problems and ways of solving them — and its learning outcomes: understanding the essence of the current stage of state communicative policy in Ukraine, applying communicative and information technologies in preparing, adopting and implementing management decisions, informing the public through constant liaison with the media, and organising public support for decisions through briefings, press conferences and other public events. The learning strategy combines students' independent work on the course's set of teaching materials — including the textbook \"Information Policy\" by Heorhii Pocheptsov and Svitlana Chukut (2006), an electronic textbook, lecture notes and these recommendations — with interactive seminars and practical classes, computer testing in interactive mode, and discussion of practically significant problems of communicative policy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., Dzhyha, T. V., & Barovska, A. V. (2007). <i>Communicative policy in public authorities: Distance course guide</i>. Secretariat of the Cabinet of Ministers of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod_rekomendatsiyi-do-dist-kursu_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod_rekomendatsiyi-do-dist-kursu_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf</a></p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine, 2007. — 39 pp.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Communicative policy in public authorities: course outline <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-165\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-165\" hidden><p>Course outline for the distance course \"Communicative Policy in Government Bodies\" by Svitlana Chukut and Tetiana Dzhyha (Secretariat of the Cabinet of Ministers of Ukraine, Kyiv, 2007, 117 pp.), the core study guide of the distance course, accompanied by methodological recommendations for its students. The outline presents the foundations of communicative policy: the basic principles of communication — its models, the rules of interaction between authorities and the public, and communication as a two-way exchange whose quality shapes how the public perceives authority; the scientific approaches to forming the communicative policy of state authorities — the theories of democracy and public participation, the principles of public relations as cooperation rather than manipulation, and the task of building an effective dialogue and public trust in government; and the problems of reforming public administration in Ukraine in their communicative aspect — the administration's inefficiency and closedness, the doctrine of administrative services and the treatment of the private person as a client, the barriers to democratising decision-making identified in the Secretariat's White Paper, and the development of e-governance as a means of ensuring the transparency of power and its accountability to society.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., & Dzhyha, T. (2007). Communicative policy in public authorities: Course outline. Secretariat of the Cabinet of Ministers of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf</a></p><div class=\"m\">Books & monographs · 2007 · Kyiv: Secretariat of the Cabinet of Ministers of Ukraine, 2007. — 117 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>8</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Legal support of the information sphere in Ukraine and abroad</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-166\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-166\" hidden><p>This self-study guide compares legal frameworks for the information sphere in Ukraine and abroad. It supports the study of rules governing institutions and information exchange. The two settings allow readers to compare institutional responsibilities and the legal tools that govern the circulation and use of information.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Skrebets, R. (2007). <i>Legal support of the information sphere in Ukraine and abroad</i> [Teaching guide]. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Practical use of e-government and e-governance: guidelines</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-167\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-167\" hidden><p>This guide helps civil servants and learners apply e-government and e-governance concepts to service delivery and institutional practice. The recommendations connect digital tools with the daily work of government and the needs of local authorities and service users.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Dzhyha, T. V. (2007). <i>Practical use of e-government and e-governance: Guidelines</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Practical use of electronic government and governance. Applied scientific developments</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-168\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-168\" hidden><p>Methodical recommendations compiled by Chukut with Tetiana Dzhyha, Oleksandr Poprotskyi, Anastasiia Borovska and Oleksandr Karpenko (Kyiv: National Academy of Public Administration, 2007), issued within the Academy's collection \"Applied scientific developments for use by employees of state authorities and local self-government bodies\" and approved by the Academy's Academic Council on 24 May 2007. The recommendations set out the technologies and mechanisms for effective interaction between state authorities, local self-government and the public, and offer state and local bodies practical recommendations for introducing electronic government. They are addressed to master's students, postgraduates, doctoral students and all who study electronic governance.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S., Dzhyha, T., Poprotskyi, O., Borovska, A., & Karpenko, O. (2007). <i>Practical use of electronic government and governance: Methodical recommendations</i>. National Academy of Public Administration.</p><div class=\"m\">Books & monographs · 2007 · In: 'Applied scientific developments for use by employees of state authorities and local self-government bodies'. Kyiv: National Academy of Public Administration under the President of Ukraine, 2007. — 32 pp.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-governance: self-study guidelines</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-169\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-169\" hidden><p>These recommendations structure independent study of e-governance principles and their application in the public sector. The guide helps participants prepare for training by structuring their study of institutional responsibilities and the introduction of electronic public services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2007). <i>E-governance: Self-study guidelines</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2007 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information Policy: a textbook</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-170\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-170\" hidden><p>A fundamental study guide offering a comprehensive examination of the theoretical, legal and managerial foundations of information policy in the context of building the information society, integrating the approaches of public administration, political science, law and the theory of strategic communications. Svitlana Chukut's authorial contribution covers the institutional-managerial and digital blocks of the discipline: the theoretical and methodological foundations of implementing electronic government, the stages of the digital transformation of public administration and the models of electronic democracy; a comparative analysis of successful world practices of information-society and e-governance development (the European Union, the USA, Great Britain, Estonia, Singapore); and the mechanisms of Ukraine's state information policy, the protection of information resources, citizens' access to public information and overcoming the digital divide. One of the first basic academic editions in Ukraine to integrate e-governance into a general course on state information policy, the book contains a complete teaching and methodological complex — a glossary, review questions, topics for research papers and the normative base — and is widely used in training specialists in public administration, political science, international relations and information security.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pocheptsov, H. H., & Chukut, S. A. (2006). <i>Information policy</i>. Znannia. <a class=\"apa-source\" href=\"https://catalog.library.dp.ua/cgi-bin/irbis64r_12/cgiirbis_64.exe?C21COM=F&amp;I21DBN=EKNK_PRINT&amp;LNG=&amp;P21DBN=EKNK&amp;S21FMT=infow_wh_print&amp;Z21MFN=11559\" target=\"_blank\" rel=\"noopener\">https://catalog.library.dp.ua/cgi-bin/irbis64r_12/cgiirbis_64.exe?C21COM=F&amp;I21DBN=EKNK_PRINT&amp;LNG=&amp;P21DBN=EKNK&amp;S21FMT=infow_wh_print&amp;Z21MFN=11559</a></p><div class=\"m\">Books & monographs · 2006 · Kyiv: Znannia. — 663 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>634</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Editorial board member of scholarly journals</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-171\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-171\" hidden><p>Editorial board service for Strategic Priorities, Democratic Governance and publications of the National Academy of Public Administration. These roles span journals and collections that publish work on public policy, governance and the operation of public institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Editorial board member of scholarly journals</i> [Editorial service record]. (2006–2012).</p><div class=\"m\">Books & monographs · 2006–2012 · 'Strategic Priorities', 'Democratic Governance', National Academy of Public Administration under the President of Ukraine Bulletin and Proceedings</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problems and prospects of e-governance development in the conditions of modern social progress: foreign and domestic experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-172\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-172\" hidden><p>How do you bring government online in a country where the idea is still new — and what can be learned from countries that started earlier? In this 2006 research study, Svitlana Chukut set out to identify and study the problems of e-governance in the modern development of Ukraine and other countries, drawing on their shared experience, and to work out scientifically grounded proposals and recommendations for implementing e-governance and the prospects for its development. The study compared the e-governments of the world's leading countries with the situation in Ukraine, examined the main problems and achievements in the formation of e-government in Ukraine, and weighed the advantages of e-governance alongside traditional administration in order to set the priorities for digital democracy. Its results were new in several respects: fundamentally new definitions of e-government, new approaches to forming e-government in Ukraine divided into stages, and new approaches to overcoming the obstacles in the way. The comparison supported a practical conclusion — Ukraine has all the resources to build an integral e-government system and to involve citizens themselves as the main actors of state policy — and the study closed with practical recommendations, including for the Academy's teaching: new e-governance courses and a specialisation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Problems and prospects of e-governance development in the conditions of modern social progress: Foreign and domestic experience</i> [Research report]. (2006). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2006 · Research report. Kyiv: National Academy of Public Administration under the President of Ukraine, 2006</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problems and prospects of e-government implementation: world and domestic experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-173\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-173\" hidden><p>Chukut distinguishes the competing terms — e-governance, e-state, e-management, e-society — and defines e-government as the adaptation of public administration to the new requirements of social development: both the services the state provides to citizens and their interactive interaction through a feedback system (citizen → government → citizen) built on modern ICT. She describes the three stages of e-government formation — government websites carrying reference information; integration into a single portal with interactive services and feedback; and predominantly online communication with round-the-clock services and digital democracy — and reports the UN E-Government Survey 2003 readiness index, on which Ukraine (0.462) stood slightly above the world average (0.402) and ahead of Russia and Belarus, while the United States (0.927) led. Ukraine, she argues, lacks both a concept for building the information society and a body responsible for it — unlike Canada's Information Highway Advisory Council, the US Information Infrastructure Task Force or the EU's Directorate-General for Information Society — and she groups the obstacles into financial, technological, mental, cultural, educational, political and professional problems. The article then examines the most widespread problems of e-government implementation and their solutions in the United States (including the four reasons ICT spending failed to raise public-sector productivity, share-in-savings contracts under the E-Government Act of 2002, and measures against the digital divide), the European Union and Great Britain.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2005). Problems and prospects of e-government implementation: World and domestic experience. In <i>Public administration in Ukraine: Realities and prospects</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Articles · 2005 · 'Public Administration in Ukraine: Realities and Prospects', Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problems and obstacles to e-government: world and domestic experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-174\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-174\" hidden><p>Chukut distinguishes the neighbouring concepts — e-governance as the ICT-supported formation of citizens' civic position and self-governance, e-government as the actions of the state and its bodies — and defines e-government as the adaptation of public administration to new requirements of social development, combining state services with interactive feedback between citizen and government. She describes three stages of building e-government, from publishing reference information on agency websites through a unified portal with online services to predominantly online interaction with digital democracy, and reads the 2003 UN E-Government Survey readiness index (Ukraine 0.462, above the world average yet held back by the absence of a national concept and a responsible body). The article catalogues Ukraine's obstacles — financial, technological, mental, cultural, educational, political and professional — and examines how the United States, the European Union and the United Kingdom address such problems, including shared-savings contracts under the E-Government Act of 2002.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2005). Problems and obstacles to e-government: World and domestic experience. In <i>Public administration in Ukraine: Realities and prospects</i>. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Articles · 2005 · Ibid.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>7</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ukrainian-German public administration reform project (GTZ, German Government)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-175\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-175\" hidden><p>Ukraine's civil servants needed training for a more modern, digital administration. In this Ukrainian-German reform project (2005–2008), run by the National Academy of Public Administration with a Berlin partner school and funded by the German government (GTZ), Svitlana Chukut wrote the e-governance module — the digital-government part of the course — for Master's programmes in public administration. The module brought digital government into the standard training of future public managers.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span><i>Ukrainian-german public administration reform project (GTZ, german government)</i> [Research project]. (2005–2008). National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Projects · 2005–2008 · Participant — 'E-governance' module</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information Policy: a textbook (Pocheptsov, Chukut)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-176\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-176\" hidden><p>The author’s catalogue lists this manual by Heorhii Pocheptsov and Svitlana Chukut among their publications on information policy. This title belongs to a series of textbooks that connect information regulation, public communication and digital government.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pocheptsov, H. H., & Chukut, S. A. (2005). <i>Information policy</i>. Ukrainian Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 2005 · Kyiv: Publishing House of the Ukrainian Academy of Public Administration</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information policy and public relations: methodological guide</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-177\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-177\" hidden><p>A methodological companion to the Information Policy and Public Relations course, designed to support independent study. Designed as a study aid, it connects the objectives of information policy with communication between institutions and the people they serve.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Nadolnyi, I. F. (2004). <i>Information policy and public relations: Methodological guide</i>. Centre of Educational Literature. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Books & monographs · 2004 · Kyiv: Centre of Educational Literature</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information policy and PR: distance course outline</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-178\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-178\" hidden><p>A distance-learning outline connecting information policy, communications strategy and public relations practice. The outline structures distance study around the relationship between information flows, institutional strategy and communication with the public.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Pocheptsov, H. H., & Chukut, S. A. (2004). <i>Information policy and PR: Distance course outline</i>. Centre of Educational Literature. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Books & monographs · 2004 · Kyiv: Centre of Educational Literature. — 84 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>15</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Methodological recommendations for students of the distance course 'Information Policy'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-179\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-179\" hidden><p>A study guide for learners enrolled in the distance course on information policy. It supports independent work on the course topics. The guide complements the course by organising independent study of the concepts and public policy questions addressed in its learning activities.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2004). <i>Methodological recommendations for students of the distance course &#x27;information policy&#x27;</i> [Teaching guide].</p><div class=\"m\">Books & monographs · 2004</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The essence of e-government and principles of its organisation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-180\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-180\" hidden><p>In this early programmatic article, written to open a journal rubric on the essence and development of electronic government, Chukut examines the contested definitions of e-government — as a portal, as interactive state–citizen interaction (Vershinin), as network information and communication infrastructure (Koshkin) — and the OECD's e-government project with its four assessment groups, from foresight and public-administration reform to measurement. Drawing on the eEurope 2002 and 2005 programmes and the draft \"Electronic Ukraine\" programme, she distinguishes a government that is merely online from a true electronic government, sets out eleven principles for organising e-government — citizen orientation, convenience and simplicity, business transformation, minimal cost and complexity, service quality, compliance, scalability, performance, reporting, speed of implementation and readiness to act — and concludes with e-government defined as the adaptation of public administration to new conditions of social development, built on a citizen–government feedback loop.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2003). The essence of e-government and principles of its organisation. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 2003 · Bulletin of Ukrainian Academy of Public Administration, No. 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>52</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Building the information society in Ukraine: problems and prospects</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-181\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-181\" hidden><p>Chukut surveys the first steps toward building an information society in Ukraine. After noting the world community's parallel efforts — the eEurope initiative, the United Kingdom's modernising-government programme, Russia's federal \"Electronic Russia\" programme — she lists the Ukrainian framework created between 1998 and 2003: the Law on the National Informatization Program, presidential decrees on Internet access in Ukraine, on openness of state authorities and on protecting state information resources, Cabinet resolutions on publishing executive activity online and on creating the \"Electronic Government\" information system (24 February 2003), and the draft \"Electronic Ukraine\" programme. She concludes that, although the need is fully recognised at the level of state administration, most problems remain unresolved, and closes with the Council of Europe's 1999 Budapest Declaration: a truly democratic information society rests on policies encouraging access and participation, competence and readiness, creativity and diversity with appropriate protection.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2003). Building the information society in Ukraine: Problems and prospects. <i>International Congress, Kyiv, 1–2.04.2003</i>.</p><div class=\"m\">Articles · 2003 · International congress, Kyiv, 1–2.04.2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">State cultural policy amid the information society: foreign and domestic experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-182\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-182\" hidden><p>Chukut examines how the building of the information society transforms state cultural policy, drawing on UNESCO's analysis and European practice. She sets out the four aspects UNESCO identifies: new information technologies generate new communication models and a new aesthetic discourse, feeding \"global creativity\"; the cultural industry gains economic weight on a global market, sharpening copyright and anti-piracy problems; cultural heritage — material and immaterial — becomes a policy prerogative exposed to illegal trade and transnational actors; and the information revolution itself carries economic, social and political consequences that demand a clear definition of public interests in cyberspace and protection of citizens' rights. She reviews UNESCO's Medium-Term Strategy for 1996–2001 and argues that cultural policy's focus shifts from the creative process itself to the means of transmitting its results to the consumer. Canada's experience — a national information highway centred on culture and the digitisation of heritage, whose support for domestic media production turned the country into a major exporter of film and video — is set against the European Union's: the Fourth Framework Programme, the \"Multimedia Access to Europe's Cultural Heritage\" Memorandum of Understanding (1995–1998), and the first Culture 2000 programme, with their commitments on digitised access, heritage protection and cultural diversity. She concludes that common features of modern cultural policy — IT in both creation and dissemination, digitised heritage with non-discriminatory access, lifelong distance education, protection of morality and democratic values, preservation of cultural and linguistic diversity, and deeper international cooperation — should be introduced into Ukraine's own cultural policy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2003). State cultural policy amid the information society: Foreign and domestic experience. <i>Culturological Readings in Memory of V. Pidkopaiev</i>. Center for Culturological Research.</p><div class=\"m\">Articles · 2003 · Culturological readings in memory of V. Pidkopaiev, Center for Culturological Research, 2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">E-government: problems and priorities</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-183\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-183\" hidden><p>An extended treatment of the problems and priorities of e-government development in foreign and domestic experience. Chukut revisits the contested definition of e-government and the OECD project — its long-term horizon to 2010, the criteria of twenty-first-century governance (legitimacy, rule of law, transparency, accountability and honesty, efficiency, coherence, adaptation, partnership and consultation) and its four assessment groups — before setting out the eleven principles of organising e-government, from citizen orientation and business transformation to scalability, reporting and speed of implementation, and the key provisions drawn from foreign practice: focus on the real needs of citizens and business, partnership with high-technology industry, digital-democracy mechanisms, private-sector service quality, multi-channel delivery, network and information security, and the training of civil servants for new forms of work.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2003). E-government: Problems and priorities. Proc. of Ukrainian Academy of Public Administration Research Conf., May 2003.</p><div class=\"m\">Articles · 2003 · Proc. of Ukrainian Academy of Public Administration research conf., May 2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Information Policy: a textbook. Part 2 <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-184\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-184\" hidden><p>Part two examines information policy through the introduction of electronic government. It places the modernisation of Ukraine’s public administration in the context of the information society. The volume connects institutional and technical choices with access to information and the organisation of public services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A., & Lytvynenko, O. V. (2003). <i>Information policy: A textbook. part 2</i>. National Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf</a></p><div class=\"m\">Books & monographs · 2003 · Kyiv: National Academy of Public Administration under the President of Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>25</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Comparative analysis of e-government development in England and Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-185\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-185\" hidden><p>A comparative analysis of how e-government was built in England and in Ukraine. The comparison places early Ukrainian initiatives in international context. It provides a way to examine how public strategies and administrative capacity shaped the transition to online services.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2002). Comparative analysis of e-government development in england and Ukraine. In <i>Public administration in the context of Ukraine’s integration into the European Union, vol. 2</i>. Ukrainian Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Articles · 2002 · 'Public Administration amid Ukraine's EU Integration', vol.2, Kyiv: Ukrainian Academy of Public Administration</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Humanitarian Policy: a textbook</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-186\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-186\" hidden><p>Textbook by Vitalii Skurativskyi, Volodymyr Troshchynskyi and Svitlana Chukut (UAPA Publishing House; Milenium, Kyiv, 2002, 262 pp.). One of the first systematic Ukrainian study guides devoted to the theoretical-methodological and applied aspects of public administration of the humanitarian sphere. The work comprehensively analyses the essence, structure and priorities of state humanitarian policy amid the transformation of Ukrainian society, with particular attention to the mechanisms of state regulation of the development of education, science, culture, language and information policy, and to the interaction of state authorities with civil-society institutions. The book systematises domestic and foreign experience of forming a state's humanitarian policy and establishes the basic conceptual and categorical apparatus for training specialists in public administration and local self-government; it became a basic source for teaching normative and elective disciplines in humanitarian and social policy in Ukrainian higher education institutions. Intended for students, master's students and doctoral candidates in the \"Public Management and Administration\" field, civil servants, local self-government officials and researchers.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Skurativskyi, V. A., Troshchynskyi, V. P., & Chukut, S. A. (2002). <i>Humanitarian policy in Ukraine</i>. UAPA Press and Milenium.</p><div class=\"m\">Books & monographs · 2002 · Kyiv: Ukrainian Academy of Public Administration; Milenium. — 262 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>114</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Humanitarian policy for cultural development</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-187\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-187\" hidden><p>This chapter in Humanitarian Policy in Ukraine examines the state’s role in cultural development and the institutional tools available to it. The chapter treats cultural development as an area of public policy and places government responsibilities in the context of support for cultural institutions and activities.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2002). Humanitarian policy for cultural development. In <i>Humanitarian policy in Ukraine</i>. Milenium. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Books & monographs · 2002 · Chapter. 'Humanitarian Policy'. Kyiv: Milenium</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Humanitarian policy for scientific development</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-188\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-188\" hidden><p>This chapter in Humanitarian Policy in Ukraine places science within public policy and examines the state’s responsibilities for research development. The chapter places scientific development within Ukraine’s humanitarian policy and considers the institutions and policy instruments that support research.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2002). Humanitarian policy for scientific development. In <i>Humanitarian policy in Ukraine</i>. Milenium. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Books & monographs · 2002 · Chapter. Ibid.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">State information policy in Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-189\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-189\" hidden><p>This chapter in part one of Information Policy examines Ukraine’s state priorities and the role of public institutions in the information sector. The analysis situates information policy among the responsibilities of the state, focusing on the institutions that develop it and the areas of public life it governs.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2002). State information policy in Ukraine. In <i>Information policy, part 1</i> (pp. 56–88). Ukrainian Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Books & monographs · 2002 · Chapter. 'Information Policy'. Part 1. Kyiv: Ukrainian Academy of Public Administration. Pp. 56–88</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diploma of Honour</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-190\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-190\" hidden><p>An honorary diploma conferred in 2002 by the National Academy of Public Administration under the President of Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>National Academy of Public Administration under the President of Ukraine. (2002). <i>Diploma of honour</i> [Award record].</p><div class=\"m\">Awards · 2002 · National Academy of Public Administration under the President of Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Choice and public opinion</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-191\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-191\" hidden><p>Examines choice and public opinion and the relation between them. The article connects individual choices with judgements that form and circulate in society. It places this relationship in the study of social and cultural mechanisms that shape collective decisions.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2001). Choice and public opinion. <i>Bulletin of the Academy of Cultural Executives</i>, (3).</p><div class=\"m\">Articles · 2001 · Bulletin of the Academy of Cultural Executives, No. 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Cultural policy of Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-192\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-192\" hidden><p>Examines the cultural policy of Ukraine. The study considers the role of public institutions in cultural development in Ukraine. It situates government action in a field that includes both heritage preservation and contemporary cultural practice.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2001). Cultural policy of Ukraine. <i>Bulletin of the Academy of Cultural Executives</i>, (3).</p><div class=\"m\">Articles · 2001 · Bulletin of the Academy of Cultural Executives, No. 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ethical and cultural dominants of the political process</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-193\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-193\" hidden><p>An article on the ethical and cultural dominants of the political process — tradition, stereotype and ritual as the forms that reproduce the generational integrity of spiritual culture. Chukut first names the negative moments in the relations between spiritual culture and politics: the domination of the political will to power by spiritless economic forces, its subjection to expansionist nationalism, and the distortion of originally spiritual concepts and of the noble national idea; with Alfred Weber's Germany as example, she ties these to the absence of an old political tradition able to absorb spiritual elements into practice, of that tradition's symbolic embodiment, and of definite guiding ideas pointing to humanity's mission. She then examines each dominant: tradition, which over time can lose adaptability and harden into a stereotype — stable, rigid and conservative, built of a cognitive image and an instrumental-practical attitude, and able in the political process to popularise a phenomenon according to public opinion and those who shape it; and ritual, which following Foucault she sets within politics as activity crystallised by a spiritual culture that is itself a code of conduct. Political ritual draws a magic circle around rulers even as mass media bring their images closer; it fixes legitimacy on a territory by reviving rituals that appeal to national memory and common patriotic values — flag, awards, invocations of the nation in leaders' speeches — thereby expressing the governed's cohesion around shared values, symbols and history and renewing collective approval of established power, as in a new leader's tour of the country. Alongside these consensual rituals stand rituals of confrontation — rallies and street demonstrations, symbols of antagonism that likewise require their supporters' physical presence — and she closes on the modern condition: political ritual is now unthinkable without mass media, above all television, which favours novelty, while ritual itself always sets tradition in motion by direct or hidden reference to it.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2001). Ethical and cultural dominants of the political process. <i>Collected Papers of Ukrainian Academy of Public Administration</i>.</p><div class=\"m\">Articles · 2001 · Collected papers of Ukrainian Academy of Public Administration</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ukraine's state cultural policy in contemporary world experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-194\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-194\" hidden><p>Examines Ukraine's state cultural policy in the context of contemporary world experience — its main directions and development trends. The comparative perspective places Ukraine’s priorities in the wider debate about the role of public institutions and the policy instruments that support culture.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (2001). Ukraine’s state cultural policy in the context of contemporary international experience: Key directions and development trends. <i>Bulletin of the State Academy of Culture and Arts Management</i>, (1), 12–19.</p><div class=\"m\">Articles · 2001 · Bulletin of the State Academy of Culture and Arts Management, No. 1, pp. 12–19</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICATE</div><div class=\"lib-copy\"><div class=\"t\">'Theory and Practice of Distance Learning'</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-195\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-195\" hidden><p>World Bank training on the principles of distance education and their application in practice. The subject connects distance education with course design, communication between learners and instructors, and the role of learning materials.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>World Bank. (2001). <i>&#x27;Theory and practice of distance learning&#x27;</i> [Training certificate].</p><div class=\"m\">Certificates · 2001 · World Bank</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Implementing state cultural policy as a priority for the humanitarian sphere</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-196\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-196\" hidden><p>An article arguing that implementing state cultural policy is the priority direction for developing Ukraine's humanitarian sphere. Opening from President Kuchma's address — that economic and social progress depends more on the spiritual and cultural component than on purely technical innovation, and that neglect of the humanitarian sphere has cost the state dearly — Chukut orders the concepts dialectically: state policy as the general realisation of the state's interests, humanitarian policy as its particular form addressed to citizens and their worldview, and cultural policy as the concrete realisation of the state's interests in culture, where culture is both the result and the means of a person's and a society's self-awareness and self-knowledge; cultural policy must therefore be integrative, spanning all spheres of social life. She defines the state's cultural policy by its first tasks — educating citizens, preserving cultural identity, upholding rituals and norms, and supporting citizens' creative contribution to spiritual culture — in line with UNESCO's definition, and insists that it is wrong to reduce it to either \"managing culture\" or \"supporting culture\": both are needed, expressed in clear priorities for what the state manages and funds. Citing Institute of Sociology data (1994–1998) on Ukrainians' shrinking access to their national culture and deteriorating opportunities to take part in cultural life, she faults the metaphysical approach that treats consequences rather than causes and borrows foreign forms uncritically. She then examines the European Union's first culture programme, Culture 2000 — its support for creativity, heritage, cultural diversity and a common European cultural space — within Ukraine's EU-integration strategy, and concludes that Ukraine's cultural policy must learn to answer the challenge of global economic change, drawing on the whole wealth of Ukrainian and world heritage to revive national identity and serve state-building.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (2000). Implementing state cultural policy as a priority for the humanitarian sphere. 'Ukraine: Advance Into the 21St Century', Kyiv: Ukrainian Academy of Public Administration.</p><div class=\"m\">Articles · 2000 · 'Ukraine: Advance into the 21st Century', Kyiv: Ukrainian Academy of Public Administration</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Conceptual analysis of choice in managing socio-cultural processes</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-197\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-197\" hidden><p>An article giving a conceptual analysis of choice as the mechanism by which, within continuity, the problem of attaining the ideal is resolved — social choice depending on the level of a society's developed needs. Chukut begins from the existentialist premise (Sartre, Camus) that a person is a self-made project who always chooses, even in catastrophe: submission can itself be conscious. With Lypynsky she holds that conscious choice in political creativity presupposes free will beside innate, spontaneous desires — the highest forms of culture were created by people and nations who believed in free will and chose between good and evil — while a person still inherits the statics of social life: the language, territory, state order and cultural level found at birth, which ease or complicate one's own creativity. Against Althusser's structuralism, in which the person is a puppet of the ideological state apparatus performing pre-written roles, she sets the ethical core of the problem: with Kierkegaard, the absolute choice is between good and evil, and what matters is the act of choosing itself, performed with energy and passion, by which the personality defines itself — delay is itself a loss, for life then chooses in one's stead. Reading Nietzsche's three metamorphoses of the spirit as three types of choice, she maps the camel (\"thou shalt\", the state choosing for the person) onto formal continuity and the child — the person who consciously chooses from humanity's accumulated heritage or creates what is missing — onto informal continuity, with the lion (\"I will\") as negation between them; choice thus actualises the content of continuity, and the more developed a society and its needs, the more consciously its choice of continuity is made.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Conceptual analysis of choice in managing socio-cultural processes. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1999 · Bulletin of Ukrainian Academy of Public Administration, No. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The state idea and the social ideal: their functional role in Ukraine's state-building</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-198\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-198\" hidden><p>An article on the functional role of the state idea and the social ideal in Ukraine's state-building. Chukut argues that a transforming society needs a single consolidating beginning that gives meaning to change across all spheres: historically this integrative function was performed by state religions (Hinduism in India, Confucianism in China, Protestantism in England) and in the modern world by ideologies such as Marxism-Leninism. She examines how the United States built its American Creed and how Japan — under its samurai elite, which preserved and developed the national culture while deliberately adopting Western technology, institutions and science, and rejecting Western individualism — modernised without losing itself, an experience she judges most useful for Ukraine. Through Ilyenkov, Kant, Marx, Novgorodtsev's absolute ideal and Weber's ideal types she distinguishes the ideal — society's unattainable model of what it strives to be — from the idea, the practical means of approaching it, and, following Franko on Drahomanov, holds that the lack of a national ideal was the chief tragedy of Ukraine's political efforts. Drawing on Tomashevsky's diagnosis of the missing single Ukrainian state idea and on Rymarenko, she traces the idea of an independent, united Ukraine from Cossack autonomy and Khmelnytsky's state through the Ukrainian People's Republic to the 1991 Act of Independence, sets out the state idea's apologetic, critical and futurological functions and the tasks of a state ideology, and proposes as Ukraine's integrating state idea national unity founded on developing its own culture, with critical respect — not blind copying — for the experience of other developed countries.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). The state idea and the social ideal: Their functional role in Ukraine's state-building. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 1999 · Bulletin of Ukrainian Academy of Public Administration, No. 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The role of modern mass media in state-building (selected aspects)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-199\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-199\" hidden><p>Examines selected aspects of the role of modern mass media in state-building processes. The article situates media in the circulation of public information and the formation of public opinion. These functions help explain their role in relations between institutions and society during state-building.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). The role of modern mass media in state-building (selected aspects). <i>Bulletin of Ukrainian Academy of Public Administration</i>, (3).</p><div class=\"m\">Articles · 1999 · Bulletin of Ukrainian Academy of Public Administration, No. 3</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The essence and role of public opinion in state-building</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-200\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-200\" hidden><p>An article on the essence and role of public opinion in state-building, built largely on Gabriel Tarde's Opinion and the Crowd. Chukut follows Tarde in distinguishing tradition, reason and public opinion as three branches of the social spirit: opinion develops last but spreads fastest, grows at the expense of the other two, and in modernity has become stronger than both tradition and institutional reason. She traces how individual judgements become public opinion — first through public speech and private conversation, then decisively through the book and above all the periodical press, which welded scattered local opinions into national and even international ones, levelled the weight of voices into a count, awakened national feeling along language borders, and made universal suffrage and parliamentary majority possible, so that power itself is now manufactured in cafés, clubs and salons and transformed by the press that feeds on it. With Hegel's Philosophy of Right she argues that publicity is the most effective means of forming state interests: only through public debate does public opinion gain true content, learn the state's real concerns and come to respect ability and office, while opinion itself — which fuses truth and error, the eternal principles of justice as common sense with prejudice — deserves both respect for its essential ground and contempt for its concrete utterance, and only a great person discerns the true within it. She closes with the public-relations understanding of public opinion as a dynamic consensus arising from coinciding attitudes, its measurable characteristics — direction, intensity, stability, information saturation and social support — and Hadley Cantril's laws of its formation, as the working basis for influencing it.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). The essence and role of public opinion in state-building. <i>Hrani</i>, (3(5)).</p><div class=\"m\">Articles · 1999 · Hrani, No. 3(5)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>17</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Heritage protection as a pressing contemporary issue</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-201\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-201\" hidden><p>Examines the protection of cultural heritage as a pressing issue of the present day. Heritage is treated as a public responsibility linked to cultural transmission. The subject encompasses both the conditions for preservation and the place of heritage in collective life.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Heritage protection as a pressing contemporary issue. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1999 · Collected papers of Ukrainian Academy of Public Administration, No. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Key aspects of cultural policy reform in Ukraine in light of world experience</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-202\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-202\" hidden><p>Examines the main aspects of reforming cultural policy in Ukraine in the context of world experience. The article links challenges in Ukraine with international experience. The comparison provides a way to examine the institutional choices involved in reforming cultural policy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Key aspects of cultural policy reform in Ukraine in light of world experience. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 1999 · Collected papers of Ukrainian Academy of Public Administration, No. 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problems of modern social institutions amid Ukraine's transformation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-203\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-203\" hidden><p>Examines the problems of how modern social institutions function amid the transformation of Ukrainian society. The article considers the pressures that transformation in Ukrainian society places on institutions that coordinate collective action and sustain social practices.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Problems of modern social institutions amid Ukraine's transformation. <i>Pressing Issues of Public Administration, Kharkiv</i>, (2).</p><div class=\"m\">Articles · 1999 · Pressing Issues of Public Administration, Kharkiv, No. 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The creative elite: a theoretical and methodological aspect</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-204\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-204\" hidden><p>A theoretical and methodological article on the creative elite and its place in spiritual culture. Chukut distinguishes the ruling elite, which decides what citizens should take from humanity's cultural heritage and what artists should create, from the creative elite, which is guided by personal values, creates and activates that heritage, and carries informal continuity — so the direction of continuity in spiritual culture depends on the elite's development, education and professionalism. Through Toynbee she presents civilisation as the work of creative individuals and minorities: the non-creative majority follows by mimesis, imitation directed in primitive societies at the older generation and in civilisations at creative personalities, whose withdrawal-and-return renews them; but mimesis is mechanical, and success breeds the \"nemesis of creativity\", when yesterday's creators fail the next challenge and block the new — whence the breakdown of civilisations through the creative minority's loss of creativity, the majority's refusal to follow a merely dominant minority, and the loss of social unity. Through Lypynsky she sets out the national aristocracy: the active minority that organises and rules the passive majority, holds material force (the will to power, the means of war and of production) and, indispensably, moral authority grounded in its own public morality and the masses' acceptance. She derives the social mechanism of the creative elite's formation from its functions — bearer of national culture's continuity and of the nation's identity, generator of new knowledge, guide of national revival, participant in the exchange of domestic and world experience, creator of national spiritual culture, guardian of values and historical memory, and driver of the national idea — and closes on the creative personality and the crowd, which mutually define each other: society's level shows in how wide a choice of paths it leaves the person, who may live \"parallel\" to the crowd by her own rules or confront it \"perpendicularly\", at the risk of destruction or, through mimesis, of changing social life itself.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). The creative elite: A theoretical and methodological aspect. <i>Pressing Issues of Public Administration, Odesa</i>, (1).</p><div class=\"m\">Articles · 1999 · Pressing Issues of Public Administration, Odesa, No. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Spiritual culture and the national question in Ukraine's state-building</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-205\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-205\" hidden><p>An article on the relationship between spiritual culture and the national question in Ukraine's state-building at the beginning of the twentieth century, when — as in Shevchenko, Kulish, Lesia Ukrainka, Franko, Drahomanov and Hrushevsky — national self-expression became the most pressing question of public life. Following Bochkovsky's development of Mancini, Chukut sets out culture's threefold significance for a nation: belonging to one cultural type unites a community while marking it off from others; a shared culture — above all language and writing — eases mutual understanding and manifests national belonging; and common cultural interests are a condition of the community's arising. She stresses, with Starosolsky, that historical tradition is not the past itself but the present's living experience of it, and, with Dnistriansky, that a people is constituted by nature, culture and territory, culture being the new factor without which a people does not become a people. Through Mikhnovsky she argues that nationalism is compatible with cosmopolitanism and humanism — save with chauvinism — and that the healthy nationalism of oppressed peoples is a source of creativity and freedom; through Lypynsky, that every nation is a product of history created by its national aristocracy's organisational work, that the statics of social life inherited from previous generations conditions its dynamics, and that political culture grows with accumulated experience, voluntarism and intelligence. She concludes that national self-consciousness, the leading role of the national — ruling and creative — elite, and the link between national culture and state-building remain pressing for state policy in every sphere of Ukraine's life.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Spiritual culture and the national question in Ukraine's state-building. <i>Pressing Issues of Public Administration, Lviv</i>, (2).</p><div class=\"m\">Articles · 1999 · Pressing Issues of Public Administration, Lviv, No. 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">What does Ukraine's current ruling elite lack? <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-206\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-206\" hidden><p>An article asking what Ukraine's present-day ruling elite lacks. Chukut first separates the ruling elite — which in culture decides what citizens should take from humanity's heritage and what artists should create — from the creative elite, and builds on Lypynsky's national aristocracy: an active minority whose power lasts only when its material force is legitimised by moral authority, itself formed by the aristocracy's public morality and by the masses' acceptance of its forms of organisation; a leading stratum with weak memory, weak conscious will and weak intelligence amid strong emotionality cannot give a nation political culture or a state life of its own. With Toffler she describes the worldwide decay of elites' capacity to take timely, competent decisions, the resulting power vacuum and \"black hole\" in society, the messianic faith in replacing the leader, and the three fallacies behind the demand for strong leadership — the myth of authoritarian efficiency, the assumption that yesterday's leadership style fits today, and the personalisation of what is in fact institutional collapse — arguing that the Third Wave requires leaders who listen, imagine and accept leadership's limits. For Ukraine, whose ruling elite as that of an independent state is still forming, she presents the 1996–1997 national surveys: the public identifies the elite with the richest (44%) and high office-holders (42%), only 15% with the best and most capable; trust has collapsed (President 17.6%, ministers 2.4%, deputies 3.9%), a third feel resentment or hostility toward the elite and 54% indifference, and Shchokin's profile shows an elite aged mostly 40–50 with predominantly technical education and too few specialists able to run the mechanism of continuity in spiritual culture — hence the irrational use of heritage, the dominance of mass culture and the devaluation of universal values. Against this she sets meritocratic cadre selection (France's National School of Administration, Tokyo University, the US Senior Executive Service; Ukraine's Administrative Reform Commission and the formative role of the Ukrainian Academy of Public Administration) and answers her title directly: what the ruling elite lacks is a single consolidating state idea — as the American Creed in the United States or, in Japan, the samurai elite's union of Eastern spirituality with Western technology, whose targeted modernisation preserved and even strengthened Japanese culture.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). What does Ukraine's current ruling elite lack? <i>Viche</i>, (6). <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf</a></p><div class=\"m\">Articles · 1999 · Viche, No. 6</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ritual: its place and role in managing continuity in spiritual culture</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-207\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-207\" hidden><p>Examines ritual, its place and significance in the system of managing continuity in spiritual culture. Ritual is considered as a repeated social practice that makes shared values visible and passes them between generations. The article places that role in the wider study of cultural continuity.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Ritual: Its place and role in managing continuity in spiritual culture. <i>Komandor</i>, (2).</p><div class=\"m\">Articles · 1999 · Komandor, No. 2</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Selected problems of ancient Chinese public administration in a contemporary context</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-208\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-208\" hidden><p>Examines selected problems of public administration in ancient China in a contemporary context. The comparison with contemporary issues provides a way to consider how authority is organised and which principles guide administration in different historical settings.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Selected problems of ancient chinese public administration in a contemporary context. <i>Komandor</i>, (3).</p><div class=\"m\">Articles · 1999 · Komandor, No. 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">European experience of improving cultural policy in building the Ukrainian state</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-209\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-209\" hidden><p>Examines European experience of improving cultural policy in the context of building the Ukrainian state. The European comparison places Ukraine’s cultural policy choices in the context of building public institutions and preserving cultural heritage.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). European experience of improving cultural policy in building the Ukrainian state. <i>'Ukraine on the Threshold of the Third Millennium', Kyiv</i>.</p><div class=\"m\">Articles · 1999 · 'Ukraine on the Threshold of the Third Millennium', Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The mechanism of continuity in spiritual culture</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-210\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-210\" hidden><p>Examines the mechanism by which continuity functions in spiritual culture. The work examines how values and practices are passed between generations. It forms part of the author’s research on continuity across institutions, cultural heritage and collective life.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). The mechanism of continuity in spiritual culture. <i>'Ukraine on the Threshold of the Third Millennium', Kyiv</i>.</p><div class=\"m\">Articles · 1999 · 'Ukraine on the Threshold of the Third Millennium', Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The Genesis of Spiritual Culture (the Management Dimension)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-211\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-211\" hidden><p>Chukut's monograph (Ukrainian Academy of Public Administration under the President of Ukraine, Kyiv, 1999; approved for publication by the Academy's Academic Council on 24 December 1998) studies the genesis of spiritual culture through the lens of public administration. Written at the turn of the millennium, it opens from the era's spiritual-culture problems — the devaluation of universal values, \"creativity to order\" measured by money and media accompaniment, the dominance of mass culture, the loss of trust in society's ideals, and the tension between uncritical borrowing of foreign culture and one-sided use of the national heritage. The first chapter traces the mutual conditioning of spiritual culture and state administration from the Ancient world through Hobbes (\"the state as a precondition of culture\") and Locke (\"tradition and civil society\"), German classical philosophy and the dialectical-materialist conception of history to the management of cultural continuity in the nineteenth and twentieth centuries. The second develops a methodology of continuity (succession): spiritual culture as a phenomenon of social life, its continuity characteristics and research methods, its subjects — the ruling elite as the subject of formal continuity and the creative elite of informal continuity — and its mechanisms, in which the ideal is the goal, choice the driver, and public opinion and values the medium. The third examines the forms of continuity — tradition as the principal form, the stereotype as its rudiment, innovation, ritual, habitus, archetype and symbol, and language as the transitional link between forms and means, including the language of politicians and its functioning in contemporary Ukrainian society. The fourth turns to the means: cultural heritage, social institutions and technical means, above all mass media and the computer production of information, within a national system of mass communication. An afterword draws the conclusions into state cultural policy — the support and management of culture.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (1999). <i>The genesis of spiritual culture (the management dimension)</i>. Ukrainian Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf</a></p><div class=\"m\">Books & monographs · 1999 · Monograph. Kyiv: Ukrainian Academy of Public Administration. — 256 pp.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>82</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Reproducing the generational integrity of spiritual culture (the management aspect)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-212\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-212\" hidden><p>Abstract of the Doctor of Sciences dissertation on how spiritual culture is transmitted across generations and the role of institutions and public administration in that continuity. The study examines the mechanisms by which one generation transmits its values and practices. It situates that question in public administration and cultural policy.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (1999). <i>Reproducing the generational integrity of spiritual culture (the management aspect)</i> [Doctor of Sciences dissertation abstract]. Ukrainian Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Books & monographs · 1999 · Doctoral thesis abstract. Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>10</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a><span class=\"scholar-record-note\">Google Scholar count for the record under the dissertation title.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Spiritual culture in Ukraine's humanitarian policy</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-213\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-213\" hidden><p>A scientific and methodological development prepared at the Ukrainian Academy of Public Administration under the President of Ukraine (Kyiv, 1999), setting out how spiritual culture figures in Ukraine's humanitarian policy. Its first part places culture within state-building: culture as a society's unwritten beliefs, evaluations and accepted rules — analysed through technology, economy, social organisation, religion and symbolism — and spiritual culture not as a frozen result but as the process of creating, accumulating, transmitting and using cultural acquisitions, whose core mechanism is continuity, the reproduction of a generation's cultural integrity. The second part examines Ukraine's state cultural policy: against the command-administrative concept of \"managing culture\", which subordinated culture to politics and economics, it sets the concept of \"supporting culture\" recognised by developed democracies and grounded in culture's intrinsic value, while arguing that the cultural sphere reaches far beyond the arts — to education, science, freedom of conscience and of speech — as in UNESCO's definition of cultural policy as the sum of a society's conscious actions aimed at cultural goals. The third part works through nine directions of state policy in spiritual culture: legislative support, the information sphere, cultural heritage, language policy, rituals, ceremonies and holidays, the development of the cultural and artistic sphere, the cultures of national minorities, youth culture, and international cooperation — with the Ministry of Culture and Arts as the central executive body implementing policy in the field.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1999). Spiritual culture in Ukraine's humanitarian policy. In <i>Programme Ukraine 2010</i>. Kyiv: Ukrainian Academy of Public Administration.</p><div class=\"m\">Books & monographs · 1999 · Chapter. 'Programme Ukraine 2010'. Kyiv: Ukrainian Academy of Public Administration</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Genesis of Spiritual Culture (management dimension) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-214\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-214\" hidden><p>Examines the genesis of spiritual culture from the standpoint of management. The book examines cultural transmission and the roles of institutions, language and media. It connects these mechanisms with the responsibilities of the state in supporting culture.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (1999). <i>Genesis of spiritual culture (management dimension)</i>. Ukrainian Academy of Public Administration under the President of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf</a></p><div class=\"m\">Articles · 1999</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a><span class=\"scholar-record-note\">These citations are included in the combined count on the monograph entry.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">The impact of state policy on the functioning of spiritual culture continuity forms</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-215\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-215\" hidden><p>An article examining how state policy shapes the functioning of the forms of continuity in spiritual culture — traditions, customs, innovations, rituals, stereotypes, laws and language — through which a society's social and historical experience is accumulated and transmitted. Chukut defines state policy in culture as the set of the state's goals in the cultural sphere, the principles it observes and the mechanisms that secure them, and takes tradition as the principal form of continuity: passing through formation, intensive development and decline, it accumulates the value-laden experience of past generations, while the stereotype is a tradition frozen and stripped of self-development, and innovation is continuity's external form that renews tradition's outward shapes. Drawing on Unamuno's \"eternal tradition\", Hayek and Laszlo's critique of modernism, she argues that cultural diversity is humanity's reserve of adaptation, and that state policy acts directly on which forms flourish: where the state creates conditions for a free economy, citizens' free choice and political freedom, innovation is activated first — a pattern recurring roughly every thirty years in Ukraine's spiritual culture, in the late 1920s, late 1950s and late 1980s thaws. She warns that mass and pop culture dehumanise, narrowing a person to material needs, and concludes that spiritual culture forms relatively independent thinking and citizenship, while the national idea produced by the state integrates citizens around a common future and shared values.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1998). The impact of state policy on the functioning of spiritual culture continuity forms. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1998 · Collected papers of Ukrainian Academy of Public Administration, No. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Language: mistress or maid?</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-216\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-216\" hidden><p>Poses the question of language's standing — mistress or maid? The title raises a question about the place of language in public life. The piece forms part of the author’s work on the relationship between language, culture and power.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1998). Language: Mistress or maid? <i>Komandor</i>, (1).</p><div class=\"m\">Articles · 1998 · Komandor, No. 1</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Hobbes's theory of the state as a precondition of culture in the context of Ukraine's democratisation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-217\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-217\" hidden><p>An article reading Thomas Hobbes's theory of the state as a precondition of culture against the problems of democratising Ukrainian society. Chukut notes that managing continuity in spiritual culture has always stood at the centre of state-building, and presents Hobbes as an early theorist of that control — and of alienation: people create the state, the \"great Leviathan\", by alienating much of their natural rights, whereupon it rises above its creators and rules them. For Hobbes, outside the state reign the passions, war, fear, poverty and barbarism; within it, reason, peace, security, wealth, the sciences and goodwill — only in the state is there a common measure of virtue and vice, namely its laws, and good dispositions reduce to justice and mercy. She follows his treatment of the instruments of control: religion, historically the first mechanism of state supervision over what people should believe, do and inherit — yet religion, for Hobbes, is not philosophy but law in each state; books and preachers that glorify tyrannicide breed Ravaillacs and Clements rather than citizens; and the sovereign holds the right to judge which doctrines are hostile to civil peace and to forbid them, above all doctrines of divided obedience, the root — she stresses with Hobbes — of every civil war in the Christian world. At the same time she draws out the limits Hobbes sets on power: freedom as the absence of impediments, the distinction between the people (one will, capable of one action) and the multitude, the rule that laws should pursue errors rather than the erring — since opinions are changed by persuasion, not threats — that sound civil doctrine must be codified and taught first in the universities, that rulers sin against their office by multiplying laws beyond the good of the state and its citizens, and that punishment should direct the will rather than break it. She concludes that studying and putting into practice such European experience is necessary for Ukraine's further democratisation.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. (1998). Hobbes's theory of the state as a precondition of culture in the context of Ukraine's democratisation. <i>Prydniprovskyi Visnyk</i>, (95–96).</p><div class=\"m\">Articles · 1998 · Prydniprovskyi Visnyk, No. 95–96</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">State Information Policy of Ukraine <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Open source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-218\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-218\" hidden><p>The document examines Ukraine’s state information policy and proposals for improving it, including issues of freedom of expression and government action. The document places access to information and freedom of expression within state policy. It connects them to the responsibilities of public authorities and regulation of the information sector.</p></div><p class=\"apa\"><span class=\"apa-label\">APA 7</span>Chukut, S. A. (n.d.). <i>State information policy of Ukraine</i>. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf</a></p><div class=\"m\">Books & monographs</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Svitlana Chukut’s Google Scholar profile</a></div></div></div>", "bio-projects-04": "Principal investigator — artificial intelligence, smart tourism and Ukraine’s recovery", "bio-projects-44": "Research and methodological guide: government–civil society engagement", "bio-projects-46": "Practical use of electronic government and governance — methodological recommendations", "page-egov-days-03": "National forum · Kyiv · 2008–2011", "egov-editions-23": "Launching a national forum", "media-events-02": "Talks and <span class=\"grad\">professional engagements</span>"}, "fr": {"bio-research-01": "Axes de recherche", "bio-research-02": "Axes et <span class=\"grad\">méthodes de recherche</span>", "bio-research-18": "Méthodes et démarche analytique", "research-theme-government": "Gouvernance numérique et confiance publique", "research-theme-ai": "IA, villes intelligentes et services publics", "research-theme-culture": "Information, culture et inclusion", "research-theme-learning": "Apprentissage numérique et compétences professionnelles", "bio-research-19": "<strong>Analyse comparative des politiques publiques.</strong> Ses travaux comparent les dispositifs institutionnels et les pratiques d’administration électronique entre pays, en tenant compte des conditions nécessaires à leur adaptation.", "bio-research-20": "<strong>Analyse documentaire et historique.</strong> La législation, les documents institutionnels et les archives permettent d’examiner l’évolution des responsabilités publiques, de la politique de l’information et des pratiques administratives.", "bio-research-21": "<strong>Études de cas et analyse de programmes.</strong> Les études de services électroniques et d’initiatives de villes intelligentes examinent leur mise en œuvre dans son contexte organisationnel, notamment la participation, la continuité des services et l’accès.", "bio-research-22": "<strong>Perspectives des parties prenantes.</strong> La consultation et les échanges avec les praticiens éclairent l’analyse des obstacles à la mise en œuvre et la formulation de recommandations pour les institutions publiques.", "bio-research-23": "<strong>Conception pédagogique fondée sur la recherche.</strong> Les travaux sur la gouvernance numérique, l’apprentissage assisté par l’IA et la ludification nourrissent les scénarios, les ressources pédagogiques et le perfectionnement professionnel.", "bio-research-24": "<strong>Données qualitatives et quantitatives.</strong> Son portfolio comprend des projets à méthodes mixtes et des travaux sur les compétences en IA des agents publics. La question de recherche et les données disponibles déterminent la démarche analytique.", "bio-research-25": "<strong>Mobilisation des connaissances.</strong> Les publications, les guides pratiques, les contributions aux politiques publiques et l’enseignement relient les résultats de recherche aux décisions institutionnelles et aux pratiques professionnelles.", "bio-research-26": "<strong>Accessibilité et inclusion.</strong> Ses travaux appliqués examinent les obstacles liés au handicap, à la langue et au contexte culturel. Les principes d’accessibilité orientent la conception des ressources pédagogiques numériques.", "page-courses-02": "Cours et programmes de formation", "courses-list-01": "Conception de cours", "courses-list-03": "La Prof. Svitlana Chukut a conçu les cours présentés ici dans le cadre de ses activités en Ukraine et au Canada. Le catalogue réunit enseignement universitaire, perfectionnement des agents publics et apprentissage numérique appliqué. Ouvrez un cours pour en consulter le contenu.", "courses-public-03": "Cette rubrique présente les cours conçus par la Prof. Svitlana Chukut à l’Académie nationale d’administration publique d’Ukraine et à l’Institut polytechnique de Kyiv Igor Sikorsky. Chaque notice précise le contexte du programme et le contenu disponible du cours.", "courses-kpi-02": "Catalogue des <span class=\"grad\">cours au KPI</span>", "courses-kpi-03": "Le catalogue du KPI présente 24 cours, avec le niveau du programme, les crédits ECTS, le statut, les dates de conception et les descriptions disponibles. Les cours sont classés par ordre alphabétique. Ouvrez un cours pour consulter son contenu et ses modalités d’évaluation.", "courses-kpi-06": "Cours obligatoire", "courses-kpi-54": "Cours obligatoire", "home-quick-17": "Cours universitaires et modules d’apprentissage appliqué conçus dans le cadre de ses activités universitaires et pédagogiques.", "home-quick-20": "Conférences, interventions publiques et forums, avec dates, rôles et documents justificatifs.", "home-quick-21": "événements documentés", "home-quick-32": "CV universitaires, certificats, distinctions et documents relatifs aux publications.", "home-quick-33": "documents et pièces justificatives", "mdMoreT": "Explorer les événements et interventions publiques", "alt-event-subcommission-2017": "Réunion élargie de la sous-commission pour la spécialité 281 « Gestion et administration publiques », Institut polytechnique de Kyiv Igor Sikorsky, le 12 octobre 2017", "description-book-76-title": "<p>Partie 7 du manuel en quinze parties « Gouvernement électronique et démocratie électronique » (Kyiv, 2017), préparé dans le cadre du programme EGAP « Le gouvernement électronique pour la responsabilité et la participation » avec le soutien de la Direction suisse du développement et de la coopération et approuvé par le Conseil académique de l'Académie nationale d'administration publique auprès du Président de l'Ukraine. La partie de Svitlana Chukut couvre le développement de l’administration électronique aux niveaux local et régional : les concepts de région électronique et de ville électronique (« ville intelligente »), l'état de l’administration électronique régional en Ukraine, l'expérience de mise en œuvre de Lviv et Vinnytsia, et les principales directions du développement de l’administration électronique à Kyiv, y compris les services administratifs électroniques au niveau local. Une deuxième section présente les meilleures pratiques étrangères — Australie, France, Suisse et Émirats arabes unis. La partie de 72 pages se termine par des questions d'auto-contrôle, une bibliographie recommandée et des travaux pour les séances pratiques, et s'adresse aux étudiants en administration publique, aux fonctionnaires et élus locaux en perfectionnement, ainsi qu'aux représentants des organisations de la société civile et des entreprises.</p>", "description-book-institutional-2011-title": "<p>Ouvrage collectif du programme de master en administration électronique, publié à Kyiv en 2011 (172 pages) sous la direction générale de Svitlana Chukut et Olha Zahvoiska, et titre inaugural de la série « Bibliothèque du gouvernement électronique ». Rédigé par les étudiants du programme dans le cadre du projet de recherche de la chaire sur les fondements de l’administration électronique, il examine comment sept pays — Autriche, Belgique, Irlande, Russie, Singapour, Thaïlande et Finlande — organisent le soutien institutionnel de l’administration électronique : organes responsables, coordination et législation. Svitlana Chukut a dirigé les travaux à l’origine du volume et enseigné la discipline de administration électronique dans le cadre de laquelle la recherche a été menée. Sa préface en tire la leçon pour l’Ukraine : créer une structure institutionnelle dédiée à la société de l’information et au administration électronique, et transformer les unités informatiques existantes des organes d’État et locaux en unités de administration électronique.</p>", "description-book-142-title": "<p>Matériaux méthodiques pour la discipline « Fondements théoriques, méthodologiques, organisationnels et institutionnels du gouvernement électronique », publiés à Kyiv en 2010 (166 pages) sous la direction scientifique de Svitlana Chukut et Olha Zahvoiska et approuvés par le conseil scientifique de l’Académie nationale. Rédigé par neuf étudiants du programme de master en administration électronique, le volume passe en revue les meilleures pratiques étrangères de mise en œuvre de l’administration électronique dans neuf pays — Australie, Inde, Canada, Allemagne, Norvège, Corée du Sud, Russie, Singapour et États-Unis — des indices de développement des Nations unies et des stratégies nationales aux portails et services phares. Svitlana Chukut a dirigé les travaux à l’origine du volume et enseigné la discipline pour laquelle ces matériaux ont été préparés.</p>", "description-book-143-title": "<p>Développement scientifique et méthodique (Kyiv, 2010, 64 p.) préparé par un collectif de quinze auteurs sous la direction scientifique de Svitlana Chukut, comme produit du projet de recherche « Mise en place de mécanismes d'interaction efficace entre le gouvernement, le public et les médias : aspect théorique et appliqué » (enregistrement d'État n° 0109U003027). Il examine la formation de la responsabilité civique et son rôle dans la société civile, l'interaction entre l'individu et l'État dans la perception de l'information, l'interaction gouvernement–public et l'influence des médias sur ces processus, la conception de projets socioculturels au niveau régional, les risques dans les projets de communication, et l'introduction par projets de l’administration électronique et de la démocratie électronique dans les régions, y compris le pilote « École de gouvernement électronique ». Il traite aussi de la propagande médiatique et des technologies de relations publiques « sales », des centres analytiques non gouvernementaux et de l'influence des médias sur la formation de la société civile ; il s'adresse aux étudiants, aux enseignants, aux instituts de la société civile et aux responsables gouvernementaux chargés des relations avec le public et les médias.</p>", "description-lib-book-11": "<p>Actes de la conférence scientifique et pratique tenue à l'Académie nationale d'administration publique auprès du Président de l'Ukraine pour la Journée de l’administration électronique, le 14 mai 2008 (Kyiv, 2008, 128 p. ; rédactrices générales Svitlana Chukut et Olha Zahvoiska ; recommandé par le Conseil académique de l'Académie, protocole n° 148/8-4 du 28 août 2008). Le volume présente des approches scientifico-pratiques, des résultats de recherche et des expériences de mise en œuvre dans l’administration électronique et la démocratie électronique : ses sections couvrent l’administration électronique au niveau central et au niveau local, les services électroniques, la démocratie électronique, et les principales tâches de l’administration électronique — y compris le rôle de la corporation Microsoft dans leur réalisation — et il se termine par les recommandations adoptées à l'issue de la Journée de l’administration électronique 2008. Les matériaux, tirés de l'expérience nationale et étrangère de pointe de l’administration électronique dans l'administration centrale, locale et régionale, s'adressent aux praticiens de l'administration publique et des entreprises, aux dirigeants des autorités étatiques et locales, des entreprises, des institutions et des organisations de la société civile, et à tous ceux qui étudient, recherchent, mettent en œuvre ou utilisent les technologies de administration électronique.</p>", "description-book-160-title": "<p>Recueil des meilleurs travaux créatifs des auditeurs de la nouvelle spécialité « Administration publique », rédigés pour la discipline « Gouvernement électronique » à l'Académie nationale d'administration publique auprès du Président de l'Ukraine (Kyiv, 2008, 200 p. ; collectif d'auteurs de dix auditeurs ; rédactrice générale Svitlana Chukut). Dix chapitres par pays passent en revue la manière dont l’administration électronique a été mise en œuvre en Grande-Bretagne, en Estonie, au Canada, en Allemagne, en Pologne, en Russie, à Singapour, aux États-Unis, en France et en Suède. Destiné à tous ceux qui s'intéressent aux problèmes de la mise en œuvre de l’administration électronique en Ukraine et dans le monde.</p>", "description-book-democracy-2008-title": "<p>Communication de Svitlana Chukut dans les actes de la Journée de l’administration électronique 2008 (p. 89–95). Elle définit la démocratie électronique comme l’État assurant les conditions préalables nécessaires à la participation des citoyens à l’élaboration et à l’adoption des décisions de l’État à l’aide des technologies modernes de l’information et de la communication, et explique que l’administration électronique construit la confiance entre le gouvernement et les citoyens sur laquelle elle repose — par la participation à la prise de décision, l’ouverture, la responsabilité et la prévention de la corruption. Elle expose les principales étapes de la formation de la démocratie électronique : l’e-information, un flux à sens unique des organes de l’État vers les citoyens (accès aux documents, catalogues, registres et index, projets de loi publiés et livres blancs et verts, rapports et guides en ligne, par courriel, portails web, communication mobile, kiosques d’information et disques — avec les problèmes connexes d’information confidentielle, de secrets d’État, de vie privée et de sécurité nationale) ; l’e-consultation, dans laquelle le gouvernement demande l’opinion des citoyens en ligne et reçoit demandes, plaintes, propositions et réponses à des sondages dans une relation bidirectionnelle limitée entravée par la fracture numérique ; l’e-participation, l’implication active des citoyens, fondée sur la rétroaction, dans la prise de décision et l’élaboration des politiques, via des forums et des clavardages gouvernementaux et publics, des jeux interactifs et des espaces de travail virtuels ; et l’e-partenariat, dans lequel la responsabilité des décisions est partagée par les deux parties sur une base de confiance mutuelle — une étape encore à ses débuts. Elle conclut avec les problèmes à résoudre — inégalité numérique, accès pour les personnes handicapées, illettrisme en TIC, personnel, capacité technique, financement, statut juridique et responsabilité, sécurité et vie privée — et les moyens de les résoudre, de la garantie de l’accès et de la réingénierie de la fonction publique à la modification de la législation et à la combinaison des TIC avec les moyens traditionnels.</p>", "description-book-169-title": "<p>Recommandations méthodiques compilées par Svitlana Chukut avec Tetiana Dzhyha, Oleksandr Poprotskyi, Anastasiia Borovska et Oleksandr Karpenko (Kyiv : Académie nationale d'administration publique, 2007), publiées dans le recueil de l'Académie « Développements scientifiques appliqués à l'usage des employés des autorités d'État et des collectivités locales » et approuvées par le conseil académique de l'Académie le 24 mai 2007. Les recommandations exposent les technologies et les mécanismes d'une interaction efficace entre les autorités d'État, les collectivités locales et le public, et offrent aux organes d'État et locaux des recommandations pratiques pour l'introduction de l’administration électronique. Elles s'adressent aux étudiants de master, aux doctorants et à tous ceux qui étudient l’administration électronique.</p>", "description-book-england-2002-title": "<p>Une analyse comparative de la construction de l’administration électronique en Angleterre et en Ukraine. La comparaison replace les premières initiatives ukrainiennes dans une perspective internationale. Elle permet d’examiner le rôle des stratégies publiques et des capacités administratives dans le passage aux démarches en ligne.</p>", "staticLibrary": "<div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Organisatrice de la XIIIe conférence scientifique et pratique internationale « Problèmes actuels de gestion » <a href=\"http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-0\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-0\" hidden><p>Participation à l’organisation de la treizième conférence scientifique et pratique « Problèmes contemporains de gestion », organisée par l’Institut polytechnique de Kyiv Igor Sikorsky en septembre 2025. La notice documente le rôle d’organisation de Svitlana Chukut dans une rencontre du département consacrée aux enjeux contemporains de la gestion et de l’administration publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2025, 25 septembre). <i>Organisatrice de la XIIIe conférence scientifique et pratique internationale « Problèmes actuels de gestion</i> [Notice de conférence]. <a class=\"apa-source\" href=\"http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/\" target=\"_blank\" rel=\"noopener\">http://fsp.kpi.ua/ua/xiii-mizhnarodna-naukovo-praktichna-konferentsiya-uspishno-vidbulasya/</a></p><div class=\"m\">Interventions · 2025 · Institut polytechnique de Kyiv Igor Sikorsky, 25.09.2025</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Approches innovantes du tourisme intelligent pendant la guerre et la relance d’après-guerre <a href=\"https://ela.kpi.ua/items/b5e7707d-f944-4157-b0a8-4d214682e58e\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-1\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-1\" hidden><p>À partir d'entretiens approfondis avec des experts, l'étude suit la manière dont les entreprises touristiques ukrainiennes se sont adaptées aux chocs combinés de la pandémie et de la guerre — instabilité financière, fermetures et migration de la main-d'œuvre. Elle identifie les stratégies qui ont fonctionné, de la transformation numérique et des services à distance aux offres personnalisées, et examine l'essor du tourisme militaire, solidaire et virtuel. En conclusion, elle fait d'un allègement fiscal, d'une meilleure réglementation et d'une expertise professionnelle renforcée les conditions de la reprise.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Yenin, M. N., Akimova, O. A., Ischenko, A. M., Perga, I. M. et Zahvoiska, O. V. (2025). Innovative approaches to smart tourism during war and post-war recovery: The case of Ukraine [Approches innovantes du tourisme intelligent pendant la guerre et la relance d’après-guerre : le cas de l’Ukraine]. <i>Bulletin of NTUU “KPI”: Political Science. Sociology. Law</i>, (1(65)), 58–67. <a class=\"apa-source\" href=\"https://doi.org/10.20535/2308-5053.2025.1(65).332550\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/2308-5053.2025.1(65).332550</a></p><div class=\"m\">Articles · 2025 · Bulletin de l’UNTU « KPI » : Science politique. Sociologie. Droit</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Évaluation des compétences des fonctionnaires ukrainiens dans l’utilisation des outils d’IA <a href=\"https://doi.org/10.52058/2708-7530-2024-10(52)-16-31\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-2\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-2\" hidden><p>Une enquête auprès des fonctionnaires ukrainiens, analysée par statistiques descriptives et méthodes multivariées, cartographie leur maîtrise actuelle des outils d'IA sous l'angle du genre. Elle montre comment le genre, l'âge et la catégorie d'emploi se relient à ces compétences et soutient qu'une conception sensible au genre rend les services appuyés par l'IA plus équitables et inclusifs. Les auteurs recommandent des programmes nationaux de formation à l'IA, des centres d'expérimentation et des politiques numériques sensibles au genre pour combler la fracture numérique entre les sexes.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Ishchenko, A. (2024). Assessment of skills in using AI tools among public servants in Ukraine [Évaluation des compétences des fonctionnaires ukrainiens dans l’utilisation des outils d’IA]. <i>Naukovi Perspektyvy</i>, (10(52)), 16–31. <a class=\"apa-source\" href=\"https://doi.org/10.52058/2708-7530-2024-10(52)-16-31\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.52058/2708-7530-2024-10(52)-16-31</a></p><div class=\"m\">Articles · 2024 · Naukovi perspektyvy, n° 10(52), p. 16–31</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Coordinatrice de la Faculté de sociologie et de droit de KPI pour la signature du mémorandum avec la Western Sydney University <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-3\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-3\" hidden><p>Coordination, pour la Faculté de sociologie et de droit du KPI, de la signature d’un protocole d’entente avec la Western Sydney University. Le protocole formalise une relation entre les deux établissements. La notice précise le rôle joué par la Faculté de sociologie et de droit dans cette démarche de coopération universitaire.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2024). <i>Coordinatrice de la Faculté de sociologie et de droit de KPI pour la signature du mémorandum avec la Western Sydney University</i> [Notice de collaboration]. <a class=\"apa-source\" href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\">https://icd.kpi.ua/?p=18255</a></p><div class=\"m\">Interventions · 2024 · Institut polytechnique de Kyiv Igor Sikorsky — WSU</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’organisation de la fourniture de services électroniques en Ukraine en temps de guerre <a href=\"https://doi.org/10.34132/pard2023.20.14\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-4\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-4\" hidden><p>Les auteurs examinent comment les autorités publiques et les collectivités locales ukrainiennes ont maintenu les services électroniques après l'invasion à grande échelle, en retraçant les effets propres de la guerre sur ce domaine. Ils comparent l'indice des services en ligne et l'indice de développement de l'administration électronique de l'Ukraine pour 2016-2022, y compris la méthodologie révisée de l'ONU en 2022, et cartographient les actes juridiques et les institutions — au premier rang le ministère de la Transformation numérique — qui portent la fourniture de ces services. L'article se conclut par des propositions de recherches ultérieures en temps de guerre, centrées sur les besoins des citoyens et des entreprises.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Karpenko, Y. (2023). Organising e-service delivery in Ukraine during wartime [L’organisation de la fourniture de services électroniques en Ukraine en temps de guerre]. <i>Public Administration and Regional Development</i>, (20), 589–613. <a class=\"apa-source\" href=\"https://doi.org/10.34132/pard2023.20.14\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.34132/pard2023.20.14</a></p><div class=\"m\">Articles · 2023 · Administration publique et développement régional, n° 20, p. 589–613</div><div class=\"publication-translations policy-document-actions\" role=\"group\" aria-label=\"Lire en traduction\"><a class=\"text-link\" href=\"article-translations/wartime-e-services-en.html\" lang=\"en\" hreflang=\"en\">English</a><a class=\"text-link\" href=\"article-translations/wartime-e-services-fr.html\" lang=\"fr\" hreflang=\"fr\">Français</a></div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>20</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">La numérisation des processus archivistiques dans le contexte de la formation du Fonds national d’archives <a href=\"https://doi.org/10.32702/2306-6814.2023.24.163\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-5\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-5\" hidden><p>À partir des pratiques archivistiques étrangères, l'article examine la numérisation du travail d'archive au moment où se forme le Fonds national d'archives de l'Ukraine et où il s'intègre à l'espace mondial de l'information. Il compare la NARA des États-Unis — et sa stratégie complète de conservation numérique : standardisation, planification des risques et gestion des fichiers — et les Archives nationales d'Australie, et considère aussi les expériences chinoise et polonaise. Les deux institutions s'appuient sur le stockage en nuage et utilisent l'intelligence artificielle pour automatiser le traitement des documents, notamment le renseignement des métadonnées, ce qui réduit les coûts de maintenance.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Karapoziuk, A. (2023). Digitising archival processes amid the national archival fond's formation [La numérisation des processus archivistiques dans le contexte de la formation du Fonds national d’archives]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (24), 163–170. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2023.24.163\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2023.24.163</a></p><div class=\"m\">Articles · 2023 · Investytsiyi: praktyka ta dosvid, n° 24, p. 163–170</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>8</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le tourisme intelligent pendant la guerre et la relance d’après-guerre : le cas de l’Ukraine <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-6\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-6\" hidden><p>L’étude examine les effets de la pandémie et de la guerre sur le tourisme ukrainien. Elle s’appuie sur des entretiens d’experts pour dégager des pistes de relance et des usages des outils numériques dans le secteur.</p><p>L’analyse distingue les difficultés rencontrées par les entreprises des réponses qu’elles ont mises en place, notamment l’adaptation de leurs offres et le recours aux services à distance.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Akimova, O., Ischenko, A., Yenin, M., Perga, I. et Zahvoiska, O. (2023). The smart tourism during the war and post-war recovery: The case of Ukraine [Le tourisme intelligent pendant la guerre et la relance d’après-guerre : le cas de l’Ukraine]. Dans <i>Business rejuvenation, resilience, and creativity in a changing world and post pandemic future: Book of papers and posters for the 2023 GISU International Research Symposium</i> (p. 18–23). Alliance GISU. <a class=\"apa-source\" href=\"https://imathm.edu.lk/files/documents/file_name/1ab71bb9-f35d-42f4-a006-6234f88ff6a3/book_of_papers_and_posters.pdf\" target=\"_blank\" rel=\"noopener\">https://imathm.edu.lk/files/documents/file_name/1ab71bb9-f35d-42f4-a006-6234f88ff6a3/book_of_papers_and_posters.pdf</a></p><div class=\"m\">Conférences · 2023 · Symposium GISU, Sydney, Australie (participante la plus active)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L'intelligence artificielle dans l'administration publique : défis et menaces</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-7\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-7\" hidden><p>Thèses de conférence dans les actes de la XIIe Conférence internationale « Problèmes contemporains de gestion » (Kyiv, 24 novembre 2023, p. 147–150). Svitlana Chukut note que les risques des TIC dans l'administration publique ont fortement augmenté avec l'intelligence artificielle — un champ ouvert au gouvernement par le rapport « Hello World » de l'OCDE — et, la candidature de l'Ukraine à l'Union européenne rendant la pratique européenne directement pertinente, examine l'approche de l'Union : investissement via Europe numérique et Horizon Europe, stratégie européenne pour les données, et cadre juridique fondé sur le risque arrêté en décembre 2023. Elle explique les niveaux de la loi sur l'IA : les systèmes à risque inacceptable sont interdits (manipulation cognitivo-comportementale, notation sociale, catégorisation biométrique, identification biométrique à distance en temps réel, avec d'étroites exceptions pour les forces de l'ordre) ; les systèmes à haut risque — pour la plupart dans l'administration publique, des infrastructures critiques et de l'éducation à l'emploi, aux services essentiels, aux forces de l'ordre, à la migration et à l'interprétation juridique, y compris les systèmes influençant les élections — exigent une évaluation avant déploiement et tout au long de leur cycle de vie, les citoyens obtenant le droit de se plaindre et de recevoir des explications ; l'IA générative doit divulguer le contenu généré par IA, empêcher le contenu illégal et publier des résumés des données d'entraînement, les modèles à usage général présentant un risque systémique étant évalués et leurs incidents signalés ; les systèmes à risque limité doivent une transparence minimale, comme l'étiquetage des hypertrucages. Les amendes pour non-conformité vont de 7,5 millions d'euros ou 1,5 pour cent du chiffre d'affaires à 35 millions d'euros ou 7 pour cent. Elle signale aussi le jeu de données ouvert de la plateforme ELISE sur les cas d'IA dans le secteur public (143 en décembre 2023) et l'usage du traitement du langage naturel par CitizenLab pour la participation civique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2023). Artificial intelligence in public administration: Challenges and threats [L&#x27;intelligence artificielle dans l&#x27;administration publique : défis et menaces]. Dans <i>Proceedings of the XII International Scientific-Practical Conference “Contemporary Problems of Management”</i> (p. 147–150). Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Conférences · 2023 · Actes de la XIIe conférence internationale « Problèmes contemporains de gestion », Kyiv, 24 novembre 2023, p. 147–150</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Orbicom « Transformation numérique de l’administration publique pour les objectifs de développement durable »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-8\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-8\" hidden><p>Comment les gouvernements et les villes peuvent-ils passer au numérique d'une manière qui aide aussi à atteindre les objectifs de développement durable — les objectifs mondiaux de l'ONU pour la santé, l'éducation, l'égalité et l'environnement ? Ce projet international du réseau Orbicom (mars 2023 – septembre 2025) étudie cette question, et Svitlana Chukut y participe comme chercheuse associée à l'Institut polytechnique de Kyiv Igor Sikorsky, où elle dirige le thème de recherche d'initiative enregistré de l'université, « Transformation numérique de l'administration publique et de l'autonomie locale : défis et possibilités pour atteindre les ODD » (n° d'enregistrement d'État 0123U101483) — une recherche fondamentale destinée à produire des documents méthodologiques et des matériaux analytiques. Les travaux suivent trois axes : la numérisation de l'administration publique aux niveaux national et local, avec notamment ses articles sur l'organisation des services électroniques en temps de guerre (avec Ye. Karpenko) et sur la numérisation des archives (avec A. Karapoziuk) ; les villes intelligentes et l'intelligence artificielle, avec notamment l'étude sur le tourisme intelligent, les systèmes énergétiques intelligents utilisant les mégadonnées (avec L. Shumska) et les défis et menaces de l'intelligence artificielle dans l'administration publique ; et l'impact de la numérisation sur les processus sociaux et l'administration publique. Pour la seule première période couverte par le rapport (mars 2023 – mai 2024), le thème a produit 12 articles dans des revues professionnelles (catégorie B) ; des travaux d'étudiants ont été préparés pour des concours internationaux — un travail d'O. Shyts et L. Shumska a remporté la 1re place au concours international sur les sciences de gestion, sociales et comportementales dans la mise en œuvre du développement durable — et pour le concours national de la jeunesse pour la Journée de la fonction publique ; et deux propositions de projet ont été élaborées : un projet ukraino-letton sur les compétences numériques et l'accès aux technologies numériques pour les femmes migrantes forcées ukrainiennes en Lettonie, et une proposition au Fonds national de recherche d'Ukraine sur la réintégration numérique et éducative des jeunes des territoires désoccupés et temporairement occupés. Les résultats alimentent directement l'enseignement : ils ont été mis en œuvre dans ses cours — Fondamentaux de l'administration électronique, Villes intelligentes, Démocratie électronique, Administration électronique et démocratie électronique, Orientations stratégiques du développement de l'administration électronique —, cinq cours à distance ont été développés et certifiés sur la plateforme Sikorsky (Moodle), et l'équipe a présenté ses travaux à quatre conférences et séminaires internationaux, dont le symposium de recherche GISU 2023.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Orbicom « Transformation numérique de l’administration publique pour les objectifs de développement durable</i> [Projet de recherche]. (2023–2025). Orbicom.</p><div class=\"m\">Projets · 2023–2025 · Participante</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Conférence publique « Comment les réseaux sociaux et la messagerie électronique sont devenus des armes dans la guerre de la Russie contre l’Ukraine » <a href=\"https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-9\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-9\" hidden><p>Conférence au Club Rotary de Kingston sur la manière dont les réseaux sociaux et la messagerie électronique servent à diffuser l’information et à façonner les récits pendant la guerre de la Russie contre l’Ukraine.</p><p>L’intervention situe les échanges sur ces plateformes dans le contexte plus large de la communication publique et de la circulation de l’information en temps de guerre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2023). <i>How social media &amp; e-messaging are the real weapons in the bitter Russia–Ukraine war</i> [Comment les réseaux sociaux et la messagerie électronique sont devenus des armes dans la guerre de la Russie contre l’Ukraine] [Conférence publique]. Club Rotary de Kingston, Ontario, Canada. <a class=\"apa-source\" href=\"https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war\" target=\"_blank\" rel=\"noopener\">https://kingstonrotary.ca/Stories/how-social-media-e-messaging-are-the-real-weapons-in-the-bitter-russia-ukraine-war</a></p><div class=\"m\">Interventions · 2023 · Club Rotary de Kingston, Ontario, Canada</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Participante la plus active du symposium international GISU <a href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-10\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-10\" hidden><p>Distinction pour la participation au symposium de recherche de l’Alliance GISU à Sydney, où ont été présentés des travaux sur la résilience du tourisme ukrainien. Les actes du symposium contiennent la contribution de l’équipe sur les réponses des entreprises touristiques ukrainiennes aux perturbations liées à la guerre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Alliance GISU. (2023). <i>Participante la plus active du symposium international GISU</i> [Document de reconnaissance]. <a class=\"apa-source\" href=\"https://icd.kpi.ua/?p=18255\" target=\"_blank\" rel=\"noopener\">https://icd.kpi.ua/?p=18255</a></p><div class=\"m\">Interventions · 2023 · Sydney, Australie</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement pour la préparation du lauréat d’un concours international (1re place)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-11\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-11\" hidden><p>Remerciements pour l’encadrement d’un travail étudiant arrivé en première place à un concours international de recherche.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Remerciement pour la préparation du lauréat d’un concours international (1re place)</i> [Document de reconnaissance]. (2023).</p><div class=\"m\">Distinctions · 2023 · Concours international</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L. Shumska et O. Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-12\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-12\" hidden><p>Travail de recherche étudiant « Garantir l’inclusion sociale dans les systèmes énergétiques intelligents pour atteindre le développement durable en conditions de guerre », par L. Shumska et O. Shyts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Première étude de l’inclusion sociale dans le contexte des systèmes énergétiques intelligents : il analyse l’expérience de la Pologne, de l’Écosse et du Royaume-Uni, ainsi que du Canada, et formule des recommandations pour implanter la meilleure expérience étrangère en Ukraine en conditions de guerre. Le travail a été présenté à trois conférences internationales et ses résultats ont été mis en œuvre à l’administration d’État du district de Solomiansk à Kyiv, à la centrale nucléaire de Khmelnytskyi d’Energoatom, au centre Sotsioplus et à la fondation caritative « Drevo Nadii » ; deux articles et quatre communications de conférence ont été publiés.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Shumska, L. et Shyts, O. (2023). <i>Ensuring social inclusion in smart power systems to achieve sustainable development in conditions of war</i> [Garantir l’inclusion sociale dans les systèmes énergétiques intelligents pour atteindre le développement durable en conditions de guerre] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/vitayemo-z-pershym-mistsem-na-mizhnarodnomu-konkursi-studentskyh-naukovyh-robit/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/vitayemo-z-pershym-mistsem-na-mizhnarodnomu-konkursi-studentskyh-naukovyh-robit/</a></p><div class=\"m\">Direction scientifique · 2023 · 1re place — Diplôme de 1er degré · concours international — Garantir l’inclusion sociale dans les systèmes énergétiques intelligents pour atteindre le développement durable en conditions de guerre</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">Enseignement innovant avec ChatGPT</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-13\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-13\" hidden><p>Formation sur l’intégration de ChatGPT dans l’enseignement et sur la conception d’activités pédagogiques faisant appel à l’IA générative. Dans un contexte de formation, ces usages invitent à préciser le rôle de l’outil dans une activité, la part du travail attendue des apprenants et les critères d’évaluation.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Vanderbilt University. (2023). <i>Enseignement innovant avec ChatGPT</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2023 · Vanderbilt University</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">Méthodes qualitatives de recherche</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-14\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-14\" hidden><p>Formation de l’Ukraine Global Faculty consacrée aux approches qualitatives et à leur utilisation dans la conception d’une recherche. Ces méthodes servent à étudier les expériences, les interprétations et les pratiques. Leur choix dépend de la question de recherche et du type de données nécessaires pour y répondre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ukraine Global Faculty. (2023). <i>Méthodes qualitatives de recherche</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2023 · Ukraine Global Faculty</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">Méthodes quantitatives de recherche</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-15\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-15\" hidden><p>Formation de l’Ukraine Global Faculty sur les méthodes quantitatives et leur application à l’étude de questions de recherche. Ce volet de la formation à la recherche traite de données mesurables et de leur analyse pour décrire des phénomènes, comparer des groupes ou étudier des relations entre variables.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ukraine Global Faculty. (2023). <i>Méthodes quantitatives de recherche</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2023 · Ukraine Global Faculty</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">TCPS 2 : CORE — Éthique de la recherche</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-16\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-16\" hidden><p>Formation canadienne sur l’éthique de la recherche avec des êtres humains, fondée sur l’Énoncé de politique des trois conseils. Le cadre canadien aborde notamment le consentement, la protection de la vie privée et l’évaluation des risques dans les projets qui font appel à des participants.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Tri-agency Institutional Programs Secretariat. (2023). <i>TCPS 2 : CORE — Éthique de la recherche</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2023 · Tri-agency Institutional Programs Secretariat</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">Formation linguistique renforcée (ELT)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-17\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-17\" hidden><p>Formation de COSTI destinée au développement des compétences linguistiques en anglais dans un contexte professionnel canadien. Le programme place l’apprentissage de la langue dans des situations de travail où il faut échanger avec des collègues, comprendre des consignes et communiquer avec le public.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>COSTI. (2023). <i>Formation linguistique renforcée (ELT)</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2023 · COSTI</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diversité culturelle dans les villes intelligentes : l’expérience de l’Union européenne et les défis pour l’Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-18\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-18\" hidden><p>Chapitre écrit avec Olha Zahvoiska pour la monographie collective « Repères européens de l’administration publique » (Kyiv, 2023), dans sa section consacrée à l’identité européenne et à la diversité culturelle. Il examine ce que la diversité culturelle signifie au sein d’une ville intelligente — infrastructure numérique inclusive, interfaces multilingues, patrimoine préservé numériquement, événements culturels et planification culturelle fondée sur les données — et présente les approches et le cadre juridique de l’Union européenne pour la protéger. Sur cette toile de fond, il passe en revue les défis pour l’Ukraine, de la fracture ethnique et linguistique et du fossé numérique à la destruction du patrimoine culturel par la guerre et au déplacement des communautés, et se conclut par des recommandations pour aligner la législation ukrainienne sur les villes intelligentes sur les exigences européennes.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Zahvoiska, O. (2023). Cultural diversity in smart cities: Experience of the European Union and challenges for Ukraine [Diversité culturelle dans les villes intelligentes : l’expérience de l’Union européenne et les défis pour l’Ukraine]. Dans Y. Lykhach (dir.), <i>European benchmarks of public administration</i> (p. 185–194).</p><div class=\"m\">Livres et monographies · 2023 · Chapitre 7.1. Dans : « Repères européens de l’administration publique ». Kyiv, 2023, p. 185–194</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en place de réseaux énergétiques intelligents comme composante de la ville intelligente grâce aux mégadonnées <a href=\"https://doi.org/10.32702/2306-6814.2022.3.88\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-19\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-19\" hidden><p>L'article établit les liens conceptuels entre ville intelligente, mégadonnées et réseaux énergétiques intelligents, puis examine les stratégies de gestion au Canada (Smart Metering Initiative), au Danemark (EcoGrid 2.0) et en Corée du Sud (le banc d'essai de l'île de Jeju). En Ukraine, constate-t-il, le comptage intelligent est déployé par les fournisseurs privés d'électricité plutôt qu'à l'initiative du gouvernement, sans définition juridique du réseau ou du compteur intelligent ni stratégie de transition approuvée. Il identifie les risques pour la vie privée et la cybersécurité et formule des recommandations pratiques pour appliquer l'expérience étrangère en évitant les cybermenaces.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Shumska, L. (2022). Smart grids as a smart-city component using big data [Mise en place de réseaux énergétiques intelligents comme composante de la ville intelligente grâce aux mégadonnées]. <i>Investytsiyi: Praktyka ta Dosvid</i>, <i>3</i>, 88–95. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2022.3.88\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2022.3.88</a></p><div class=\"m\">Articles · 2022 · Investytsiyi: praktyka ta dosvid, vol. 3, p. 88–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/osnovy-egu-2022-titlepage-hq.webp\" alt=\"Fondements de l’administration électronique : manuel\"><div class=\"lib-copy\"><div class=\"t\">Fondements de l’administration électronique : manuel <a href=\"https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-20\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-20\" hidden><p>Ce manuel électronique de 268 pages, publié en 2022 par l’Université technique nationale d’Ukraine « Institut polytechnique de Kyiv Igor Sikorsky », propose une introduction structurée à l’administration électronique. Il s’adresse aux étudiants de premier cycle de la spécialité 281, Administration et gestion publiques, notamment des programmes Gestion administrative et Administration électronique, ainsi qu’aux étudiants du cours transversal Fondements de l’administration électronique. Prof. Svitlana Chukut en est coautrice et rédactrice responsable, aux côtés des coautrices Olha Zahvoiska et Yana Tsymbalenko.</p><p>Ses huit chapitres relient les fondements conceptuels aux dimensions institutionnelles et sociales du gouvernement numérique. Ils traitent des modèles d’administration électronique et des obstacles à leur mise en œuvre; des méthodes et indices d’évaluation des Nations Unies, concernant notamment le développement de l’administration électronique, les services en ligne, les infrastructures de télécommunications, le capital humain, la participation électronique et les services locaux en ligne; puis de l’évolution de l’administration électronique en Ukraine.</p><p>L’étude des services publics numériques aborde leur maturité, l’interopérabilité, l’inclusion des groupes vulnérables et le portail Diia, avec des exemples autrichiens et danois. D’autres chapitres examinent la démocratie électronique, les pétitions, le parlement électronique et le vote électronique, notamment les normes du Conseil de l’Europe et les expériences des États-Unis et de l’Estonie. Le dernier chapitre analyse la guerre en réseau et la pandémie de COVID-19 comme défis pour la gouvernance numérique et la participation démocratique.</p><p>La démarche pédagogique dépasse l’acquisition de connaissances. L’introduction précise des compétences de recherche documentaire, d’analyse, de formulation de recommandations, de travail en équipe et de prise de décision. Le manuel comprend des travaux de recherche individuels, des exigences et des sujets de projets collectifs, un glossaire et une bibliographie. Cet ensemble favorise l’enquête autonome et l’examen des liens entre services numériques, participation, inclusion et risques de mise en œuvre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Zahvoiska, O. V. et Tsymbalenko, Y. Y. (2022). <i>Fundamentals of electronic governance</i> [Fondements de l’administration électronique]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/ab842173-d6da-430a-811e-b4923cbc5463</a></p><div class=\"m\">Livres et monographies · 2022 · Kyiv : Institut polytechnique de Kyiv Igor Sikorsky. — 268 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>74</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement pour la préparation du lauréat d’un concours international (2e place)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-21\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-21\" hidden><p>Remerciements de l’Université technique nationale du pétrole et du gaz d’Ivano-Frankivsk pour la direction d’un travail étudiant primé lors d’un concours international.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université technique nationale de pétrole et de gaz d’Ivano-Frankivsk. (2022). <i>Remerciement pour la préparation du lauréat d’un concours international (2e place)</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2022 · Université technique nationale de pétrole et de gaz d’Ivano-Frankivsk</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mykyta Skreminskyi <a href=\"https://ktpu.kpi.ua/dosiahnennia-kafedry/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-22\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-22\" hidden><p>Travail de recherche étudiant « L’administration électronique dans le processus de réalisation des objectifs de développement durable dans le contexte de la pandémie de COVID-19 », par Mykyta Skreminskyi, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail examine le rôle de l’administration électronique dans la réalisation des objectifs de développement durable des Nations unies pendant la pandémie de COVID-19, lorsque les restrictions de quarantaine ont fait de l’administration électronique un outil efficace contre la propagation de l’infection. Il analyse l’expérience internationale et ukrainienne des outils d’administration électronique employés contre la pandémie et formule des recommandations. Ses résultats ont été mis en œuvre au Centre éducatif et scientifique de sociologie appliquée « Sotsioplus » ; l’auteur compte trois publications.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Skreminskyi, M. (2022). <i>Electronic governance in the process of achieving sustainable development goals in the context of the COVID-19 pandemic</i> [L’administration électronique dans le processus de réalisation des objectifs de développement durable dans le contexte de la pandémie de COVID-19] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/dosiahnennia-kafedry/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/dosiahnennia-kafedry/</a></p><div class=\"m\">Direction scientifique · 2022 · 2e place — Diplôme de 2e degré · Concours international des travaux scientifiques étudiants « Managerial, Social and Behavioural Sciences in Implementing the Principles of Sustainable Development » — L’administration électronique dans le processus de réalisation des objectifs de développement durable dans le contexte de la pandémie de COVID-19</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Oleksandra Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-23\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-23\" hidden><p>Travail de recherche étudiant « Inclusion sociale et développement durable », par Oleksandra Shyts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie l’inclusion sociale et le développement durable, y compris l’inclusion numérique et l’inégalité numérique dans les villes intelligentes ; une enquête a mis en évidence des problèmes d’accessibilité, d’implication et d’égalité des chances en Ukraine et à Kyiv. Il analyse les meilleures pratiques étrangères et formule des recommandations pour l’Ukraine. Ses résultats ont été mis en œuvre au centre Sotsioplus ; l’auteure compte trois publications (2021).</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Shyts, O. (2022). <i>Social inclusion and sustainable development</i> [Inclusion sociale et développement durable] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2022 · 1re place — Diplôme de 1er degré · Ier tour · Concours panukrainien des travaux scientifiques étudiants « Gestion de l'e-business et des technologies intelligentes » — Inclusion sociale et développement durable</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Sofiia Potapenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-24\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-24\" hidden><p>Travail de recherche étudiant « L’expérience de mise en place de la ville intelligente à Zurich et les possibilités de son implantation en Ukraine » (code de concours « Compbeg »), par Potapenko, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail analyse le développement de la ville intelligente de Zurich, en Suisse, et les possibilités d’implanter cette expérience en Ukraine, en comparant les composantes et les étapes de développement des villes intelligentes en Suisse et en Ukraine. Il a été publié dans SWorldJournal (n° 11, 2022, Bulgarie) et présenté à la IIIe Conférence panukrainienne à Kyiv (2021) ; ses résultats et recommandations ont été mis en œuvre chez EVON LLC (certificat de mise en œuvre).</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Potapenko, S. (2022). <i>The experience of implementing the smart city in Zurich and the possibilities of its implementation in Ukraine</i> [L’expérience de mise en place de la ville intelligente à Zurich et les possibilités de son implantation en Ukraine] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2022 · 3e place — Diplôme de 3e degré · Ier tour · Concours panukrainien des travaux scientifiques étudiants « Gestion de l'e-business et des technologies intelligentes » — L’expérience de mise en place de la ville intelligente à Zurich et les possibilités de son implantation en Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Garantir l’inclusion sociale dans les villes intelligentes : défis et tendances actuelles <a href=\"https://doi.org/10.32702/2307-2156-2021.1.5\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-25\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-25\" hidden><p>L'étude dégage les notions d'inégalité numérique, de fracture numérique, d'illettrisme numérique et d'inclusion numérique et sociale, en montrant comment l'inégalité numérique approfondit l'inégalité sociale. Elle passe en revue les cadres juridiques aux niveaux international et européen et la pratique de villes intelligentes comme Vienne, et en tire les exigences essentielles d'accessibilité lorsque les technologies modernes ne sont pas adaptées aux citoyens les plus vulnérables. L'expérience ukrainienne est ensuite évaluée au regard de ces exigences, et des voies pour garantir l'inclusion en Ukraine sont proposées.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Shyts, O. (2021). Ensuring social inclusion in smart cities: Challenges and current trends [Garantir l’inclusion sociale dans les villes intelligentes : défis et tendances actuelles]. <i>Derzhavne Upravlinnia</i>, (1). <a class=\"apa-source\" href=\"https://doi.org/10.32702/2307-2156-2021.1.5\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2307-2156-2021.1.5</a></p><div class=\"m\">Articles · 2021 · Derzhavne upravlinnia, n° 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Stratégies de communication dans la gestion et l’administration publiques : expérience étrangère et ukrainienne <a href=\"https://doi.org/10.32702/2306-6814.2021.12.72\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-26\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-26\" hidden><p>Après avoir défini la communication, les stratégies de communication et la politique de communication, l'article compare la manière dont ces stratégies sont construites et mises en œuvre en Europe, en Amérique du Nord et en Asie — le projet participatif Consul à Madrid, la stratégie canadienne centrée sur les citoyens et le modèle local du Bangladesh. Il soutient qu'une stratégie ne fonctionne que si les rôles de chaque partie sont clairement définis, transformant l'idée centrale d'une organisation en messages clés pour chaque public. La pratique ukrainienne est analysée aux niveaux national et local, à travers la Verkhovna Rada et le conseil municipal de Merefa.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Yatsenko, V. (2021). Communication strategies in public management and administration: Foreign and Ukrainian experience [Stratégies de communication dans la gestion et l’administration publiques : expérience étrangère et ukrainienne]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (12), 72–79. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2021.12.72\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2021.12.72</a></p><div class=\"m\">Articles · 2021 · Investytsiyi: praktyka ta dosvid, n° 12, p. 72–79</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>44</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problèmes d’interprétation du « développement durable » dans l’administration publique de l’Ukraine : notion, traduction, communication <a href=\"https://doi.org/10.51547/ppp.dp.ua/2021.6.4\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-27\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-27\" hidden><p>Le travail rassemble les arguments et contre-arguments du débat scientifique sur la manière dont le « développement durable » est compris dans les documents politiques ukrainiens — un sens façonné par l'usage politique et par la traduction de l'anglais plutôt que par les seuls résultats de la recherche. En comparant les examens nationaux volontaires des pays dont l'Ukraine s'inspire (2017-2020) à la science et à la pratique ukrainiennes, il montre comment des lectures divergentes affectent la participation du public, la construction de partenariats et l'administration électronique. Il conclut que l'administration publique ukrainienne doit réévaluer ses approches appliquées, car l'ambiguïté du concept laisse le pays sans stratégie claire ni objectifs stables.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Drahomyretska, N., Romanenko, Y. et Sazykina, T. (2021). Interpreting 'sustainable development' in Ukraine's public administration [Problèmes d’interprétation du « développement durable » dans l’administration publique de l’Ukraine : notion, traduction, communication]. <i>Dnipro Scientific Journal</i>, (6). <a class=\"apa-source\" href=\"https://doi.org/10.51547/ppp.dp.ua/2021.6.4\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.51547/ppp.dp.ua/2021.6.4</a></p><div class=\"m\">Articles · 2021 · Revue scientifique de Dnipro, n° 6</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le contexte organisationnel et juridique de l’action du gouvernement ukrainien en matière de développement durable <a href=\"https://doi.org/10.51547/ppp.dp.ua/2021.5.1\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-28\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-28\" hidden><p>L'Ukraine, note l'article, importe l'expérience étrangère en matière de développement durable et l'adapte, plutôt que d'exporter la sienne — et sa science adapte de même les concepts étrangers. Les auteurs comparent la manière dont l'Ukraine et les pays dont elle s'inspire ont bâti les structures organisationnelles et consultatives chargées du développement durable. Ils constatent un écart entre les définitions juridique et scientifique du concept en Ukraine, qui fait sans cesse créer puis abolir ces structures et déstabilise l'orientation des politiques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Drahomyretska, N. et Romanenko, Y. (2021). The organisational and legal context of Ukraine's government action on sustainable development [Le contexte organisationnel et juridique de l’action du gouvernement ukrainien en matière de développement durable]. <i>Dnipro Scientific Journal</i>, (5). <a class=\"apa-source\" href=\"https://doi.org/10.51547/ppp.dp.ua/2021.5.1\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.51547/ppp.dp.ua/2021.5.1</a></p><div class=\"m\">Articles · 2021 · Revue scientifique de Dnipro, n° 5</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Administration publique et COVID-19 : défis et transformation numérique <a href=\"https://doi.org/10.20535/spu2021.249115\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-29\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-29\" hidden><p>La COVID-19 a agi comme un catalyseur qui a forcé le changement dans la gestion publique à un rythme accéléré, les gouvernements devant décider vite sous la pression de la force majeure. Au-delà des défis déjà fixés par les objectifs de développement durable de l'ONU, la pandémie a approfondi la fracture numérique, la pauvreté et la faim et fait peser une menace réelle sur la vie des citoyens. L'article fait de ces pressions combinées le point de départ de la transformation numérique de la gestion publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2021). Public management and COVID-19: Challenges and digital transformation [Administration publique et COVID-19 : défis et transformation numérique]. Dans <i>Proceedings of the XI International Scientific-Practical Conference “Contemporary Problems of Management”</i> (p. 323–326). Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://doi.org/10.20535/spu2021.249115\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/spu2021.249115</a></p><div class=\"m\">Articles · 2021 · Actes de la XIe conférence internationale, p. 323–326</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Administration publique et COVID-19 : défis et transformation numérique <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-30\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-30\" hidden><p>Thèses de conférence dans lesquelles Svitlana Chukut traite la pandémie de COVID-19 comme un catalyseur de changement accéléré dans l'administration publique. Suivant la Banque mondiale, elle regroupe les défis en santé, économie et fiscalité, ajoute les risques de corruption des achats d'urgence, et note comment la crise a révélé une coordination faible, des institutions fragiles, une reddition de comptes insuffisante et le patronage — ainsi que le danger que les gouvernements utilisent l'urgence pour usurper le pouvoir et restreindre les droits. Elle expose les directions d'action gouvernementale en pandémie définies par l'OCDE, de la confiance publique et du gouvernement numérique à la gestion des risques et à l'intégrité publique, et le rôle de la transformation numérique : comme l'a observé Liu Zhenmin, des Nations unies, les technologies numériques ont permis aux gouvernements de continuer à communiquer et à fournir des services en ligne pendant toute la pandémie, même si les problèmes de vie privée et de désinformation se sont aigusés. Les thèses présentent le Recueil d'initiatives de gouvernement numérique des Nations unies en réponse à la COVID-19 et examinent en détail les outils construits par l'État français — avant tout Tchap, la messagerie gouvernementale sécurisée gérée par la Direction interministérielle du numérique (plus de 200 000 utilisateurs en novembre 2021), aux côtés des web- et audioconférences d'État, de la plateforme de communautés professionnelles Osmose et de l'espace de travail collaboratif Resana. Elle conclut que les réponses doivent adapter les modèles de fonctionnement, de service et d'interaction avec les citoyens aux outils numériques, fonder l'action collective sur la confiance — « se rassembler tout en restant séparés » — et développer un gouvernement efficace, inclusif et responsable.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2021). <i>Public management and COVID-19: Challenges and digital transformation</i> [Administration publique et COVID-19 : défis et transformation numérique] [Communication plénière]. XIe conférence internationale « Problèmes contemporains de gestion », Kyiv, Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2021/12/spu2021.pdf</a></p><div class=\"m\">Conférences · 2021 · Communication PLÉNIÈRE. XIe conférence internationale « Problèmes actuels de gestion », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Audit des systèmes de gestion et d’engagement des parties prenantes de l’entreprise d’État NAEK « Energoatom »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-31\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-31\" hidden><p>Rendre une centrale nucléaire plus sûre ne concerne pas seulement les équipements : les travaux touchent les personnes qui y travaillent et les communautés qui vivent aux alentours, et ces personnes doivent être correctement informées et associées. En 2021, Svitlana Chukut a réalisé, comme exécutante du projet, un audit du volet social de ces travaux au sein de l'entreprise d'État NAEK « Energoatom », l'opérateur nucléaire de l'Ukraine. L'audit portait sur l'activité de l'entreprise en matière sociale — concernant son personnel et la population — pendant la mise en œuvre du Programme complexe (consolidé) de renforcement de la sécurité des unités des centrales nucléaires ukrainiennes et du Plan de mesures environnementales et sociales, dans le cadre d'un contrat de recherche entre l'Institut polytechnique de Kyiv Igor Sikorsky et Energoatom (n° D/0201.01/3011.01) ; côté client, les travaux relevaient du chef du thème de recherche, Anatolii Melnychenko. Du 27 août au 20 septembre 2021, les travaux ont associé l'audit lui-même à un accompagnement méthodologique, analytique et organisationnel de la recherche sociologique. Leur cœur : l'examen et l'analyse de la conformité du système de gestion d'Energoatom et de son système d'information et d'implication des parties prenantes à la législation ukrainienne, aux exigences de la Banque européenne pour la reconstruction et le développement (BERD) et aux meilleures pratiques mondiales. Les travaux comprenaient aussi l'analyse experte de la documentation de l'entreprise, la collecte de données supplémentaires et, au besoin, des vérifications directement sur les sites des centrales nucléaires, puis une analyse finale et une discussion des résultats avec le client. Le produit final a été un rapport scientifique (rapport d'audit) assorti d'un résumé exécutif en ukrainien, en russe et en anglais, et l'acte de réception signé confirme que les travaux ont été réalisés en totalité.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Audit des systèmes de gestion et d’engagement des parties prenantes de l’entreprise d’État NAEK « Energoatom</i> [Projet de recherche]. (2021). Energoatom.</p><div class=\"m\">Projets · 2021 · Exécutante du projet</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">GISU « Projets de recherche sur les villes intelligentes et le tourisme »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-32\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-32\" hidden><p>Comment le tourisme ukrainien peut-il continuer à fonctionner pendant la guerre — et se reconstruire ensuite ? C'est la question au cœur de cette recherche de l'Alliance GISU sur les villes intelligentes et le tourisme, à laquelle Svitlana Chukut participe pour l'Institut polytechnique de Kyiv Igor Sikorsky. À partir d'entretiens approfondis avec des experts, le travail examine comment les entreprises touristiques ont fait face aux chocs combinés de la pandémie et de la guerre à grande échelle — difficultés financières, fermetures et départs de personnel — et présente les approches qui ont aidé : le passage au numérique, les services à distance, des offres adaptées à chaque voyageur, et de nouvelles formes comme le tourisme militaire, solidaire et virtuel. L'objectif est pratique : avec un allègement fiscal, des règles plus claires et une expertise professionnelle renforcée, le tourisme ukrainien peut se relever et devenir plus résilient.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>GISU « Projets de recherche sur les villes intelligentes et le tourisme</i> [Projet de recherche]. (2021–). Alliance GISU.</p><div class=\"m\">Projets · 2021–… · Participante de l’Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">GISU « Stratégies d’entreprise innovantes face à l’impact de la COVID-19 sur le tourisme »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-33\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-33\" hidden><p>Quand la COVID-19 a arrêté les voyages, les entreprises touristiques ont dû réinventer leur manière de travailler presque du jour au lendemain. Ce projet de l'Alliance GISU (2021–2024) a recueilli et comparé les nouvelles stratégies commerciales qui ont aidé le tourisme à traverser la pandémie. Son objectif : un cadre pratique — un ensemble de lignes directrices — pour aider le tourisme à se relever et à devenir plus résilient après la COVID-19 ; Svitlana Chukut y a participé comme participante associée à l'Institut polytechnique de Kyiv Igor Sikorsky.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>GISU « Stratégies d’entreprise innovantes face à l’impact de la COVID-19 sur le tourisme</i> [Projet de recherche]. (2021–2024). Alliance GISU.</p><div class=\"m\">Projets · 2021–2024 · Participante</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diplôme, 2e place, « Meilleures pratiques d’innovation pédagogique »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-34\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-34\" hidden><p>Diplôme de deuxième place décerné par l’Agence nationale de la fonction publique d’Ukraine pour une pratique d’innovation pédagogique élaborée avec Yana Tsymbalenko.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Agence nationale de la fonction publique d’Ukraine. (2021). <i>Diplôme, 2e place, « Meilleures pratiques d’innovation pédagogique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2021 · Agence nationale d’Ukraine pour la fonction publique (co-auteure Ya. Yu. Tsymbalenko)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement en qualité de membre du comité d’organisation de l’Olympiade d’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-35\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-35\" hidden><p>Remerciements du KPI pour l’organisation d’une olympiade étudiante consacrée à l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2021). <i>Remerciement en qualité de membre du comité d’organisation de l’Olympiade d’administration électronique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2021 · Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement en qualité de membre du jury de l’Olympiade d’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-36\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-36\" hidden><p>Remerciements du KPI pour la participation au jury d’une olympiade consacrée à l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2021). <i>Remerciement en qualité de membre du jury de l’Olympiade d’administration électronique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2021 · Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement pour la préparation d’une lauréate (O. Chyts, 2e place)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-37\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-37\" hidden><p>Remerciements de l’Université nationale d’économie Vadym Hetman de Kyiv pour l’encadrement d’un travail étudiant primé.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale d’économie de Kyiv Vadym Hetman. (2021). <i>Remerciement pour la préparation d’une lauréate (O. Chyts, 2e place)</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2021 · Université nationale d’économie de Kyiv Vadym Hetman</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Oleksandra Shyts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-38\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-38\" hidden><p>Travail de recherche étudiant « L’inclusion sociale comme déterminant du développement des technologies intelligentes » (code de concours « Buty poruch »), par Oleksandra Shyts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie les tendances actuelles de l’inclusion sociale comme déterminant du développement des technologies intelligentes, à partir de la meilleure expérience étrangère et ukrainienne ; une enquête a mis en évidence des problèmes d’accessibilité, d’implication et d’égalité des chances. Il analyse les pratiques étrangères et formule des recommandations pour l’Ukraine. Le travail a été présenté à la IIe Conférence scientifique internationale sur les technologies scientifiques et pratiques (Luxembourg, 2021) et à la IVe Conférence scientifique et pratique internationale de Tchernihiv (2021) ; ses résultats sont utilisés au centre Sotsioplus. Un article dans une revue professionnelle (catégorie B) et deux communications à des conférences internationales ont été publiés.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Shyts, O. (2021). <i>Social inclusion as a determinant of the development of smart technologies</i> [L’inclusion sociale comme déterminant du développement des technologies intelligentes] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2021 · 2e place — Diplôme de 2e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — L’inclusion sociale comme déterminant du développement des technologies intelligentes</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Lidiia Shumska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-39\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-39\" hidden><p>Travail de recherche étudiant « La gestion des systèmes énergétiques intelligents à l’aide des mégadonnées : les meilleures pratiques étrangères » (code de concours « Systèmes énergétiques intelligents »), par L. Shumska, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail examine les meilleures pratiques étrangères de gestion des systèmes énergétiques intelligents à l’aide des mégadonnées et les possibilités de les implanter en Ukraine. Il a été présenté à la XIe Conférence scientifique et pratique internationale « Problèmes actuels de gestion : transformation de l’administration publique dans le monde post-COVID » ; ses résultats ont été mis en œuvre à l’administration d’État du district de Solomiansk à Kyiv et à la centrale nucléaire de Khmelnytskyi d’Energoatom. Un article et une communication de conférence ont été publiés.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Shumska, L. (2021). <i>Managing smart power systems using big data: Best foreign practices</i> [La gestion des systèmes énergétiques intelligents à l’aide des mégadonnées : les meilleures pratiques étrangères] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2021 · 2e place (2022) — Diplôme de 2e degré · Ier tour · Concours panukrainien des travaux scientifiques étudiants « Gestion de l'e-business et des technologies intelligentes » ; 2e place (2022) — Diplôme de 2e degré · Ier tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — La gestion des systèmes énergétiques intelligents à l’aide des mégadonnées : les meilleures pratiques étrangères</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-40\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-40\" hidden><p>Travail de recherche étudiant « Modernisation de la gestion des infrastructures et des transports par l’application des technologies de l’Internet des objets » (code de concours « Mobilité intelligente »), par Anna Kruts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie la modernisation de la gestion des infrastructures et des transports par l’application des technologies de l’Internet des objets. Il examine les fondements théoriques de l’Internet des objets dans le contexte de l’administration électronique, la structure de la gestion des transports et des infrastructures en Ukraine, l’expérience étrangère de l’Internet des objets dans les transports et les infrastructures ainsi que les tendances actuelles de la mobilité intelligente, le cadre juridique et la pratique ukrainiens, et les perspectives de l’Internet des objets dans ce domaine, et formule des conclusions et des recommandations.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kruts, A. (2021). <i>Modernisation of infrastructure and transport management through the application of Internet of Things technologies</i> [Modernisation de la gestion des infrastructures et des transports par l’application des technologies de l’Internet des objets] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2021 · Modernisation de la gestion des infrastructures et des transports par l’application des technologies de l’Internet des objets</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">Fondements de la théorie des tests</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-41\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-41\" hidden><p>Formation du ministère ukrainien de l’Éducation et des Sciences sur la théorie des tests et sur la conception et la révision des questions d’évaluation. La théorie des tests aide à examiner le lien entre la compétence à évaluer et les questions utilisées pour en recueillir des preuves.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ministère de l’Éducation et des Sciences de l’Ukraine. (2021). <i>Fondements de la théorie des tests</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2021 · Ministère de l’Éducation et des Sciences de l’Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Formation de la pensée scientifique ukrainienne moderne sur l’histoire du développement de l’administration électronique nationale : aspect interdisciplinaire <a href=\"https://doi.org/10.20535/2307-5244.51.2020.220187\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-42\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-42\" hidden><p>À partir d'une décennie de travaux en administration publique, science politique, économie, droit, histoire et sciences techniques, les auteurs caractérisent l'état actuel de la pensée ukrainienne sur l'histoire de l'administration électronique nationale. Ils cartographient les principales directions de recherche et les cadres théoriques, et dégagent les lacunes et controverses qui demandent encore étude. Le discours est divisé en six étapes, de la prise de conscience des nouvelles technologies dans les années 1990 à une sixième étape, ouverte en 2019, de développement intensif, de nouveaux modèles théoriques et de consolidation de la base de recherche.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Drahomyretska, N. et Mykhailutsa, M. (2020). The formation of Ukrainian scholarly thought on the history of domestic e-governance [Formation de la pensée scientifique ukrainienne moderne sur l’histoire du développement de l’administration électronique nationale : aspect interdisciplinaire]. <i>Storinky Istorii</i>, (51). <a class=\"apa-source\" href=\"https://doi.org/10.20535/2307-5244.51.2020.220187\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.20535/2307-5244.51.2020.220187</a></p><div class=\"m\">Articles · 2020 · Pages d’histoire, n° 51 (Web of Science)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>9</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diplôme, 3e place, « Meilleures pratiques d’innovation pédagogique » <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-43\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-43\" hidden><p>Diplôme de troisième place attribué par l’Agence nationale de la fonction publique d’Ukraine lors de son concours de pratiques d’innovation pédagogique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Agence nationale de la fonction publique d’Ukraine. (2020). <i>Diplôme, 3e place, « Meilleures pratiques d’innovation pédagogique</i> [Document de reconnaissance]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/10/IMG_20201009_121507.jpg</a></p><div class=\"m\">Distinctions · 2020 · Agence nationale d’Ukraine pour la fonction publique</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Certificat pour la préparation des lauréats d’un concours</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-44\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-44\" hidden><p>Reconnaissance de l’Université nationale du commerce et de l’économie de Kyiv pour l’encadrement d’étudiants lauréats d’un concours.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale de commerce et d’économie de Kyiv. (2020). <i>Certificat pour la préparation des lauréats d’un concours</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2020 · Université nationale de commerce et d’économie de Kyiv</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Nazarii Volytskyi</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-45\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-45\" hidden><p>Travail de recherche étudiant « Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés », par Nazarii Volytskyi et Vladyslav Trachuk, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants (3e place).</p><p>Le travail examine en particulier la continuité des démarches administratives lorsque l’accès aux services en personne est limité.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Volytskyi, N. et Trachuk, V. (2020). <i>Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories</i> [Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf</a></p><div class=\"m\">Direction scientifique · 2020 · 3e place — Diplôme de 3e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés ; 1re place — Diplôme de 1er degré · Concours panukrainien des travaux créatifs parmi les jeunes à l'occasion de la Journée de la fonction publique (Agence nationale d'Ukraine pour la fonction publique), 2020</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mariia Ruban</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-46\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-46\" hidden><p>Travail créatif de Mariia Ruban, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Lauréate du concours panukrainien des travaux créatifs parmi les jeunes à l'occasion de la Journée de la fonction publique (Agence nationale d'Ukraine pour la fonction publique), 2020 — 1re place, diplôme de 1er degré.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Travail primé au concours créatif pour la Journée de la fonction publique</i> [Notice de distinction étudiante]. (2020). Agence nationale de la fonction publique d’Ukraine.</p><div class=\"m\">Direction scientifique · 2020 · 1re place — Diplôme de 1er degré · Concours panukrainien des travaux créatifs parmi les jeunes à l'occasion de la Journée de la fonction publique (Agence nationale d'Ukraine pour la fonction publique)</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Vladyslav Trachuk</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-47\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-47\" hidden><p>Travail de recherche étudiant « Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés », par Nazarii Volytskyi et Vladyslav Trachuk, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants (3e place).</p><p>Le travail examine en particulier la continuité des démarches administratives lorsque l’accès aux services en personne est limité.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Volytskyi, N. et Trachuk, V. (2020). <i>Electronic services as an effective tool for the reintegration of temporarily uncontrolled territories</i> [Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-trachuk-volytskyy.pdf</a></p><div class=\"m\">Direction scientifique · 2020 · 3e place — Diplôme de 3e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Les services électroniques comme outil efficace de réintégration des territoires temporairement non contrôlés</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-48\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-48\" hidden><p>Travail de recherche étudiant « Introduction des services électroniques dans le domaine de la santé à l’aide des technologies de l’Internet des objets », par Anna Kruts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie l’introduction des services électroniques dans le domaine de la santé à l’aide des technologies de l’Internet des objets. Il examine les fondements théoriques et méthodologiques des services électroniques et de l’Internet des objets, les fondements conceptuels et juridiques de l’introduction des services électroniques de santé en Ukraine, les meilleures pratiques étrangères — l’Internet des objets dans les services médicaux électroniques, la dépersonnalisation des données, l’expérience des États-Unis en matière de dossiers médicaux électroniques dans le contexte de l’anonymisation des données personnelles et les services médicaux électroniques dans les pays de l’Union européenne — ainsi que les tendances actuelles en Ukraine, notamment l’élaboration et la mise en œuvre du système « e-Health » et des systèmes électroniques d’information médicale, et les voies d’amélioration des services électroniques de santé en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kruts, A. (2020). <i>Introducing electronic services in healthcare using Internet of Things technologies</i> [Introduction des services électroniques dans le domaine de la santé à l’aide des technologies de l’Internet des objets] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-kruts.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2020/12/naukovo-doslidna-robota-studentiv-kruts.pdf</a></p><div class=\"m\">Direction scientifique · 2020 · 3e place — Diplôme de 3e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Introduction des services électroniques dans le domaine de la santé à l’aide des technologies de l’Internet des objets</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Karina Feshchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-49\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-49\" hidden><p>Travail de recherche étudiant « La fourniture de services électroniques dans le contexte du développement des villes intelligentes », par Karina Feshchenko, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail examine la fourniture de services électroniques dans le contexte du développement des villes intelligentes : l’utilisation des données électroniques à Singapour, les services électroniques en Estonie et au Danemark, l’expérience de Chicago et le programme « Kyiv Smart City » ; il évalue la fourniture de services électroniques au Forum des villes intelligentes d’Ukraine et formule des conclusions pour l’Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Feshchenko, K. (2020). <i>Providing electronic services in the context of smart city development</i> [La fourniture de services électroniques dans le contexte du développement des villes intelligentes] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2020 · La fourniture de services électroniques dans le contexte du développement des villes intelligentes</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Recommandations méthodologiques pour la préparation et la soutenance du travail de qualification <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2020/02/recommendation_am_qualification-work-bakalavrat.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-50\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-50\" hidden><p>Guide destiné aux étudiants du programme de gestion administrative. Il explique comment préparer un travail de fin d’études et organiser sa soutenance. Le document s’adresse aux étudiants de premier cycle du programme de gestion administrative. Il présente les étapes de préparation du travail ainsi que les attentes relatives à sa rédaction, à sa présentation et à sa soutenance.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ivanytska, O. M., Melnychenko, A. A., Chukut, S. A. et Bryl, Y. O. (2020). <i>Methodological recommendations for preparing and defending a qualification thesis</i> [Recommandations méthodologiques pour la préparation et la soutenance du travail de qualification]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/0e9d12d7-bd6a-4e02-8118-4f314070e6c4\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/0e9d12d7-bd6a-4e02-8118-4f314070e6c4</a></p><div class=\"m\">Livres et monographies · 2020 · Institut polytechnique de Kyiv Igor Sikorsky</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Recommandations méthodologiques sur la rédaction, le contenu et la présentation du travail de qualification <a href=\"https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-51\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-51\" hidden><p>Le guide précise les exigences de contenu, de rédaction, de présentation et de soutenance des travaux de fin d’études du baccalauréat en administration électronique. Destiné au programme de premier cycle en administration électronique, le guide aide à distinguer les exigences relatives à la structure du mémoire de celles qui concernent sa présentation et sa soutenance.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Tsymbalenko, Y. Y., Arkhypova, Y. O. et Bryl, Y. O. (2020). <i>Methodological recommendations on the writing, content and formatting of a qualification thesis</i> [Recommandations méthodologiques sur la rédaction, le contenu et la présentation du travail de qualification]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93\" target=\"_blank\" rel=\"noopener\">https://ela.kpi.ua/items/456c067e-f67c-4aa2-ab02-f9683c086d93</a></p><div class=\"m\">Livres et monographies · 2020 · Institut polytechnique de Kyiv Igor Sikorsky</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Meilleures pratiques européennes et ukrainiennes de fourniture de services électroniques aux populations vulnérables <a href=\"https://doi.org/10.32702/2306-6814.2019.5.91\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-52\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-52\" hidden><p>L'article passe en revue la pratique de l'UE en matière d'appui aux personnes handicapées et aux retraités par les services électroniques — y compris le suivi annuel des services publics numériques — et les projets qui encouragent les personnes limitées dans leurs capacités à utiliser les TIC modernes, en soulignant les axes du Danemark. La fourniture ukrainienne est ensuite analysée sous l'angle de la qualité et de l'accessibilité, et jugée juridiquement insuffisante : la loi n'exige presque pas d'adapter les e-services aux groupes vulnérables ni de les servir en priorité. Les auteurs élaborent l'indice d'accessibilité de l'utilisation des services électroniques en Ukraine (AIES) pour mesurer le recours, l'accessibilité et la qualité.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Tsiptsiura, T. (2019). Best European and Ukrainian e-service practices for vulnerable populations [Meilleures pratiques européennes et ukrainiennes de fourniture de services électroniques aux populations vulnérables]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (5), 91–97. <a class=\"apa-source\" href=\"https://doi.org/10.32702/2306-6814.2019.5.91\" target=\"_blank\" rel=\"noopener\">https://doi.org/10.32702/2306-6814.2019.5.91</a></p><div class=\"m\">Articles · 2019 · Investytsiyi: praktyka ta dosvid, n° 5, p. 91–97</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>9</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en place de services électroniques en Ukraine pour les catégories vulnérables de citoyens <a href=\"https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-53\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-53\" hidden><p>Intervention à une table ronde à Vinnytsia sur l’accès des personnes vulnérables aux services publics numériques en Ukraine. La question centrale est l’accessibilité des démarches en ligne pour des personnes qui rencontrent des obstacles d’accès à Internet, d’équipement ou de compétences numériques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2019). Implementation of electronic services in Ukraine for vulnerable groups of citizens [Mise en place de services électroniques en Ukraine pour les catégories vulnérables de citoyens]. Dans S. O. Dorohykh (dir.), <i>Soutien informationnel, juridique, organisationnel et administratif au développement régional innovant : actes de la table ronde</i> (p. 124–128). Artek. <a class=\"apa-source\" href=\"https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf\" target=\"_blank\" rel=\"noopener\">https://ippi.org.ua/sites/default/files/vinnicya_materiali_kruglogo_stolu_druk.pdf</a></p><div class=\"m\">Conférences · 2019 · Table ronde, Vinnytsia · Actes de la table ronde, p. 124–128</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Du gouvernement électronique à la gouvernance intelligente : défis et menaces actuels <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-54\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-54\" hidden><p>Communication plénière à Kyiv sur le passage de l’administration électronique à une gouvernance qui mobilise les données et les outils numériques pour améliorer l’action publique. La communication place la prestation de services numériques dans un cadre plus large qui comprend l’organisation des institutions, l’usage de l’information et les relations avec les citoyens.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2019). From e-government to smart governance: Current challenges and threats [Du gouvernement électronique à la gouvernance intelligente : défis et menaces actuels]. Dans <i>Problèmes contemporains de gestion : la gouvernance dans le contexte des transformations numériques</i> (p. 8–10). Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/11/spu2019.pdf#page=8</a></p><div class=\"m\">Conférences · 2019 · Communication PLÉNIÈRE. Xe conférence internationale « Problèmes actuels de gestion », Kyiv · Actes de la conférence, p. 8–10</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-55\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-55\" hidden><p>Distinction officielle du ministère de l’Éducation et des Sciences d’Ukraine inscrite au dossier professionnel de Svitlana Chukut.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ministère de l’Éducation et des Sciences de l’Ukraine. (2019). <i>Remerciement</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Ministère de l’Éducation et des Sciences de l’Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Distinction honorifique du Conseil académique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-56\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-56\" hidden><p>Distinction honorifique décernée par le conseil académique de l’Institut polytechnique de Kyiv Igor Sikorsky.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Conseil académique du KPI. (2019). <i>Distinction honorifique du Conseil académique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Certificat pour la préparation des lauréats (1re place — T. Tsiptsioura)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-57\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-57\" hidden><p>Remerciements de l’Université nationale du commerce et de l’économie de Kyiv pour la direction de travaux étudiants primés en 2019.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale de commerce et d’économie de Kyiv. (2019). <i>Certificat pour la préparation des lauréats (1re place — T. Tsiptsioura)</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Université nationale de commerce et d’économie de Kyiv</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement pour le travail au sein de la commission sectorielle d’un concours</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-58\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-58\" hidden><p>Remerciements de l’Université nationale du commerce et de l’économie de Kyiv pour la participation aux travaux d’un comité de concours.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale de commerce et d’économie de Kyiv. (2019). <i>Remerciement pour le travail au sein de la commission sectorielle d’un concours</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Université nationale de commerce et d’économie de Kyiv</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement en qualité de membre du jury de l’Olympiade d’administration publique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-59\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-59\" hidden><p>Remerciements de l’Institut polytechnique de Kyiv Igor Sikorsky pour la participation au jury d’une olympiade étudiante.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2019). <i>Remerciement en qualité de membre du jury de l’Olympiade d’administration publique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diplôme, 2e place, « Meilleures pratiques d’innovation pédagogique »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-60\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-60\" hidden><p>Diplôme de deuxième place décerné en 2019 par l’Agence nationale de la fonction publique d’Ukraine lors d’un concours de pratiques d’innovation pédagogique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Agence nationale de la fonction publique d’Ukraine. (2019). <i>Diplôme, 2e place, « Meilleures pratiques d’innovation pédagogique</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2019 · Agence nationale d’Ukraine pour la fonction publique</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Tetiana Tsiptsiura</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-61\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-61\" hidden><p>Travail de recherche étudiant « Introduction des services électroniques pour les populations vulnérables : la meilleure expérience étrangère et ukrainienne », par Tetiana Tsiptsiura, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants en « Administration et gestion publiques » (1re place). Le travail étudie les tendances actuelles de l’introduction des services électroniques pour les populations vulnérables, à partir de la meilleure expérience étrangère et ukrainienne. Il souligne que la commodité et l’accessibilité des e-services sont décisives pour les personnes ayant des besoins particuliers et que les groupes vulnérables courent un risque élevé d’isolement numérique. Il analyse le cadre juridique et les pratiques étrangères, évalue l’état et les problèmes de l’introduction des e-services en Ukraine, élabore un indice de calcul de l’accessibilité de l’utilisation des e-services en Ukraine et formule des recommandations pour implanter la meilleure expérience étrangère.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Tsiptsiura, T. (2019). <i>Introducing electronic services for vulnerable populations: The best foreign and Ukrainian experience</i> [Introduction des services électroniques pour les populations vulnérables : la meilleure expérience étrangère et ukrainienne] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-tsiptsyura.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-tsiptsyura.pdf</a></p><div class=\"m\">Direction scientifique · 2019 · 1re place — Diplôme de 1er degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » ; 2e place — Diplôme de 2e degré · IIe tour · Olympiade étudiante panukrainienne dans la spécialité « Administration et gestion publiques » (2019) — Introduction des services électroniques pour les populations vulnérables : la meilleure expérience étrangère et ukrainienne</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Anna Kruts</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-62\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-62\" hidden><p>Travail de recherche étudiant « Tendances actuelles de l’application des technologies de l’Internet des objets à la mise en œuvre de l’administration électronique au niveau local », par Anna Kruts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants en « Administration et gestion publiques » (2e place, 2019 ; 3e place, 2020). Le travail étudie les tendances actuelles de l’application des technologies de l’Internet des objets à la mise en œuvre de l’administration électronique au niveau local. Il considère les technologies de l’Internet des objets comme une condition nécessaire du développement des villes intelligentes et examine les fondements théoriques et juridiques de l’Internet des objets, en relevant les menaces croissantes d’utilisation abusive de ces technologies et d’atteintes à la vie privée.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kruts, A. (2019). <i>Current trends in the use of Internet of Things technologies in implementing e-governance at the local level</i> [Tendances actuelles de l’application des technologies de l’Internet des objets à la mise en œuvre de l’administration électronique au niveau local] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2019 · 2e place (2019) — Diplôme de 2e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Tendances actuelles de l’application des technologies de l’Internet des objets à la mise en œuvre de l’administration électronique au niveau local</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Karina Feshchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-63\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-63\" hidden><p>Travail de recherche étudiant « Les meilleures pratiques étrangères de développement des villes intelligentes et les possibilités de leur implantation en Ukraine » (code de concours « Znaiemo yak ! »), par Karyna Feshchenko, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail analyse les meilleures pratiques étrangères de développement des villes intelligentes et les possibilités de leur implantation en Ukraine : le concept et les technologies de base des villes intelligentes, le cadre juridique en Ukraine, l’expérience de Singapour, d’Amsterdam et de Chicago, le programme « Kyiv Smart City » et le Forum des villes intelligentes d’Ukraine, et formule des recommandations pour l’Ukraine. Ses résultats et recommandations peuvent servir à améliorer le développement des villes intelligentes en Ukraine, en particulier dans les travaux du Département des technologies de l’information du conseil municipal de Vinnytsia. Le travail a été présenté à cinq conférences en 2017–2018 : la conférence scientifique et pratique « Internet des objets : problèmes de régulation juridique et de mise en œuvre » (Kyiv, 2017 et 2018), la conférence scientifique et pratique internationale « Problèmes contemporains de gestion : impératifs pour assurer le développement durable » (Kyiv, 2017), la conférence scientifique et pratique internationale de Poltava (2018) et la conférence panukrainienne « Forum de la démocratie directe » (Kyiv, 2018).</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Feshchenko, K. (2019). <i>Best foreign practices of smart city development and the possibilities of their implementation in Ukraine</i> [Les meilleures pratiques étrangères de développement des villes intelligentes et les possibilités de leur implantation en Ukraine] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-feschenko-2019.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2019/12/naukovo-doslidna-robota-studentiv-feschenko-2019.pdf</a></p><div class=\"m\">Direction scientifique · 2019 · 2e place — Diplôme de 2e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Les meilleures pratiques étrangères de développement des villes intelligentes et les possibilités de leur implantation en Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">« Experte en accréditation des programmes d’études » (Prometheus)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-64\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-64\" hidden><p>Formation offerte sur Prometheus pour préparer les spécialistes à évaluer les programmes d’études dans le cadre de l’accréditation de l’enseignement supérieur. Dans le contexte de l’assurance qualité, l’évaluation porte notamment sur la cohérence entre les objectifs d’un programme, son contenu et les résultats d’apprentissage attendus.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Agence nationale d’assurance qualité de l’enseignement supérieur. (2019). <i>Experte en accréditation des programmes d’études » (Prometheus)</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2019 · Agence nationale d’assurance qualité de l’enseignement supérieur</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Blockchain ou système de gestion électronique des documents : tendances actuelles de mise en œuvre dans les organes du pouvoir exécutif de l’Ukraine <a href=\"http://www.investplan.com.ua/?op=1&z=5871&i=12\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-65\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-65\" hidden><p>L'article examine la mise en œuvre de la circulation électronique de documents dans les organes exécutifs de l'Ukraine, avec une attention particulière au blockchain — la technologie moderne des registres distribués. Svitlana Chukut et K. Buryachenko analysent les systèmes de circulation électronique de documents les plus répandus dans les organes exécutifs ainsi que les principaux actes juridiques qui les régissent, et étudient l'expérience d'utilisation des technologies modernes de l'information et de la communication dans les organes exécutifs, notamment à l'Agence nationale de la fonction publique d'Ukraine. Elles identifient les principaux problèmes qui entravent la mise en œuvre efficace des systèmes de circulation électronique de documents en Ukraine et analysent les approches modernes d'application de la technologie blockchain dans le développement de l’administration électronique, en notant les principaux problèmes de la technologie et les risques de son introduction. Elles concluent que l'introduction de technologies blockchain sans expérimentation appropriée peut engendrer des problèmes encore plus grands que les avantages revendiqués de leur utilisation.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Buriachenko, K. O. (2018). Blockchain or an electronic document management system: Implementation trends in Ukraine’s executive authorities [Blockchain ou système de gestion électronique des documents : tendances actuelles de mise en œuvre dans les organes du pouvoir exécutif de l’Ukraine]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (1), 70–77. <a class=\"apa-source\" href=\"https://library.wunu.edu.ua/libsearch/DocDescription?doc_id=379092\" target=\"_blank\" rel=\"noopener\">https://library.wunu.edu.ua/libsearch/DocDescription?doc_id=379092</a></p><div class=\"m\">Articles · 2018 · Investytsiyi: praktyka ta dosvid, n° 1, p. 70–76</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>31</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Application du principe « numérique par défaut » : problèmes et perspectives</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-66\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-66\" hidden><p>Communication à Kyiv sur le principe du numérique par défaut et sa mise en œuvre dans le cadre du droit de l’information. Le sujet soulève des questions sur la traduction des procédures administratives dans un environnement numérique et sur l’accès aux services lorsqu’un canal en ligne devient le choix par défaut.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2018). <i>Applying the &#x27;digital by default&#x27; principle</i> [Application du principe « numérique par défaut » : problèmes et perspectives] [Communication à un colloque]. « Droit de l’information », Kyiv, Ukraine.</p><div class=\"m\">Conférences · 2018 · « Droit de l’information », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Administration électronique : réalités et défis</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-67\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-67\" hidden><p>Conférence publique dans le cadre d’une olympiade nationale au KPI sur l’état de l’administration électronique et les obstacles à sa mise en œuvre. Présentée dans un cadre de formation en administration publique, l’intervention relie les outils numériques aux conditions institutionnelles et aux compétences nécessaires pour les mettre en œuvre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2018). <i>E-governance: Realities and challenges</i> [Administration électronique : réalités et défis] [Conférence publique]. Olympiade panukrainienne, Institut polytechnique de Kyiv Igor Sikorsky, Kyiv, Ukraine.</p><div class=\"m\">Conférences · 2018 · Conférence ouverte. Olympiade panukrainienne, Institut polytechnique de Kyiv Igor Sikorsky</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">« Tendances actuelles de mise en œuvre de l’administration électronique en Ukraine »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-68\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-68\" hidden><p>L'Ukraine transférait de plus en plus de services publics en ligne — mais quelles approches fonctionnaient vraiment ? Dirigée par Svitlana Chukut, cette recherche enregistrée par l'État (2018–2020, n° 0118U100305) a passé en revue la manière dont l'administration électronique — les services et démarches publics en ligne — était mise en place dans tout le pays. Elle a recueilli les exemples les plus réussis (« meilleures pratiques ») pour que d'autres administrations puissent s'inspirer de ce qui fonctionnait déjà.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Tendances actuelles de mise en œuvre de l’administration électronique en Ukraine</i> [Projet de recherche]. (2018–2020). Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Projets · 2018–2020 · Directrice de recherche · Enregistrement d’État n° 0118U100305</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Certificat pour la préparation des lauréats d’un concours de travaux étudiants</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-69\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-69\" hidden><p>Reconnaissance de l’Université nationale du commerce et de l’économie de Kyiv pour l’encadrement d’étudiants primés lors d’un concours en 2018.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale de commerce et d’économie de Kyiv. (2018). <i>Certificat pour la préparation des lauréats d’un concours de travaux étudiants</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2018 · Université nationale de commerce et d’économie de Kyiv</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Arina Kuts <a href=\"https://ktpu.kpi.ua/kuts-arina-dvichi-peremozhnitsya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-70\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-70\" hidden><p>Travail de recherche étudiant « Le transfert des achats publics au format électronique comme instrument efficace de lutte contre la corruption », par Arina Kuts, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie le transfert des achats publics au format électronique comme instrument efficace de lutte contre la corruption. Il examine les fondements théoriques des achats publics — leur notion, leur essence, leurs principes de base et le cycle des achats —, l’expérience internationale des achats publics et l’architecture des systèmes électroniques d’achats publics, ainsi que le fonctionnement du système électronique d’achats publics « ProZorro » comme instrument de lutte contre la corruption, et les problèmes et perspectives de développement des achats publics électroniques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kuts, A. R. (2018). <i>Transferring procurement to electronic format as an effective tool for combating corruption</i> [Le transfert des achats publics au format électronique comme instrument efficace de lutte contre la corruption] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-kruts-2018.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-kruts-2018.pdf</a></p><div class=\"m\">Direction scientifique · 2018 · 1re place — Diplôme de 1er degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » ; 1re place — Diplôme de 1er degré · IIe tour · Olympiade étudiante panukrainienne dans la spécialité « Administration et gestion publiques » — Le transfert des achats publics au format électronique comme instrument efficace de lutte contre la corruption</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Maria Pashchak</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-71\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-71\" hidden><p>Travail de recherche étudiant « Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique », par Maria Pashchak et Olena Plotnikova, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants (2e place).</p><p>L’étude compare notamment le soutien aux jeunes entreprises au Chili avec les services fédéraux et l’identité électronique en Belgique, puis examine les possibilités d’adaptation en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pashchak, M. Z. et Plotnikova, O. V. (2018). <i>Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</i> [Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf</a></p><div class=\"m\">Direction scientifique · 2018 · 2e place — Diplôme de 2e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Olena Plotnikova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-72\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-72\" hidden><p>Travail de recherche étudiant « Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique », par Maria Pashchak et Olena Plotnikova, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Présenté au concours panukrainien des travaux de recherche étudiants (2e place).</p><p>L’étude compare notamment le soutien aux jeunes entreprises au Chili avec les services fédéraux et l’identité électronique en Belgique, puis examine les possibilités d’adaptation en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pashchak, M. Z. et Plotnikova, O. V. (2018). <i>Directions for implementing the e-governance development experience of Chile and Belgium in Ukraine</i> [Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-pashhak-plotnikova.pdf</a></p><div class=\"m\">Direction scientifique · 2018 · 2e place — Diplôme de 2e degré · IIe tour · Concours panukrainien des travaux scientifiques étudiants dans la spécialité « Administration et gestion publiques » — Voies d’implantation en Ukraine de l’expérience du Chili et de la Belgique en développement de l’administration électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">K. V. Prylepko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-73\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-73\" hidden><p>Travail de recherche étudiant « L’introduction de l’interaction électronique comme condition nécessaire du développement de l’administration électronique : expérience étrangère et nationale », par K. V. Prylepko, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie l’introduction de l’interaction électronique comme condition nécessaire du développement de l’administration électronique, à partir de l’expérience étrangère et nationale.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Prylepko, K. V. (2018). <i>Introducing electronic interaction as a necessary condition for the development of e-governance: Foreign and domestic experience</i> [L’introduction de l’interaction électronique comme condition nécessaire du développement de l’administration électronique : expérience étrangère et nationale] [Présentation de recherche étudiante]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-prylepko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2018/12/naukovo-doslidna-robota-studentiv-prylepko.pdf</a></p><div class=\"m\">Direction scientifique · 2018 · Concours panukrainien des travaux de recherche étudiants dans la spécialité « Administration et gestion publiques » — L’introduction de l’interaction électronique comme condition nécessaire du développement de l’administration électronique : expérience étrangère et nationale</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Norme de l’enseignement supérieur pour la spécialité 281 « Administration et gestion publiques » <a href=\"https://kntu.net.ua/ukr/content/download/77869/451807/file/Наказ%20МОНУ%20№%201172%20«Про%20затвердження%20стандарту%20вищої%20освіти%20за%20спеціальністю%20281%20«Публічне%20управління%20та%20адміністрування»%20для%20першого%20(бакалаврського)%20рівня%20ВО.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-74\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-74\" hidden><p>Norme nationale qui définit les compétences et les résultats d’apprentissage attendus au premier cycle en administration et gestion publiques, spécialité 281. La norme fixe également le cadre de la formation et de l’évaluation des diplômés. Elle sert de référence aux établissements qui élaborent ou révisent leurs programmes de baccalauréat dans cette spécialité.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ministère de l’Éducation et des Sciences de l’Ukraine. (2018, 29 octobre). <i>Norme de l’enseignement supérieur pour la spécialité 281 « Administration et gestion publiques</i> [Arrêté n° 1172]. <a class=\"apa-source\" href=\"https://mon.gov.ua/npa/pro-zatverdzhennya-standartu-vishoyi-osviti-za-specialnistyu-281-publichne-upravlinnya-ta-administruvannya-dlya-pershogo-bakalavrskogo-rivnya-vishoyi-osviti\" target=\"_blank\" rel=\"noopener\">https://mon.gov.ua/npa/pro-zatverdzhennya-standartu-vishoyi-osviti-za-specialnistyu-281-publichne-upravlinnya-ta-administruvannya-dlya-pershogo-bakalavrskogo-rivnya-vishoyi-osviti</a></p><div class=\"m\">Livres et monographies · 2018 · Ministère de l’Éducation et des Sciences de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’interopérabilité comme condition nécessaire de la mise en œuvre de l’administration électronique : l’expérience de l’Union européenne <a href=\"http://journals.maup.com.ua/index.php/public-management/article/view/587\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-75\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-75\" hidden><p>Écrit avec Valerii Dmytrenko, l'article traite l'interopérabilité comme la condition préalable sans laquelle l’administration électronique ne peut fonctionner, ni au niveau local ni au niveau national. Il analyse le nouveau cadre européen d'interopérabilité et le plan d'action pour l'interopérabilité de l'Union européenne, adoptés à l'ère du marché unique numérique européen, ainsi que les outils et solutions que l'Union applique pour faire fonctionner les services électroniques ensemble. Deux cas locaux — la plateforme e-Bourgogne en France et le programme de normes ouvertes OSLO en Flandre — montrent l'interopérabilité en pratique, et l'article se conclut par la transposition de l'expérience européenne au niveau local en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Dmytrenko, V. (2017). Interoperability as a necessary condition for the implementation of e-governance: Experience of the European Union [L’interopérabilité comme condition nécessaire de la mise en œuvre de l’administration électronique : l’expérience de l’Union européenne]. <i>Public Management</i>, (5(10)), 293–303. <a class=\"apa-source\" href=\"http://journals.maup.com.ua/index.php/public-management/article/view/587\" target=\"_blank\" rel=\"noopener\">http://journals.maup.com.ua/index.php/public-management/article/view/587</a></p><div class=\"m\">Articles · 2017 · Gouvernance publique, n° 5 (10), p. 293–303</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Développement de l’administration électronique aux niveaux local et régional</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-76\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-76\" hidden><p>Partie 7 du manuel en quinze parties « Gouvernement électronique et démocratie électronique » (Kyiv, 2017), préparé dans le cadre du programme EGAP « Le gouvernement électronique pour la responsabilité et la participation » avec le soutien de la Direction suisse du développement et de la coopération et approuvé par le Conseil académique de l'Académie nationale d'administration publique auprès du Président de l'Ukraine. La partie de Svitlana Chukut couvre le développement de l’administration électronique aux niveaux local et régional : les concepts de région électronique et de ville électronique (« ville intelligente »), l'état de l’administration électronique régional en Ukraine, l'expérience de mise en œuvre de Lviv et Vinnytsia, et les principales directions du développement de l’administration électronique à Kyiv, y compris les services administratifs électroniques au niveau local. Une deuxième section présente les meilleures pratiques étrangères — Australie, France, Suisse et Émirats arabes unis. La partie de 72 pages se termine par des questions d'auto-contrôle, une bibliographie recommandée et des travaux pour les séances pratiques, et s'adresse aux étudiants en administration publique, aux fonctionnaires et élus locaux en perfectionnement, ainsi qu'aux représentants des organisations de la société civile et des entreprises.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2017). E-governance development at local and regional levels [Développement de l’administration électronique aux niveaux local et régional]. Dans A. I. Semenchenko et V. M. Dreshpak (dir.), <i>E-governance and e-democracy: A textbook in 15 parts</i>. FOP Moskalenko O. M. <a class=\"apa-source\" href=\"https://library.pdpu.edu.ua/images/2018/NN/demokrat/07.pdf\" target=\"_blank\" rel=\"noopener\">https://library.pdpu.edu.ua/images/2018/NN/demokrat/07.pdf</a></p><div class=\"m\">Livres et monographies · 2017 · Partie 7. Dans : « Gouvernement électronique et démocratie électronique », manuel en 15 parties. Kyiv : FOP Moskalenko O. M., 2017. — 72 p. ISBN 978-966-2214-78-9</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>14</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">De l’Internet des objets à la ville intelligente : problèmes et perspectives <a href=\"https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-77\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-77\" hidden><p>Communication dans les actes de la conférence « Internet des objets : problèmes de réglementation juridique et de mise en œuvre » (conférence scientifique et pratique, Kyiv, 24 octobre 2017, p. 83–85). Dans le contexte de la poursuite de l'urbanisation — plus de 2,5 milliards d'habitants urbains supplémentaires dans les décennies à venir — et de la diffusion des technologies de l'information et de la communication et de l'Internet des objets, qui améliorent la qualité de vie tout en accentuant les problèmes de sécurité des données personnelles, de vie privée et de fracture numérique, l'article examine les tendances actuelles du développement des villes intelligentes à travers la stratégie « Smart Dubai ». L'expérience de Dubaï — plus de 100 initiatives intelligentes et plus de 1 000 services intelligents lancés par une vingtaine de départements gouvernementaux et de partenaires privés en moins de trois ans, et la feuille de route Smart Dubai 2021, qui fait du bonheur humain l'indicateur clé de succès et vise une ville efficace, fluide, sûre et personnalisée selon six dimensions stratégiques : vie intelligente, économie intelligente, gouvernance intelligente, mobilité intelligente, environnement intelligent et personnes intelligentes — est évaluée comme un modèle de l'approche d'innovation urbaine fondée sur la coopération entre administrations, entreprises, communauté scientifique et citoyens. L'article conclut que cette expérience peut servir l'Ukraine, à condition que les citoyens et leurs besoins — et non les entreprises développeuses — guident les stratégies de ville intelligente, en tenant compte des problèmes et des avantages propres à chaque ville.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2017). Current trends in Smart City development: The \"Smart Dubai 2021\" example [Tendances actuelles du développement des villes intelligentes : l’exemple de « Smart Dubai 2021 »]. Dans Internet of Things: Problems of Legal Regulation and Implementation (p. 83–85). Kyiv: Polytechnic Publishing House, Igor Sikorsky Kyiv Polytechnic Institute. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/internet-rechej-problemi-pravovogo-regulyuvannya-ta-vprovadzhennya/</a></p><div class=\"m\">Conférences · 2017 · « Internet des objets : problèmes de réglementation juridique et de mise en œuvre », Kyiv, 2017, p. 83–85</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Remerciement</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-78\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-78\" hidden><p>Lettre officielle de remerciements de l’Institut polytechnique de Kyiv Igor Sikorsky, datée de 2017.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2017). <i>Remerciement</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2017 · Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">« Développement des compétences civiques » (DOCCU)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-79\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-79\" hidden><p>Formation du projet suisse-ukrainien DOCCU consacrée aux compétences civiques et à leur développement dans la formation. Le projet relie l’éducation civique à des situations de participation, de dialogue et de prise de décision dans la vie publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Projet suisse–ukrainien DOCCU. (2017). <i>Développement des compétences civiques » (DOCCU)</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2017 · Projet suisse-ukrainien</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. L. Poliarna et V. V. Riabets <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-80\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-80\" hidden><p>Travail de recherche étudiant réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Kyiv : Institut polytechnique de Kyiv Igor Sikorsky, 2017.</p><p>Les auteurs comparent les services en ligne de police dans plusieurs pays européens avec l’offre qui existait alors en Ukraine. Ils proposent des pistes pour rendre les informations et les démarches policières plus accessibles par voie numérique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Poliarna, V. L. et Riabets, V. V. (2017). <i>European practices of e-service delivery in law enforcement</i> [Pratiques européennes de fourniture de services électroniques dans les activités des forces de l’ordre] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-ryabets.pdf</a></p><div class=\"m\">Direction scientifique · 2017 · IIe tour du concours panukrainien des travaux de recherche étudiants dans le domaine des sciences « Administration publique », Université d’État de Soumy, 22–23 mars 2017 — Pratiques européennes de fourniture de services électroniques dans les activités des forces de l’ordre</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>15</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Arina Kuts <a href=\"https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-81\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-81\" hidden><p>Travail de recherche étudiant réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure à l’Institut polytechnique de Kyiv Igor Sikorsky. Actes des « Lectures Glouchkov », 2017, p. 101.</p><p>La communication aborde la place des contrats intelligents dans le cadre juridique, en particulier la reconnaissance des engagements exécutés par du code et la responsabilité des parties.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kuts, A. R. (2017). Prospects for the legal regulation of smart contracts [Perspectives de régulation juridique des contrats intelligents (smart contracts)]. Dans <i>Glushkov Readings</i> (p. 101). <a class=\"apa-source\" href=\"https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf\" target=\"_blank\" rel=\"noopener\">https://glushkov-conf.comtext.space/files/2017_%D0%B3%D0%BB%D1%83%D1%88%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B5_%D1%87%D1%82%D0%B5%D0%BD%D0%B8%D1%8F.pdf</a></p><div class=\"m\">Direction scientifique · 2017 · Perspectives de régulation juridique des contrats intelligents (smart contracts)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">K. V. Konashevska et O. L. Kyselova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-82\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-82\" hidden><p>Travail de recherche étudiant « Implantation en Ukraine de l’expérience du Japon et de la Nouvelle-Zélande en développement de la démocratie électronique », par K. V. Konashevska et O. L. Kyselova, réalisé sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure. Le travail étudie l’essence de la démocratie électronique, l’expérience internationale de mise en œuvre de la démocratie électronique au Japon et en Nouvelle-Zélande, ainsi que l’état actuel du développement de la démocratie électronique en Ukraine, et formule des conclusions sur l’implantation de cette expérience en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Konashevska, K. V. et Kyseliova, O. L. (2017). <i>Implementing the e-democracy development experience of Japan and New Zealand in Ukraine</i> [Implantation en Ukraine de l’expérience du Japon et de la Nouvelle-Zélande en développement de la démocratie électronique] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-konashevska-kiselova.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/naukovo-doslidna-robota-studentiv-konashevska-kiselova.pdf</a></p><div class=\"m\">Direction scientifique · 2017 · IIe tour du concours panukrainien des travaux de recherche étudiants dans le domaine des sciences « Administration publique », Université d’État de Soumy, 22–23 mars 2017 — Implantation en Ukraine de l’expérience du Japon et de la Nouvelle-Zélande en développement de la démocratie électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Projet de norme de l’enseignement supérieur de l’Ukraine au niveau de la maîtrise (281) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-83\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-83\" hidden><p>Projet de norme de 2017 qui précise les compétences et les résultats d’apprentissage au niveau de la maîtrise en administration et gestion publiques. Le document couvre aussi le volume du programme, l’évaluation des diplômés et l’assurance qualité interne. Son statut de projet situe ces propositions dans le processus d’élaboration de la norme.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Ministère de l’Éducation et des Sciences de l’Ukraine. (2017). <i>Projet de norme de l’enseignement supérieur de l’Ukraine au niveau de la maîtrise (281)</i>. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2017/12/SVO_magistr_281-074-Publichne-upravlinnya-ta-administruvannya_red.pdf</a></p><div class=\"m\">Livres et monographies · 2017 · Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en œuvre du parlement électronique en Ukraine dans le contexte des tendances mondiales actuelles</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-84\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-84\" hidden><p>L'étude examine la manière dont un parlement électronique est introduit en Ukraine en conformité avec les tendances mondiales actuelles. Elle analyse la structure de l'information publiée sur le portail de la Verkhovna Rada et sa complétude au regard des recommandations des spécialistes du Centre mondial des technologies de l'information et de la communication au Parlement. Sur cette base, elle dégage les principales priorités et les principaux problèmes du développement du parlement électronique en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2016). E-parliament in Ukraine in light of current world trends [Mise en œuvre du parlement électronique en Ukraine dans le contexte des tendances mondiales actuelles]. <i>State and Regions. Public Administration</i>, (1(53)), 133–137.</p><div class=\"m\">Articles · 2016 · État et régions. Série : Administration publique, n° 1 (53), p. 133–137</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>22</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Particularités de la mise en œuvre de l’administration électronique aux Émirats arabes unis <a href=\"http://www.investplan.com.ua/?op=1&z=4986&i=19\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-85\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-85\" hidden><p>L'article étudie l'expérience des Émirats en matière de mise en œuvre de la gouvernance électronique et la possibilité de l'appliquer en Ukraine, en analysant les fondements stratégiques du processus de 2001 à 2016 et ses principaux axes. Il établit qu'une politique publique réussie a porté les Émirats arabes unis parmi les pays à indice élevé de développement de l'administration électronique, et examine les principes de la fourniture de services électroniques aux citoyens. Une attention particulière va au système national d'identification — l'introduction des cartes d'identité et leur protection — ainsi qu'aux meilleures pratiques des villes électroniques du pays.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Shuliak, M. (2016). E-governance implementation in the UAE: Specifics [Particularités de la mise en œuvre de l’administration électronique aux Émirats arabes unis]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (8), 92–95. <a class=\"apa-source\" href=\"http://www.investplan.com.ua/?op=1&amp;z=4986&amp;i=19\" target=\"_blank\" rel=\"noopener\">http://www.investplan.com.ua/?op=1&amp;z=4986&amp;i=19</a></p><div class=\"m\">Articles · 2016 · Investytsiyi: praktyka ta dosvid, n° 8, p. 92–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>29</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Analyse des meilleures pratiques de fourniture de services électroniques aux Émirats arabes unis <a href=\"http://www.dy.nayka.com.ua/?op=1&z=962\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-86\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-86\" hidden><p>À partir des rapports des Nations Unies sur l’administration électronique de 2003 à 2014, l'article suit la maturation des services en ligne des Émirats — y compris la chute marquée de son indice en 2010, qu'il attribue au changement de méthodologie de calcul de l'ONU plutôt qu'à un recul réel. Il examine la réponse des autorités, avant tout le programme national « UAE Vision 2021 » adopté en 2010 et la création d'un portail dédié, puis passe en revue les services effectivement utilisés par les citoyens et les entreprises, de la carte d'identité émiratie et de l'admission à l'université au permis de conduire et aux services médicaux. Les auteurs concluent que cette expérience s'inscrit dans les tendances mondiales de pointe en matière de prestation de services électroniques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Shuliak, M. (2016). Best e-service practices in the UAE: Analysis [Analyse des meilleures pratiques de fourniture de services électroniques aux Émirats arabes unis]. <i>Derzhavne Upravlinnia</i>, (4). <a class=\"apa-source\" href=\"http://www.dy.nayka.com.ua/?op=1&amp;z=962\" target=\"_blank\" rel=\"noopener\">http://www.dy.nayka.com.ua/?op=1&amp;z=962</a></p><div class=\"m\">Articles · 2016 · Derzhavne upravlinnia, n° 4</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Meilleures pratiques européennes de mise en œuvre de l’administration électronique : l’expérience du Danemark <a href=\"http://www.investplan.com.ua/?op=1&z=5314&i=28\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-87\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-87\" hidden><p>L'article retrace les étapes du développement de la gouvernance électronique au Royaume du Danemark, du programme de administration électronique 2002-2007 à la stratégie numérique publique commune 2011-2016, et en évalue l'état actuel et les perspectives. Il dégage trois axes principaux : le passage au flux électronique de documents, le bien-être électronique et la coopération électronique entre citoyens, autorités publiques à tous les niveaux et collectivités locales, ainsi que les mécanismes de participation publique en ligne aux décisions gouvernementales. Il conclut que l'expérience danoise correspond aux tendances mondiales actuelles et formule des recommandations pour l'appliquer en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Poliarna, V. (2016). Best European e-governance practices: The Danish experience [Meilleures pratiques européennes de mise en œuvre de l’administration électronique : l’expérience du Danemark]. <i>Investytsiyi: Praktyka ta Dosvid</i>, (24), 140–145. <a class=\"apa-source\" href=\"http://www.investplan.com.ua/?op=1&amp;z=5314&amp;i=28\" target=\"_blank\" rel=\"noopener\">http://www.investplan.com.ua/?op=1&amp;z=5314&amp;i=28</a></p><div class=\"m\">Articles · 2016 · Investytsiyi: praktyka ta dosvid, n° 24, p. 140–145</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Principales orientations et priorités de la fourniture de services électroniques dans les pays de l’UE : l’exemple du Danemark <a href=\"http://www.dy.nayka.com.ua/?op=1&z=1015\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-88\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-88\" hidden><p>À partir des rapports des Nations Unies sur l’administration électronique de 2003 à 2016, l'article suit les services en ligne danois à travers leurs indices et leurs stades de maturité, y compris la baisse marquée de 2014 qui a coûté au pays des places au classement mondial. Il examine le cadre stratégique du système — la stratégie numérique publique commune de 2011 et la stratégie de bien-être numérique 2013–2020 — ainsi que l'infrastructure qu'utilisent effectivement citoyens et entreprises : le portail Borger.dk, la signature numérique NemID et le système de facturation électronique NemHandel, obligatoire pour les fournisseurs des autorités publiques. Les auteurs concluent que l'expérience danoise s'inscrit dans les tendances mondiales de pointe et peut inspirer l'Ukraine, en soulignant notamment la plateforme Digitalisér.dk de partage des connaissances sur la numérisation.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Poliarna, V. (2016). E-service priorities in the EU: The Danish case [Principales orientations et priorités de la fourniture de services électroniques dans les pays de l’UE : l’exemple du Danemark]. <i>Derzhavne Upravlinnia</i>, (4). <a class=\"apa-source\" href=\"http://www.dy.nayka.com.ua/?op=1&amp;z=1015\" target=\"_blank\" rel=\"noopener\">http://www.dy.nayka.com.ua/?op=1&amp;z=1015</a></p><div class=\"m\">Articles · 2016 · Derzhavne upravlinnia, n° 4</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>23</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Développement du parlement électronique en Ukraine dans le contexte de l’expérience mondiale actuelle</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-89\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-89\" hidden><p>Ce chapitre compare le développement du parlement électronique en Ukraine aux pratiques internationales. Il examine l’accès à l’information parlementaire, la transparence et les possibilités de participation du public.</p><p>Le chapitre situe ces outils dans le fonctionnement d’une assemblée législative et dans ses échanges avec le public. Il s’adresse aux lecteurs qui étudient la modernisation des institutions parlementaires.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Lutsuk, L. (2016). E-parliament development in Ukraine in current world context [Développement du parlement électronique en Ukraine dans le contexte de l’expérience mondiale actuelle]. Dans O. A. Ivakin et D. V. Yakovlev (dir.), <i>Time of Choice: Challenges of the Information Era</i> (p. 360–371). Helvetyka Publishing House.</p><div class=\"m\">Livres et monographies · 2016 · Chapitre dans la monographie collective « Le temps du choix : les défis de l’ère de l’information », sous la direction de O. A. Ivakin et D. V. Yakovlev. Odesa : Maison d’édition « Helvetyka », 2016, p. 360–371</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">« L’impact de l’administration électronique sur les transformations sociales »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-90\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-90\" hidden><p>Le passage du gouvernement en ligne change-t-il vraiment le fonctionnement de la société ? Dirigée par Svitlana Chukut (2016–2018, enregistrement d'État n° 0115U000019), la recherche a examiné deux exemples : le parlement électronique ukrainien (le travail et l'information en ligne de la Verkhovna Rada, le parlement national) comparé aux pratiques mondiales, et les idées de « ville intelligente » pour gérer les services locaux en ligne. Elle s'est conclue par des recommandations pratiques pour corriger les problèmes relevés, à l'usage des autorités ukrainiennes et locales.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>L’impact de l’administration électronique sur les transformations sociales</i> [Projet de recherche]. (2016–2018). Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Projets · 2016–2018 · Directrice de recherche · Enregistrement d’État n° 0115U000019 (2016–2018)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ville intelligente ou ville électronique : approches actuelles de la compréhension de la mise en œuvre <a href=\"https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&I21DBN=UJRN&IMAGE_FILE_DOWNLOAD=0&Image_file_name=PDF%2Fipd_2016_13_17.pdf&P21DBN=UJRN&Z21ID=\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-91\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-91\" hidden><p>L'article met les deux notions face à face et demande ce que chacune signifie concrètement pour le gouvernement local. Il distingue deux lectures de la « ville intelligente » : une lecture commerciale, portée par les grandes entreprises informatiques pour vendre leurs produits et automatiser tous les processus urbains, et une lecture de développement durable, où la technologie sert la qualité de vie des habitants dans toutes les sphères de la ville. Face à la première, il pèse les risques — atteinte à la vie privée, contrôle total des citoyens et dévalorisation de la participation publique aux décisions — et illustre les deux lectures par des pratiques étrangères et ukrainiennes. Il se conclut sur les principaux problèmes qui freinent l’administration électronique local en Ukraine et sur les moyens de les surmonter.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Dmytrenko, V. (2016). Smart city or e-city: Modern approaches to understanding the implementation [Ville intelligente ou ville électronique : approches actuelles de la compréhension de la mise en œuvre]. <i>Investments: Practice and Experience</i>, (13), 89–93. <a class=\"apa-source\" href=\"https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&amp;I21DBN=UJRN&amp;IMAGE_FILE_DOWNLOAD=0&amp;Image_file_name=PDF%2Fipd_2016_13_17.pdf&amp;P21DBN=UJRN&amp;Z21ID=\" target=\"_blank\" rel=\"noopener\">https://irbis-nbuv.gov.ua/cgi-bin/irbis_nbuv/cgiirbis_64.exe?C21COM=2&amp;I21DBN=UJRN&amp;IMAGE_FILE_DOWNLOAD=0&amp;Image_file_name=PDF%2Fipd_2016_13_17.pdf&amp;P21DBN=UJRN&amp;Z21ID=</a></p><div class=\"m\">Articles · 2016 · Investissements : pratique et expérience, n° 13, p. 89–93</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>183</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’état de l’administration publique de la sphère de l’information en Ukraine <a href=\"http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-92\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-92\" hidden><p>Le chapitre dresse le bilan de la gouvernance de la sphère de l'information ukrainienne au tournant des années 2000 et de ses défaillances. Il documente les pressions exercées sur les médias indépendants — tentatives de censure, soutien sélectif de l'État et demandes de dommages-intérêts punitives — qui ont suscité l'inquiétude du Conseil de l'Europe, et étaye ce tableau par les statistiques de l'époque : plus de 10 000 périodiques enregistrés, dont environ 6 500 seulement paraissaient réellement ; une production de livres tombée à 0,3 exemplaire par habitant ; et 791 organismes de télévision et de radio titulaires de 931 licences, pour la plupart déficitaires. Il conclut que la stabilité de l'espace national de télévision et de radio dépend avant tout de l'état de l'économie et d'une législation saine garantissant des règles égales à tous les acteurs de l'information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2016). The state of public administration of the information sphere in Ukraine [L’état de l’administration publique de la sphère de l’information en Ukraine]. <i>State Information Policy of Ukraine</i>. <a class=\"apa-source\" href=\"http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf\" target=\"_blank\" rel=\"noopener\">http://files.znu.edu.ua/files/Bibliobooks/Inshi84/0064583.pdf</a></p><div class=\"m\">Articles · 2016 · Politique d’information de l’État en Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Analyse comparative de l’utilisation d’Internet dans les pays de l’Union européenne <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-93\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-93\" hidden><p>Un portrait comparatif de l'usage d'Internet dans l'Union européenne au tournant des années 2000, construit à partir des statistiques de la Commission européenne de 1999–2001 et encadré par la déclaration de Budapest du Conseil de l'Europe (1999) sur les nouvelles technologies de l'information. Il compare les États membres sur l'usage citoyen des pages gouvernementales, l'accès à Internet dans les écoles et les universités et la recherche d'informations médicales, puis suit l'adoption par les institutions entre 1999 et 2001 — utilisateurs, accès au travail, présence en ligne et intranets — dans dix pays. Il se termine par le profil humain de l'Internet européen naissant : où l'on se connectait, à quelles fins, pourquoi un tiers des Européens restait hors ligne et comment le télétravail se diffusait.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2016). Comparative analysis of Internet use in European Union countries [Analyse comparative de l’utilisation d’Internet dans les pays de l’Union européenne]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Porivnyalnij-analiz-vikoristannya-Internet-v-krayinah-YEvropejskogo-Soyuzu.pdf</a></p><div class=\"m\">Articles · 2016</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en œuvre de l’administration électronique en conditions de guerre en réseau</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-94\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-94\" hidden><p>Écrit alors que la guerre de la Russie contre l'Ukraine se déployait, l'article examine ce que la guerre en réseau fait à un État qui tente simultanément de gouverner par voie électronique. Il identifie les composantes les plus exposées du gouvernement et de la démocratie électroniques — ressources d'information et bases de données de l'État, données personnelles des citoyens, y compris celles des habitants des territoires occupés et des participants à l'opération antiterroriste, et tout service électronique exigeant une identification personnelle — et montre comment les réseaux sociaux, les sondages publics et certaines organisations civiques peuvent être retournés contre la sécurité nationale. Sa prescription est séquencée : bâtir un système national d'identification électronique aux normes européennes eIDAS, protéger l'information et les données personnelles, et bloquer les canaux destructeurs, en préservant l'équilibre entre sécurité et vie privée.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2016). Implementing e-governance amid network warfare [Mise en œuvre de l’administration électronique en conditions de guerre en réseau]. <i>'Public Management and Administration', Kyiv</i>, (1).</p><div class=\"m\">Articles · 2016 · « Administration et gestion publiques », Kyiv, n° 1</div><div class=\"publication-translations policy-document-actions\" role=\"group\" aria-label=\"Lire en traduction\"><a class=\"text-link\" href=\"article-translations/network-warfare-en.html\" lang=\"en\" hreflang=\"en\">English</a><a class=\"text-link\" href=\"article-translations/network-warfare-fr.html\" lang=\"fr\" hreflang=\"fr\">Français</a></div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’impact de l’administration électronique sur la transformation du rôle de l’État</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-95\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-95\" hidden><p>Communication à Kyiv sur les changements que l’administration électronique entraîne dans le rôle de l’État et ses relations avec la société. Le sujet relie la transformation des démarches administratives à des questions de responsabilité publique, d’accès à l’information et de participation citoyenne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2015). <i>How e-governance transforms the role of the state</i> [L’impact de l’administration électronique sur la transformation du rôle de l’État] [Communication à un colloque]. « L’État et le changement social mondial », Kyiv, Ukraine.</p><div class=\"m\">Conférences · 2015 · « L’État et les changements sociaux mondiaux », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’impact de l’administration électronique sur le processus de décentralisation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-96\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-96\" hidden><p>La communication examine les liens entre l’administration électronique et la décentralisation, en particulier la place des collectivités locales dans la prestation de services publics. Cette contribution replace les outils numériques dans la répartition des responsabilités entre administrations centrales et collectivités. Elle permet d’aborder la coordination des services lorsque les compétences sont exercées à plusieurs niveaux.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2015). How e-governance impacts decentralisation [L’impact de l’administration électronique sur le processus de décentralisation]. Dans A. A. Melnychenko et I. V. Vyselko (dir.), <i>Proceedings of the VIII International Scientific-Practical Conference 'Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation'</i> (p. 181–182). TOV NVP Interservis.</p><div class=\"m\">Conférences · 2015 · Actes de la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 181–182</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">EGAP « L’administration électronique pour la redevabilité du pouvoir et la participation des communautés » (Suisse)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-97\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-97\" hidden><p>EGAP est le programme suisso-ukrainien «E-Governance for Accountability and Participation» (administration électronique pour la responsabilité et la participation), mis en œuvre par la East Europe Foundation avec le soutien de la Suisse afin de rendre l'administration plus responsable et d'élargir la participation des citoyens grâce aux outils numériques. Sa première phase s'est déroulée de 2015 à 2019. Les citoyens font davantage confiance au gouvernement lorsqu'ils peuvent voir comment les décisions sont prises et y prendre part. EGAP — « L'administration électronique pour la redevabilité du pouvoir et la participation des communautés » — est un programme suisse-ukrainien, mis en œuvre par la Fondation Europe de l'Est, qui a utilisé les outils numériques pour ouvrir le gouvernement et associer les communautés. Svitlana Chukut a rejoint le programme comme experte en novembre 2015. Dans sa composante formation (composante 2) — qui a étudié et généralisé la meilleure expérience internationale et nationale et élaboré sur cette base la documentation de formation, formé des formateurs et apporté une aide méthodologique et consultative aux personnes qui organisaient et animaient les cours pour les fonctionnaires et les agents des collectivités locales, et renforcé la capacité des organes exécutifs, des collectivités locales et des citoyens à utiliser les outils d'administration électronique et de démocratie électronique — sa mission d'experte en 2016 était de contribuer à créer un cours national de formation à l'administration électronique et à la démocratie électronique destiné aux fonctionnaires et aux agents des collectivités locales. Elle a coécrit le programme d'une discipline universitaire facultative sur ce sujet (textes du programme d'études et du programme de travail ; 40 heures au total, dont 20 heures de contribution personnelle) et préparé des supports prêts à enseigner pour deux thèmes de l'ensemble de documentation du cours, chacun comprenant théorie, recommandations pour les travaux pratiques et les séminaires, tests, glossaire et bibliographie recommandée : le thème 7, « Suivi, évaluation et prévision du développement du système d'administration électronique », et le thème 8, « Développement de l'administration électronique aux niveaux régional et local », coécrit avec V. M. Dreshpak. Les produits finaux ont été remis au chef du groupe de travail et au coordinateur de la composante 2 : les fonctionnaires de toute l'Ukraine disposent ainsi d'un même cours national et de supports pédagogiques prêts à l'emploi sur l'administration électronique et la démocratie électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Programme EGAP. (2015–2017). <i>EGAP « L’administration électronique pour la redevabilité du pouvoir et la participation des communautés » (Suisse)</i> [Projet de recherche].</p><div class=\"m\">Projets · 2015–2017 · Experte</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ya. A. Braiko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-98\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-98\" hidden><p>Communication étudiante de Ya. A. Braiko sur les services électroniques en Australie, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas australien sert de point de comparaison pour étudier l’organisation de l’accès aux services publics en ligne et les conditions de leur utilisation par la population.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Braiko, Y. A. (2015). Electronic services in Australia [Les services électroniques en Australie]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 89–90).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 89–90 — Les services électroniques en Australie</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">I. A. Buzmakova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-99\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-99\" hidden><p>Communication étudiante de I. A. Buzmakova sur la mise en œuvre de l’administration électronique comme voie d’amélioration de la gestion et de la fourniture de services, d’après l’expérience de l’Inde, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>L’exemple indien met en relation la modernisation des processus administratifs et l’accès des citoyens aux services publics.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Buzmakova, I. A. (2015). Implementing e-governance as a way to improve management and service delivery: The experience of India [La mise en œuvre de l’administration électronique comme voie d’amélioration de la gestion et de la fourniture de services : l’expérience de l’Inde]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 90–92).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 90–92 — La mise en œuvre de l’administration électronique comme voie d’amélioration de la gestion et de la fourniture de services : l’expérience de l’Inde</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-100\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-100\" hidden><p>Communication étudiante de B. V. Viskushchenko sur l’influence de l’administration électronique sur la confiance des citoyens envers les autorités publiques, présentée à la XIIIe conférence scientifique et pratique internationale « La créativité dans les dimensions philosophiques » (Kyiv, 14–15 mai 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La communication étudie le lien entre l’expérience des services numériques et la confiance accordée aux institutions, un enjeu qui dépend aussi de la manière dont les administrations communiquent avec le public.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Viskushchenko, B. V. (2015). <i>The impact of e-governance on citizens&#x27; trust in public authorities</i> [L’influence de l’administration électronique sur la confiance des citoyens envers les autorités publiques] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2015 · XIIIe conférence scientifique et pratique internationale « La créativité dans les dimensions philosophiques », Kyiv, 14–15 mai 2015 — L’influence de l’administration électronique sur la confiance des citoyens envers les autorités publiques</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-101\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-101\" hidden><p>Communication étudiante de B. V. Viskushchenko sur les avantages de l’activité gouvernementale en ligne, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le sujet concerne les usages de canaux numériques pour rendre l’information publique plus accessible et simplifier les échanges avec l’administration.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Viskushchenko, B. V. (2015). Advantages of online government activity [Les avantages de l’activité gouvernementale en ligne]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 92–93).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 92–93 — Les avantages de l’activité gouvernementale en ligne</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Kh. O. Kapitan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-102\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-102\" hidden><p>Communication étudiante de Kh. O. Kapitan sur la formation et le développement de la douane électronique de l’Ukraine, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La recherche situe la numérisation des douanes dans l’évolution des procédures de déclaration et du traitement de l’information administrative.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kapitan, K. O. (2015). Formation and development of the electronic customs of Ukraine [Formation et développement de la douane électronique de l’Ukraine]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 99–100).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 99–100 — Formation et développement de la douane électronique de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">T. V. Kvasha</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-103\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-103\" hidden><p>Communication étudiante de T. V. Kvasha sur les avantages des services électroniques dans l’interaction entre gouvernement et citoyens, présentée à la XVIIIe conférence panukrainienne des étudiants et doctorants « Journées de la science » (Kyiv, 22–23 avril 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>L’analyse porte sur ce que les démarches en ligne changent pour les citoyens, notamment l’accès aux renseignements et la possibilité d’interagir avec l’administration à distance.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kvasha, T. V. (2015). Advantages of electronic services in government–citizen interaction [Les avantages des services électroniques dans l’interaction entre gouvernement et citoyens]. Dans <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (p. 150–151).</p><div class=\"m\">Direction scientifique · 2015 · XVIIIe conférence scientifique et pratique panukrainienne des étudiants et doctorants « Journées de la science », Kyiv, 22–23 avril 2015, p. 150–151 — Les avantages des services électroniques dans l’interaction entre gouvernement et citoyens</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. S. Kvitkovska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-104\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-104\" hidden><p>Communication étudiante de V. S. Kvitkovska sur le développement de l’administration électronique à Singapour comme exemple pour l’Ukraine, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas de Singapour fournit un cadre de comparaison pour examiner quels aspects d’une administration numérique peuvent être transposés à des institutions ukrainiennes.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kvitkovska, V. S. (2015). Development of e-governance in Singapore as an example for Ukraine [Le développement de l’administration électronique à Singapour comme exemple pour l’Ukraine]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 102–104).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 102–104 — Le développement de l’administration électronique à Singapour comme exemple pour l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Kokhan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-105\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-105\" hidden><p>Communication étudiante de O. A. Kokhan sur l’utilisation de la technologie de benchmarking dans l’administration électronique en Ukraine, présentée à la XVIIIe conférence panukrainienne des étudiants et doctorants « Journées de la science » (Kyiv, 22–23 avril 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le sujet relie l’analyse comparative à l’évaluation des pratiques publiques. Il met l’accent sur la manière de comparer des services avant de sélectionner des pistes d’amélioration.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kokhan, O. A. (2015). Using benchmarking technology in e-governance in Ukraine [L’utilisation de la technologie de benchmarking dans l’administration électronique en Ukraine]. Dans <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (p. 168–169).</p><div class=\"m\">Direction scientifique · 2015 · XVIIIe conférence scientifique et pratique panukrainienne des étudiants et doctorants « Journées de la science », Kyiv, 22–23 avril 2015, p. 168–169 — L’utilisation de la technologie de benchmarking dans l’administration électronique en Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">H. O. Kulikova</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-106\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-106\" hidden><p>Communication étudiante de H. O. Kulikova sur les meilleures pratiques mondiales d’administration électronique, d’après l’exemple de la Norvège, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas norvégien élargit l’analyse comparative des choix institutionnels et des modes de prestation qui sous-tendent l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kulikova, H. O. (2015). Best world practices of e-governance: Norway [Les meilleures pratiques mondiales d’administration électronique : la Norvège]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 104–105).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 104–105 — Les meilleures pratiques mondiales d’administration électronique : la Norvège</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Petrakovych</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-107\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-107\" hidden><p>Communication étudiante de O. A. Petrakovych sur Londres comme exemple de ville électronique pour l’Ukraine, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Londres sert d’exemple pour réfléchir à la manière dont une municipalité peut organiser l’accès aux services et à l’information à l’échelle d’une ville.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Petrakovych, O. A. (2015). London as an example of an electronic city for Ukraine [Londres comme exemple de ville électronique pour l’Ukraine]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 107–109).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 107–109 — Londres comme exemple de ville électronique pour l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">V. L. Poliarna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-108\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-108\" hidden><p>Communication étudiante de V. L. Poliarna sur l’administration électronique comme indicateur d’une administration publique réussie, d’après l’expérience du Danemark, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La contribution mobilise l’expérience danoise pour examiner le rapport entre la maturité des services numériques et la capacité de l’administration à les fournir.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Poliarna, V. L. (2015). E-governance as an indicator of successful public administration: The experience of denmark [L’administration électronique comme indicateur d’une administration publique réussie : l’expérience du Danemark]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 111–112).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 111–112 — L’administration électronique comme indicateur d’une administration publique réussie : l’expérience du Danemark</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. V. Tivonenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-109\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-109\" hidden><p>Communication étudiante de A. V. Tivonenko sur la décentralisation et son influence sur le développement de l’administration électronique en Ukraine, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La communication examine la répartition des compétences entre niveaux de gouvernement et ses implications pour la coordination des services en ligne en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Tivonenko, A. V. (2015). Decentralisation and its impact on the development of e-governance in Ukraine [La décentralisation et son influence sur le développement de l’administration électronique en Ukraine]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 112–114).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 112–114 — La décentralisation et son influence sur le développement de l’administration électronique en Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. S. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-110\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-110\" hidden><p>Communication étudiante de A. S. Umanska sur l’administration électronique comme mécanisme efficace de lutte contre la corruption, présentée à la XVIIIe conférence panukrainienne des étudiants et doctorants « Journées de la science » (Kyiv, 22–23 avril 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La contribution aborde la transparence des démarches numériques et la façon dont la traçabilité des décisions peut soutenir la prévention de la corruption.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Umanska, A. S. (2015). Electronic government as an effective mechanism for combating corruption [Le gouvernement électronique comme mécanisme efficace de lutte contre la corruption]. Dans <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (p. 161–162).</p><div class=\"m\">Direction scientifique · 2015 · XVIIIe conférence scientifique et pratique panukrainienne des étudiants et doctorants « Journées de la science », Kyiv, 22–23 avril 2015, p. 161–162 — Le gouvernement électronique comme mécanisme efficace de lutte contre la corruption</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-111\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-111\" hidden><p>Communication étudiante de A. M. Chorna sur l’introduction du commerce électronique pour les marchés publics, présentée à la VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion » (Kyiv, 10 décembre 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>L’étude relie les outils du commerce électronique au déroulement d’un marché public, de la publication d’un appel d’offres à la soumission des dossiers.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chorna, A. M. (2015). Introducing electronic commerce for public procurement [L’introduction du commerce électronique pour les marchés publics]. Dans <i>Proceedings of the VIII International Scientific-Practical Conference “Contemporary Problems of Management: The Dialectics of Centralisation and Decentralisation”</i> (p. 114–115).</p><div class=\"m\">Direction scientifique · 2015 · VIIIe conférence scientifique et pratique internationale « Problèmes contemporains de gestion : dialectique de la centralisation et de la décentralisation », Kyiv, 10 décembre 2015, p. 114–115 — L’introduction du commerce électronique pour les marchés publics</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-112\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-112\" hidden><p>Communication étudiante de A. M. Chorna sur les perspectives des études de prospective dans la mise en œuvre de l’administration électronique, présentée à la XVIIIe conférence panukrainienne des étudiants et doctorants « Journées de la science » (Kyiv, 22–23 avril 2015), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La contribution situe la prospective dans la planification de l’administration numérique, où il faut tenir compte de l’évolution des technologies et des besoins des usagers.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chorna, A. M. (2015). Prospects of foresight research in implementing e-governance [Les perspectives des études de prospective dans la mise en œuvre de l’administration électronique]. Dans <i>Proceedings of the XVIII All-Ukrainian Scientific-Practical Conference of Students and Postgraduates “Days of Science”</i> (p. 178–179).</p><div class=\"m\">Direction scientifique · 2015 · XVIIIe conférence scientifique et pratique panukrainienne des étudiants et doctorants « Journées de la science », Kyiv, 22–23 avril 2015, p. 178–179 — Les perspectives des études de prospective dans la mise en œuvre de l’administration électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Guerre moderne, société de réseau et psychologie des foules <a href=\"https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-113\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-113\" hidden><p>Thèses de conférence appliquant la théorie de la foule de Serge Moscovici à la guerre de la Russie contre l'Ukraine en 2013–2014. Svitlana Chukut rappelle les postulats de la théorie — la foule comme communauté psychique agissant inconsciemment, son conservatisme et son besoin d'un chef, la base irrationnelle de la propagande, et le rôle d'une idée supérieure transformée en images collectives — et montre comment la propagande russe a construit son cadrage « fasciste » pendant une décennie, de la campagne de 2004 à la révolution de la Dignité, à l'occupation de la Crimée et à l'invasion du continent. Dans une société en réseau, soutient-elle, la télévision, la radio, la presse écrite, les médias en ligne et les réseaux sociaux agissent en synergie sur la conscience de masse par superposition et projection, et les idées-images simplifiées et sans cesse répétées (« junte de Kyiv », « fascistes », « bourreaux ») déclenchent automatiquement les comportements. Le Maïdan, note-t-elle, n'était pas une foule mais une communauté d'individus partageant les mêmes idées, ce qui explique l'échec de l'arme à Kyiv ; comme contre-exemple, elle cite l'imagerie tolkienienne de Serhiy Loiko (« Mordor », « orques ») dans l'entrevue d'octobre 2014 à Écho de Moscou, retirée du site de la station par Roskomnadzor. La guerre moderne, conclut-elle, se mène avec des armes informationnelles autant qu'avec des armées, et l'Ukraine peut les utiliser en offensive comme en défense.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2014). Modern warfare, the network society and crowd psychology [Guerre moderne, société de réseau et psychologie des foules]. <i>Plenary talk, 'Great Wars, Great Transformations' Conference, Kyiv</i>. <a class=\"apa-source\" href=\"https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf\" target=\"_blank\" rel=\"noopener\">https://sociology.kpi.ua/wp-content/uploads/2015/01/Програма_Соціологія_2014.pdf</a></p><div class=\"m\">Conférences · 2014 · Communication PLÉNIÈRE. « Grandes guerres, grandes transformations », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Particularités de la mise en œuvre de l’administration électronique en conditions de guerre en réseau</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-114\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-114\" hidden><p>Thèses de conférence dans lesquelles Svitlana Chukut demande ce que devient l’administration électronique sous la guerre en réseau que la Russie mène contre l'Ukraine. Elle rappelle les étapes positives de 2014 — la création de l'Agence d'État pour le développement de l’administration électronique et le projet de Livre vert sur l’administration électronique en Ukraine — et les oppose à la nature de la guerre en réseau telle que la définit son idéologue russe Alexandre Douguine : détruire les idées fondamentales d'un peuple sur sa culture, sa société et son État afin de semer la peur, la désorientation et le chaos, réorienter puis détruire les valeurs spirituelles et culturelles traditionnelles, et établir un contrôle sans occupation directe, par des efforts intégrés physiques, informationnels, cognitifs et sociaux dans lesquels la composante informationnelle mène. Dans ce contexte, avertit-elle, les instruments de démocratie électronique du Livre vert — collecte de signatures et pétitions, appels, consultations, questionnaires, vote électronique — peuvent produire l'effet inverse : elle cite le sondage du Figaro sur la vente des Mistral à la Russie, falsifié par un vote automatisé de masse (sur quelque 260 000 répondants, 180 000 provenaient d'adresses IP robotisées, pour la plupart russes). Des risques particuliers s'attachent à l'interaction électronique entre les autorités étatiques et locales, où des sociétés informatiques ayant une « trace russe » peuvent être impliquées ; aux services électroniques, qui exigent un système national d'identification électronique ; et à la protection et au contenu des bases de données créées par les organes de l'État. Elle pose l'équilibre non résolu — sécurité de l'État contre vie privée, développement de la démocratie électronique contre victoire dans la guerre en réseau — et conclut que la tâche de l'Ukraine est d'utiliser les avantages de l’administration électronique pour la victoire tout en protégeant ses composantes les plus vulnérables de l'ingérence étrangère : mieux vaut avancer plus lentement, mais dans la bonne direction.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2014). E-governance implementation amid network warfare [Particularités de la mise en œuvre de l’administration électronique en conditions de guerre en réseau]. <i>'V. Hlushkov, Cybernetics Pioneer', Kyiv</i>.</p><div class=\"m\">Conférences · 2014 · « V. M. Glouchkov — pionnier de la cybernétique », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Yu. S. Bielik</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-115\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-115\" hidden><p>Communication étudiante de Yu. S. Bielik sur l’expérience de la mise en œuvre de l’administration électronique en Suède, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas suédois constitue un point de comparaison pour l’étude des choix d’organisation et de la prestation des services publics numériques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Bielik, Y. S. (2014). Experience of implementing e-governance in sweden [L’expérience de la mise en œuvre de l’administration électronique en Suède]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 80–82).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 80–82 — L’expérience de la mise en œuvre de l’administration électronique en Suède</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">B. V. Viskushchenko</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-116\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-116\" hidden><p>Communication étudiante de B. V. Viskushchenko sur la mise en œuvre de l’administration électronique dans les pays étrangers, d’après l’exemple de l’Irlande, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas irlandais permet de comparer une trajectoire nationale de modernisation administrative avec les besoins et les conditions de mise en œuvre en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Viskushchenko, B. V. (2014). Implementing e-governance in foreign countries: The example of ireland [La mise en œuvre de l’administration électronique dans les pays étrangers : l’exemple de l’Irlande]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 83–84).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 83–84 — La mise en œuvre de l’administration électronique dans les pays étrangers : l’exemple de l’Irlande</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. V. Volodin</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-117\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-117\" hidden><p>Communication étudiante de O. V. Volodin sur l’introduction de l’archive électronique comme facteur de gestion dans l’administration électronique, présentée à la conférence scientifique et pratique « Défis contemporains pour les sciences sociales dans le contexte de la mondialisation » (Lviv, 30–31 mai 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>L’étude situe les archives numériques dans le cycle de gestion des documents publics. Elle lie leur organisation à la capacité des administrations de conserver et de retrouver l’information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Volodin, O. V. (2014). Introducing the e-archive as a management factor in e-governance [L’introduction de l’archive électronique comme facteur de gestion dans l’administration électronique]. Dans <i>Scientific-Practical Conference &#x27;Modern Challenges for the Social Sciences in the Context of Globalisation&#x27;</i> (p. 35–37).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique « Défis contemporains pour les sciences sociales dans le contexte de la mondialisation », Lviv, 30–31 mai 2014, p. 35–37 — L’introduction de l’archive électronique comme facteur de gestion dans l’administration électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. V. Volodin</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-118\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-118\" hidden><p>Communication étudiante de O. V. Volodin sur la conception sociale comme composante de l’activité socio-ingénierie dans la gestion des organisations, présentée à la conférence scientifique et pratique internationale du Forum scientifique international (Kyiv, 8 mai 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le sujet relie la conception d’interventions sociales au fonctionnement des organisations et à la manière dont elles définissent un problème de gestion.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Volodin, O. V. (2014). Social design as a component of socio-engineering activity in organisational management [La conception sociale comme composante de l’activité socio-ingénierie dans la gestion des organisations]. Dans <i>International Scientific-Practical Conference &#x27;International Scientific Forum: Science and Practice in the Modern World&#x27;</i> (p. 5–9).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique internationale « Forum scientifique international : la science et la pratique dans le monde contemporain », Kyiv, 8 mai 2014, p. 5–9 — La conception sociale comme composante de l’activité socio-ingénierie dans la gestion des organisations</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">T. Kvasha</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-119\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-119\" hidden><p>Communication étudiante de T. Kvasha sur Internet comme outil de communication entre le gouvernement et les citoyens, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La communication examine Internet comme canal à la fois d’information publique et d’échange, en lien avec la participation des citoyens.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kvasha, T. (2014). The Internet as a tool of communication between government and citizens [Internet comme outil de communication entre le gouvernement et les citoyens]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 99–101).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 99–101 — Internet comme outil de communication entre le gouvernement et les citoyens</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">O. A. Kokhan</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-120\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-120\" hidden><p>Communication étudiante de O. A. Kokhan sur le surplus d’information et les technologies de sa création dans l’espace d’information contemporain, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le sujet porte sur les mécanismes qui accroissent le volume d’information disponible et sur les difficultés de sélection et d’interprétation qui peuvent en résulter.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Kokhan, O. A. (2014). Information surplus and the technologies of its creation in the modern information space [Le surplus d’information et les technologies de sa création dans l’espace d’information contemporain]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 200–202).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 200–202 — Le surplus d’information et les technologies de sa création dans l’espace d’information contemporain</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">N. A. Saukh</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-121\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-121\" hidden><p>Communication étudiante de N. A. Saukh sur l’activité des organisations de la société civile dans le développement de la démocratie électronique, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>La communication situe les organisations de la société civile parmi les acteurs qui facilitent l’expression des citoyens et leur participation aux échanges avec les institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Saukh, N. A. (2014). Activities of civil society organisations in the development of electronic democracy [L’activité des organisations de la société civile dans le développement de la démocratie électronique]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 122–124).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 122–124 — L’activité des organisations de la société civile dans le développement de la démocratie électronique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-122\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-122\" hidden><p>Communication étudiante de A. Umanska sur le système d’administration électronique au Royaume de Bahreïn, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cas de Bahreïn élargit la comparaison internationale des stratégies de gouvernement numérique et de l’organisation des services en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Umanska, A. (2014). The e-governance system in the kingdom of bahrain [Le système d’administration électronique au Royaume de Bahreïn]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 125–126).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 125–126 — Le système d’administration électronique au Royaume de Bahreïn</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. S. Umanska</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-123\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-123\" hidden><p>Communication étudiante de A. S. Umanska sur la gouvernance démocratique et les technologies de l’information et de la communication — leurs concepts clés — présentée à la conférence scientifique et pratique internationale de sociologie « Grandes guerres, grandes transformations » (Kyiv, 27–28 novembre 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>Le cadre conceptuel relie les technologies de l’information et de la communication aux questions de participation, de transparence et de fonctionnement démocratique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Umanska, A. S. (2014). <i>Democratic governance and information and communication technologies: Key concepts</i> [Gouvernance démocratique et technologies de l’information et de la communication : concepts clés] [Travail de recherche étudiant]. Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique internationale de sociologie « Grandes guerres, grandes transformations : sociologie historique du XXe siècle, 1914–2014 », Kyiv, 27–28 novembre 2014 — Gouvernance démocratique et technologies de l’information et de la communication : concepts clés</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">A. M. Chorna</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-124\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-124\" hidden><p>Communication étudiante de A. M. Chorna sur la mise en œuvre de l’administration électronique dans les pays étrangers, d’après l’exemple de l’Australie, présentée à la conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique » (Kyiv, 2014), réalisée sous la direction scientifique de S. A. Chukut, docteure ès sciences en administration publique, professeure.</p><p>L’exemple australien fournit un cadre de comparaison pour étudier les dispositifs institutionnels qui permettent de proposer des services publics en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chorna, A. M. (2014). Implementing e-governance in foreign countries: The example of Australia [La mise en œuvre de l’administration électronique dans les pays étrangers : l’exemple de l’Australie]. Dans <i>Proceedings of the All-Ukrainian Scientific-Practical Conference “V. M. Glushkov: Pioneer of Cybernetics”</i> (p. 129–130).</p><div class=\"m\">Direction scientifique · 2014 · Conférence scientifique et pratique panukrainienne « V. M. Glushkov — pionnier de la cybernétique », Kyiv, 2014, p. 129–130 — La mise en œuvre de l’administration électronique dans les pays étrangers : l’exemple de l’Australie</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Tendances et problèmes de la mise en œuvre de l’administration électronique en Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-125\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-125\" hidden><p>Thèses de conférence dans lesquelles Svitlana Chukut présente l’administration électronique comme la réponse à un déficit mondial de confiance entre les citoyens et le pouvoir : le réseau mondial crée une rétroaction durable et une interaction interactive, et la démocratie électronique — composante centrale de l’administration électronique — sert les besoins des citoyens tout en luttant contre la corruption, la bureaucratisation et le formalisme. Elle rappelle les critères de l'OCDE pour la construction de l’administration électronique et ses principes de fonctionnement — services à tout moment (24 h/24 et 7 j/7), simplicité et transparence maximales pour les citoyens ordinaires, normes techniques communes et interopérabilité, confidentialité et sécurité de l'information, et orientation inconditionnelle vers l'opinion des citoyens — et passe en revue le développement actuel de l'Ukraine : flux électronique de documents avec signature numérique, centres de services administratifs et « guichet unique », et administration électronique sectoriel, de la télémédecine et de l'enseignement à distance aux tribunaux. Elle conclut en décrivant sept blocs de problèmes : interopérabilité, sécurité nationale, identité nationale, sécurité économique, protection de la vie privée (avec l'avertissement d'une issue orwellienne si les règles sur les données personnelles échouent), responsabilité, et force majeure — soutenant que les services les plus critiques devraient conserver une part électronique de 70 à 80 pour cent plutôt que de passer entièrement en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2013). Trends and problems of e-governance implementation in Ukraine [Tendances et problèmes de la mise en œuvre de l’administration électronique en Ukraine]. <i>VII International Conference 'Contemporary Problems of Management', Kyiv</i>.</p><div class=\"m\">Conférences · 2013 · VIIe conférence internationale « Problèmes actuels de gestion », Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>30</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Membre des comités de programme et d’organisation de la conférence internationale « Problèmes actuels de gestion » <a href=\"https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-126\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-126\" hidden><p>Participation aux comités de programme et d’organisation de la conférence « Problèmes contemporains de gestion » à l’Institut polytechnique de Kyiv Igor Sikorsky. Ce rôle s’inscrit dans la coordination d’une rencontre scientifique réunissant des travaux sur les enjeux de gestion et d’administration publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Institut polytechnique de Kyiv Igor Sikorsky. (2013–). <i>Membre des comités de programme et d’organisation de la conférence internationale « Problèmes actuels de gestion</i> [Notice de conférence]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/conference/suchasni-problemy-upravlinnya/</a></p><div class=\"m\">Conférences · 2013–… · Conférence internationale « Problèmes actuels de gestion », Institut polytechnique de Kyiv Igor Sikorsky</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">« L’impact de l’administration électronique sur les transformations sociétales »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-127\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-127\" hidden><p>Le gouvernement numérique peut-il changer la société pour le mieux — et qu'est-ce qui l'en empêche ? De 2013 à 2017, un thème de recherche d'initiative dirigé par Svitlana Chukut à la Faculté de sociologie et de droit de l'Institut polytechnique de Kyiv (chaire de théorie et de pratique de la gestion) a étudié cette question sur trois fronts. D'abord, le parlement électronique : l'équipe a analysé la mise en place du parlement électronique en Ukraine au regard des tendances mondiales actuelles, en examinant la structure et l'exhaustivité de l'information présentée sur le portail de la Verkhovna Rada à la lumière des recommandations du Centre mondial pour les TIC au Parlement, et a dégagé les priorités et les problèmes. Un parlement électronique est un organe législatif que les TIC rendent plus ouvert, transparent et responsable, et le niveau de l'Ukraine correspond aux tendances internationales ; les principaux obstacles sont la faible connaissance, par les citoyens, des possibilités que leur offre le parlement électronique et la coordination insuffisante entre les pouvoirs législatif et exécutif. Le travail a également souligné l'importance des applications mobiles — pour un accès plus simple et de meilleure qualité à l'information et aux services, et pour le suivi de l'opinion publique. Ensuite, les villes intelligentes : l'équipe a étudié les approches modernes des concepts de « ville intelligente » et de « ville électronique » dans l'administration électronique locale — une approche, promue par les grandes entreprises informatiques, vise l'automatisation de tous les processus de la vie urbaine, tandis que l'autre, inscrite dans le cadre du développement durable, utilise les TIC dans toutes les sphères du fonctionnement de la ville pour améliorer la qualité de vie de ses habitants — et a nommé les menaces d'un enthousiasme excessif pour les technologies de la ville intelligente : les risques pour la protection de la vie privée, le contrôle total sur les citoyens et la dévalorisation de la participation des citoyens au processus de prise de décision. Enfin, le niveau local : les pratiques ukrainiennes et étrangères de développement de l'administration électronique au niveau local ont été analysées, les principaux problèmes qui freinent l'administration électronique locale en Ukraine ont été identifiés et des recommandations pour les surmonter ont été élaborées. Les résultats ont été mis en œuvre dans le processus d'enseignement ; le thème a produit 5 articles dans des revues indexées dans des bases de données scientométriques et 5 dans des revues professionnelles de la liste du ministère de l'Éducation et des Sciences de l'Ukraine, 22 communications de conférence (dont 18 lors de conférences internationales), associé 17 étudiants, et 10 mémoires de master ont été préparés et soutenus. Les résultats peuvent être utilisés par la Verkhovna Rada d'Ukraine, l'Agence d'État pour le développement de l'administration électronique, le ministère du Développement économique, les administrations d'État locales et les organes d'autonomie locale, ainsi que dans l'enseignement de la spécialité 074 « Administration publique et administration ».</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>L’impact de l’administration électronique sur les transformations sociétales</i> [Projet de recherche]. (2013–2017). Institut polytechnique de Kyiv Igor Sikorsky.</p><div class=\"m\">Projets · 2013–2017 · Thème de recherche d’initiative — Faculté de sociologie et de droit, chaire de théorie et de pratique de la gestion ; directrice de recherche · Enregistrement d’État n° 0115U000019 (2016–2018)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Certificat d’auteur n° 42281 : « Administration électronique : conception, méthodologie, outils et programmes »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-128\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-128\" hidden><p>Le certificat n° 42281 porte sur un travail consacré aux concepts, méthodes, outils et programmes de l’administration électronique, réalisé avec Olha Zahvoiska. La notice identifie le document et ses coauteures. Les quatre axes du titre situent sa portée, des bases conceptuelles aux modalités de mise en œuvre de l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Zahvoiska, O. V. (2012). <i>E-governance: Concept, methodology, tools and programmes</i> [Administration électronique : concept, méthodologie, outils et programmes] [Certificat de droit d’auteur n° 42281].</p><div class=\"m\">Livres et monographies · 2012 · Certificat d’auteur</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Tendances de développement de l’administration électronique et risques de sa mise en œuvre</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-129\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-129\" hidden><p>Thèses de conférence dans lesquelles Svitlana Chukut présente l’administration électronique comme la réponse à un déficit mondial de confiance entre les citoyens et le pouvoir : le réseau mondial crée une rétroaction durable et une interaction interactive, et la démocratie électronique — composante centrale de l’administration électronique — sert les besoins des citoyens tout en luttant contre la corruption, la bureaucratisation et le formalisme. Elle rappelle les critères de l'OCDE pour la construction de l’administration électronique et ses principes de fonctionnement — services à tout moment (24 h/24 et 7 j/7), simplicité et transparence maximales pour les citoyens ordinaires, normes techniques communes et interopérabilité, confidentialité et sécurité de l'information, et orientation inconditionnelle vers l'opinion des citoyens — et passe en revue le développement actuel de l'Ukraine : flux électronique de documents avec signature numérique, centres de services administratifs et « guichet unique », et administration électronique sectoriel, de la télémédecine et de l'enseignement à distance aux tribunaux. Elle conclut en décrivant sept blocs de problèmes : interopérabilité, sécurité nationale, identité nationale, sécurité économique, protection de la vie privée (avec l'avertissement d'une issue orwellienne si les règles sur les données personnelles échouent), responsabilité, et force majeure — soutenant que les services les plus critiques devraient conserver une part électronique de 70 à 80 pour cent plutôt que de passer entièrement en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2012). E-governance development trends and implementation risks [Tendances de développement de l’administration électronique et risques de sa mise en œuvre]. <i>'Information Society in Ukraine' congress, Kyiv</i>.</p><div class=\"m\">Conférences · 2012 · Congrès « La société de l’information en Ukraine », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Fondements théorico-méthodologiques, institutionnels et organisationnels de l’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-130\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-130\" hidden><p>Expose les fondements théoriques, méthodologiques, institutionnels et organisationnels de l'administration électronique. Le texte distingue les principes qui orientent une réforme des conditions institutionnelles et organisationnelles qui la rendent réalisable. Il situe l’administration électronique dans la transformation des processus de l’État.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Zahvoiska, O. (2011). Theoretical, methodological, institutional and organisational foundations of e-governance [Fondements théorico-méthodologiques, institutionnels et organisationnels de l’administration électronique]. <i>Research Digest, Kyiv</i>, (3).</p><div class=\"m\">Articles · 2011 · Digest d’information sur la recherche, vol. 3, Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Fondements théorico-méthodologiques, organisationnels et institutionnels de la mise en œuvre de l’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-131\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-131\" hidden><p>Rapport final du projet de recherche mené en 2011 à la chaire de politique de l'information de l'Académie nationale d'administration publique, sous la direction scientifique de Svitlana Chukut (180 pages, 152 sources). Il systématise la théorie et la pratique de la mise en œuvre de l’administration électronique en Ukraine : le concept national de développement de l’administration électronique que l'équipe a contribué à rédiger pour le gouvernement, un projet pilote pour les organes d'État et locaux, les services électroniques, le personnel et le programme de master en administration électronique, les ressources d'information électroniques nationales et la protection des données personnelles. Une partie distincte examine les niveaux régional et local, et la partie finale passe en revue les fondements institutionnels et organisationnels de l’administration électronique dans dix pays — de l'Australie et du Canada à Singapour et à la Thaïlande — comme meilleures pratiques étrangères pour l'Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Theoretical, methodological, organisational and institutional foundations of e-governance implementation</i> [Fondements théorico-méthodologiques, organisationnels et institutionnels de la mise en œuvre de l’administration électronique] [Rapport final de recherche]. (2011). Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zvit_Teoretiko-metodologichni-institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zvit_Teoretiko-metodologichni-institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2011 · Rapport final de recherche, Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en place des mécanismes d’interaction du gouvernement avec les organisations non gouvernementales</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-132\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-132\" hidden><p>L’édition de 2011 met en relation la participation des organisations non gouvernementales, le rôle des médias et la responsabilité civique. Elle propose des pistes d’action aux personnes chargées des relations avec la société civile.</p><p>Le guide s’adresse aux personnes chargées des relations entre l’administration et la société civile. Il situe la participation dans le contexte des échanges avec les médias et de la responsabilité des institutions.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Zahvoiska, O. V., Drahomyretska, N. M., Dreshpak, V. M., Soloviov, S. H., Dzhyha, T. V., Kandahura, K. S., Matvieienko, I. V., Shmatovalenko, L. S., Fomenko, T. M., Loshkariova, Y. M., Demkiv, T. F., Derekh, I. A., Kupriianenko, L. V. et Martynets, N. S. (2011). <i>Building government–NGO interaction mechanisms</i> [Mise en place des mécanismes d’interaction du gouvernement avec les organisations non gouvernementales]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/02/CHukut-S.A.-Nalagodzhennya-mehanizmiv-vzayemodiyi-z-neuryadovimi-gromad-organizatsiyami.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2014/02/CHukut-S.A.-Nalagodzhennya-mehanizmiv-vzayemodiyi-z-neuryadovimi-gromad-organizatsiyami.pdf</a></p><div class=\"m\">Livres et monographies · 2011 · Développement scientifique et méthodologique. Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine. — 80 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">« Modernisation du secteur public par le gouvernement électronique »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-133\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-133\" hidden><p>Formation de l’Université nationale de Kyiv-Mohyla sur l’usage du gouvernement électronique pour moderniser les institutions et les services du secteur public. Le thème de la formation relie l’adoption des services en ligne à la réorganisation des processus administratifs et à l’évolution des compétences dans le secteur public.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Université nationale « Académie Mohyla de Kyiv ». (2011). <i>Modernisation du secteur public par le gouvernement électronique</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2011 · Université nationale « Académie Mohyla de Kyiv »</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Fondements institutionnels et organisationnels de la mise en œuvre de l’administration électronique en Ukraine <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-134\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-134\" hidden><p>Ouvrage collectif du programme de master en administration électronique, publié à Kyiv en 2011 (172 pages) sous la direction générale de Svitlana Chukut et Olha Zahvoiska, et titre inaugural de la série « Bibliothèque du gouvernement électronique ». Rédigé par les étudiants du programme dans le cadre du projet de recherche de la chaire sur les fondements de l’administration électronique, il examine comment sept pays — Autriche, Belgique, Irlande, Russie, Singapour, Thaïlande et Finlande — organisent le soutien institutionnel de l’administration électronique : organes responsables, coordination et législation. Svitlana Chukut a dirigé les travaux à l’origine du volume et enseigné la discipline de administration électronique dans le cadre de laquelle la recherche a été menée. Sa préface en tire la leçon pour l’Ukraine : créer une structure institutionnelle dédiée à la société de l’information et au administration électronique, et transformer les unités informatiques existantes des organes d’État et locaux en unités de administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Zahvoiska, O. V. (dir.). (2011). <i>Institutional and organisational foundations of e-governance implementation: Best foreign practices</i> [Fondements institutionnels et organisationnels de la mise en œuvre de l’administration électronique : meilleures pratiques étrangères]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Institutsijni-ta-organizatsijni-zasadi-vprovadzhennya-e_uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2011</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>12</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le programme de master en gouvernement électronique comme mécanisme institutionnel moderne de réforme de l’administration publique <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-135\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-135\" hidden><p>Écrit avec Olha Zahvoiska pour le premier numéro de la revue « E-Governance » (2010), l’article présente le programme de master en administration électronique comme un mécanisme institutionnel moderne de réforme de l’administration publique. Il examine comment d’autres pays ont introduit de tels programmes, puis expose la manière dont le programme ukrainien a été élaboré : la spécialité 8.150110 « Gouvernement électronique », conçue par la chaire de politique de l’information en 2008 et licenciée en 2009, et ce à quoi ses diplômés — dirigeants et spécialistes des systèmes organisationnels de administration électronique — sont formés selon la caractéristique éducative et de qualification et le programme éducatif et professionnel.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Zahvoiska, O. (2010). The master's programme in e-governance as a modern institutional mechanism for reforming public administration [Le programme de master en gouvernement électronique comme mécanisme institutionnel moderne de réforme de l’administration publique]. <i>E-Governance</i>, (1), 41–54. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/ZHurnal_Elektronne-uryaduvannya_1_2010.pdf</a></p><div class=\"m\">Articles · 2010 · « Administration électronique », n° 1, p. 41–54</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>16</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Questions de dotation en personnel pour la mise en œuvre de l’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-136\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-136\" hidden><p>Écrit avec Oleksandr Kukarin et Olha Zahvoiska, l'article traite le personnel qualifié comme la condition préalable à la mise en œuvre de l’administration électronique. Il décrit comment l'Académie nationale a commencé en 2009 à former des masters dans la nouvelle spécialité « Gouvernement électronique », et comment, en 2010, le classificateur national des professions a introduit une qualification formelle — « dirigeant des systèmes organisationnels de gouvernement électronique » (code 1229.7) — aux fonctions définies : stratégie et concepts, coordination de projets, rédaction juridique, analyse de la préparation et gestion de l'information. Les auteurs fixent les exigences de qualification pour ces dirigeants, les principes d'une formation continue, un modèle de stage en deux étapes pour les étudiants de master, et une proposition structurelle : transformer les unités informatiques existantes des organes d'État et locaux en unités de administration électronique, à commencer par le secrétariat du Cabinet des ministres.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Zahvoiska, O. et Kukarin, O. (2010). Staffing for e-governance implementation [Questions de dotation en personnel pour la mise en œuvre de l’administration électronique]. <i>Richelieu Readings, Odesa</i>, 67–70.</p><div class=\"m\">Articles · 2010 · Lectures Richelieu, Odesa, p. 67–70</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le programme de master en administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-137\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-137\" hidden><p>La contribution de Svitlana Chukut au recueil de Kyiv « Experience in Implementation of E-Democracy and E-Governance in Ukraine » (2010) présente le programme de master en administration électronique élaboré à l'Académie nationale d'administration publique — le premier du genre en Ukraine, préparé en 2008 pour la spécialité « Gouvernement électronique » (8.150110) et approuvé par l'arrêté n° 268 du ministère de l'Éducation et des Sciences du 24 mars 2009. Le texte expose les objectifs du programme — former des spécialistes qui utilisent créativement les TIC modernes, introduisent des technologies avancées de administration électronique pour les services publics et améliorent l'administration publique selon les normes mondiales et européennes —, les huit compétences professionnelles qu'il forme, de la rédaction de stratégies et de concepts à l'évaluation de la préparation électronique d'une institution, et ses traits distinctifs : forte orientation pratique, stage en deux étapes débouchant sur un mémoire de master soutenu, et dimensions européennes de la formation. Il énumère les disciplines obligatoires, de la démocratie électronique aux services électroniques, et les quatre filières de spécialisation — nationale, locale et régionale, entreprise, et gestion de l'information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2010). Master's program in electronic governance [Le programme de master en administration électronique]. Dans S. Dziuba (dir.), <i>Experience in implementation of e-democracy and e-governance in Ukraine</i> (p. 36–37). National Center for Support of Electronic Governance, Kyiv.</p><div class=\"m\">Articles · 2010 · Section 4.4. Dans : « Experience in Implementation of E-Democracy and E-Governance in Ukraine ». Centre national d’appui au gouvernement électronique, Kyiv, 2010, p. 36–37</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Travaux de recherche « Fondements théorico-méthodologiques de la mise en œuvre de l’administration électronique »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-138\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-138\" hidden><p>L'Ukraine voulait un gouvernement numérique, mais il n'existait pas de mode d'emploi commun pour le construire. Dirigé par Svitlana Chukut à l'Académie nationale d'administration publique (2010–2011, enregistrement d'État n° 0201U004833), ce projet a étudié les régularités de la formation et du développement de l'administration électronique en Ukraine et dans le monde, exposé son essence, ses méthodes et ses principes, et examiné les modèles de sa mise en œuvre aux niveaux national, régional et local. Il a étudié les problèmes et les perspectives de la formation de l'administration électronique au regard de la pratique nationale, ainsi que les étapes et les tâches de la mise en œuvre au regard des meilleures pratiques étrangères — et l'équipe a participé directement à la rédaction du Concept de développement de l'administration électronique en Ukraine. Ses produits ont été pratiques : un guide méthodologique sur l'introduction de l'administration électronique dans un établissement d'enseignement général ; les matériaux méthodologiques « Meilleures pratiques de mise en œuvre de l'administration électronique : l'expérience étrangère » (2010, 144 p.) ; les matériaux d'information et d'analyse « État et problèmes de la mise en œuvre de l'administration électronique dans les organes exécutifs centraux et locaux de l'Ukraine » ; les actes électroniques de la conférence « Défis et possibilités de la mise en œuvre de l'administration électronique en situation de crise » ; et les deux premiers numéros de la revue scientifique internationale « E-Governance ». Les résultats ont été utilisés par le Secrétariat du Conseil des ministres (son département des ressources et technologies de l'information) et par le Comité d'État pour l'informatisation, et intégrés au cours « Fondements théorico-méthodologiques, organisationnels et institutionnels de l'administration électronique » de la spécialité de master « Administration électronique ».</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Travaux de recherche « Fondements théorico-méthodologiques de la mise en œuvre de l’administration électronique</i> [Projet de recherche]. (2010–2011). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2010–2011 · Directrice de recherche</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Au sein du groupe de travail d’experts en administration électronique <a href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-139\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-139\" hidden><p>Le Fonds international Renaissance présente la participation de Svitlana Chukut au groupe d’experts sur le développement de l’administration électronique en Ukraine. Le dossier situe cette participation dans la préparation du premier cadre national de développement de l’administration électronique. Il documente la coopération entre les acteurs institutionnels et les experts.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Fondation internationale Renaissance. (2010). <i>Au sein du groupe de travail d’experts en administration électronique</i> [Notice de projet]. <a class=\"apa-source\" href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\">https://www.irf.ua/en/?p=70400</a></p><div class=\"m\">Interventions · 2010 · Actualité de la Fondation Renaissance</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Meilleures pratiques de mise en œuvre de l’administration électronique : expérience étrangère (recueil) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-140\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-140\" hidden><p>Matériaux méthodiques pour la discipline « Fondements théoriques, méthodologiques, organisationnels et institutionnels du gouvernement électronique », publiés à Kyiv en 2010 (166 pages) sous la direction scientifique de Svitlana Chukut et Olha Zahvoiska et approuvés par le conseil scientifique de l’Académie nationale. Rédigé par neuf étudiants du programme de master en administration électronique, le volume passe en revue les meilleures pratiques étrangères de mise en œuvre de l’administration électronique dans neuf pays — Australie, Inde, Canada, Allemagne, Norvège, Corée du Sud, Russie, Singapour et États-Unis — des indices de développement des Nations unies et des stratégies nationales aux portails et services phares. Svitlana Chukut a dirigé les travaux à l’origine du volume et enseigné la discipline pour laquelle ces matériaux ont été préparés.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Zahvoiska, O. V. (dir.). (2010). <i>Best practices in implementing e-governance: Foreign experience</i> [Meilleures pratiques de mise en œuvre de l’administration électronique : expérience étrangère]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Krashhi-praktiki-vprovadzhennya-elektronnogo-uryaduvannya_zarubizhnij-dosvid.pdf</a></p><div class=\"m\">Livres et monographies · 2010</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en place de mécanismes d’interaction entre le gouvernement et les organisations publiques non gouvernementales</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-141\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-141\" hidden><p>Développement scientifique et méthodique (Kyiv, 2010, 64 p.) préparé par un collectif de quinze auteurs sous la direction scientifique de Svitlana Chukut, comme produit du projet de recherche « Mise en place de mécanismes d'interaction efficace entre le gouvernement, le public et les médias : aspect théorique et appliqué » (enregistrement d'État n° 0109U003027). Il examine la formation de la responsabilité civique et son rôle dans la société civile, l'interaction entre l'individu et l'État dans la perception de l'information, l'interaction gouvernement–public et l'influence des médias sur ces processus, la conception de projets socioculturels au niveau régional, les risques dans les projets de communication, et l'introduction par projets de l’administration électronique et de la démocratie électronique dans les régions, y compris le pilote « École de gouvernement électronique ». Il traite aussi de la propagande médiatique et des technologies de relations publiques « sales », des centres analytiques non gouvernementaux et de l'influence des médias sur la formation de la société civile ; il s'adresse aux étudiants, aux enseignants, aux instituts de la société civile et aux responsables gouvernementaux chargés des relations avec le public et les médias.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Zahvoiska, O., Drahomyretska, N., Dreshpak, V., Soloviov, S., Dzhyha, T., Kandahura, K., Matvieienko, I., Shmatovalenko, L., Fomenko, T., Loshkariova (Hrechishkina), Y., Demkiv, T., Derekh, I., Kupriianenko, L. et Martynets, N. (2010). <i>Establishing mechanisms of interaction between the Government and non-governmental public organisations: Scientific and methodical development</i> [Mise en place de mécanismes d’interaction entre le gouvernement et les organisations publiques non gouvernementales : guide scientifique et méthodologique]. National Academy of Public Administration under the President of Ukraine.</p><div class=\"m\">Livres et monographies · 2010 · Développement scientifique et méthodique. Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine, 2010. — 64 p.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Questions d’interopérabilité de la fourniture des services publics électroniques</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-142\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-142\" hidden><p>Écrit avec Olha Zahvoiska pour le « Bulletin de la fonction publique d'Ukraine » (2009, n° 1), l'article soutient que l'interopérabilité n'est pas une question technique étroite de réseaux informatiques : elle s'étend à l'échange d'information entre réseaux et à la réorganisation des procédures administratives, afin que les services publics électroniques puissent réellement être fournis — entre administrations, entre niveaux de gouvernement et par-delà les frontières de l'Union européenne. Un développement non coordonné, avertissent les auteures, produit des « îlots » de administration électronique incapables d'interagir. La réponse qu'elles développent est la formation professionnelle : après un tour d'horizon des programmes de master en administration électronique, de Syracuse et McGill à Oslo, Tampere et Waseda, l'article présente le premier programme ukrainien de master en administration électronique, élaboré en 2008 à la chaire de politique de l'information de l'Académie nationale — ses modules, ses quatre spécialisations et les compétences que ses diplômés devaient apporter à l'administration d'État et locale.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Zahvoiska, O. (2009). Interoperability of e-public service delivery [Questions d’interopérabilité de la fourniture des services publics électroniques]. <i>Bulletin of the Civil Service of Ukraine</i>, (1), 78–81.</p><div class=\"m\">Articles · 2009 · Bulletin de la fonction publique, vol. 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>10</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Administration électronique : support de cours <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-143\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-143\" hidden><p>Ce support de cours présente les concepts et les principes de mise en œuvre de l’administration électronique. Il relie les choix institutionnels et technologiques à l’organisation des services publics.</p><p>Le support fournit un cadre de formation pour étudier la coordination des administrations, l’accès aux services en ligne et les décisions qui accompagnent leur déploiement.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Kukarin, O. B. (2009). <i>E-governance: Course outline</i> [Administration électronique : support de cours]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Elektrone_uryaduvannya_CHukut_Kukarin_2009.pdf</a></p><div class=\"m\">Livres et monographies · 2009 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information en Ukraine : recommandations méthodologiques pour les travaux pratiques</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-144\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-144\" hidden><p>Ces recommandations accompagnent les travaux pratiques et l’étude autonome du cours sur la politique de l’information en Ukraine. Elles aident à mettre les notions du cours en relation avec des situations de l’administration publique.</p><p>Le guide organise les travaux autour de l’analyse des politiques publiques de l’information et de leur mise en application. Les exercices complètent les cours destinés aux futurs spécialistes de l’administration publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Zahvoiska, O. V., Kukarin, O. B. et Poprotskyi, O. P. (2009). <i>Information policy in Ukraine: Practical class guidelines</i> [Politique d’information en Ukraine : recommandations méthodologiques pour les travaux pratiques]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod-rekomend_Informatsijna-politika.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod-rekomend_Informatsijna-politika.pdf</a></p><div class=\"m\">Livres et monographies · 2009 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Rédactrice en chef de la revue internationale « Administration électronique »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-145\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-145\" hidden><p>Direction de la revue scientifique internationale E-Governance, consacrée à la recherche et aux pratiques de l’administration électronique, de 2009 à 2011. La responsabilité éditoriale s’inscrit dans la constitution d’un espace de diffusion scientifique consacré à l’administration numérique et à la modernisation des services publics.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Rédactrice en chef de la revue internationale « Administration électronique</i> [Notice de service éditorial]. (2009–2011).</p><div class=\"m\">Livres et monographies · 2009–2011 · Travail éditorial</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Travaux de recherche « Mise en place de mécanismes d’interaction efficace entre le gouvernement, le public et les médias : aspect théorique et appliqué »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-146\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-146\" hidden><p>Les décisions publiques passent mieux lorsque fonctionnaires, citoyens et médias se comprennent vraiment. Dirigée par Svitlana Chukut (2009–2010, enregistrement d'État n° 0109U003027), cette recherche a conçu des mécanismes pratiques pour cette interaction — et les a mis à l'épreuve sur le terrain. L'équipe a testé, à titre pilote, le niveau de responsabilité civique : dans le cadre du projet pilote « École d'administration électronique » dans le district de Novovorontsovka, région de Kherson, et d'un projet de communication mené en application d'une résolution du président du Conseil des ministres de Crimée. Elle a élaboré et mis en pratique les projets socioculturels et d'information « Responsabilité civique » ainsi qu'une vidéo, et élaboré et mis en œuvre, à l'Administration d'État régionale de Kherson, le projet « Mécanismes de formation de la réserve présidentielle de cadres \"Nouvelle élite de la nation\" au niveau régional ». Parmi ses produits écrits : des recommandations méthodologiques pour le cours « Communications dans l'administration publique » (48 p.), le manuel scientifique et méthodologique « Mise en place des mécanismes d'interaction du Gouvernement avec les organisations non gouvernementales » (64 p., réalisé par une équipe d'auteurs dirigée par Chukut), un programme de séminaire-formation sur l'interaction du Gouvernement avec les ONG, et le manuel achevé « Communications dans l'administration publique ». La mise en œuvre a été formalisée par des actes d'implémentation : le Département des relations publiques du Secrétariat du Conseil des ministres (décembre 2009), le Conseil des ministres de Crimée (21 janvier 2010), le Département de la presse et de l'information de l'Administration d'État régionale de Kherson (15 décembre 2010) et le Département de l'éducation du district de Novovorontsovka (22 janvier 2010). Par sa participation au groupe de travail du Comité d'État pour l'informatisation, la recherche a également alimenté le Concept de développement de l'administration électronique en Ukraine, adopté par la résolution du Conseil des ministres n° 2250-r du 13 décembre 2010.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Travaux de recherche « Mise en place de mécanismes d’interaction efficace entre le gouvernement, le public et les médias : aspect théorique et appliqué</i> [Projet de recherche]. (2009–2010). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2009–2010 · Directrice de recherche</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Concept de développement de l’administration électronique en Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-147\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-147\" hidden><p>Document de politique collectif préparé avec le soutien de la Fondation internationale Renaissance et édité par Andrii Semenchenko, Svitlana Chukut figurant parmi ses douze auteurs. La Conception définit le but, les objectifs principaux, les tâches, les fonctions et les principes de base de la mise en œuvre et du développement de l’administration électronique en Ukraine jusqu'en 2015, ses étapes et ses conditions préalables, ainsi que ses particularités en conditions de crise, avec la politique de l'État dans ce domaine. Elle propose un appareil catégoriel et conceptuel pour le champ, des mécanismes de gestion du développement de l’administration électronique et de prestation des services publics, et sert de base à une stratégie de développement, à des documents de programme et à un projet de loi sur l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Baranov, O. A., Demkova, M. S., Dziuba, S. V., Yefanov, A. V., Zhyliaiev, I. B., Klepets, E. L., Misnikov, I., Arvo, O., Popova, T. V., Ruban, I. A. et Semenchenko, A. I. (2009). <i>Electronic government development concept for Ukraine</i> [Concept de développement de l’administration électronique en Ukraine] [Document de travail].</p><div class=\"m\">Livres et monographies · 2009 · Kyiv, 2009. — 16 p.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Projet de manuel « Fondements conceptuels du développement de l’administration électronique » <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-148\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-148\" hidden><p>Projet de manuel préparé par un collectif de douze auteurs édité par Andrii Semenchenko, Svitlana Chukut figurant parmi les auteurs. S'appuyant sur la Conception nationale, il définit la finalité, les buts, les tâches, les fonctions et les principes de base de la mise en œuvre et du développement de l’administration électronique en Ukraine, analyse la pratique ukrainienne et étrangère d'application des technologies de administration électronique, et propose un modèle d'administration publique pour la société de l'information. Il élabore les étapes du développement de l’administration électronique, ses mécanismes de gestion, et le soutien législatif, administrativo-organisationnel et technologique que le système requiert ; il est recommandé aux spécialistes de l'administration publique, aux enseignants et aux chercheurs.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Semenchenko, A. I. (dir.). (2009). <i>Conceptual foundations of e-governance development in Ukraine</i> [Fondements conceptuels du développement de l’administration électronique en Ukraine] [Projet de manuel]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Kontseptualni-zasadi-rozvitku-elektronnogo-uryaduvannya-v-Ukrayini.pdf</a></p><div class=\"m\">Livres et monographies · 2009 · Kyiv, 2009. — 82 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>77</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mise en place de mécanismes d’interaction efficace du gouvernement avec le public et les médias : rapport intermédiaire de recherche (enregistrement d’État n° 0109U003027)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-149\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-149\" hidden><p>Voici le rapport à mi-parcours (Kyiv, 2009) de la recherche de l'Académie dirigée par Svitlana Chukut sur la manière dont le gouvernement, les citoyens et les médias peuvent mieux interagir (enregistrement d'État n° 0109U003027). Rédigé avec des collègues, dont N. M. Drahomyretska et V. M. Dreshpak, il rendait compte de l'avancement du projet et de ses premiers résultats. La recherche achevée a ensuite produit un manuel, des recommandations pédagogiques et un projet pilote adoptés par le Secrétariat du Conseil des ministres.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Establishing mechanisms for effective government interaction with the public and mass media: Interim research report (state registration no. 0109u003027)</i> [Mise en place de mécanismes d’interaction efficace du gouvernement avec le public et les médias : rapport intermédiaire de recherche (enregistrement d’État n° 0109U003027)] [Rapport intermédiaire]. (2009). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2009 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Appui scientifique et méthodologique aux relations publiques dans les organes du pouvoir exécutif de l’État <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-150\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-150\" hidden><p>Recommandations méthodiques produites par un collectif de sept auteurs sous la direction générale de Svitlana Chukut à l'Académie nationale d'administration publique (Kyiv, 2008, 72 p.), comme produit du projet de recherche « Élaboration du soutien scientifique et méthodique aux relations publiques dans les organes exécutifs » (enregistrement d'État n° 0107U005909), qu'elle a dirigé. Les recommandations exposent les fondements organisationnels des relations publiques dans les organes exécutifs, la planification et la régulation juridique des unités chargées de l'interaction avec les médias et des relations publiques, ainsi que les méthodes et technologies par lesquelles les autorités publiques travaillent avec les médias et le public. Elles s'adressent aux étudiants de la spécialité « Administration publique » et au personnel de ces unités.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (General Ed.), Dzhyha, T., Barovska, A., Karpenko, O., Nedashkivska, T., Poprotskyi, O. et Skrebets, R. (2008). Scientific and methodological support for public relations in executive bodies: Methodical recommendations [Appui scientifique et méthodologique aux relations publiques dans les organes du pouvoir exécutif de l’État]. National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Naukovo-metodichne-zabezpechennya-zv-yazkiv-z-gromadskistyu-v-ODVV.pdf</a></p><div class=\"m\">Articles · 2008 · Recommandations méthodologiques. Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine, 2008. — 72 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>5</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/egov-2008.jpg\" alt=\"Expérience nationale et étrangère de mise en œuvre de l’administration électronique\"><div class=\"lib-copy\"><div class=\"t\">Expérience nationale et étrangère de mise en œuvre de l’administration électronique <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-151\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-151\" hidden><p>Actes de la conférence scientifique et pratique tenue à l'Académie nationale d'administration publique auprès du Président de l'Ukraine pour la Journée de l’administration électronique, le 14 mai 2008 (Kyiv, 2008, 128 p. ; rédactrices générales Svitlana Chukut et Olha Zahvoiska ; recommandé par le Conseil académique de l'Académie, protocole n° 148/8-4 du 28 août 2008). Le volume présente des approches scientifico-pratiques, des résultats de recherche et des expériences de mise en œuvre dans l’administration électronique et la démocratie électronique : ses sections couvrent l’administration électronique au niveau central et au niveau local, les services électroniques, la démocratie électronique, et les principales tâches de l’administration électronique — y compris le rôle de la corporation Microsoft dans leur réalisation — et il se termine par les recommandations adoptées à l'issue de la Journée de l’administration électronique 2008. Les matériaux, tirés de l'expérience nationale et étrangère de pointe de l’administration électronique dans l'administration centrale, locale et régionale, s'adressent aux praticiens de l'administration publique et des entreprises, aux dirigeants des autorités étatiques et locales, des entreprises, des institutions et des organisations de la société civile, et à tous ceux qui étudient, recherchent, mettent en œuvre ou utilisent les technologies de administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Zahvoiska, O. V. (dir.). (2008). <i>Domestic and foreign experience of implementing e-governance</i> [Expérience nationale et étrangère de mise en œuvre de l’administration électronique]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Vitchiznyanij-i-zarubizhnij-dosvid-vprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2008 · Actes de la conférence scientifique et pratique « Journée du gouvernement électronique – 2008 ». Kyiv : Académie nationale d'administration publique auprès du Président de l'Ukraine, 2008. — 128 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>24</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/info-policy-textbook-cover.jpg\" alt=\"Politique d’information : manuel (2e éd.)\"><div class=\"lib-copy\"><div class=\"t\">Politique d’information : manuel (2e éd.)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-152\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-152\" hidden><p>Un ouvrage d'étude fondamental consacré à l'examen complet des fondements théoriques, juridiques et gestionnaires de la politique de l'information dans le contexte de la construction de la société de l'information, intégrant les approches de l'administration publique, de la science politique, du droit et de la théorie des communications stratégiques. La contribution d'auteure de Svitlana Chukut couvre les blocs institutionnel-gestionnaire et numérique de la discipline : les fondements théoriques et méthodologiques de la mise en œuvre de l’administration électronique, les étapes de la transformation numérique de l'administration publique et les modèles de démocratie électronique ; une analyse comparative des pratiques mondiales réussies de développement de la société de l'information et de la gouvernance électronique (l'Union européenne, les États-Unis, la Grande-Bretagne, l'Estonie, Singapour) ; et les mécanismes de la politique de l'information de l'État ukrainien, la protection des ressources informationnelles, l'accès des citoyens à l'information publique et la réduction de la fracture numérique. L'un des premiers ouvrages académiques de base en Ukraine à intégrer la gouvernance électronique dans un cours général de politique de l'information de l'État, le livre contient un complexe pédagogique et méthodologique complet — glossaire, questions de contrôle, sujets de travaux scientifiques et base normative — et est largement utilisé dans la formation des spécialistes en administration publique, science politique, relations internationales et sécurité de l'information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pocheptsov, H. H. et Chukut, S. A. (2008). <i>Information policy</i> [Politique de l’information] (2e éd.). Znannia. <a class=\"apa-source\" href=\"https://koha.oa.edu.ua/cgi-bin/koha/opac-detail.pl?biblionumber=340847\" target=\"_blank\" rel=\"noopener\">https://koha.oa.edu.ua/cgi-bin/koha/opac-detail.pl?biblionumber=340847</a></p><div class=\"m\">Livres et monographies · 2008 · Kyiv : Znannia, 2e éd. — 663 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>35</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique de communication dans les organes du pouvoir d’État : support de cours</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-153\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-153\" hidden><p>Conspectus de cours magistral pour la discipline « Politique de communication dans les organes du pouvoir d'État », par Svitlana Chukut et Tetiana Dzhyha (Maison d'édition de l'Académie nationale d'administration publique, Kyiv, 2008, 72 p. ; approuvé par le Conseil académique de l'Académie nationale d'administration publique auprès du Président de l'Ukraine, procès-verbal n° 111/11-1 du 11 novembre 2008). Le conspectus expose les principaux fondements théoriques et méthodologiques de la discipline : il définit les dispositions clés de la politique de communication, présente les tâches principales des unités de communication des organes du pouvoir, analyse l'expérience étrangère de mise en œuvre de la politique de communication et révèle les principales technologies d'interaction avec le public. Ses chapitres portent sur la démocratisation de la prise de décision en Ukraine, le cadre réglementaire et juridique de l'interaction des autorités avec le public, les tâches et fonctions des unités de communication, la pratique étrangère et la planification des communications des organes exécutifs avec le public et les médias. Le manuel est destiné aux étudiants en master de l'Académie nationale, spécialité « Administration publique », spécialisation « Processus informationnels dans l'administration publique », et est également utile aux gestionnaires praticiens et aux spécialistes de la politique de l'information, des communications et des relations publiques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Dzhyha, T. (2008). Communicative policy in public authorities: Lecture outline [Politique de communication dans les organes du pouvoir d’État : support de cours]. NAPA Publishing House.</p><div class=\"m\">Livres et monographies · 2008 · Kyiv : Maison d'édition de l'Académie nationale d'administration publique, 2008. — 72 p.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information et administration électronique : support de cours</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-154\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-154\" hidden><p>Ce support relie les politiques de l’information au fonctionnement des administrations numériques. Il aborde notamment l’organisation des échanges d’information et les services offerts en ligne. Le support permet d’examiner ensemble les règles qui régissent l’information publique et les choix administratifs nécessaires pour offrir des services en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Kukarin, O. B. (2008). <i>Information policy and e-governance: Course outline</i> [Politique d’information et administration électronique : support de cours]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_Informatsijna-politika-ta-elektronne-uryaduvannya_CHukut_Kukarin.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_Informatsijna-politika-ta-elektronne-uryaduvannya_CHukut_Kukarin.pdf</a></p><div class=\"m\">Livres et monographies · 2008 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Direction scientifique de recueils sur l’administration électronique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-155\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-155\" hidden><p>Direction scientifique de trois recueils sur l’expérience internationale, les pratiques exemplaires et les fondements institutionnels de l’administration électronique. Les recueils réunissent des études comparatives destinées à l’enseignement et à la pratique. Ils abordent le rôle des institutions, des stratégies nationales et des services offerts au public.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Direction scientifique de recueils sur l’administration électronique</i> [Notice de service éditorial]. (2008–2011).</p><div class=\"m\">Livres et monographies · 2008–2011 · « Expérience étrangère… » (2008), « Meilleures pratiques… » (2010), « Fondements institutionnels… » (2011)</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Travaux de recherche « Élaboration du soutien scientifique et méthodique aux relations publiques dans les organes exécutifs » (enregistrement d’État n° 0107U005909)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-156\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-156\" hidden><p>Comment un ministère ou une mairie doit-il s'adresser au public — ouvertement, professionnellement, et surtout en situation de crise ? Cette étude de l'Académie menée en 2008 sous la direction de Svitlana Chukut (enregistrement d'État n° 0107U005909 ; rapport de recherche de 135 pages) visait à donner aux relations publiques gouvernementales en Ukraine une base scientifique et méthodologique. L'équipe a défini les principales directions de développement et de fonctionnement des relations publiques dans l'administration publique, analysé l'expérience étrangère et développé davantage les fondements méthodologiques de l'interaction entre les autorités publiques et le public, conformément aux propositions de l'Administration du Président et des organes exécutifs. Elle a également élaboré les fondements du travail d'information et d'analyse des services de relations publiques dans les organes d'État, analysé l'interaction des autorités publiques avec les conseils publics auprès du Président, du Gouvernement, des ministères et des chefs d'administrations d'État locales, étudié les relations publiques en situation de crise et analysé l'influence des technologies de l'information modernes sur les relations publiques. Les résultats ont été pratiques : le manuscrit du manuel scientifique et pratique « Relations publiques dans l'administration publique : aspect théorique et appliqué » a été préparé pour l'impression, 22 articles scientifiques ont été publiés et 5 manuels scientifiques et méthodologiques préparés ; les résultats ont été mis en œuvre en coopération avec le Département des relations publiques du Secrétariat du Conseil des ministres de l'Ukraine et intégrés aux matériaux pédagogiques de la chaire.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Travaux de recherche « Élaboration du soutien scientifique et méthodique aux relations publiques dans les organes exécutifs » (enregistrement d’État n° 0107U005909)</i> [Projet de recherche]. (2008). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2008 · Directrice de recherche</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Concept de développement de l’administration électronique en Ukraine (ordonnance du Conseil des ministres n° 2250-r) <a href=\"https://www.irf.ua/en/?p=70400\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-157\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-157\" hidden><p>Avant 2010, l'Ukraine n'avait aucun plan national unique pour le gouvernement numérique. Un groupe de travail auprès du Comité d'État de l'informatisation, soutenu par la Fondation internationale Renaissance, a rédigé le premier Concept de développement de l'administration électronique du pays — un plan indiquant quoi construire et dans quel ordre. Svitlana Chukut était membre du groupe, et le Conseil des ministres a approuvé le Concept le 13 décembre 2010 (ordonnance n° 2250-r), en faisant le point de départ officiel des réformes du gouvernement numérique en Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Cabinet des ministres de l’Ukraine. (2010, 13 décembre). <i>Approbation du Concept de développement de l’administration électronique en Ukraine</i> [Arrêté n° 2250-r]. <a class=\"apa-source\" href=\"https://zakon.rada.gov.ua/laws/show/2250-2010-%D1%80\" target=\"_blank\" rel=\"noopener\">https://zakon.rada.gov.ua/laws/show/2250-2010-%D1%80</a></p><div class=\"m\">Projets · 2008–2010 · Membre du groupe de travail (subvention de la Fondation Renaissance)</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Expérience étrangère de mise en œuvre de l’administration électronique <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-158\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-158\" hidden><p>Recueil des meilleurs travaux créatifs des auditeurs de la nouvelle spécialité « Administration publique », rédigés pour la discipline « Gouvernement électronique » à l'Académie nationale d'administration publique auprès du Président de l'Ukraine (Kyiv, 2008, 200 p. ; collectif d'auteurs de dix auditeurs ; rédactrice générale Svitlana Chukut). Dix chapitres par pays passent en revue la manière dont l’administration électronique a été mise en œuvre en Grande-Bretagne, en Estonie, au Canada, en Allemagne, en Pologne, en Russie, à Singapour, aux États-Unis, en France et en Suède. Destiné à tous ceux qui s'intéressent aux problèmes de la mise en œuvre de l’administration électronique en Ukraine et dans le monde.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (dir.), Kaminska, T., Kaminskyi, A., Pasichnyk, M., Seleshchuk, V., Havrylets, O., Kyryliuk, I., Mazhak, N., Yakymenko, O., Bekirova, A. et Yesypenko, A. (2008). Foreign experience in implementing e-governance [Expérience étrangère de mise en œuvre de l’administration électronique]. National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Zarubizhnij-dosvid-uprovadzhennya-elektronnogo-uryaduvannya.pdf</a></p><div class=\"m\">Articles · 2008 · Kyiv : Académie nationale d'administration publique auprès du Président de l'Ukraine, 2008. — 200 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>29</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Démocratie électronique : essence et principales étapes <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-159\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-159\" hidden><p>Communication de Svitlana Chukut dans les actes de la Journée de l’administration électronique 2008 (p. 89–95). Elle définit la démocratie électronique comme l’État assurant les conditions préalables nécessaires à la participation des citoyens à l’élaboration et à l’adoption des décisions de l’État à l’aide des technologies modernes de l’information et de la communication, et explique que l’administration électronique construit la confiance entre le gouvernement et les citoyens sur laquelle elle repose — par la participation à la prise de décision, l’ouverture, la responsabilité et la prévention de la corruption. Elle expose les principales étapes de la formation de la démocratie électronique : l’e-information, un flux à sens unique des organes de l’État vers les citoyens (accès aux documents, catalogues, registres et index, projets de loi publiés et livres blancs et verts, rapports et guides en ligne, par courriel, portails web, communication mobile, kiosques d’information et disques — avec les problèmes connexes d’information confidentielle, de secrets d’État, de vie privée et de sécurité nationale) ; l’e-consultation, dans laquelle le gouvernement demande l’opinion des citoyens en ligne et reçoit demandes, plaintes, propositions et réponses à des sondages dans une relation bidirectionnelle limitée entravée par la fracture numérique ; l’e-participation, l’implication active des citoyens, fondée sur la rétroaction, dans la prise de décision et l’élaboration des politiques, via des forums et des clavardages gouvernementaux et publics, des jeux interactifs et des espaces de travail virtuels ; et l’e-partenariat, dans lequel la responsabilité des décisions est partagée par les deux parties sur une base de confiance mutuelle — une étape encore à ses débuts. Elle conclut avec les problèmes à résoudre — inégalité numérique, accès pour les personnes handicapées, illettrisme en TIC, personnel, capacité technique, financement, statut juridique et responsabilité, sécurité et vie privée — et les moyens de les résoudre, de la garantie de l’accès et de la réingénierie de la fonction publique à la modification de la législation et à la combinaison des TIC avec les moyens traditionnels.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2008). E-democracy: Essence and main stages [Démocratie électronique : essence et principales étapes]. Dans S. Chukut et O. Zahvoiska (dir.), <i>Domestic and foreign experience of e-governance implementation</i> (p. 89–95). National Academy of Public Administration under the President of Ukraine, Kyiv. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2014/09/CHukut_Elektronna-demokratiya_Etapi-rozvitku_9_11_17.pdf</a></p><div class=\"m\">Articles · 2008 · Actes de la conférence scientifique et pratique « Journée du gouvernement électronique – 2008 » : « Expérience nationale et étrangère de mise en œuvre de l’administration électronique ». Kyiv : Académie nationale d'administration publique auprès du Président de l'Ukraine, 2008, p. 89–95</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gouvernement électronique : guide scientifique et pratique <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-160\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-160\" hidden><p>Un guide scientifique et pratique composé par Svitlana Chukut avec I. V. Klymenko et K. O. Lynov. Il expose l'essence, les principes et les approches de la mise en œuvre de l’administration électronique en Ukraine, à la lumière de l'expérience étrangère, et en détaille les mécanismes pratiques : les obstacles liés à la fracture numérique, les objectifs et les résultats attendus du système d'information « Gouvernement électronique », une classification des services et processus publics électroniques, les portails gouvernementaux comme principal canal de communication et les modèles d'architecture permettant d'intégrer les composantes du système. Il s'adresse aux auditeurs du système de perfectionnement en administration publique, aux fonctionnaires et aux chercheurs.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Klymenko, I. V. et Lynov, K. O. (2007). <i>Electronic government: A scientific and practical reference guide</i> [Gouvernement électronique : guide scientifique et pratique]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf</a></p><div class=\"m\">Articles · 2007 · Copie numérique du guide de 2007</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a><span class=\"scholar-record-note\">Cette copie numérique est comprise dans le total des citations du guide.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gouvernement électronique : guide scientifique et pratique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-161\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-161\" hidden><p>Ce guide destiné aux fonctionnaires, aux chercheurs et aux participants à la formation continue présente les architectures du gouvernement électronique, les normes de données et de documents ainsi que les portails et les services publics numériques.</p><p>Le guide compare des modèles étrangers et met ces expériences en relation avec les conditions de mise en œuvre en Ukraine, du niveau central aux administrations régionales et locales.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Klymenko, I. V. et Lynov, K. O. (2007). <i>Electronic government: A scientific and practical reference guide</i> [Gouvernement électronique : guide scientifique et pratique]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Elektronnij-uryad_nauk_prak-dovidnik_CHukut_Linov_Klimenko.pdf</a></p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine. — 70 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>38</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information en Ukraine : recommandations méthodologiques de cours</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-162\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-162\" hidden><p>Ce guide accompagne l’étude de la politique de l’information en Ukraine. Il oriente la préparation des cours et l’analyse du rôle des institutions publiques dans ce domaine. Les recommandations accompagnent l’étude des responsabilités de l’État, des règles applicables à l’information et de leurs implications pour les institutions publiques ukrainiennes.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2007). <i>Information policy in Ukraine: Course guidelines</i> [Politique d’information en Ukraine : recommandations méthodologiques de cours]. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><img class=\"lib-cover\" src=\"assets/books/info-policy.jpg\" alt=\"Politique d’information en Ukraine : support de cours\"><div class=\"lib-copy\"><div class=\"t\">Politique d’information en Ukraine : support de cours <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-163\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-163\" hidden><p>Conspectus de cours magistral pour la discipline « Politique de l'information en Ukraine », par Svitlana Chukut et Tetiana Dzhyha (Kyiv, 2007, 94 p.). Le conspectus expose les principaux fondements théoriques et méthodologiques de la discipline : il décrit les dispositions clés de la politique de l'information, révèle l'activité des autorités centrales dans le domaine de l'information, présente les principes essentiels de la politique de l'information des pays étrangers en matière de construction de la société de l'information, analyse la réglementation juridique de la sphère informationnelle et les principaux aspects de la mise en œuvre de la gouvernance électronique en Ukraine et dans le monde, et met l'accent sur les questions problématiques et clés de la politique de communication dans les organes du pouvoir. Ses chapitres portent sur la politique de l'information de l'État ukrainien et les autorités centrales dans la sphère informationnelle, la politique de l'information étrangère en matière de construction de la société de l'information, et la réglementation juridique de la sphère informationnelle. Le manuel est destiné aux étudiants en master de l'Académie nationale d'administration publique auprès du Président de l'Ukraine, spécialité « Administration publique », et est également utile aux gestionnaires praticiens, aux spécialistes de la politique de l'information, ainsi qu'aux étudiants et enseignants des spécialités économiques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Dzhyha, T. V. (2007). <i>Information policy in Ukraine: Lecture outline</i> [Politique d’information en Ukraine : support de cours]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt-lektsij_CHukut_Dzhiga_Informatsijna-politika-v-Ukrayini.pdf</a></p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine, 2007. — 94 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique de communication dans les organes du pouvoir d’État : recommandations méthodologiques pour le cours à distance</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-164\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-164\" hidden><p>Recommandations méthodologiques pour les auditeurs du cours à distance « Politique de communication dans les organes du pouvoir d’État », compilées par Svitlana Chukut avec Tetiana Dzhyha et Anna Barovska (Académie nationale d’administration publique auprès du Président de l’Ukraine, Kyiv, 2007, 39 p.). Les recommandations accompagnent un cours de perfectionnement destiné au personnel des organes exécutifs chargé de l’interaction avec les médias et le public : sa tâche est de former un personnel hautement qualifié capable d’élaborer, d’analyser et de mettre en œuvre la politique de communication de l’État et d’introduire des technologies avancées d’administration publique selon les normes mondiales et européennes. Elles exposent les objectifs du cours — révéler les principes de l’interaction des autorités de l’État avec le public, les méthodes de travail avec les associations civiques et les médias, l’état actuel de l’interaction des autorités ukrainiennes avec les médias, ses problèmes les plus pressants et les moyens de les résoudre — et ses résultats d’apprentissage : comprendre l’essence de l’étape actuelle de la politique de communication de l’État en Ukraine, appliquer les technologies de communication et d’information dans la préparation, l’adoption et la mise en œuvre des décisions de gestion, informer le public par une liaison constante avec les médias, et organiser le soutien public des décisions par des briefings, des conférences de presse et d’autres événements publics. La stratégie d’apprentissage combine le travail indépendant des auditeurs sur l’ensemble des matériaux pédagogiques du cours — dont le manuel « Politique de l’information » de Heorhii Pocheptsov et Svitlana Chukut (2006), un manuel électronique, des notes de cours et ces recommandations — avec des séminaires et des travaux pratiques interactifs, des tests informatiques en mode interactif et la discussion de problèmes pratiquement significatifs de la politique de communication.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A., Dzhyha, T. V. et Barovska, A. V. (2007). <i>Communicative policy in public authorities: Distance course guide</i> [Politique de communication dans les organes du pouvoir d’État : recommandations méthodologiques pour le cours à distance]. Secrétariat du Cabinet des ministres de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod_rekomendatsiyi-do-dist-kursu_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Metod_rekomendatsiyi-do-dist-kursu_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf</a></p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine, 2007. — 39 p.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique de communication dans les organes du pouvoir d’État : support de cours pour le cours à distance <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-165\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-165\" hidden><p>Conspectus du cours à distance « Politique de communication dans les organes du pouvoir d’État », par Svitlana Chukut et Tetiana Dzhyha (Secrétariat du Cabinet des ministres de l’Ukraine, Kyiv, 2007, 117 p.), manuel d’étude principal du cours à distance, accompagné de recommandations méthodologiques pour ses auditeurs. Le conspectus présente les fondements de la politique de communication : les principes de base de la communication — ses modèles, les règles d’interaction entre les autorités et le public, et la communication comme échange bilatéral dont la qualité façonne la perception de l’autorité par le public ; les approches scientifiques de la formation de la politique de communication des autorités de l’État — les théories de la démocratie et de la participation publique, les principes des relations publiques comme coopération plutôt que manipulation, et la tâche d’établir un dialogue efficace et la confiance du public envers le gouvernement ; et les problèmes de la réforme de l’administration publique en Ukraine dans leur aspect communicatif — l’inefficacité et la fermeture de l’administration, la doctrine des services administratifs et le traitement de la personne privée comme un client, les obstacles à la démocratisation de la prise de décision identifiés dans le Livre blanc du Secrétariat, et le développement de la gouvernance électronique comme moyen d’assurer la transparence du pouvoir et sa responsabilité devant la société.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. et Dzhyha, T. (2007). Communicative policy in public authorities: Course outline [Politique de communication dans les organes du pouvoir d’État : support de cours pour le cours à distance]. Secretariat of the Cabinet of Ministers of Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Opornij-konspekt_Komunikativna-politika-v-organah-derzhavnoyi-vladi.pdf</a></p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Secrétariat du Cabinet des ministres de l’Ukraine, 2007. — 117 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>8</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Cadre juridique de la sphère de l’information en Ukraine et à l’étranger : recommandations méthodologiques</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-166\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-166\" hidden><p>Ce guide d’étude autonome compare l’encadrement juridique de la sphère de l’information en Ukraine et à l’étranger. Il accompagne l’étude des règles qui s’appliquent aux institutions et aux échanges d’information.</p><p>Les deux contextes permettent de comparer les responsabilités des institutions publiques et les instruments juridiques qui encadrent la circulation et l’utilisation de l’information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Skrebets, R. (2007). <i>Legal support of the information sphere in Ukraine and abroad</i> [Cadre juridique de la sphère de l’information en Ukraine et à l’étranger : recommandations méthodologiques] [Guide pédagogique]. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Utilisation pratique du gouvernement électronique et de l’administration électronique : recommandations méthodologiques</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-167\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-167\" hidden><p>Ce guide aide les fonctionnaires et les participants aux formations à appliquer les notions de gouvernement et d’administration électroniques à la prestation des services et au fonctionnement des institutions.</p><p>Les recommandations relient l’introduction des outils numériques aux tâches quotidiennes des administrations et aux besoins des collectivités locales et des personnes qui utilisent les services.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Dzhyha, T. V. (2007). <i>Practical use of e-government and e-governance: Guidelines</i> [Utilisation pratique du gouvernement électronique et de l’administration électronique : recommandations méthodologiques]. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Utilisation pratique du gouvernement électronique et de l’administration électronique. Développements scientifiques appliqués</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-168\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-168\" hidden><p>Recommandations méthodiques compilées par Svitlana Chukut avec Tetiana Dzhyha, Oleksandr Poprotskyi, Anastasiia Borovska et Oleksandr Karpenko (Kyiv : Académie nationale d'administration publique, 2007), publiées dans le recueil de l'Académie « Développements scientifiques appliqués à l'usage des employés des autorités d'État et des collectivités locales » et approuvées par le conseil académique de l'Académie le 24 mai 2007. Les recommandations exposent les technologies et les mécanismes d'une interaction efficace entre les autorités d'État, les collectivités locales et le public, et offrent aux organes d'État et locaux des recommandations pratiques pour l'introduction de l’administration électronique. Elles s'adressent aux étudiants de master, aux doctorants et à tous ceux qui étudient l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S., Dzhyha, T., Poprotskyi, O., Borovska, A. et Karpenko, O. (2007). <i>Practical use of electronic government and governance: Methodical recommendations</i> [Utilisation pratique du gouvernement électronique et de l’administration électronique : recommandations méthodologiques]. National Academy of Public Administration.</p><div class=\"m\">Livres et monographies · 2007 · Dans : « Développements scientifiques appliqués à l’usage des employés des autorités d’État et des collectivités locales ». Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine, 2007. — 32 p.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Administration électronique : recommandations méthodologiques pour le travail autonome</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-169\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-169\" hidden><p>Ces recommandations structurent l’étude autonome des principes de l’administration électronique et de leur mise en œuvre dans le secteur public. Le guide accompagne la préparation des participants à la formation. Il structure leur étude des responsabilités institutionnelles et de la mise en place de services administratifs électroniques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2007). <i>E-governance: Self-study guidelines</i> [Administration électronique : recommandations méthodologiques pour le travail autonome]. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 2007 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information : manuel</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-170\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-170\" hidden><p>Un ouvrage d'étude fondamental consacré à l'examen complet des fondements théoriques, juridiques et gestionnaires de la politique de l'information dans le contexte de la construction de la société de l'information, intégrant les approches de l'administration publique, de la science politique, du droit et de la théorie des communications stratégiques. La contribution d'auteure de Svitlana Chukut couvre les blocs institutionnel-gestionnaire et numérique de la discipline : les fondements théoriques et méthodologiques de la mise en œuvre de l’administration électronique, les étapes de la transformation numérique de l'administration publique et les modèles de démocratie électronique ; une analyse comparative des pratiques mondiales réussies de développement de la société de l'information et de la gouvernance électronique (l'Union européenne, les États-Unis, la Grande-Bretagne, l'Estonie, Singapour) ; et les mécanismes de la politique de l'information de l'État ukrainien, la protection des ressources informationnelles, l'accès des citoyens à l'information publique et la réduction de la fracture numérique. L'un des premiers ouvrages académiques de base en Ukraine à intégrer la gouvernance électronique dans un cours général de politique de l'information de l'État, le livre contient un complexe pédagogique et méthodologique complet — glossaire, questions de contrôle, sujets de travaux scientifiques et base normative — et est largement utilisé dans la formation des spécialistes en administration publique, science politique, relations internationales et sécurité de l'information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pocheptsov, H. H. et Chukut, S. A. (2006). <i>Information policy</i> [Politique de l’information]. Znannia. <a class=\"apa-source\" href=\"https://catalog.library.dp.ua/cgi-bin/irbis64r_12/cgiirbis_64.exe?C21COM=F&amp;I21DBN=EKNK_PRINT&amp;LNG=&amp;P21DBN=EKNK&amp;S21FMT=infow_wh_print&amp;Z21MFN=11559\" target=\"_blank\" rel=\"noopener\">https://catalog.library.dp.ua/cgi-bin/irbis64r_12/cgiirbis_64.exe?C21COM=F&amp;I21DBN=EKNK_PRINT&amp;LNG=&amp;P21DBN=EKNK&amp;S21FMT=infow_wh_print&amp;Z21MFN=11559</a></p><div class=\"m\">Livres et monographies · 2006 · Kyiv : Znannia. — 663 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>634</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Membre des comités de rédaction de publications spécialisées</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-171\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-171\" hidden><p>Participation aux comités de rédaction de Strategic Priorities, Democratic Governance et de publications de l’Académie nationale d’administration publique. Ces fonctions couvrent des revues et des recueils qui diffusent des travaux sur les politiques publiques, la gouvernance et le fonctionnement des administrations.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Membre des comités de rédaction de publications spécialisées</i> [Notice de service éditorial]. (2006–2012).</p><div class=\"m\">Livres et monographies · 2006–2012 · « Priorités stratégiques », « Gouvernance démocratique », « Bulletin » et « Recueil » de l’Académie nationale d’administration publique auprès du Président de l’Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problèmes et perspectives du développement de l'administration électronique dans les conditions du progrès social moderne : expérience étrangère et nationale</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-172\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-172\" hidden><p>Comment mettre l'administration en ligne dans un pays où l'idée est encore nouvelle — et que peut-on apprendre des pays qui s'y sont mis plus tôt ? Dans cette étude de 2006, Svitlana Chukut s'est donné pour but d'identifier et d'étudier les problèmes de l'administration électronique dans le développement moderne de l'Ukraine et d'autres pays, en s'appuyant sur leur expérience commune, et d'élaborer des propositions et des recommandations scientifiquement fondées pour la mise en œuvre de l'administration électronique et les perspectives de son développement. L'étude a comparé les administrations électroniques des principaux pays du monde à la situation en Ukraine, examiné les principaux problèmes et les acquis de la formation du gouvernement électronique en Ukraine, et pesé les avantages de l'administration électronique par rapport à l'administration traditionnelle afin de définir les priorités de la démocratie numérique. Ses résultats étaient nouveaux à plusieurs égards : des définitions fondamentalement nouvelles du gouvernement électronique, de nouvelles approches de sa formation en Ukraine réparties en étapes, et de nouvelles approches pour surmonter les obstacles. La comparaison a débouché sur une conclusion pratique — l'Ukraine dispose de toutes les ressources nécessaires pour construire un système intégral de gouvernement électronique et y associer les citoyens eux-mêmes comme principaux acteurs de la politique de l'État — et l'étude s'est conclue par des recommandations pratiques, notamment pour l'enseignement : de nouveaux cours d'administration électronique et une spécialisation à l'Académie nationale d'administration publique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Problems and prospects of e-governance development in the conditions of modern social progress: Foreign and domestic experience</i> [Problèmes et perspectives du développement de l&#x27;administration électronique dans les conditions du progrès social moderne : expérience étrangère et nationale] [Rapport de recherche]. (2006). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2006 · Rapport de recherche. Kyiv : Académie nationale d'administration publique auprès du Président de l'Ukraine, 2006</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problèmes et perspectives de la mise en œuvre du gouvernement électronique : expérience mondiale et nationale</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-173\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-173\" hidden><p>Svitlana Chukut distingue les termes concurrents — administration électronique au sens large, État électronique, gestion électronique, société électronique — et définit l’administration électronique comme l'adaptation de l'administration publique aux nouvelles exigences du développement social : à la fois les services que l'État fournit aux citoyens et leur interaction interactive grâce à un système de rétroaction (citoyen → gouvernement → citoyen) fondé sur les TIC modernes. Elle décrit les trois étapes de la formation de l’administration électronique — sites gouvernementaux portant une information de référence ; intégration dans un portail unique avec services interactifs et rétroaction ; et communication principalement en ligne avec services 24 heures sur 24 et démocratie numérique — et rapporte l'indice de préparation au administration électronique de l'Enquête 2003 des Nations unies, sur lequel l'Ukraine (0,462) se situait légèrement au-dessus de la moyenne mondiale (0,402) et devant la Russie et la Biélorussie, tandis que les États-Unis (0,927) menaient. L'Ukraine, soutient-elle, manque à la fois d'une conception de la construction de la société de l'information et d'un organe responsable — contrairement au Conseil consultatif de l'autoroute de l'information du Canada, au groupe de travail américain sur l'infrastructure de l'information ou à la direction générale Société de l'information de l'UE — et elle regroupe les obstacles en problèmes financiers, technologiques, mentaux, culturels, éducatifs, politiques et professionnels. L'article examine ensuite les problèmes les plus répandus de la mise en œuvre de l’administration électronique et leurs solutions aux États-Unis (y compris les quatre raisons pour lesquelles les dépenses en TIC n'ont pas accru la productivité du secteur public, les contrats à économies partagées sous la loi de 2002 sur l’administration électronique, et les mesures contre la fracture numérique), dans l'Union européenne et en Grande-Bretagne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2005). Problems and prospects of e-government implementation: World and domestic experience [Problèmes et perspectives de la mise en œuvre du gouvernement électronique : expérience mondiale et nationale]. Dans <i>Administration publique en Ukraine : réalités et perspectives</i>. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Articles · 2005 · Recueil « L’administration publique en Ukraine : réalités et perspectives », Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problèmes et obstacles sur la voie du gouvernement électronique : expérience mondiale et nationale</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-174\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-174\" hidden><p>Svitlana Chukut distingue les notions voisines — la gouvernance électronique comme formation, appuyée par les TIC, de la position civique et de l'auto-gouvernement des citoyens, et l’administration électronique comme les actions de l'État et de ses organes — et définit l’administration électronique comme l'adaptation de l'administration publique aux nouvelles exigences du développement social, combinant les services de l'État avec une rétroaction interactive entre le citoyen et le gouvernement. Elle décrit trois étapes de construction de l’administration électronique, de la publication d'informations de référence sur les sites des administrations, en passant par un portail unifié avec services en ligne, jusqu'à une interaction principalement en ligne avec démocratie numérique, et lit l'indice de préparation de l'enquête 2003 des Nations unies sur l’administration électronique (Ukraine 0,462, au-dessus de la moyenne mondiale, mais freinée par l'absence d'une conception nationale et d'un organe responsable). L'article catalogue les obstacles ukrainiens — financiers, technologiques, mentaux, culturels, éducatifs, politiques et professionnels — et examine comment les États-Unis, l'Union européenne et le Royaume-Uni traitent de tels problèmes, y compris les contrats à économies partagées de la loi de 2002 sur l’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2005). Problems and obstacles to e-government: World and domestic experience [Problèmes et obstacles sur la voie du gouvernement électronique : expérience mondiale et nationale]. Dans <i>Administration publique en Ukraine : réalités et perspectives</i>. Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Articles · 2005 · Ibid.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>7</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Projet ukraino-allemand « Appui à la réforme de l’administration publique » (GTZ, gouvernement de la RFA)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-175\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-175\" hidden><p>Les fonctionnaires ukrainiens avaient besoin d'une formation pour une administration plus moderne et plus numérique. Dans ce projet de réforme ukraino-allemand (2005–2008), mené par l'Académie nationale d'administration publique avec une école partenaire de Berlin et financé par le gouvernement allemand (GTZ), Svitlana Chukut a rédigé le module « administration électronique » — la partie du cours consacrée au gouvernement numérique — pour les programmes de master en administration publique. Ce module a fait entrer le gouvernement numérique dans la formation standard des futurs gestionnaires publics.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span><i>Projet ukraino-allemand « Appui à la réforme de l’administration publique » (GTZ, gouvernement de la RFA)</i> [Projet de recherche]. (2005–2008). Académie nationale d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Projets · 2005–2008 · Participante — module « Administration électronique »</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information : manuel (Pocheptsov, Chukut)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-176\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-176\" hidden><p>Le catalogue de l’autrice recense ce manuel de Heorhii Pocheptsov et Svitlana Chukut dans la série de publications consacrées à la politique de l’information. Ce titre fait partie d’un ensemble de manuels qui rapprochent les questions de réglementation de l’information, de communication publique et d’administration électronique.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pocheptsov, H. H. et Chukut, S. A. (2005). <i>Information policy</i> [Politique de l’information]. Académie ukrainienne d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 2005 · Kyiv : Éditions de l’Académie ukrainienne d’administration publique</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information et relations publiques : recommandations méthodologiques</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-177\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-177\" hidden><p>Guide méthodologique qui accompagne l’apprentissage de la politique de l’information et des relations publiques. Il est conçu pour le travail autonome dans le cadre du cours. Conçu comme un outil de travail, il aide à relier les objectifs d’une politique de l’information aux pratiques de communication entre institutions et publics.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Nadolnyi, I. F. (2004). <i>Information policy and public relations: Methodological guide</i> [Politique d’information et relations publiques : recommandations méthodologiques]. Centre de littérature pédagogique. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Livres et monographies · 2004 · Kyiv : Centre de littérature éducative</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information et relations publiques : support de cours à distance</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-178\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-178\" hidden><p>Support de cours à distance qui met en relation la politique de l’information, les stratégies de communication et la pratique des relations publiques. Le support organise la progression à distance autour des rapports entre circulation de l’information, stratégie institutionnelle et communication avec le public.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Pocheptsov, H. H. et Chukut, S. A. (2004). <i>Information policy and PR: Distance course outline</i> [Politique d’information et relations publiques : support de cours à distance]. Centre de littérature pédagogique. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Livres et monographies · 2004 · Kyiv : Centre de littérature éducative. — 84 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>15</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Recommandations méthodologiques pour les auditeurs du cours à distance « Politique d’information »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-179\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-179\" hidden><p>Guide de travail destiné aux personnes inscrites au cours à distance sur la politique de l’information. Il accompagne l’étude autonome des thèmes du cours. Destiné à compléter le cours, le guide aide à organiser l’étude des concepts et des questions de politique publique abordés dans les activités d’apprentissage.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2004). <i>Methodological recommendations for students of the distance course &#x27;information policy&#x27;</i> [Recommandations méthodologiques pour les auditeurs du cours à distance « Politique d’information] [Guide pédagogique].</p><div class=\"m\">Livres et monographies · 2004</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Essence du gouvernement électronique et principes de son organisation</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-180\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-180\" hidden><p>Dans cet article programmatique précoce, écrit pour ouvrir une rubrique de revue sur l'essence et le développement de l’administration électronique, Svitlana Chukut examine les définitions disputées de l’administration électronique — comme portail, comme interaction interactive État–citoyen (Verchinine), comme infrastructure de réseau d'information et de communication (Kochkine) — et le projet de administration électronique de l'OCDE avec ses quatre groupes d'évaluation, de la prospective et de la réforme de l'administration publique à la mesure. S'appuyant sur les programmes eEurope 2002 et 2005 et sur le projet de programme « Ukraine électronique », elle distingue un gouvernement simplement en ligne d'un véritabl’administration électronique, énonce onze principes d'organisation de l’administration électronique — orientation vers le citoyen, commodité et simplicité, transformation de type entreprise, coût et complexité minimaux, qualité de service, conformité, extensibilité, performance, reddition de comptes, rapidité de mise en œuvre et disposition à agir — et conclut par une définition de l’administration électronique comme adaptation de l'administration publique aux nouvelles conditions du développement social, fondée sur une boucle de rétroaction citoyen–gouvernement.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2003). The essence of e-government and principles of its organisation [Essence du gouvernement électronique et principes de son organisation]. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 2003 · Bulletin de l’Académie ukrainienne d’administration publique, n° 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>52</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Construction de la société de l’information en Ukraine : problèmes et perspectives</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-181\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-181\" hidden><p>Svitlana Chukut passe en revue les premiers pas vers la construction d'une société de l'information en Ukraine. Après avoir rappelé les efforts parallèles de la communauté mondiale — l'initiative eEurope, le programme britannique de modernisation du gouvernement, le programme fédéral russe « Russie électronique » —, elle énumère le cadre ukrainien créé entre 1998 et 2003 : la loi sur le Programme national d'informatisation, les décrets présidentiels sur l'accès à Internet en Ukraine, sur la transparence des autorités publiques et sur la protection des ressources d'information de l'État, les résolutions du Cabinet sur la publication en ligne de l'activité de l'exécutif et sur la création du système d'information « Gouvernement électronique » (24 février 2003), ainsi que le projet de programme « Ukraine électronique ». Elle conclut que, bien que le besoin soit pleinement reconnu au niveau de l'administration publique, la plupart des problèmes restent irrésolus, et termine par la Déclaration de Budapest du Conseil de l'Europe (1999) : une société de l'information véritablement démocratique repose sur des politiques encourageant l'accès et la participation, la compétence et la préparation, la créativité et la diversité, avec une protection appropriée.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2003). Building the information society in Ukraine: Problems and prospects [Construction de la société de l’information en Ukraine : problèmes et perspectives]. <i>International Congress, Kyiv, 1–2.04.2003</i>.</p><div class=\"m\">Articles · 2003 · Congrès international, Kyiv, 1–2.04.2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique culturelle de l’État dans le contexte de la construction de la société de l’information : expérience étrangère et nationale</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-182\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-182\" hidden><p>Svitlana Chukut examine comment la construction de la société de l'information transforme la politique culturelle de l'État, en s'appuyant sur l'analyse de l'UNESCO et la pratique européenne. Elle expose les quatre aspects identifiés par l'UNESCO : les nouvelles technologies de l'information engendrent de nouveaux modèles de communication et un nouveau discours esthétique, nourrissant une « créativité globale » ; l'industrie culturelle gagne un poids économique sur un marché mondial, aiguisant les problèmes de droit d'auteur et de piraterie ; le patrimoine culturel — matériel et immatériel — devient une prérogative politique exposée au commerce illégal et aux acteurs transnationaux ; et la révolution de l'information elle-même entraîne des conséquences économiques, sociales et politiques qui exigent une définition claire des intérêts publics dans le cyberespace et la protection des droits des citoyens. Elle passe en revue la Stratégie à moyen terme de l'UNESCO pour 1996–2001 et soutient que le centre d'intérêt de la politique culturelle se déplace du processus créatif lui-même vers les moyens de transmettre ses résultats au consommateur. L'expérience du Canada — une autoroute nationale de l'information centrée sur la culture et la numérisation du patrimoine, dont le soutien à la production médiatique nationale a fait du pays un grand exportateur de films et de vidéos — est mise en regard de celle de l'Union européenne : le quatrième programme-cadre, le protocole d'entente « Accès multimédia au patrimoine culturel européen » (1995–1998) et le premier programme Culture 2000, avec leurs engagements sur l'accès numérisé, la protection du patrimoine et la diversité culturelle. Elle conclut que les traits communs de la politique culturelle moderne — les TI dans la création comme dans la diffusion, un patrimoine numérisé avec un accès non discriminatoire, l'éducation à distance tout au long de la vie, la protection de la moralité et des valeurs démocratiques, la préservation de la diversité culturelle et linguistique, et l'approfondissement de la coopération internationale — devraient être introduits dans la politique culturelle propre de l'Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2003). State cultural policy amid the information society: Foreign and domestic experience [Politique culturelle de l’État dans le contexte de la construction de la société de l’information : expérience étrangère et nationale]. <i>Culturological Readings in Memory of V. Pidkopaiev</i>. Center for Culturological Research.</p><div class=\"m\">Articles · 2003 · Lectures culturologiques à la mémoire de V. Pidkopaiev, Centre de recherches culturologiques, 2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Gouvernement électronique : problèmes et priorités</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-183\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-183\" hidden><p>Traitement étendu des problèmes et des priorités du développement de l’administration électronique dans l'expérience étrangère et nationale. Svitlana Chukut revient sur la définition disputée de l’administration électronique et sur le projet de l'OCDE — son horizon de long terme jusqu'à 2010, les critères de la gouvernance du XXIe siècle (légitimité, primauté du droit, transparence, responsabilité et honnêteté, efficacité, cohérence, adaptation, partenariat et consultation) et ses quatre groupes d'évaluation — avant d'énoncer les onze principes d'organisation de l’administration électronique, de l'orientation vers le citoyen et de la transformation de type entreprise à l'extensibilité, à la reddition de comptes et à la rapidité de mise en œuvre, ainsi que les dispositions clés tirées de la pratique étrangère : concentration sur les besoins réels des citoyens et des entreprises, partenariat avec l'industrie de haute technologie, mécanismes de démocratie numérique, qualité de service comparable au secteur privé, prestation multicanale, sécurité des réseaux et de l'information, et formation des fonctionnaires aux nouvelles formes de travail.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2003). E-government: Problems and priorities [Gouvernement électronique : problèmes et priorités]. Proc. of Ukrainian Academy of Public Administration Research Conf., May 2003.</p><div class=\"m\">Articles · 2003 · Actes de la conférence scientifique et pratique de l’Académie ukrainienne d’administration publique, mai 2003</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information : manuel. Partie 2 <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-184\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-184\" hidden><p>La deuxième partie du manuel aborde la politique de l’information à travers la mise en place du gouvernement électronique. Elle situe la modernisation des administrations ukrainiennes dans le contexte de la société de l’information.</p><p>Le volume rapproche les choix institutionnels et techniques des enjeux d’accès à l’information et d’organisation des services publics.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. et Lytvynenko, O. V. (2003). <i>Information policy: A textbook. part 2</i> [Politique d’information : manuel. Partie 2]. Académie nationale d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Informatsijna-politika_chast.2_CHukut_Litvinenko_E-uryad.pdf</a></p><div class=\"m\">Livres et monographies · 2003 · Kyiv : Académie nationale d’administration publique auprès du Président de l’Ukraine</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>25</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Analyse comparative de la construction du gouvernement électronique en Angleterre et en Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-185\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-185\" hidden><p>Une analyse comparative de la construction de l’administration électronique en Angleterre et en Ukraine. La comparaison replace les premières initiatives ukrainiennes dans une perspective internationale. Elle permet d’examiner le rôle des stratégies publiques et des capacités administratives dans le passage aux démarches en ligne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2002). Comparative analysis of e-government development in england and Ukraine [Analyse comparative de la construction du gouvernement électronique en Angleterre et en Ukraine]. Dans <i>Administration publique dans le contexte de l’intégration de l’Ukraine à l’Union européenne, vol. 2</i>. Académie ukrainienne d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Articles · 2002 · « L’administration publique dans les conditions d’intégration de l’Ukraine à l’UE », vol. 2, Kyiv : Académie ukrainienne d’administration publique</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique humanitaire : manuel</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-186\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-186\" hidden><p>Manuel de Vitalii Skurativskyi, Volodymyr Troshchynskyi et Svitlana Chukut (Maison d'édition de l'Académie ukrainienne d'administration publique ; Milenium, Kyiv, 2002, 262 p.). L'un des premiers manuels ukrainiens systématiques consacrés aux aspects théoriques, méthodologiques et appliqués de l'administration publique de la sphère humanitaire. L'ouvrage analyse de manière complète l'essence, la structure et les priorités de la politique humanitaire de l'État dans le contexte de la transformation de la société ukrainienne, en accordant une attention particulière aux mécanismes de régulation étatique du développement de l'éducation, de la science, de la culture, de la politique linguistique et de la politique de l'information, ainsi qu'à l'interaction des autorités de l'État avec les institutions de la société civile. Le livre systématise l'expérience nationale et étrangère de formation de la politique humanitaire de l'État et établit l'appareil conceptuel et catégoriel de base pour la formation des spécialistes en administration publique et en autonomie locale ; il est devenu une source de base pour l'enseignement des disciplines normatives et optionnelles de politique humanitaire et sociale dans les établissements d'enseignement supérieur ukrainiens. Destiné aux étudiants, étudiants en master et doctorants du domaine « Administration publique et administration », aux fonctionnaires, aux responsables de l'autonomie locale et aux chercheurs.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Skurativskyi, V. A., Troshchynskyi, V. P. et Chukut, S. A. (2002). <i>Humanitarian policy in Ukraine</i> [Politique humanitaire en Ukraine]. Éditions de l’UAPA et Milenium.</p><div class=\"m\">Livres et monographies · 2002 · Kyiv : Académie ukrainienne d’administration publique ; Milenium. — 262 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>114</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique humanitaire pour le développement de la culture</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-187\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-187\" hidden><p>Ce chapitre du manuel Politique humanitaire en Ukraine examine la responsabilité de l’État dans le développement de la culture et les moyens institutionnels dont il dispose. Le chapitre aborde le développement culturel comme un domaine de politique publique. Il situe les responsabilités de l’État dans le soutien aux institutions et aux activités culturelles.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2002). Humanitarian policy for cultural development [Politique humanitaire pour le développement de la culture]. Dans <i>Politique humanitaire en Ukraine</i>. Milenium. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Livres et monographies · 2002 · Chapitre. « Politique humanitaire ». Kyiv : Milenium</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique humanitaire pour le développement de la science</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-188\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-188\" hidden><p>Ce chapitre du manuel Politique humanitaire en Ukraine situe la science dans l’action publique et examine les responsabilités de l’État dans le développement de la recherche. Le chapitre situe le développement scientifique dans la politique humanitaire de l’Ukraine. Il s’intéresse à la place des institutions et des instruments publics qui soutiennent la recherche.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2002). Humanitarian policy for scientific development [Politique humanitaire pour le développement de la science]. Dans <i>Politique humanitaire en Ukraine</i>. Milenium. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Livres et monographies · 2002 · Chapitre. Ibid.</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information de l’État en Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-189\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-189\" hidden><p>Ce chapitre de la première partie du manuel Politique de l’information analyse les priorités de l’État ukrainien et le rôle de ses institutions dans le secteur de l’information.</p><p>L’analyse situe la politique de l’information parmi les responsabilités de l’État. Elle porte sur les institutions qui l’élaborent et les domaines de la vie publique qu’elle encadre.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2002). State information policy in Ukraine [Politique d’information de l’État en Ukraine]. Dans <i>Politique de l’information, partie 1</i> (p. 56–88). Académie ukrainienne d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/navchalna-literatura/\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/navchalna-literatura/</a></p><div class=\"m\">Livres et monographies · 2002 · Chapitre. « Politique d’information ». Partie 1. Kyiv : Académie ukrainienne d’administration publique. P. 56–88</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Diplôme d’honneur</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-190\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-190\" hidden><p>Diplôme d’honneur décerné en 2002 par l’Académie nationale d’administration publique auprès du Président de l’Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Académie nationale d’administration publique auprès du Président de l’Ukraine. (2002). <i>Diplôme d’honneur</i> [Document de reconnaissance].</p><div class=\"m\">Distinctions · 2002 · Académie nationale d’administration publique auprès du Président de l’Ukraine</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Choix et opinion publique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-191\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-191\" hidden><p>Examine le choix et l'opinion publique, ainsi que leur relation. L’article relie les choix individuels aux jugements qui se forment et circulent dans la société. Il inscrit ce lien dans l’étude des mécanismes sociaux et culturels qui orientent les décisions collectives.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2001). Choice and public opinion [Choix et opinion publique]. <i>Bulletin of the Academy of Cultural Executives</i>, (3).</p><div class=\"m\">Articles · 2001 · Bulletin de l’Académie des cadres dirigeants de la culture, n° 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique culturelle de l’Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-192\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-192\" hidden><p>Examine la politique culturelle de l'Ukraine. L’étude aborde le rôle des institutions publiques dans le développement de la culture en Ukraine. Elle situe l’action de l’État dans un domaine où se croisent la préservation du patrimoine et les pratiques culturelles contemporaines.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2001). Cultural policy of Ukraine [Politique culturelle de l’Ukraine]. <i>Bulletin of the Academy of Cultural Executives</i>, (3).</p><div class=\"m\">Articles · 2001 · Bulletin de l’Académie des cadres dirigeants de la culture, n° 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Dominantes éthico-culturelles du processus politique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-193\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-193\" hidden><p>Un article sur les dominantes éthiques et culturelles du processus politique — la tradition, le stéréotype et le rituel comme formes qui reproduisent l’intégrité générationnelle de la culture spirituelle. Svitlana Chukut nomme d’abord les moments négatifs dans les relations entre culture spirituelle et politique : la domination de la volonté politique de puissance par des forces économiques sans esprit, sa soumission au nationalisme expansionniste, et la distorsion de concepts à l’origine spirituels et de la noble idée nationale ; avec l’exemple de l’Allemagne d’Alfred Weber, elle les rattache à l’absence d’une vieille tradition politique capable d’absorber les éléments spirituels dans la pratique, de l’incarnation symbolique de cette tradition, et d’idées directrices définies pointant vers la mission de l’humanité. Elle examine ensuite chaque dominante : la tradition, qui avec le temps peut perdre son adaptabilité et se durcir en stéréotype — stable, rigide et conservateur, fait d’une image cognitive et d’une attitude instrumentale et pratique, et capable dans le processus politique de populariser un phénomène selon l’opinion publique et ceux qui la façonnent ; et le rituel, qu’à la suite de Foucault elle situe dans une politique entendue comme activité cristallisée par une culture spirituelle qui est elle-même un code de conduite. Le rituel politique trace un cercle magique autour des gouvernants alors même que les médias de masse rapprochent leurs images ; il fixe la légitimité sur un territoire en faisant revivre des rituels qui font appel à la mémoire nationale et aux valeurs patriotiques communes — drapeau, décorations, invocations de la nation dans les discours des leaders — exprimant ainsi la cohésion des gouvernés autour de valeurs, de symboles et d’une histoire partagés et renouvelant l’approbation collective du pouvoir établi, comme lors de la tournée d’un nouveau leader dans le pays. À côté de ces rituels consensuels se tiennent les rituels de confrontation — meetings et manifestations de rue, symboles d’antagonisme qui exigent également la présence physique de leurs partisans — et elle conclut sur la condition moderne : le rituel politique est désormais impensable sans les médias de masse, avant tout la télévision, qui favorise la nouveauté, tandis que le rituel lui-même met toujours la tradition en mouvement par un renvoi direct ou caché à elle.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2001). Ethical and cultural dominants of the political process [Dominantes éthico-culturelles du processus politique]. <i>Collected Papers of Ukrainian Academy of Public Administration</i>.</p><div class=\"m\">Articles · 2001 · Recueil de travaux scientifiques de l’Académie ukrainienne d’administration publique</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique culturelle de l’État ukrainien dans le contexte de l’expérience mondiale actuelle : principales orientations et tendances de développement</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-194\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-194\" hidden><p>Examine la politique culturelle de l'État ukrainien dans le contexte de l'expérience mondiale contemporaine : ses principaux axes et tendances. La perspective comparative situe les priorités de l’Ukraine dans un débat plus large sur la place des institutions publiques et sur les instruments de soutien à la culture.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (2001). Ukraine’s state cultural policy in the context of contemporary international experience: Key directions and development trends [Politique culturelle de l’État ukrainien dans le contexte de l’expérience mondiale actuelle : principales orientations et tendances de développement]. <i>Bulletin de l’Académie d’État des cadres de la culture et des arts</i>, (1), 12–19.</p><div class=\"m\">Articles · 2001 · Bulletin de l’Académie d’État des cadres de la culture et des arts, n° 1, p. 12–19</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it visual\"><div class=\"lib-badge\">CERTIFICAT</div><div class=\"lib-copy\"><div class=\"t\">« Théorie et pratique de l’apprentissage à distance »</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-195\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-195\" hidden><p>Formation de la Banque mondiale portant sur les principes de l’enseignement à distance et leur mise en application. Le thème est abordé sous l’angle de la conception des formations à distance, de la communication entre apprenants et formateurs et du rôle des supports d’apprentissage.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Banque mondiale. (2001). <i>Théorie et pratique de l’apprentissage à distance</i> [Certificat de formation].</p><div class=\"m\">Certificats · 2001 · Banque mondiale</div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">La mise en œuvre de la politique culturelle de l’État comme orientation prioritaire du développement de la sphère humanitaire</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-196\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-196\" hidden><p>Un article qui soutient que la mise en œuvre de la politique culturelle de l’État est la direction prioritaire du développement de la sphère humanitaire ukrainienne. Partant de l’allocution du président Kuchma — selon laquelle le progrès économique et social dépend davantage de la composante spirituelle et culturelle que de l’innovation purement technique, et la négligence de la sphère humanitaire a coûté cher à l’État — Svitlana Chukut ordonne dialectiquement les concepts : la politique de l’État comme réalisation générale des intérêts de l’État, la politique humanitaire comme sa forme particulière adressée aux citoyens et à leur vision du monde, et la politique culturelle comme la réalisation concrète des intérêts de l’État dans la culture, où la culture est à la fois le résultat et le moyen de la conscience et de la connaissance de soi d’une personne et d’une société ; la politique culturelle doit donc être intégrative, couvrant toutes les sphères de la vie sociale. Elle définit la politique culturelle de l’État par ses premières tâches — éduquer les citoyens, préserver l’identité culturelle, maintenir les rituels et les normes, et soutenir la contribution créatrice des citoyens à la culture spirituelle — conformément à la définition de l’UNESCO, et insiste sur le fait qu’il est erroné de la réduire soit à la « gestion de la culture », soit au « soutien à la culture » : les deux sont nécessaires, exprimés en priorités claires quant à ce que l’État gère et finance. Citant les données de l’Institut de sociologie (1994–1998) sur l’accès déclinant des Ukrainiens à leur culture nationale et la détérioration de leurs possibilités de participer à la vie culturelle, elle reproche à l’approche métaphysique de traiter les conséquences plutôt que les causes et d’emprunter sans esprit critique les formes étrangères. Elle examine ensuite le premier programme culturel de l’Union européenne, Culture 2000 — son soutien à la créativité, au patrimoine, à la diversité culturelle et à un espace culturel européen commun — dans le cadre de la stratégie d’intégration européenne de l’Ukraine, et conclut que la politique culturelle ukrainienne doit apprendre à répondre au défi du changement économique mondial, en s’appuyant sur toute la richesse du patrimoine ukrainien et mondial pour faire revivre l’identité nationale et servir la construction de l’État.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (2000). Implementing state cultural policy as a priority for the humanitarian sphere [La mise en œuvre de la politique culturelle de l’État comme orientation prioritaire du développement de la sphère humanitaire]. 'Ukraine: Advance Into the 21St Century', Kyiv: Ukrainian Academy of Public Administration.</p><div class=\"m\">Articles · 2000 · « L’Ukraine : progrès au XXIe siècle », Kyiv : Académie ukrainienne d’administration publique</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Analyse conceptuelle du choix dans le contexte de la gestion des processus socioculturels</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-197\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-197\" hidden><p>Un article qui donne une analyse conceptuelle du choix comme mécanisme par lequel, au sein de la continuité, se résout le problème de l’atteinte de l’idéal — le choix social dépendant du niveau des besoins développés d’une société. Svitlana Chukut part du postulat existentialiste (Sartre, Camus) selon lequel la personne est un projet qu’elle fait d’elle-même et qui choisit toujours, même dans la catastrophe : la soumission peut elle-même être consciente. Avec Lypynsky, elle soutient que le choix conscient dans la créativité politique suppose le libre arbitre à côté des désirs innés et spontanés — les plus hautes formes de culture ont été créées par des personnes et des nations qui croyaient au libre arbitre et choisissaient entre le bien et le mal — tandis que la personne hérite néanmoins de la statique de la vie sociale : la langue, le territoire, l’ordre étatique et le niveau culturel trouvés à la naissance, qui facilitent ou compliquent sa propre créativité. À l’opposé du structuralisme d’Althusser, où la personne est une marionnette de l’appareil idéologique d’État jouant des rôles écrits d’avance, elle place le noyau éthique du problème : avec Kierkegaard, le choix absolu est entre le bien et le mal, et ce qui compte est l’acte de choisir lui-même, accompli avec énergie et passion, par lequel la personnalité se définit — tarder est déjà une perte, car la vie choisit alors à sa place. Lisant les trois métamorphoses de l’esprit de Nietzsche comme trois types de choix, elle rapporte le chameau (« tu dois », l’État choisissant pour la personne) à la continuité formelle et l’enfant — la personne qui choisit consciemment dans l’héritage accumulé de l’humanité ou crée ce qui manque — à la continuité informelle, le lion (« je veux ») étant la négation entre les deux ; le choix actualise ainsi le contenu de la continuité, et plus une société et ses besoins sont développés, plus son choix de continuité s’accomplit consciemment.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Conceptual analysis of choice in managing socio-cultural processes [Analyse conceptuelle du choix dans le contexte de la gestion des processus socioculturels]. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1999 · Bulletin de l’Académie ukrainienne d’administration publique, n° 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’idée d’État et l’idéal social : leur signification fonctionnelle dans les processus de construction de l’État ukrainien</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-198\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-198\" hidden><p>Un article sur le rôle fonctionnel de l’idée d’État et de l’idéal social dans la construction de l’État ukrainien. Svitlana Chukut soutient qu'une société en transformation a besoin d'un principe consolidant unique qui donne un sens au changement dans toutes les sphères : historiquement, cette fonction intégratrice a été remplie par les religions d'État (l'hindouisme en Inde, le confucianisme en Chine, le protestantisme en Angleterre) et, dans le monde moderne, par des idéologies telles que le marxisme-léninisme. Elle examine la manière dont les États-Unis ont construit leur American Creed et dont le Japon — sous son élite samouraï, qui a préservé et développé la culture nationale tout en adoptant délibérément la technologie, les institutions et la science occidentales, et en rejetant l'individualisme occidental — s'est modernisé sans se perdre, une expérience qu'elle juge la plus utile pour l’Ukraine. À travers Ilyenkov, Kant, Marx, l'idéal absolu de Novgorodtsev et les types idéaux de Weber, elle distingue l’idéal — le modèle inaccessible de ce que la société aspire à être — de l'idée, moyen pratique de s'en approcher, et, suivant Franko à propos de Drahomanov, tient l'absence d'idéal national pour la principale tragédie des efforts politiques ukrainiens. S'appuyant sur le diagnostic de Tomashevsky quant à l'absence d'une idée d’État ukrainienne unique et sur Rymarenko, elle retrace l'idée d'une Ukraine indépendante et unie, de l'autonomie cosaque et de l’État de Khmelnytsky à la République populaire ukrainienne et à l'Acte d'indépendance de 1991, expose les fonctions apologétique, critique et futurologique de l’idée d’État ainsi que les tâches d'une idéologie d’État, et propose comme idée d’État intégratrice de l’Ukraine l'unité nationale fondée sur le développement de sa propre culture, avec un respect critique — et non une copie aveugle — de l'expérience des autres pays développés.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). The state idea and the social ideal: Their functional role in Ukraine's state-building [L’idée d’État et l’idéal social : leur signification fonctionnelle dans les processus de construction de l’État ukrainien]. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 1999 · Bulletin de l’Académie ukrainienne d’administration publique, n° 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le rôle des médias modernes dans les processus de construction de l’État (aspects choisis)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-199\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-199\" hidden><p>Examine certains aspects du rôle des médias modernes dans les processus de construction de l'État. L’article situe les médias dans la circulation de l’information publique et la formation de l’opinion. Ces fonctions éclairent leur rôle dans les rapports entre les institutions et la société au cours de la construction de l’État.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). The role of modern mass media in state-building (selected aspects) [Le rôle des médias modernes dans les processus de construction de l’État (aspects choisis)]. <i>Bulletin of Ukrainian Academy of Public Administration</i>, (3).</p><div class=\"m\">Articles · 1999 · Bulletin de l’Académie ukrainienne d’administration publique, n° 3</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>11</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Essence et rôle de l’opinion publique dans les processus de construction de l’État</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-200\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-200\" hidden><p>Un article sur l’essence et le rôle de l’opinion publique dans la construction de l’État, largement construit sur L’opinion et la foule de Gabriel Tarde. Svitlana Chukut suit Tarde en distinguant la tradition, la raison et l’opinion publique comme trois branches de l’esprit social : l’opinion se développe en dernier mais se répand le plus vite, croît aux dépens des deux autres et, dans la modernité, est devenue plus forte que la tradition comme que la raison institutionnelle. Elle retrace la manière dont les jugements individuels deviennent opinion publique — d’abord par la parole publique et la conversation privée, puis de manière décisive par le livre et surtout par la presse périodique, qui a soudé des opinions locales dispersées en opinions nationales et même internationales, transformé le poids des voix en un simple décompte, éveillé le sentiment national le long des frontières linguistiques et rendu possibles le suffrage universel et la majorité parlementaire, de sorte que le pouvoir lui-même se fabrique désormais dans les cafés, les clubs et les salons et se transforme par la presse qui s’en nourrit. Avec la Philosophie du droit de Hegel, elle soutient que la publicité est le moyen le plus efficace de former les intérêts de l’État : c’est seulement par le débat public que l’opinion publique acquiert un contenu véritable, apprend les préoccupations réelles de l’État et en vient à respecter la capacité et la fonction, tandis que l’opinion elle-même — qui fusionne vérité et erreur, les principes éternels de la justice comme sens commun avec les préjugés — mérite à la fois le respect pour son fond essentiel et le mépris pour son expression concrète, et seule une grande personne discerne le vrai en elle. Elle conclut par la conception de l’opinion publique propre aux relations publiques — un consensus dynamique né d’attitudes convergentes —, ses caractéristiques mesurables — direction, intensité, stabilité, saturation informationnelle et soutien social — et les lois de sa formation selon Hadley Cantril, comme base de travail pour l’influencer.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). The essence and role of public opinion in state-building [Essence et rôle de l’opinion publique dans les processus de construction de l’État]. <i>Hrani</i>, (3(5)).</p><div class=\"m\">Articles · 1999 · Hrani, n° 3(5)</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>17</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Protection du patrimoine culturel comme problème actuel d’aujourd’hui</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-201\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-201\" hidden><p>Examine la protection du patrimoine culturel comme une question d'actualité pressante. Le patrimoine est abordé comme une responsabilité publique liée à la transmission culturelle. La question porte autant sur les conditions de conservation que sur la place du patrimoine dans la vie collective.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Heritage protection as a pressing contemporary issue [Protection du patrimoine culturel comme problème actuel d’aujourd’hui]. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1999 · Recueil de travaux scientifiques de l’Académie ukrainienne d’administration publique, n° 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Principaux aspects de la réforme de la politique culturelle en Ukraine à la lumière de l’expérience mondiale</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-202\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-202\" hidden><p>Examine les principaux aspects de la réforme de la politique culturelle en Ukraine dans le contexte de l'expérience mondiale. L’article met en relation les enjeux ukrainiens et l’expérience d’autres pays. La comparaison sert à examiner les choix institutionnels auxquels l’Ukraine est confrontée dans la réforme de sa politique culturelle.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Key aspects of cultural policy reform in Ukraine in light of world experience [Principaux aspects de la réforme de la politique culturelle en Ukraine à la lumière de l’expérience mondiale]. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (2).</p><div class=\"m\">Articles · 1999 · Recueil de travaux scientifiques de l’Académie ukrainienne d’administration publique, n° 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Problèmes de fonctionnement des institutions sociales modernes dans les conditions de transformation de la société ukrainienne</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-203\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-203\" hidden><p>Examine les problèmes de fonctionnement des institutions sociales modernes dans la transformation de la société ukrainienne. L’article aborde les tensions que la transformation de la société ukrainienne crée pour des institutions chargées de coordonner l’action collective et de maintenir des pratiques sociales.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Problems of modern social institutions amid Ukraine's transformation [Problèmes de fonctionnement des institutions sociales modernes dans les conditions de transformation de la société ukrainienne]. <i>Pressing Issues of Public Administration, Kharkiv</i>, (2).</p><div class=\"m\">Articles · 1999 · Problèmes actuels de l’administration publique, Kharkiv, n° 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’élite créatrice : aspect théorique et méthodologique</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-204\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-204\" hidden><p>Un article théorique et méthodologique sur l’élite créatrice et sa place dans la culture spirituelle. Svitlana Chukut distingue l’élite dirigeante, qui décide de ce que les citoyens doivent prendre de l’héritage culturel de l’humanité et de ce que les artistes doivent créer, de l’élite créatrice, qui est guidée par des valeurs personnelles, crée et active cet héritage et porte la continuité informelle — de sorte que la direction de la continuité dans la culture spirituelle dépend du développement, de l’éducation et du professionnalisme de l’élite. À travers Toynbee, elle présente la civilisation comme l’œuvre d’individus et de minorités créateurs : la majorité non créatrice suit par mimésis, imitation dirigée dans les sociétés primitives vers la génération aînée et dans les civilisations vers les personnalités créatrices, dont le retrait-et-retour les renouvelle ; mais la mimésis est mécanique, et le succès engendre la « némésis de la créativité », lorsque les créateurs d’hier échouent devant le défi suivant et bloquent les nouveaux — d’où la désagrégation des civilisations par la perte de créativité de la minorité créatrice, le refus de la majorité de suivre une minorité simplement dominante et la perte de l’unité sociale. À travers Lypynsky, elle expose l’aristocratie nationale : la minorité active qui organise et gouverne la majorité passive, détient la force matérielle (la volonté de puissance, les moyens de guerre et de production) et, indispensablement, une autorité morale fondée sur sa propre moralité publique et sur l’acceptation des masses. Elle déduit le mécanisme social de formation de l’élite créatrice de ses fonctions — porteuse de la continuité de la culture nationale et de l’identité de la nation, génératrice de connaissances nouvelles, guide du renouveau national, participante à l’échange des expériences nationale et mondiale, créatrice de la culture spirituelle nationale, gardienne des valeurs et de la mémoire historique, et moteur de l’idée nationale — et conclut sur la personnalité créatrice et la foule, qui se définissent mutuellement : le niveau d’une société se voit à l’ampleur du choix de voies qu’elle laisse à la personne, qui peut vivre « en parallèle » de la foule selon ses propres règles ou l’affronter « perpendiculairement », au risque de la destruction ou, par la mimésis, de changer la vie sociale elle-même.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). The creative elite: A theoretical and methodological aspect [L’élite créatrice : aspect théorique et méthodologique]. <i>Pressing Issues of Public Administration, Odesa</i>, (1).</p><div class=\"m\">Articles · 1999 · Problèmes actuels de l’administration publique, Odesa, n° 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Culture spirituelle et question nationale dans le contexte du processus de construction de l’État en Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-205\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-205\" hidden><p>Un article sur le rapport entre la culture spirituelle et la question nationale dans la construction de l’État ukrainien au début du XXe siècle, lorsque — comme chez Shevchenko, Kulish, Lesia Ukrainka, Franko, Drahomanov et Hrushevsky — l'expression nationale devint la question la plus pressante de la vie publique. Suivant le développement par Bochkovsky de la théorie de Mancini, Svitlana Chukut expose la triple signification de la culture pour une nation : l'appartenance à un même type culturel unit une communauté tout en la distinguant des autres ; une culture partagée — avant tout la langue et l'écriture — facilite la compréhension mutuelle et manifeste l'appartenance nationale ; et des intérêts culturels communs sont une condition de l'émergence de la communauté. Elle souligne, avec Starosolsky, que la tradition historique n'est pas le passé lui-même mais l'expérience vivante que le présent en fait, et, avec Dnistriansky, qu'un peuple est constitué par la nature, la culture et le territoire, la culture étant le facteur nouveau sans lequel un peuple ne devient pas un peuple. À travers Mikhnovsky, elle soutient que le nationalisme est compatible avec le cosmopolitisme et l'humanisme — sauf avec le chauvinisme — et que le nationalisme sain des peuples opprimés est une source de créativité et de liberté ; à travers Lypynsky, que toute nation est un produit de l'histoire créé par le travail d'organisation de son aristocratie nationale, que la statique de la vie sociale héritée des générations précédentes conditionne sa dynamique, et que la culture politique croît avec l'expérience accumulée, le volontarisme et l'intelligence. Elle conclut que la conscience nationale, le rôle dirigeant de l'élite nationale — dirigeante et créatrice — et le lien entre culture nationale et construction de l’État demeurent pressants pour la politique de l’État dans toutes les sphères de la vie ukrainienne.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Spiritual culture and the national question in Ukraine's state-building [Culture spirituelle et question nationale dans le contexte du processus de construction de l’État en Ukraine]. <i>Pressing Issues of Public Administration, Lviv</i>, (2).</p><div class=\"m\">Articles · 1999 · Problèmes actuels de l’administration publique, Lviv, n° 2</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>1</strong> <span>citation</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Ce qui manque à l’élite dirigeante actuelle de l’Ukraine ? <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-206\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-206\" hidden><p>Un article qui demande ce qui manque à l’élite dirigeante actuelle de l’Ukraine. Svitlana Chukut sépare d’abord l’élite dirigeante — qui, en matière de culture, décide de ce que les citoyens doivent prendre de l’héritage de l’humanité et de ce que les artistes doivent créer — de l’élite créatrice, et s’appuie sur l’aristocratie nationale de Lypynsky : une minorité active dont le pouvoir ne dure que lorsque sa force matérielle est légitimée par une autorité morale, elle-même formée par la moralité publique de l’aristocratie et par l’acceptation par les masses de ses formes d’organisation ; une couche dirigeante à la mémoire faible, à la volonté consciente faible et à l’intelligence faible au milieu d’une forte émotivité ne peut donner à une nation ni culture politique ni vie étatique propre. Avec Toffler, elle décrit la dégradation mondiale de la capacité des élites à prendre des décisions opportunes et compétentes, le vide de pouvoir et le « trou noir » qui en résultent dans la société, la foi messianique dans le remplacement du leader, et les trois erreurs derrière la demande d’un leadership fort — le mythe de l’efficacité autoritaire, l’hypothèse que le style de leadership d’hier convient à aujourd’hui, et la personnalisation de ce qui est en fait un effondrement institutionnel — soutenant que la Troisième Vague exige des leaders qui écoutent, imaginent et acceptent les limites du leadership. Pour l’Ukraine, dont l’élite dirigeante en tant que celle d’un État indépendant est encore en formation, elle présente les enquêtes nationales de 1996–1997 : le public identifie l’élite aux plus riches (44 %) et aux hauts fonctionnaires (42 %), et seulement 15 % aux meilleurs et aux plus capables ; la confiance s’est effondrée (Président 17,6 %, ministres 2,4 %, députés 3,9 %), un tiers éprouve du ressentiment ou de l’hostilité envers l’élite et 54 % de l’indifférence, et le profil de Shchokin montre une élite âgée pour la plupart de 40 à 50 ans, à formation majoritairement technique, avec trop peu de spécialistes capables de faire fonctionner le mécanisme de continuité dans la culture spirituelle — d’où l’usage irrationnel du patrimoine, la domination de la culture de masse et la dévaluation des valeurs universelles. À cela elle oppose la sélection méritocratique des cadres (l’École nationale d’administration en France, l’Université de Tokyo, le Senior Executive Service aux États-Unis ; la Commission de réforme administrative en Ukraine et le rôle formateur de l’Académie ukrainienne d’administration publique) et répond directement à son titre : ce qui manque à l’élite dirigeante, c’est une idée d’État consolidante unique — comme l’American Creed aux États-Unis ou, au Japon, l’union par l’élite samouraï de la spiritualité orientale et de la technologie occidentale, dont la modernisation ciblée a préservé et même renforcé la culture japonaise.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). What does Ukraine's current ruling elite lack? [Ce qui manque à l’élite dirigeante actuelle de l’Ukraine ?]. <i>Viche</i>, (6). <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/CHogo-ne-vistachaye-sogodnishnij-pravlyachij-eliti-Ukrayini.docx.pdf</a></p><div class=\"m\">Articles · 1999 · Viche, n° 6</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>13</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Le rituel, sa place et sa signification dans le système de gestion de la continuité dans la culture spirituelle</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-207\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-207\" hidden><p>Examine le rituel, sa place et sa signification dans le système de gestion de la continuité de la culture spirituelle. Le rituel est étudié comme une pratique répétée qui rend visibles des valeurs et les transmet entre générations. L’article inscrit cette fonction dans la réflexion plus large sur la continuité culturelle.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Ritual: Its place and role in managing continuity in spiritual culture [Le rituel, sa place et sa signification dans le système de gestion de la continuité dans la culture spirituelle]. <i>Komandor</i>, (2).</p><div class=\"m\">Articles · 1999 · Komandor, n° 2</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Quelques problèmes de l’administration publique de la Chine ancienne dans le contexte actuel</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-208\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-208\" hidden><p>Examine certains problèmes de l'administration publique de la Chine ancienne dans un contexte contemporain. Le rapprochement avec des questions contemporaines permet de réfléchir à l’organisation de l’autorité et aux principes qui orientent l’action administrative dans différents contextes historiques.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Selected problems of ancient chinese public administration in a contemporary context [Quelques problèmes de l’administration publique de la Chine ancienne dans le contexte actuel]. <i>Komandor</i>, (3).</p><div class=\"m\">Articles · 1999 · Komandor, n° 3</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Expérience européenne de perfectionnement de la politique culturelle dans le contexte de la construction de l’État ukrainien</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-209\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-209\" hidden><p>Examine l'expérience européenne d'amélioration de la politique culturelle dans le contexte de la construction de l'État ukrainien. La comparaison européenne sert à situer les choix de politique culturelle de l’Ukraine dans le contexte de la construction de ses institutions et de la préservation de son patrimoine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). European experience of improving cultural policy in building the Ukrainian state [Expérience européenne de perfectionnement de la politique culturelle dans le contexte de la construction de l’État ukrainien]. <i>'Ukraine on the Threshold of the Third Millennium', Kyiv</i>.</p><div class=\"m\">Articles · 1999 · Recueil « L’Ukraine au seuil du troisième millénaire », Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>4</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Mécanisme de fonctionnement de la continuité dans la culture spirituelle</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-210\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-210\" hidden><p>Examine le mécanisme de fonctionnement de la continuité dans la culture spirituelle. Le texte examine la transmission des valeurs et des pratiques entre générations. Il s’inscrit dans la recherche de l’autrice sur les formes de continuité qui relient les institutions, le patrimoine et la vie collective.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). The mechanism of continuity in spiritual culture [Mécanisme de fonctionnement de la continuité dans la culture spirituelle]. <i>'Ukraine on the Threshold of the Third Millennium', Kyiv</i>.</p><div class=\"m\">Articles · 1999 · Recueil « L’Ukraine au seuil du troisième millénaire », Kyiv</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Genèse de la culture spirituelle (dimension managériale)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-211\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-211\" hidden><p>La monographie de Svitlana Chukut (Académie ukrainienne d'administration publique auprès du Président de l'Ukraine, Kyiv, 1999 ; approuvée pour publication par le Conseil académique de l'Académie le 24 décembre 1998) étudie la genèse de la culture spirituelle à travers le prisme de l'administration publique. Écrite au tournant du millénaire, elle part des problèmes de la culture spirituelle de l'époque — la dévalorisation des valeurs universelles, la « créativité sur commande » mesurée par l'argent et l'accompagnement médiatique, la domination de la culture de masse, la perte de confiance dans les idéaux de la société, et la tension entre l'emprunt acritique de la culture étrangère et l'usage unilatéral du patrimoine national. Le premier chapitre retrace le conditionnement mutuel de la culture spirituelle et de l'administration de l'État, du monde antique à Hobbes (« l'État comme condition préalable de la culture ») et Locke (« tradition et société civile »), à la philosophie classique allemande et à la conception dialectico-matérialiste de l'histoire, jusqu'à la gestion de la continuité culturelle aux XIXe et XXe siècles. Le deuxième développe une méthodologie de la continuité (succession) : la culture spirituelle comme phénomène de la vie sociale, ses caractéristiques de continuité et ses méthodes de recherche, ses sujets — l'élite dirigeante comme sujet de la continuité formelle et l'élite créatrice de la continuité informelle — et ses mécanismes, dans lesquels l'idéal est le but, le choix le moteur, et l'opinion publique et les valeurs le milieu. Le troisième examine les formes de la continuité — la tradition comme forme principale, le stéréotype comme son rudiment, l'innovation, le rituel, l'habitus, l'archétype et le symbole, et la langue comme lien de transition entre les formes et les moyens, y compris la langue des politiciens et son fonctionnement dans la société ukrainienne contemporaine. Le quatrième se tourne vers les moyens : le patrimoine culturel, les institutions sociales et les moyens techniques, avant tout les médias de masse et la production informatique de l'information, au sein d'un système national de communication de masse. Une postface rassemble les conclusions dans la politique culturelle de l'État — le soutien et la gestion de la culture.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (1999). <i>The genesis of spiritual culture (the management dimension)</i> [Genèse de la culture spirituelle (dimension managériale)]. Académie ukrainienne d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf</a></p><div class=\"m\">Livres et monographies · 1999 · Monographie. Kyiv : Académie ukrainienne d’administration publique. — 256 p.</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>82</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Reproduction de l’intégrité générationnelle de la culture spirituelle (aspect managérial)</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-212\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-212\" hidden><p>Résumé de la thèse de doctorat ès sciences sur la transmission de la culture spirituelle entre générations et le rôle des institutions et de l’action publique dans cette continuité.</p><p>L’étude interroge les mécanismes qui permettent à une génération de transmettre ses valeurs et ses pratiques. Elle situe cette question dans le champ de l’administration publique et de la politique culturelle.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (1999). <i>Reproducing the generational integrity of spiritual culture (the management aspect)</i> [Reproduction de l’intégrité générationnelle de la culture spirituelle (aspect managérial)] [Résumé de thèse de doctorat ès sciences]. Académie ukrainienne d’administration publique auprès du Président de l’Ukraine.</p><div class=\"m\">Livres et monographies · 1999 · Résumé de thèse de doctorat ès sciences. Kyiv</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>10</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a><span class=\"scholar-record-note\">Décompte de Google Scholar pour la notice au titre de la thèse.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">La culture spirituelle dans la politique humanitaire de l’Ukraine</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-213\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-213\" hidden><p>Un développement scientifique et méthodologique préparé à l’Académie ukrainienne d'administration publique auprès du Président de l’Ukraine (Kyiv, 1999), qui expose la place de la culture spirituelle dans la politique humanitaire de l’Ukraine. Sa première partie situe la culture dans la construction de l’État : la culture comme croyances non écrites, évaluations et règles acceptées d'une société — analysée à travers la technologie, l'économie, l'organisation sociale, la religion et le symbolisme — et la culture spirituelle non comme un résultat figé mais comme le processus de création, d'accumulation, de transmission et d'utilisation des acquis culturels, dont le mécanisme central est la continuité, reproduction de l'intégrité culturelle d'une génération. La deuxième partie examine la politique culturelle de l’État ukrainien : à la conception administrativo-directive de la « gestion de la culture », qui subordonnait la culture à la politique et à l'économie, elle oppose la conception du « soutien à la culture » reconnue par les démocraties développées et fondée sur la valeur intrinsèque de la culture, tout en soutenant que la sphère culturelle dépasse largement les arts — éducation, science, liberté de conscience et de parole — comme dans la définition de l'UNESCO de la politique culturelle comme somme des actions conscientes d'une société visant des objectifs culturels. La troisième partie déploie neuf directions de la politique de l’État dans la culture spirituelle : le soutien législatif, la sphère de l'information, le patrimoine culturel, la politique linguistique, les rituels, cérémonies et fêtes, le développement de la sphère culturelle et artistique, les cultures des minorités nationales, la culture des jeunes et la coopération internationale — le ministère de la Culture et des Arts étant l'organe exécutif central qui met en œuvre la politique dans ce domaine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1999). Spiritual culture in Ukraine's humanitarian policy [La culture spirituelle dans la politique humanitaire de l’Ukraine]. Dans <i>Programme Ukraine 2010</i>. Kyiv: Ukrainian Academy of Public Administration.</p><div class=\"m\">Livres et monographies · 1999 · Chapitre. « Programme « Ukraine – 2010 » ». Kyiv : Académie ukrainienne d’administration publique</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>6</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Genèse de la culture spirituelle (dimension managériale) <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-214\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-214\" hidden><p>Examine la genèse de la culture spirituelle sous l'angle de la gestion. L’ouvrage étudie la transmission des acquis culturels et le rôle des institutions, de la langue et des médias. Il relie ces mécanismes aux responsabilités de l’État dans le soutien à la culture.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (1999). <i>Genesis of spiritual culture (management dimension)</i> [Genèse de la culture spirituelle (dimension managériale)]. Académie ukrainienne d’administration publique auprès du Président de l’Ukraine. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Geneza-duhovnoyi-kulturi-upravlinskij-vimir.pdf</a></p><div class=\"m\">Articles · 1999</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a><span class=\"scholar-record-note\">Ces citations sont comprises dans le total de la notice de la monographie.</span></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">L’impact de la politique de l’État sur le fonctionnement des formes de continuité de la culture spirituelle</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-215\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-215\" hidden><p>Un article qui examine comment la politique de l’État façonne le fonctionnement des formes de continuité dans la culture spirituelle — traditions, coutumes, innovations, rituels, stéréotypes, lois et langue — par lesquelles l'expérience sociale et historique d'une société s'accumule et se transmet. Svitlana Chukut définit la politique de l’État en matière de culture comme l'ensemble des objectifs de l’État dans la sphère culturelle, des principes qu'il observe et des mécanismes qui les garantissent, et prend la tradition pour principale forme de continuité : passant par la formation, le développement intensif et le déclin, elle accumule l'expérience chargée de valeurs des générations passées, tandis que le stéréotype est une tradition figée et privée de développement propre, et l'innovation la forme extérieure de la continuité qui renouvelle les formes extérieures de la tradition. S'appuyant sur la « tradition éternelle » d'Unamuno, sur Hayek et sur la critique du modernisme de Laszlo, elle soutient que la diversité culturelle est la réserve d'adaptation de l'humanité, et que la politique de l’État agit directement sur les formes qui s'épanouissent : là où l’État crée les conditions d'une économie libre, du libre choix des citoyens et de la liberté politique, l'innovation s'active en premier — un schéma qui se répète environ tous les trente ans dans la culture spirituelle ukrainienne, lors des dégels de la fin des années 1920, de la fin des années 1950 et de la fin des années 1980. Elle avertit que la culture de masse et la culture pop déshumanisent, réduisant la personne aux besoins matériels, et conclut que la culture spirituelle forme une pensée relativement indépendante et la citoyenneté, tandis que l'idée nationale produite par l’État intègre les citoyens autour d'un avenir commun et de valeurs partagées.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1998). The impact of state policy on the functioning of spiritual culture continuity forms [L’impact de la politique de l’État sur le fonctionnement des formes de continuité de la culture spirituelle]. <i>Collected Papers of Ukrainian Academy of Public Administration</i>, (1).</p><div class=\"m\">Articles · 1998 · Recueil de travaux scientifiques de l’Académie ukrainienne d’administration publique, n° 1</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>2</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Langue : maîtresse ou servante ?</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-216\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-216\" hidden><p>Pose la question du statut de la langue : maîtresse ou servante ? La formulation met en jeu le statut de la langue dans la vie publique. Le texte s’inscrit dans la réflexion de l’autrice sur les rapports entre langue, culture et pouvoir.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1998). Language: Mistress or maid? [Langue : maîtresse ou servante ?]. <i>Komandor</i>, (1).</p><div class=\"m\">Articles · 1998 · Komandor, n° 1</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">La théorie de Hobbes sur l’État comme condition préalable de la culture dans le contexte des problèmes actuels de démocratisation de la société ukrainienne</div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-217\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-217\" hidden><p>Un article qui lit la théorie de l’État de Thomas Hobbes comme condition préalable de la culture à la lumière des problèmes de démocratisation de la société ukrainienne. Svitlana Chukut note que la gestion de la continuité dans la culture spirituelle a toujours été au centre de la construction de l’État, et présente Hobbes comme un théoricien précoce de ce contrôle — et de l’aliénation : les hommes créent l’État, le « grand Léviathan », en aliénant une grande partie de leurs droits naturels, après quoi il s’élève au-dessus de ses créateurs et les gouverne. Pour Hobbes, hors de l’État règnent les passions, la guerre, la peur, la pauvreté et la barbarie ; en son sein, la raison, la paix, la sécurité, la richesse, les sciences et la bienveillance — c’est seulement dans l’État qu’existe une mesure commune de la vertu et du vice, à savoir ses lois, et les bonnes dispositions se réduisent à la justice et à la miséricorde. Elle suit son traitement des instruments de contrôle : la religion, historiquement le premier mécanisme de supervision par l’État de ce que les gens doivent croire, faire et hériter — mais la religion, pour Hobbes, n’est pas une philosophie, c’est une loi dans chaque État ; les livres et les prédicateurs qui glorifient le tyrannicide engendrent des Ravaillac et des Clément plutôt que des citoyens ; et le souverain détient le droit de juger quelles doctrines sont hostiles à la paix civile et de les interdire, avant tout les doctrines de l’obéissance divisée, racine — souligne-t-elle avec Hobbes — de toutes les guerres civiles du monde chrétien. En même temps, elle dégage les limites que Hobbes fixe au pouvoir : la liberté comme absence d’obstacles, la distinction entre le peuple (une volonté, capable d’une action) et la multitude, la règle selon laquelle les lois doivent poursuivre les erreurs plutôt que ceux qui errent — les opinions se changent par la persuasion, non par les menaces —, la nécessité de codifier une saine doctrine civile et de l’enseigner d’abord dans les universités, la faute des gouvernants qui multiplient les lois au-delà du bien de l’État et de ses citoyens, et la fin de la peine, qui doit diriger la volonté plutôt que la briser. Elle conclut que l’étude et la mise en pratique d’une telle expérience européenne sont nécessaires à la poursuite de la démocratisation de l’Ukraine.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. (1998). Hobbes's theory of the state as a precondition of culture in the context of Ukraine's democratisation [La théorie de Hobbes sur l’État comme condition préalable de la culture dans le contexte des problèmes actuels de démocratisation de la société ukrainienne]. <i>Prydniprovskyi Visnyk</i>, (95–96).</p><div class=\"m\">Articles · 1998 · Prydniprovskyi Visnyk, n° 95–96</div><div class=\"scholar-citation\"><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div><div class=\"lib-it \"><div class=\"lib-copy\"><div class=\"t\">Politique d’information de l’État en Ukraine <a href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\" aria-label=\"Ouvrir la source\">Source</a></div><button type=\"button\" class=\"lib-desc-btn\" aria-expanded=\"false\" aria-controls=\"libd-218\"><span>Description</span><span class=\"lib-desc-chev\" aria-hidden=\"true\"></span></button><div class=\"d\" id=\"libd-218\" hidden><p>Le document examine la politique ukrainienne de l’information et les pistes proposées pour l’améliorer, notamment en matière de liberté d’expression et d’action publique. Le document situe le droit à l’information et la liberté d’expression dans le cadre de la politique de l’État. Il met ces questions en relation avec les responsabilités des autorités publiques et la réglementation de la sphère de l’information.</p></div><p class=\"apa\"><span class=\"apa-label\">Référence APA (7e éd.)</span>Chukut, S. A. (s. d.). <i>State information policy of Ukraine</i> [Politique d’information de l’État en Ukraine]. <a class=\"apa-source\" href=\"https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf\" target=\"_blank\" rel=\"noopener\">https://ktpu.kpi.ua/wp-content/uploads/2016/02/Derzhavna-informatsijna-politika-Ukrayini.pdf</a></p><div class=\"m\">Livres et monographies</div><div class=\"scholar-citation\"><span class=\"lib-cit\"><strong>3</strong> <span>citations</span></span><a href=\"https://scholar.google.com/citations?user=PUKuQ8QAAAAJ\" target=\"_blank\" rel=\"noopener\">Profil Google Scholar de Svitlana Chukut</a></div></div></div>", "bio-projects-04": "Chercheuse principale — intelligence artificielle, tourisme intelligent et reconstruction de l’Ukraine", "bio-projects-44": "Guide scientifique et méthodologique : relations entre les pouvoirs publics et la société civile", "bio-projects-46": "Utilisation pratique du gouvernement et de l’administration électroniques — recommandations méthodologiques", "courses-kpi-08": "Discipline normative du programme de doctorat « Gestion et administration publiques » de la spécialité 281 (2e année, semestre d'automne ; 150 heures, 5 crédits ECTS). Elle forme les connaissances théoriques et pratiques et les compétences des doctorants pour l'utilisation créative et la mise en œuvre des technologies et outils modernes d'administration électronique et de gouvernement numérique — y compris l'intelligence artificielle —, afin d'améliorer le système même d'administration publique et de favoriser les processus d'innovation dans la société selon les standards mondiaux. Son sujet est l'étude des orientations stratégiques du développement de l'administration électronique : tendances actuelles, technologies et méthodologies, y compris l'IA, les outils numériques et les pratiques innovantes. Les quatorze webinaires et leurs ateliers pratiques couvrent l'introduction à l'administration électronique et au gouvernement numérique ; les tendances de développement — administration mobile, numérique et intelligente ; l'IA dans l'administration publique — possibilités et défis ; les indices internationaux de développement de l'administration électronique — méthodologie et évaluation ; les tendances actuelles de la démocratie électronique ; l'administration électronique et les villes intelligentes — stratégies, plans et indices ; le vote électronique — défis et menaces ; le rôle de la plateforme Diia dans la transformation numérique de l'Ukraine ; le gouvernement numérique orienté vers les crises en situation d'urgence (guerre et pandémies) ; les orientations prioritaires d'après les meilleures pratiques internationales et ukrainiennes ; l'éthique et la confidentialité des données dans le gouvernement numérique ; et les tendances futures — IA, blockchain et au-delà. Le cours culmine avec la présentation en équipe des stratégies de développement de l'administration électronique élaborées par les doctorants.", "courses-kpi-26": "Spécialité 281 « Administration et gestion publiques » · master · programme « Gestion et administration publiques électronique » · 1re année", "courses-kpi-28": "Discipline obligatoire du programme éducatif « Gestion et administration publiques électronique » de la spécialité 281 (1re année, semestre d'automne ; 120 heures, 4 crédits ECTS ; contrôle final — un examen). Elle forme les connaissances théoriques et pratiques et les compétences des étudiants pour l'utilisation créative des approches étrangères modernes d'administration électronique et de démocratie électronique, visant à améliorer le système même d'administration publique et à favoriser les processus d'innovation dans la société sur la base des standards mondiaux. Construit sur le principe de l'alignement constructif et sur une approche centrée sur l'étudiant, le syllabus exige que chaque tâche successive mobilise les compétences et connaissances acquises dans la précédente. Les thèmes vont du gouvernement électronique à l'administration intelligente ; les rapports des Nations unies sur le développement de l'administration électronique à l'étranger ; la mise en œuvre en Ukraine ; les services électroniques ; l'essence de la démocratie électronique et ses principales composantes ; le vote électronique ; le parlement électronique ; et l'administration électronique et la démocratie électronique en conditions de guerre en réseau. Les étudiants apprennent à définir les orientations prioritaires de la mise en œuvre de l'administration électronique et du développement de la démocratie électronique, à utiliser les outils de la démocratie électronique en s'appuyant sur la meilleure expérience étrangère, et à mener de manière autonome une recherche sur un problème actuel de mise en œuvre. Les travaux finaux sont un projet d'équipe et un travail créatif individuel avec soutenance publique obligatoire. Dans le cadre de l'enseignement de ce cours, l'auteure a élaboré et mis en œuvre sa propre pratique d'innovation éducative « Опануй, досліди, впровадь ! » (« Maîtrise-le, étudie-le, mets-le en œuvre ! »), qui a remporté un prix au concours panukrainien « Meilleures pratiques d'introduction des innovations éducatives dans le système de formation professionnelle des fonctionnaires, des chefs d'administrations publiques locales, de leurs premiers adjoints et adjoints, des responsables de l'autonomie locale et des députés des conseils locaux », organisé par l'Agence nationale d'Ukraine pour la fonction publique, dans la nomination « Préparation des étudiants de master de la spécialité 281 Administration et gestion publiques » (2020).", "courses-kpi-41": "Cours au choix du programme « Gestion et administration publiques » (2e année, semestre de printemps ; 120 heures, 4 crédits ECTS). Il forme les connaissances et compétences des doctorants dans l'application des mécanismes de communication au sein de l'activité de gestion — notamment pour assurer l'ouverture et la transparence des autorités publiques — : stratégies et campagnes de communication, canaux de communication, planification des campagnes, travail avec les parties prenantes et évaluation de l'efficacité. Les thèmes comprennent les infox et la lutte contre la désinformation, les réseaux sociaux et les blogs, l'élaboration du scénario d'une campagne, ainsi que l'expérience réussie de campagnes à l'étranger et en Ukraine, avec les défis et menaces de leur conduite. Chaque doctorant élabore des recommandations pour une campagne de communication liée au sujet de sa propre recherche doctorale.", "courses-kpi-43": "Spécialité 281 « Administration et gestion publiques » · master · programme « Gestion et administration publiques électronique »", "courses-kpi-46": "Cours au choix du programme « Gestion et administration publiques électronique » (1re année ; 120 heures, 4 crédits ECTS). Il forme les connaissances et compétences des étudiants dans l'élaboration et l'application de stratégies de communication au sein de l'activité de gestion et des affaires. Les thèmes couvrent les variétés de stratégies de communication et leur usage dans l'administration publique et les affaires, les méthodes, formes et canaux de communication, le travail avec les parties prenantes, les enquêtes et la formulation des messages clés, les réseaux sociaux et les blogs, ainsi que les infox et leur réfutation. Les étudiants préparent le scénario détaillé d'une stratégie, étudient l'expérience étrangère réussie et les meilleurs exemples ukrainiens, et apprennent à évaluer l'efficacité d'une stratégie, à identifier les risques et à les prévenir. Le cours s'achève par la mise en œuvre en équipe d'une stratégie de communication élaborée par les étudiants.", "courses-kpi-66": "Discipline obligatoire (normative) du troisième niveau (éducatif et scientifique) de l'enseignement supérieur, au sein du programme éducatif « Gestion et administration publiques » de la spécialité 281 (domaine 28 « Gestion et administration publiques ») (2e année, semestre d'automne ; 210 heures, 7 crédits ECTS). Son but est d'unir la recherche scientifique à la pratique : chaque doctorant suit un programme de travail individuel de la pratique, formé en fonction du sujet de sa recherche doctorale et à partir des tâches du travail pédagogique, éducatif, méthodologique et organisationnel au sein du département. Les doctorants approfondissent leurs connaissances de la pédagogie de l'enseignement supérieur, mènent l'analyse scientifico-méthodique des programmes de disciplines, établissent les plans-concepts des séances, conduisent différentes formes de séances en présentiel, perfectionnent avec un regard d'auteur les disciplines des programmes de licence et de master et mettent à l'épreuve les matériaux de leur thèse. La participation aux cours magistraux, séminaires, conférences, tables rondes et cercles scientifiques développe le potentiel de leadership, les capacités oratoires et la culture de communication. Le contenu comprend six sections : l'activité pédagogique ; l'activité méthodologique ; l'activité de recherche ; l'activité éducative ; l'activité organisationnelle ; et le travail autonome. Le contrôle semestriel comprend l'établissement du programme de travail individuel et la soutenance du rapport de pratique.", "courses-teaching-28": "Gestion et administration publiques électronique", "page-egov-days-03": "Forum national · Kyiv · 2008–2011", "egov-editions-23": "Lancement d’un forum national", "media-events-02": "Interventions et <span class=\"grad\">rencontres professionnelles</span>"}};Object.keys(edits).forEach(function(l){Object.assign(PAGE[l],edits[l]);});})();
